static bool run_pinned_clean_proxy_uri_oracle(u16 frontend_port,
                                              u16 backend_port,
                                              TempDir& temp,
                                              const std::string& container_name,
                                              const char* access_scope,
                                              const CleanProxyUriOracleProfile& profile,
                                              ApiNonRootProxyUriOracleObservation& observation,
                                              std::string& error,
                                              bool listen_first = true,
                                              int* frontend_reservation = nullptr,
                                              int* backend_reservation = nullptr) {
    if (!validate_optional_held_loopback_pair(frontend_reservation,
                                              frontend_port,
                                              backend_reservation,
                                              backend_port,
                                              false,
                                              "pinned clean proxy side",
                                              error))
        return false;
    observation = ApiNonRootProxyUriOracleObservation{};
    observation.order = listen_first ? "listen-before-location" : "location-before-listen";
    observation.temp_path = temp.path;
    observation.config_path = temp.nginx_config;
    observation.log_path = temp.nginx_log;
    observation.access_path = temp.nginx_log;
    observation.process_identity = container_name;
    observation.frontend_port = frontend_port;
    observation.backend_port = backend_port;
    observation.wires.resize(5);
    for (const char* target : profile.targets) {
        const std::string request = api_request(target);
        const std::string exact_request =
            std::string("GET ") + target +
            " HTTP/1.1\r\nHost: client.example\r\nX-Dup: one\r\nX-Dup: two\r\nConnection: "
            "close\r\n\r\n";
        const size_t header_end = request.find("\r\n\r\n");
        if (request != exact_request || request.rfind("GET /", 0) != 0 ||
            request.find('#') != std::string::npos ||
            request.find("\r\nHost: client.example\r\n") == std::string::npos ||
            request.find("\r\nConnection: close\r\n") == std::string::npos ||
            request.find("\r\nContent-Length:") != std::string::npos ||
            request.find("\r\nTransfer-Encoding:") != std::string::npos ||
            request.find("\r\nTE:") != std::string::npos ||
            request.find("\r\nExpect:") != std::string::npos ||
            request.find("\r\nUpgrade:") != std::string::npos || header_end == std::string::npos ||
            header_end + 4u != request.size() || request.rfind("\r\n\r\n") != header_end) {
            error = std::string(profile.issue) +
                    " oracle vector escaped the fresh bodyless GET domain: " + target;
            return false;
        }
    }

    const std::string access_prefix = "rut-nginx-" + std::string(profile.access_tag) + "-" +
                                      access_scope + "-" + std::to_string(getpid()) + "-scoped";
    observation.access_scope = access_prefix;
    const std::string config = make_pinned_clean_proxy_uri_config(
        frontend_port, backend_port, access_prefix, profile, listen_first);
    observation.config = config;
    if (!write_file(temp.nginx_config, config.data(), config.size())) {
        error = std::string("failed to write ") + profile.issue +
                " clean proxy URI pinned nginx config";
        return false;
    }

    const auto recorder_live = [](const Recorder& recorder) {
        return recorder.running.load(std::memory_order_acquire) &&
               recorder.thread_alive.load(std::memory_order_acquire) &&
               !recorder.listener_failed.load(std::memory_order_acquire);
    };
    const auto wait_recorder_live = [&](Recorder& recorder, Child& nginx, const char* phase) {
        const auto deadline = std::chrono::steady_clock::now() + std::chrono::seconds(2);
        while (std::chrono::steady_clock::now() < deadline) {
            if (poll_child(nginx)) {
                error = std::string("pinned nginx exited before ") + profile.issue + " " + phase +
                        " recorder readiness";
                return false;
            }
            if (recorder.listener_failed.load(std::memory_order_acquire) ||
                !recorder.running.load(std::memory_order_acquire)) {
                error =
                    std::string(profile.issue) + " " + phase + " recorder failed before readiness";
                return false;
            }
            if (recorder.thread_alive.load(std::memory_order_acquire)) return true;
            usleep(1000);
        }
        error = std::string(profile.issue) + " " + phase + " recorder readiness timed out";
        return false;
    };
    const auto send_vector = [&](Child& nginx, size_t index, const std::vector<char>& expected) {
        const std::string request = api_request(profile.targets[index]);
        struct ClientGuard {
            int fd = -1;
            ~ClientGuard() {
                if (fd >= 0) close(fd);
            }
        } client{connect_once(frontend_port)};
        std::vector<char> wire;
        std::string detail;
        if (client.fd < 0 || !send_all(client.fd, request.data(), request.size()) ||
            !read_response(client.fd, wire, detail) || !read_eof(client.fd, detail)) {
            error = std::string(profile.issue) + " vector " + profile.targets[index] +
                    " response/EOF failed: " + (detail.empty() ? "connect or send failed" : detail);
            return false;
        }
        std::vector<char> normalized = wire;
        if (!normalize_date(normalized) || normalized != expected) {
            error = std::string(profile.issue) + " vector " + profile.targets[index] +
                    " did not match the exact Date-normalized nginx wire";
            return false;
        }
        if (poll_child(nginx)) {
            error = std::string("pinned nginx exited after ") + profile.issue + " vector " +
                    profile.targets[index];
            return false;
        }
        observation.wires[index] = std::move(wire);
        observation.eof_proven[index] = true;
        return true;
    };
    const auto observe_exact_count = [&](Recorder& recorder,
                                         Child& nginx,
                                         u32 expected,
                                         const char* phase) {
        const auto deadline = std::chrono::steady_clock::now() + std::chrono::milliseconds(500);
        while (std::chrono::steady_clock::now() < deadline) {
            if (poll_child(nginx)) {
                error = std::string("pinned nginx exited during ") + profile.issue + " " + phase;
                return false;
            }
            if (!recorder_live(recorder)) {
                error = std::string(profile.issue) + " recorder stopped or failed during " + phase;
                return false;
            }
            if (recorder.accepted.load(std::memory_order_acquire) != expected ||
                recorder.requests.load(std::memory_order_acquire) != expected ||
                recorder.response_send_all_calls.load(std::memory_order_acquire) != expected) {
                error = std::string(profile.issue) + " unexpected upstream count during " + phase;
                return false;
            }
            usleep(5000);
        }
        return true;
    };
    const auto wait_exact_count = [&](Recorder& recorder, Child& nginx, u32 expected) {
        const auto deadline = std::chrono::steady_clock::now() + std::chrono::seconds(2);
        while (std::chrono::steady_clock::now() < deadline) {
            if (poll_child(nginx) || !recorder_live(recorder)) {
                error = std::string("pinned nginx or ") + profile.issue +
                        " forward recorder failed while waiting for count";
                return false;
            }
            const u32 accepts = recorder.accepted.load(std::memory_order_acquire);
            const u32 requests = recorder.requests.load(std::memory_order_acquire);
            const u32 sends = recorder.response_send_all_calls.load(std::memory_order_acquire);
            if (accepts > expected || requests > expected || sends > expected) {
                error = std::string(profile.issue) +
                        " forward recorder exceeded its exact upstream count";
                return false;
            }
            if (accepts == expected && requests == expected && sends == expected) return true;
            usleep(1000);
        }
        error =
            std::string("timed out waiting for ") + profile.issue + " exact forward upstream count";
        return false;
    };

    Recorder redirect_recorder;
    redirect_recorder.observe_extra_requests_until_stop = true;
    if (!handoff_held_loopback_port(
            backend_reservation, backend_port, "pinned nginx backend recorder bind", error) ||
        !redirect_recorder.setup(backend_port)) {
        if (error.empty())
            error = std::string("failed to start ") + profile.issue +
                    " redirect zero-upstream recorder";
        return false;
    }
    DockerGuard docker(container_name);
    ChildGuard nginx;
    if (!handoff_held_loopback_port(
            frontend_reservation, frontend_port, "pinned nginx frontend bind", error) ||
        !spawn_child({"docker",
                      "run",
                      "--pull=never",
                      "--network",
                      "host",
                      "--name",
                      container_name,
                      "-v",
                      temp.nginx_config + ":/etc/nginx/nginx.conf:ro",
                      kNginxImage,
                      "nginx",
                      "-g",
                      "daemon off;"},
                     temp.nginx_log,
                     nginx.child)) {
        if (error.empty())
            error = std::string("failed to start pinned nginx for ") + profile.issue + " oracle";
        return false;
    }
    if (!wait_ready(frontend_port, nginx.child, error) ||
        !wait_recorder_live(redirect_recorder, nginx.child, "redirect"))
        return false;

    for (size_t i = 3; i < 5; i++) {
        const std::vector<char> expected = expected_clean_proxy_location_redirect(
            frontend_port, profile.location, i == 3 ? "" : "?x=1");
        if (!send_vector(nginx.child, i, expected)) return false;
        if (redirect_recorder.accepted.load(std::memory_order_acquire) != 0 ||
            redirect_recorder.requests.load(std::memory_order_acquire) != 0 ||
            redirect_recorder.response_send_all_calls.load(std::memory_order_acquire) != 0) {
            error = std::string(profile.issue) +
                    " redirect unexpectedly reached upstream: " + profile.targets[i];
            return false;
        }
    }
    if (!observe_exact_count(
            redirect_recorder, nginx.child, 0, "live redirect zero-upstream window"))
        return false;
    redirect_recorder.stop();
    observation.redirect_accepts = redirect_recorder.accepted.load(std::memory_order_acquire);
    observation.redirect_requests = redirect_recorder.requests.load(std::memory_order_acquire);
    observation.redirect_sends =
        redirect_recorder.response_send_all_calls.load(std::memory_order_acquire);
    if (redirect_recorder.thread_alive.load(std::memory_order_acquire) ||
        redirect_recorder.listener_failed.load(std::memory_order_acquire) ||
        observation.redirect_accepts != 0 || observation.redirect_requests != 0 ||
        observation.redirect_sends != 0 ||
        redirect_recorder.response_send_succeeded.load(std::memory_order_acquire) ||
        !redirect_recorder.history.empty() || !redirect_recorder.request.empty()) {
        error = std::string(profile.issue) +
                " redirect recorder did not settle with zero upstream activity";
        return false;
    }

    Recorder forward_recorder;
    forward_recorder.observe_extra_requests_until_stop = true;
    if (!forward_recorder.setup(backend_port, 3, kBackendResponse, sizeof(kBackendResponse) - 1u) ||
        !wait_recorder_live(forward_recorder, nginx.child, "forward")) {
        if (error.empty())
            error = std::string("failed to start ") + profile.issue + " forward recorder";
        return false;
    }
    const std::vector<char> success(
        kSuccessResponseNormalized,
        kSuccessResponseNormalized + sizeof(kSuccessResponseNormalized) - 1u);
    for (size_t i = 0; i < 3; i++) {
        if (!send_vector(nginx.child, i, success) ||
            !wait_exact_count(forward_recorder, nginx.child, static_cast<u32>(i + 1u)))
            return false;
    }
    if (!observe_exact_count(forward_recorder, nginx.child, 3, "live no-fourth-forward window"))
        return false;

    if (!stop_child(nginx.child)) {
        error = std::string("failed to stop pinned nginx after ") + profile.issue + " oracle";
        return false;
    }
    if (!docker.remove()) {
        error = std::string("docker rm -f failed after ") + profile.issue + " oracle";
        return false;
    }
    forward_recorder.stop();
    observation.forward_accepts = forward_recorder.accepted.load(std::memory_order_acquire);
    observation.forward_requests = forward_recorder.requests.load(std::memory_order_acquire);
    observation.forward_sends =
        forward_recorder.response_send_all_calls.load(std::memory_order_acquire);
    observation.forward_history = forward_recorder.history;
    if (forward_recorder.thread_alive.load(std::memory_order_acquire) ||
        forward_recorder.listener_failed.load(std::memory_order_acquire) ||
        observation.forward_accepts != 3 || observation.forward_requests != 3 ||
        observation.forward_sends != 3 ||
        !forward_recorder.response_send_succeeded.load(std::memory_order_acquire) ||
        !forward_recorder.response_clean_shutdown.load(std::memory_order_acquire) ||
        !forward_recorder.response_connection_closed.load(std::memory_order_acquire) ||
        observation.forward_history.size() != 3) {
        error = std::string(profile.issue) +
                " forward recorder did not settle at exactly three upstream episodes";
        return false;
    }

    std::vector<std::vector<char>> expected_history;
    expected_history.reserve(3);
    for (const char* target : profile.forward_targets) {
        const std::string request = std::string("GET ") + target + " HTTP/1.1\r\n" +
                                    "Host: 127.0.0.1:" + std::to_string(backend_port) +
                                    "\r\nX-Dup: one\r\nX-Dup: two\r\n\r\n";
        expected_history.emplace_back(request.begin(), request.end());
    }
    if (observation.forward_history != expected_history) {
        error = std::string(profile.issue) +
                " clean proxy URI did not preserve the exact upstream request wires";
        return false;
    }

    bool logs_readable = true;
    for (size_t i = 0; i < 5; i++) {
        const std::string marker = std::string("\"GET ") + profile.targets[i] + " HTTP/1.1\" " +
                                   (i < 3 ? "200 2" : "301 169") + " host=\"client.example\"";
        logs_readable = logs_readable && log_count_line_with(temp.nginx_log,
                                                             marker.c_str(),
                                                             access_prefix.c_str(),
                                                             observation.access_records[i]);
    }
    u32 forward_access = 0;
    u32 redirect_access = 0;
    u32 total_access = 0;
    u32 upstream_failures = 0;
    const std::string upstream_context = "127.0.0.1:" + std::to_string(backend_port);
    logs_readable =
        logs_readable &&
        log_count_line_with(temp.nginx_log, "200 2 host=", access_prefix.c_str(), forward_access) &&
        log_count_line_with(
            temp.nginx_log, "301 169 host=", access_prefix.c_str(), redirect_access) &&
        log_count_line_with(
            temp.nginx_log, access_prefix.c_str(), access_prefix.c_str(), total_access) &&
        log_count_line_with(
            temp.nginx_log, "connect() failed", upstream_context.c_str(), upstream_failures);
    if (!logs_readable || observation.access_records[0] != 1 ||
        observation.access_records[1] != 1 || observation.access_records[2] != 1 ||
        observation.access_records[3] != 1 || observation.access_records[4] != 1 ||
        forward_access != 3 || redirect_access != 2 || total_access != 5 ||
        upstream_failures != 0) {
        error = std::string(profile.issue) +
                " scoped access log did not prove exactly three 200/2 forwards, two 301/169 "
                "redirects, five total records, and zero upstream failures";
        return false;
    }
    std::string complete_log;
    if (!read_exact_return204_log(temp.nginx_log,
                                  (std::string(profile.issue) + " clean oracle log").c_str(),
                                  complete_log,
                                  error))
        return false;
    for (const char* severity : {"[warn]", "[error]", "[crit]", "[alert]", "[emerg]"}) {
        if (complete_log.find(severity) != std::string::npos) {
            error = std::string(profile.issue) + " nginx lifecycle log contained " + severity;
            return false;
        }
    }
    static constexpr size_t kExecutionOrder[] = {3u, 4u, 0u, 1u, 2u};
    size_t begin = 0u;
    while (begin < complete_log.size()) {
        const size_t end = complete_log.find('\n', begin);
        if (end == std::string::npos) break;
        const std::string line = complete_log.substr(begin, end - begin);
        begin = end + 1u;
        if (line.find(access_prefix) == std::string::npos) continue;
        if (observation.access_order.size() >= std::size(kExecutionOrder)) {
            error =
                std::string(profile.issue) + " access log contained more than five scoped records";
            return false;
        }
        const size_t index = kExecutionOrder[observation.access_order.size()];
        const std::string marker = std::string("\"GET ") + profile.targets[index] + " HTTP/1.1\" " +
                                   (index < 3u ? "200 2" : "301 169") + " host=\"client.example\"";
        if (line.find(marker) == std::string::npos) {
            error =
                std::string(profile.issue) + " scoped access records were reordered or malformed";
            return false;
        }
        observation.access_order.emplace_back(profile.targets[index]);
    }
    if (observation.access_order.size() != std::size(kExecutionOrder)) {
        error = std::string(profile.issue) + " access log omitted one of five ordered records";
        return false;
    }
    observation.clean_lifecycle = true;
    return true;
}

static bool validate_wildcard_service_no_uri_observation(
    const ApiNonRootProxyUriOracleObservation& observation, std::string& error) {
    const auto& profile = kWildcardServiceNoUriProxyOracleProfile;
    if ((observation.order != "listen-before-location" &&
         observation.order != "location-before-listen") ||
        observation.frontend_port == 0u || observation.backend_port == 0u ||
        observation.frontend_port == observation.backend_port || observation.temp_path.empty() ||
        observation.config_path.empty() || observation.log_path.empty() ||
        observation.access_path != observation.log_path || observation.process_identity.empty() ||
        observation.access_scope.empty() ||
        observation.config !=
            make_pinned_clean_proxy_uri_config(observation.frontend_port,
                                               observation.backend_port,
                                               observation.access_scope,
                                               profile,
                                               observation.order == "listen-before-location")) {
        error = "#357 observation lost its exact wildcard-listener/no-URI config or identity";
        return false;
    }
    if (observation.wires.size() != 5u || observation.forward_history.size() != 3u ||
        observation.access_order.size() != 5u || observation.redirect_accepts != 0u ||
        observation.redirect_requests != 0u || observation.redirect_sends != 0u ||
        observation.forward_accepts != 3u || observation.forward_requests != 3u ||
        observation.forward_sends != 3u || !observation.clean_lifecycle) {
        error =
            "#357 observation lost its five vectors, zero redirect upstream, three forwards, "
            "or clean lifecycle";
        return false;
    }
    static constexpr size_t kExecutionOrder[] = {3u, 4u, 0u, 1u, 2u};
    for (size_t i = 0u; i < 5u; i++) {
        if (!observation.eof_proven[i] || observation.access_records[i] != 1u ||
            observation.access_order[i] != profile.targets[kExecutionOrder[i]]) {
            error = "#357 observation lost exact EOF or ordered scoped access evidence";
            return false;
        }
        std::vector<char> normalized = observation.wires[i];
        const std::vector<char> expected =
            i < 3u ? std::vector<char>(
                         kSuccessResponseNormalized,
                         kSuccessResponseNormalized + sizeof(kSuccessResponseNormalized) - 1u)
                   : expected_clean_proxy_location_redirect(
                         observation.frontend_port, profile.location, i == 3u ? "" : "?x=1");
        if (!normalize_date(normalized) || normalized != expected) {
            error = "#357 observation lost an exact Date-normalized wire";
            return false;
        }
    }
    std::vector<std::vector<char>> expected_history;
    for (const char* target : profile.forward_targets) {
        const std::string request = std::string("GET ") + target + " HTTP/1.1\r\nHost: " +
                                    "127.0.0.1:" + std::to_string(observation.backend_port) +
                                    "\r\nX-Dup: one\r\nX-Dup: two\r\n\r\n";
        expected_history.emplace_back(request.begin(), request.end());
    }
    if (observation.forward_history != expected_history) {
        error =
            "#357 observation rewrote a no-URI target/query, retained Connection, lost "
            "duplicate headers, or retried";
        return false;
    }
    return true;
}

static bool validate_wildcard_service_no_uri_pair(
    const ApiNonRootProxyUriOracleObservation (&observations)[2], std::string& error) {
    if (observations[0].order != "listen-before-location" ||
        observations[1].order != "location-before-listen") {
        error = "#357 pair lost its two exact declaration orders";
        return false;
    }
    for (const auto& observation : observations)
        if (!validate_wildcard_service_no_uri_observation(observation, error)) return false;
    const u16 ports[] = {observations[0].frontend_port,
                         observations[0].backend_port,
                         observations[1].frontend_port,
                         observations[1].backend_port};
    for (size_t i = 0u; i < std::size(ports); i++) {
        for (size_t j = i + 1u; j < std::size(ports); j++) {
            if (ports[i] == ports[j]) {
                error = "#357 pair shared one of four frontend/backend ports";
                return false;
            }
        }
    }
    const std::string* resources[2][6];
    for (size_t side = 0u; side < 2u; side++) {
        resources[side][0] = &observations[side].temp_path;
        resources[side][1] = &observations[side].config_path;
        resources[side][2] = &observations[side].log_path;
        resources[side][3] = &observations[side].access_path;
        resources[side][4] = &observations[side].process_identity;
        resources[side][5] = &observations[side].access_scope;
        for (size_t i = 0u; i < 6u; i++)
            for (size_t j = i + 1u; j < 6u; j++) {
                if (i == 2u && j == 3u) continue;
                if (*resources[side][i] == *resources[side][j]) {
                    error = "#357 pinned side aliased unrelated resource identities";
                    return false;
                }
            }
    }
    for (const std::string* left : resources[0])
        for (const std::string* right : resources[1])
            if (*left == *right) {
                error = "#357 pair shared a process/temp/config/log/access identity";
                return false;
            }
    return true;
}

static bool run_wildcard_service_no_uri_self_checks(std::string& error) {
    const auto& profile = kWildcardServiceNoUriProxyOracleProfile;
    static constexpr u16 kPorts[] = {45701u, 45702u, 45703u, 45704u};
    if (strcmp(profile.issue, "#357") != 0 || strcmp(profile.location, "/service/") != 0 ||
        profile.proxy_uri[0] != '\0' || strcmp(profile.forward_targets[0], "/service/") != 0 ||
        strcmp(profile.forward_targets[1], "/service/x") != 0 ||
        strcmp(profile.forward_targets[2], "/service/x?y=1") != 0) {
        error = "#357 immutable profile mixed explicit-URI or rewritten-target semantics";
        return false;
    }
    const auto make_observation = [&](size_t side) {
        ApiNonRootProxyUriOracleObservation observation;
        observation.order = side == 0u ? "listen-before-location" : "location-before-listen";
        observation.temp_path = "/tmp/rut-nginx-357-side-" + std::to_string(side);
        observation.config_path = observation.temp_path + "/nginx.conf";
        observation.log_path = observation.temp_path + "/nginx.log";
        observation.access_path = observation.log_path;
        observation.process_identity = "rut-nginx-357-process-" + std::to_string(side);
        observation.access_scope = "rut-nginx-357-access-" + std::to_string(side);
        observation.frontend_port = kPorts[side * 2u];
        observation.backend_port = kPorts[side * 2u + 1u];
        observation.config = make_pinned_clean_proxy_uri_config(observation.frontend_port,
                                                                observation.backend_port,
                                                                observation.access_scope,
                                                                profile,
                                                                side == 0u);
        for (size_t i = 0u; i < 5u; i++) {
            std::vector<char> wire =
                i < 3u ? std::vector<char>(
                             kSuccessResponseNormalized,
                             kSuccessResponseNormalized + sizeof(kSuccessResponseNormalized) - 1u)
                       : expected_clean_proxy_location_redirect(
                             observation.frontend_port, profile.location, i == 3u ? "" : "?x=1");
            const std::string marker(29u, 'X');
            const auto date = std::search(wire.begin(), wire.end(), marker.begin(), marker.end());
            static constexpr char kDate[] = "Tue, 01 Jan 2030 00:00:00 GMT";
            if (date != wire.end()) std::copy_n(kDate, 29u, date);
            observation.wires.push_back(std::move(wire));
            observation.eof_proven[i] = true;
            observation.access_records[i] = 1u;
        }
        for (const char* target : profile.forward_targets) {
            const std::string request = std::string("GET ") + target + " HTTP/1.1\r\nHost: " +
                                        "127.0.0.1:" + std::to_string(observation.backend_port) +
                                        "\r\nX-Dup: one\r\nX-Dup: two\r\n\r\n";
            observation.forward_history.emplace_back(request.begin(), request.end());
        }
        observation.access_order = {profile.targets[3],
                                    profile.targets[4],
                                    profile.targets[0],
                                    profile.targets[1],
                                    profile.targets[2]};
        observation.forward_accepts = observation.forward_requests = observation.forward_sends = 3u;
        observation.clean_lifecycle = true;
        return observation;
    };
    ApiNonRootProxyUriOracleObservation valid[2] = {make_observation(0u), make_observation(1u)};
    if (!validate_wildcard_service_no_uri_pair(valid, error)) return false;
    const auto rejects = [&](const char* label,
                             const ApiNonRootProxyUriOracleObservation& candidate) {
        std::string detail;
        if (!validate_wildcard_service_no_uri_observation(candidate, detail)) return true;
        error = std::string("#357 observation validator accepted mutation: ") + label;
        return false;
    };
    const auto replace_unique =
        [&](std::string value, const std::string& from, const std::string& to, const char* label) {
            const size_t offset = from.empty() ? std::string::npos : value.find(from);
            if (from.empty() || from == to || offset == std::string::npos ||
                value.find(from, offset + from.size()) != std::string::npos) {
                error = std::string("#357 mutation was not unique/non-no-op: ") + label;
                return std::string{};
            }
            value.replace(offset, from.size(), to);
            return value;
        };
    auto changed = valid[0];
    changed.config =
        replace_unique(changed.config, "location /service/", "location /api/", "location");
    if (changed.config.empty() || !rejects("wrong-location", changed)) return false;
    changed = valid[0];
    changed.config = replace_unique(changed.config,
                                    "proxy_pass http://127.0.0.1:45702;",
                                    "proxy_pass http://127.0.0.1:45702/;",
                                    "explicit-uri");
    if (changed.config.empty() || !rejects("explicit-uri", changed)) return false;
    changed = valid[0];
    changed.order = "location-before-listen";
    if (!rejects("order", changed)) return false;
    changed = valid[0];
    changed.forward_history[0][4] = '/';
    changed.forward_history[0].erase(changed.forward_history[0].begin() + 5u,
                                     changed.forward_history[0].begin() + 12u);
    if (!rejects("rewritten-target", changed)) return false;
    changed = valid[0];
    changed.wires[4] =
        expected_clean_proxy_location_redirect(changed.frontend_port, profile.location, "");
    if (!rejects("redirect-query", changed)) return false;
    changed = valid[0];
    std::swap(changed.access_order[0], changed.access_order[1]);
    if (!rejects("access-order", changed)) return false;
    changed = valid[0];
    changed.access_records[2] = 0u;
    if (!rejects("access-count", changed)) return false;
    changed = valid[0];
    changed.eof_proven[0] = false;
    if (!rejects("EOF", changed)) return false;
    changed = valid[0];
    changed.clean_lifecycle = false;
    if (!rejects("lifecycle", changed)) return false;

    ApiNonRootProxyUriOracleObservation pair[2] = {valid[0], valid[1]};
    pair[1].order = "listen-before-location";
    std::string detail;
    if (validate_wildcard_service_no_uri_pair(pair, detail)) {
        error = "#357 pair validator accepted duplicate declaration order";
        return false;
    }
    pair[1] = valid[1];
    pair[1].temp_path = pair[0].temp_path;
    if (validate_wildcard_service_no_uri_pair(pair, detail)) {
        error = "#357 pair validator accepted shared resource identity";
        return false;
    }
    pair[1] = valid[1];
    pair[1].log_path = pair[0].log_path;
    pair[1].access_path = pair[1].log_path;
    if (!validate_wildcard_service_no_uri_observation(pair[1], detail) ||
        validate_wildcard_service_no_uri_pair(pair, detail)) {
        error = "#357 pair access/log alias mutation did not isolate cross-side identity";
        return false;
    }
    pair[1] = valid[1];
    pair[1].backend_port = pair[0].frontend_port;
    pair[1].config = make_pinned_clean_proxy_uri_config(
        pair[1].frontend_port, pair[1].backend_port, pair[1].access_scope, profile, false);
    pair[1].forward_history.clear();
    for (const char* target : profile.forward_targets) {
        const std::string request = std::string("GET ") + target + " HTTP/1.1\r\nHost: 127.0.0.1:" +
                                    std::to_string(pair[1].backend_port) +
                                    "\r\nX-Dup: one\r\nX-Dup: two\r\n\r\n";
        pair[1].forward_history.emplace_back(request.begin(), request.end());
    }
    if (!validate_wildcard_service_no_uri_observation(pair[1], detail) ||
        validate_wildcard_service_no_uri_pair(pair, detail)) {
        error = "#357 shared-port mutation did not isolate pair uniqueness";
        return false;
    }
    return true;
}

static bool run_pinned_wildcard_service_no_uri_oracle(
    const std::string& container_prefix,
    ApiNonRootProxyUriOracleObservation (&observations)[2],
    std::string& error) {
    u16 ports[4]{};
    for (u16& port : ports) {
        if (!allocate_port(port)) {
            error = "#357 could not allocate four isolated frontend/backend ports";
            return false;
        }
    }
    for (size_t i = 0u; i < std::size(ports); i++) {
        for (size_t j = i + 1u; j < std::size(ports); j++) {
            if (ports[i] == ports[j]) {
                error = "#357 port allocation produced a shared frontend/backend port";
                return false;
            }
        }
    }
    TempDir temps[2];
    if (!temps[0].create() || !temps[1].create() || strcmp(temps[0].path, temps[1].path) == 0) {
        error = "#357 could not create isolated declaration-order temp trees";
        return false;
    }
    if (!run_pinned_clean_proxy_uri_oracle(ports[0],
                                           ports[1],
                                           temps[0],
                                           container_prefix + "-listen-first",
                                           "listen-first",
                                           kWildcardServiceNoUriProxyOracleProfile,
                                           observations[0],
                                           error,
                                           true) ||
        !run_pinned_clean_proxy_uri_oracle(ports[2],
                                           ports[3],
                                           temps[1],
                                           container_prefix + "-location-first",
                                           "location-first",
                                           kWildcardServiceNoUriProxyOracleProfile,
                                           observations[1],
                                           error,
                                           false))
        return false;
    return validate_wildcard_service_no_uri_pair(observations, error);
}

static bool run_pinned_api_non_root_proxy_uri_oracle(
    u16 frontend_port,
    u16 backend_port,
    TempDir& temp,
    const std::string& container_name,
    const char* access_scope,
    ApiNonRootProxyUriOracleObservation& observation,
    std::string& error) {
    return run_pinned_clean_proxy_uri_oracle(frontend_port,
                                             backend_port,
                                             temp,
                                             container_name,
                                             access_scope,
                                             kApiV1ProxyUriOracleProfile,
                                             observation,
                                             error);
}

struct BoundedExactLocalPathOracleObservation {
    std::string order;
    std::string temp_path;
    std::string config_path;
    std::string log_path;
    std::string access_path;
    std::string process_identity;
    std::vector<std::vector<char>> wires;
    std::vector<std::vector<char>> local_history;
    std::vector<std::vector<char>> forward_history;
    u32 access_records[5]{};
    u32 local_accepts = 0;
    u32 local_requests = 0;
    u32 local_sends = 0;
    u32 forward_accepts = 0;
    u32 forward_requests = 0;
    u32 forward_sends = 0;
};

static bool read_exact_return204_log(const std::string& path,
                                     const char* label,
                                     std::string& contents,
                                     std::string& error);

static void dump_bounded_exact_local_path_oracle_observation(
    const BoundedExactLocalPathOracleObservation& observation) {
    std::cerr << "bounded-exact-local-path order=" << observation.order
              << " access=" << observation.access_records[0] << "/" << observation.access_records[1]
              << "/" << observation.access_records[2] << "/" << observation.access_records[3] << "/"
              << observation.access_records[4] << " upstream=" << observation.local_requests << "+"
              << observation.forward_requests << "\n";
    static constexpr const char* kLabels[] = {
        "GET /healthz", "GET /healthz?x=1", "GET /healthz/", "GET /health", "GET /"};
    for (size_t i = 0; i < observation.wires.size(); i++) {
        const char* label = i < sizeof(kLabels) / sizeof(kLabels[0]) ? kLabels[i] : "extra vector";
        dump_wire(label, observation.wires[i]);
    }
    for (size_t i = 0; i < observation.forward_history.size(); i++) {
        const std::string label = "healthz oracle upstream " + std::to_string(i + 1u);
        dump_wire(label.c_str(), observation.forward_history[i]);
    }
}

static bool capture_pinned_bounded_exact_local_path_order(
    u16 frontend_port,
    u16 backend_port,
    TempDir& temp,
    const std::string& container_name,
    bool exact_first,
    bool no_content_return204,
    BoundedExactLocalPathOracleObservation& observation,
    std::string& error,
    int* frontend_reservation = nullptr,
    int* backend_reservation = nullptr) {
    static constexpr const char* kTargets[] = {
        "/healthz", "/healthz?x=1", "/healthz/", "/health", "/"};
    static constexpr bool kLocal[] = {true, true, false, false, false};
    static_assert(sizeof(kTargets) / sizeof(kTargets[0]) == sizeof(kLocal) / sizeof(kLocal[0]));

    const auto make_request = [no_content_return204](const char* target) {
        return std::string("GET ") + target + " HTTP/1.1\r\nHost: " +
               (no_content_return204 ? "healthz-return204.example" : "healthz.example") +
               "\r\nConnection: close\r\n\r\n";
    };
    for (const char* target : kTargets) {
        const std::string request = make_request(target);
        const size_t header_end = request.find("\r\n\r\n");
        if (request.rfind(std::string("GET ") + target + " HTTP/1.1\r\n", 0) != 0 ||
            request.find('#') != std::string::npos ||
            request.find(std::string("\r\nHost: ") +
                         (no_content_return204 ? "healthz-return204.example" : "healthz.example") +
                         "\r\n") == std::string::npos ||
            request.find("\r\nConnection: close\r\n") == std::string::npos ||
            request.find("\r\nContent-Length:") != std::string::npos ||
            request.find("\r\nTransfer-Encoding:") != std::string::npos ||
            request.find("\r\nTE:") != std::string::npos ||
            request.find("\r\nExpect:") != std::string::npos ||
            request.find("\r\nUpgrade:") != std::string::npos || header_end == std::string::npos ||
            header_end + 4u != request.size() || request.rfind("\r\n\r\n") != header_end) {
            error = std::string(no_content_return204 ? "#328" : "#318") +
                    " oracle vector escaped the fresh bodyless GET domain: " + target;
            return false;
        }
    }

    observation = BoundedExactLocalPathOracleObservation{};
    observation.order = exact_first ? "exact-before-root" : "root-before-exact";
    observation.temp_path = temp.path;
    observation.config_path = temp.nginx_config;
    observation.log_path = temp.nginx_log;
    observation.access_path = no_content_return204 ? temp.nginx_access_log : temp.nginx_log;
    observation.process_identity = container_name;
    observation.wires.resize(5);
    const std::string issue = no_content_return204 ? "#328" : "#318";
    const std::string access_prefix =
        std::string("rut-nginx-") +
        (no_content_return204 ? "328-healthz-return204-" : "318-healthz-") + observation.order +
        "-" + std::to_string(getpid()) + "-scoped";
    const std::string exact_location =
        no_content_return204 ? "    location = /healthz { return 204; }\n"
                             : "    location = /healthz { return 200 \"successor-static\"; }\n";
    const std::string root_location =
        "    location / { proxy_pass http://127.0.0.1:" + std::to_string(backend_port) + "; }\n";
    const std::string config =
        "error_log stderr notice;\n"
        "events {}\n"
        "http {\n"
        "  log_format bounded_exact_local_path '" +
        access_prefix +
        (no_content_return204
             ? " raw=\"$request\" status=$status bytes=$bytes_sent host=\"$host\" "
               "upstream_addr=\"$upstream_addr\" upstream_status=$upstream_status';\n"
             : " $remote_addr - - [$time_local] \"$request\" $status $body_bytes_sent "
               "host=\"$host\"';\n") +
        "  access_log " + (no_content_return204 ? temp.nginx_access_log : "/dev/stderr") +
        " bounded_exact_local_path;\n"
        "  server {\n"
        "    listen " +
        std::to_string(frontend_port) + ";\n" +
        (exact_first ? exact_location + root_location : root_location + exact_location) +
        "  }\n"
        "}\n";
    if (!write_file(temp.nginx_config, config.data(), config.size())) {
        error = "failed to write " + issue + " bounded exact-local pinned nginx config";
        return false;
    }

    const auto recorder_live = [](const Recorder& recorder) {
        return recorder.running.load(std::memory_order_acquire) &&
               recorder.thread_alive.load(std::memory_order_acquire) &&
               !recorder.listener_failed.load(std::memory_order_acquire);
    };
    const auto wait_recorder_live = [&](Recorder& recorder, Child& nginx, const char* phase) {
        const auto deadline = std::chrono::steady_clock::now() + std::chrono::seconds(2);
        while (std::chrono::steady_clock::now() < deadline) {
            if (poll_child(nginx)) {
                error = std::string("pinned nginx exited before ") + issue + " " + phase +
                        " recorder readiness";
                return false;
            }
            if (recorder.listener_failed.load(std::memory_order_acquire) ||
                !recorder.running.load(std::memory_order_acquire)) {
                error = issue + " " + phase + " recorder failed before readiness";
                return false;
            }
            if (recorder.thread_alive.load(std::memory_order_acquire)) return true;
            usleep(1000);
        }
        error = issue + " " + phase + " recorder readiness timed out";
        return false;
    };
    const auto send_vector = [&](Child& nginx, size_t index, const char* expected) {
        const std::string request = make_request(kTargets[index]);
        struct ClientGuard {
            int fd = -1;
            ~ClientGuard() {
                if (fd >= 0) close(fd);
            }
        } client{connect_once(frontend_port)};
        std::vector<char> wire;
        std::string detail;
        if (client.fd < 0 || !send_all(client.fd, request.data(), request.size()) ||
            !(no_content_return204 && index < 2u ? read_head_response(client.fd, wire, detail)
                                                 : read_response(client.fd, wire, detail)) ||
            !read_eof(client.fd, detail)) {
            error = issue + " vector " + kTargets[index] + " response/EOF/zero-tail failed: " +
                    (detail.empty() ? "connect or send failed" : detail);
            return false;
        }
        if (!validate_exact_normalized_response(wire, expected, detail)) {
            error = issue + " vector " + kTargets[index] +
                    " exact status/reason/headers/body wire mismatch: " + detail;
            return false;
        }
        if (poll_child(nginx)) {
            error =
                std::string("pinned nginx exited after ") + issue + " vector " + kTargets[index];
            return false;
        }
        observation.wires[index] = std::move(wire);
        return true;
    };
    const auto observe_exact_count =
        [&](Recorder& recorder, Child& nginx, u32 expected, const char* phase) {
            const auto deadline = std::chrono::steady_clock::now() + std::chrono::milliseconds(500);
            while (std::chrono::steady_clock::now() < deadline) {
                if (poll_child(nginx) || !recorder_live(recorder)) {
                    error = issue + " pinned nginx or recorder failed during " + phase;
                    return false;
                }
                if (recorder.accepted.load(std::memory_order_acquire) != expected ||
                    recorder.requests.load(std::memory_order_acquire) != expected ||
                    recorder.response_send_all_calls.load(std::memory_order_acquire) != expected) {
                    error = issue + " unexpected upstream count during " + phase;
                    return false;
                }
                usleep(5000);
            }
            return true;
        };
    const auto wait_exact_count = [&](Recorder& recorder, Child& nginx, u32 expected) {
        const auto deadline = std::chrono::steady_clock::now() + std::chrono::seconds(2);
        while (std::chrono::steady_clock::now() < deadline) {
            if (poll_child(nginx) || !recorder_live(recorder)) {
                error = issue + " pinned nginx or forward recorder failed while waiting for count";
                return false;
            }
            const u32 accepts = recorder.accepted.load(std::memory_order_acquire);
            const u32 requests = recorder.requests.load(std::memory_order_acquire);
            const u32 sends = recorder.response_send_all_calls.load(std::memory_order_acquire);
            if (accepts > expected || requests > expected || sends > expected) {
                error = issue + " forward recorder exceeded its exact upstream count";
                return false;
            }
            if (accepts == expected && requests == expected && sends == expected) return true;
            usleep(1000);
        }
        error = "timed out waiting for " + issue + " exact forward upstream count";
        return false;
    };

    Recorder local_recorder;
    local_recorder.observe_extra_requests_until_stop = true;
    if (backend_reservation != nullptr && *backend_reservation >= 0) {
        close(*backend_reservation);
        *backend_reservation = -1;
    }
    if (!local_recorder.setup(backend_port)) {
        error = "failed to start " + issue + " local zero-upstream recorder";
        return false;
    }
    DockerGuard docker(container_name);
    ChildGuard nginx;
    std::vector<std::string> docker_args = {"docker",
                                            "run",
                                            "--pull=never",
                                            "--network",
                                            "host",
                                            "--name",
                                            container_name,
                                            "-v",
                                            temp.nginx_config + ":/etc/nginx/nginx.conf:ro"};
    if (no_content_return204) {
        docker_args.push_back("-v");
        docker_args.push_back(std::string(temp.path) + ":" + std::string(temp.path));
    }
    docker_args.insert(docker_args.end(), {kNginxImage, "nginx", "-g", "daemon off;"});
    if (frontend_reservation != nullptr && *frontend_reservation >= 0) {
        close(*frontend_reservation);
        *frontend_reservation = -1;
    }
    if (!spawn_child(docker_args, temp.nginx_log, nginx.child)) {
        error = "failed to start pinned nginx for " + issue + " oracle";
        return false;
    }
    if (!wait_ready(frontend_port, nginx.child, error) ||
        !wait_recorder_live(local_recorder, nginx.child, "local"))
        return false;

    for (size_t i = 0; i < 2; i++) {
        const char* expected_local = no_content_return204 ? kExactLocalReturn204ResponseNormalized
                                                          : kExactLocalCloseResponseNormalized;
        if (!kLocal[i] || !send_vector(nginx.child, i, expected_local)) return false;
        if (local_recorder.accepted.load(std::memory_order_acquire) != 0 ||
            local_recorder.requests.load(std::memory_order_acquire) != 0 ||
            local_recorder.response_send_all_calls.load(std::memory_order_acquire) != 0) {
            error = issue + " exact local vector unexpectedly reached upstream: " + kTargets[i];
            return false;
        }
    }
    if (!observe_exact_count(local_recorder, nginx.child, 0, "live local zero-upstream window"))
        return false;
    local_recorder.stop();
    observation.local_accepts = local_recorder.accepted.load(std::memory_order_acquire);
    observation.local_requests = local_recorder.requests.load(std::memory_order_acquire);
    observation.local_sends =
        local_recorder.response_send_all_calls.load(std::memory_order_acquire);
    observation.local_history = local_recorder.history;
    if (local_recorder.thread_alive.load(std::memory_order_acquire) ||
        local_recorder.listener_failed.load(std::memory_order_acquire) ||
        observation.local_accepts != 0 || observation.local_requests != 0 ||
        observation.local_sends != 0 ||
        local_recorder.response_send_succeeded.load(std::memory_order_acquire) ||
        !local_recorder.history.empty() || !local_recorder.request.empty()) {
        error = issue + " local recorder did not settle with zero upstream activity";
        return false;
    }

    Recorder forward_recorder;
    forward_recorder.observe_extra_requests_until_stop = true;
    if (!forward_recorder.setup(backend_port, 3, kBackendResponse, sizeof(kBackendResponse) - 1u) ||
        !wait_recorder_live(forward_recorder, nginx.child, "forward")) {
        if (error.empty()) error = "failed to start " + issue + " forward recorder";
        return false;
    }
    for (size_t i = 2; i < 5; i++) {
        if (kLocal[i] || !send_vector(nginx.child, i, kSuccessResponseNormalized) ||
            !wait_exact_count(forward_recorder, nginx.child, static_cast<u32>(i - 1u)))
            return false;
    }
    if (!observe_exact_count(forward_recorder, nginx.child, 3, "live no-fourth-forward window"))
        return false;

    if (!stop_child(nginx.child)) {
        error = "failed to stop pinned nginx after #318 oracle";
        return false;
    }
    if (!docker.remove()) {
        error = "docker rm -f failed after #318 oracle";
        return false;
    }
    forward_recorder.stop();
    observation.forward_accepts = forward_recorder.accepted.load(std::memory_order_acquire);
    observation.forward_requests = forward_recorder.requests.load(std::memory_order_acquire);
    observation.forward_sends =
        forward_recorder.response_send_all_calls.load(std::memory_order_acquire);
    observation.forward_history = forward_recorder.history;
    if (forward_recorder.thread_alive.load(std::memory_order_acquire) ||
        forward_recorder.listener_failed.load(std::memory_order_acquire) ||
        observation.forward_accepts != 3 || observation.forward_requests != 3 ||
        observation.forward_sends != 3 ||
        !forward_recorder.response_send_succeeded.load(std::memory_order_acquire) ||
        !forward_recorder.response_clean_shutdown.load(std::memory_order_acquire) ||
        !forward_recorder.response_connection_closed.load(std::memory_order_acquire) ||
        observation.forward_history.size() != 3) {
        error = "#318 forward recorder did not settle at exactly three upstream episodes";
        return false;
    }

    std::vector<std::vector<char>> expected_history;
    expected_history.reserve(3);
    for (size_t i = 2; i < 5; i++) {
        const std::string request = std::string("GET ") + kTargets[i] + " HTTP/1.1\r\n" +
                                    "Host: 127.0.0.1:" + std::to_string(backend_port) + "\r\n\r\n";
        expected_history.emplace_back(request.begin(), request.end());
    }
    if (observation.forward_history != expected_history) {
        error =
            "#318 root neighbors did not preserve exact method/request-target/headers/body "
            "histories";
        return false;
    }

    if (no_content_return204) {
        std::string error_log;
        if (!read_exact_return204_log(
                temp.nginx_log, "#328 bounded nginx error log", error_log, error) ||
            error_log.find("[warn]") != std::string::npos ||
            error_log.find("[error]") != std::string::npos ||
            error_log.find("[crit]") != std::string::npos ||
            error_log.find("[alert]") != std::string::npos ||
            error_log.find("[emerg]") != std::string::npos) {
            error = "#328 bounded nginx error log was not clean and bounded";
            return false;
        }
        return true;
    }

    bool logs_readable = true;
    for (size_t i = 0; i < 5; i++) {
        const std::string marker = std::string("\"GET ") + kTargets[i] + " HTTP/1.1\" 200 " +
                                   (i < 2 ? "16" : "2") + " host=\"healthz.example\"";
        logs_readable = logs_readable && log_count_line_with(temp.nginx_log,
                                                             marker.c_str(),
                                                             access_prefix.c_str(),
                                                             observation.access_records[i]);
    }
    u32 local_access = 0;
    u32 forward_access = 0;
    u32 total_access = 0;
    u32 connect_failures = 0;
    u32 upstream_failures = 0;
    const std::string upstream_context = "127.0.0.1:" + std::to_string(backend_port);
    logs_readable =
        logs_readable &&
        log_count_line_with(temp.nginx_log, "200 16 host=", access_prefix.c_str(), local_access) &&
        log_count_line_with(temp.nginx_log, "200 2 host=", access_prefix.c_str(), forward_access) &&
        log_count_line_with(
            temp.nginx_log, access_prefix.c_str(), access_prefix.c_str(), total_access) &&
        log_count_line_with(
            temp.nginx_log, "connect() failed", upstream_context.c_str(), connect_failures) &&
        log_count_line_with(
            temp.nginx_log, "upstream", upstream_context.c_str(), upstream_failures);
    if (!logs_readable || observation.access_records[0] != 1 ||
        observation.access_records[1] != 1 || observation.access_records[2] != 1 ||
        observation.access_records[3] != 1 || observation.access_records[4] != 1 ||
        local_access != 2 || forward_access != 3 || total_access != 5 || connect_failures != 0 ||
        upstream_failures != 0) {
        error =
            "#318 scoped access/error logs did not prove two local 200/16 records, three "
            "forward 200/2 records, five total records, and zero connect/upstream failures";
        return false;
    }
    return true;
}

static bool run_pinned_bounded_exact_local_path_oracle(
    u16 frontend_port,
    u16 backend_port,
    TempDir& temp,
    const std::string& container_prefix,
    BoundedExactLocalPathOracleObservation& exact_first,
    BoundedExactLocalPathOracleObservation& root_first,
    std::string& error) {
    if (!capture_pinned_bounded_exact_local_path_order(frontend_port,
                                                       backend_port,
                                                       temp,
                                                       container_prefix + "-exact-first",
                                                       true,
                                                       false,
                                                       exact_first,
                                                       error) ||
        !capture_pinned_bounded_exact_local_path_order(frontend_port,
                                                       backend_port,
                                                       temp,
                                                       container_prefix + "-root-first",
                                                       false,
                                                       false,
                                                       root_first,
                                                       error))
        return false;
    if (exact_first.wires.size() != 5 || root_first.wires.size() != 5) {
        error = "#318 oracle did not complete the exact five-vector matrix for both orders";
        return false;
    }
    for (size_t i = 0; i < 5; i++) {
        std::vector<char> exact_wire = exact_first.wires[i];
        std::vector<char> root_wire = root_first.wires[i];
        if (!normalize_date(exact_wire) || !normalize_date(root_wire) || exact_wire != root_wire) {
            error = "#318 location declaration order changed normalized vector " +
                    std::to_string(i + 1u);
            return false;
        }
    }
    if (exact_first.forward_history != root_first.forward_history) {
        error = "#318 location declaration order changed exact forward upstream history";
        return false;
    }
    return true;
}

static constexpr size_t kExactReturn204LogLimit = 8192u;

static bool bounded_log_reached_eof(
    size_t size, size_t limit, bool saw_eof, const char* label, std::string& error) {
    if (size > limit || !saw_eof) {
        error =
            std::string(label) + " reached its " + std::to_string(limit) + "-byte cap before EOF";
        return false;
    }
    return true;
}

static bool read_exact_return204_log(const std::string& path,
                                     const char* label,
                                     std::string& contents,
                                     std::string& error) {
    const int fd = open(path.c_str(), O_RDONLY | O_CLOEXEC);
    if (fd < 0) {
        error = std::string(label) + " was unreadable";
        return false;
    }
    contents.clear();
    bool saw_eof = false;
    char buffer[1024];
    for (;;) {
        if (contents.size() == kExactReturn204LogLimit) {
            char probe = 0;
            ssize_t n = 0;
            do {
                n = read(fd, &probe, 1u);
            } while (n < 0 && errno == EINTR);
            if (n == 0) saw_eof = true;
            if (n < 0) {
                close(fd);
                error = std::string(label) + " EOF probe failed";
                return false;
            }
            break;
        }
        const size_t want = std::min(sizeof(buffer), kExactReturn204LogLimit - contents.size());
        const ssize_t n = read(fd, buffer, want);
        if (n > 0) {
            contents.append(buffer, static_cast<size_t>(n));
            continue;
        }
        if (n < 0 && errno == EINTR) continue;
        if (n < 0) {
            close(fd);
            error = std::string(label) + " read failed";
            return false;
        }
        saw_eof = true;
        break;
    }
    close(fd);
    return bounded_log_reached_eof(contents.size(), kExactReturn204LogLimit, saw_eof, label, error);
}

static bool split_exact_complete_log(const std::string& contents,
                                     size_t expected_records,
                                     const char* label,
                                     std::vector<std::string>& records,
                                     std::string& error);
static bool parse_decimal_field(const std::string& field, size_t& value);

static bool parse_bounded_no_content_path_access_log(const std::string& contents,
                                                     const std::string& prefix,
                                                     u16 backend_port,
                                                     std::string& error) {
    static constexpr const char* kTargets[] = {
        "/healthz", "/healthz?x=1", "/healthz/", "/health", "/"};
    std::vector<std::string> records;
    if (!split_exact_complete_log(contents, 5u, "#328 bounded access log", records, error))
        return false;
    for (size_t i = 0; i < records.size(); i++) {
        const std::string& record = records[i];
        size_t cursor = 0;
        const auto take = [&](const std::string& literal) {
            if (record.compare(cursor, literal.size(), literal) != 0) return false;
            cursor += literal.size();
            return true;
        };
        const auto take_token = [&](const char* literal, std::string& token) {
            if (!take(literal)) return false;
            const size_t end = record.find(' ', cursor);
            if (end == std::string::npos || end == cursor) return false;
            token = record.substr(cursor, end - cursor);
            cursor = end;
            return true;
        };
        const std::string raw = std::string("GET ") + kTargets[i] + " HTTP/1.1";
        if (!take(prefix + " raw=\"" + raw + "\" status=")) {
            error = "#328 bounded access log raw target/order schema mismatch";
            return false;
        }
        std::string status;
        std::string bytes;
        if (!take_token("", status) || !take(" bytes=") || !take_token("", bytes)) {
            error = "#328 bounded access log status/size schema mismatch";
            return false;
        }
        const size_t expected_status = i < 2u ? 204u : 200u;
        const size_t expected_bytes = i < 2u ? 105u : 118u;
        size_t status_value = 0;
        size_t bytes_value = 0;
        if (!parse_decimal_field(status, status_value) ||
            !parse_decimal_field(bytes, bytes_value) || status_value != expected_status ||
            bytes_value != expected_bytes || status != std::to_string(expected_status) ||
            bytes != std::to_string(expected_bytes) ||
            !take(" host=\"healthz-return204.example\" upstream_addr=\"")) {
            error = "#328 bounded access log status/size/host fields were not exact";
            return false;
        }
        if (i < 2u) {
            if (!take("-\" upstream_status=-")) {
                error = "#328 bounded local access log did not prove zero upstream";
                return false;
            }
        } else {
            if (!take("127.0.0.1:")) {
                error = "#328 bounded fallback access log lost upstream address";
                return false;
            }
            const size_t port_end = record.find('"', cursor);
            if (port_end == std::string::npos || port_end == cursor) {
                error = "#328 bounded fallback access log has malformed upstream port";
                return false;
            }
            const std::string port = record.substr(cursor, port_end - cursor);
            size_t port_value = 0;
            if (!parse_decimal_field(port, port_value) || port_value > 65535u ||
                port_value != backend_port || port != std::to_string(backend_port) ||
                record.compare(
                    port_end, strlen("\" upstream_status=200"), "\" upstream_status=200") != 0) {
                error = "#328 bounded fallback access log upstream port/status was not exact";
                return false;
            }
            cursor = port_end + strlen("\" upstream_status=200");
        }
        if (cursor != record.size()) {
            error = "#328 bounded access log contained an unexpected tail";
            return false;
        }
    }
    return true;
}

static bool run_bounded_no_content_path_access_log_self_checks(std::string& error) {
    const std::string prefix = "rut-nginx-328-healthz-return204-exact-before-root-123-scoped";
    const char* targets[] = {"/healthz", "/healthz?x=1", "/healthz/", "/health", "/"};
    std::string valid;
    for (size_t i = 0; i < 5u; i++) {
        valid +=
            prefix + " raw=\"GET " + targets[i] + " HTTP/1.1\" status=" + (i < 2u ? "204" : "200") +
            " bytes=" + (i < 2u ? "105" : "118") +
            " host=\"healthz-return204.example\" upstream_addr=\"" +
            (i < 2u ? "-\" upstream_status=-" : "127.0.0.1:54321\" upstream_status=200") + "\n";
    }
    const auto rejects = [&](const std::string& value) {
        std::string detail;
        return !parse_bounded_no_content_path_access_log(value, prefix, 54321, detail);
    };
    const auto replace_once =
        [](std::string value, const std::string& from, const std::string& to) {
            const size_t offset = value.find(from);
            if (offset == std::string::npos) return std::string{};
            value.replace(offset, from.size(), to);
            return value;
        };
    const std::string overflow =
        replace_once(valid, "status=204", "status=999999999999999999999999999999999");
    const std::string wrong_target =
        replace_once(valid, "GET /healthz/ HTTP/1.1", "GET /healthz HTTP/1.1");
    const std::string wrong_size = replace_once(valid, "bytes=118", "bytes=119");
    const std::string wrong_status = replace_once(valid, "status=200", "status=204");
    const std::string wrong_port = replace_once(valid, "127.0.0.1:54321", "127.0.0.1:65536");
    std::string swapped = valid;
    const size_t first_end = swapped.find('\n');
    const size_t second_end = swapped.find('\n', first_end + 1u);
    swapped.replace(
        0,
        second_end + 1u,
        valid.substr(first_end + 1u, second_end - first_end) + valid.substr(0, first_end + 1u));
    if (!parse_bounded_no_content_path_access_log(valid, prefix, 54321, error)) return false;
    const std::pair<const char*, bool> mutations[] = {
        {"extra", rejects(valid + valid.substr(0, first_end + 1u))},
        {"truncated", rejects(valid.substr(0, valid.size() - 1u))},
        {"order", rejects(swapped)},
        {"raw-target", rejects(wrong_target)},
        {"size", rejects(wrong_size)},
        {"status", rejects(wrong_status)},
        {"overflow", rejects(overflow)},
        {"port", rejects(wrong_port)}};
    for (const auto& mutation : mutations) {
        if (!mutation.second) {
            error = std::string("#328 access-log mutation accepted: ") + mutation.first;
            return false;
        }
    }
    return true;
}

static bool run_bounded_no_content_path_wire_self_checks(std::string& error) {
    static constexpr char kValid[] =
        "HTTP/1.1 204 No Content\r\n"
        "Server: nginx/1.29.7\r\n"
        "Date: Wed, 26 Aug 2026 23:57:18 GMT\r\n"
        "Connection: close\r\n\r\n";
    const std::vector<char> valid(kValid, kValid + sizeof(kValid) - 1u);
    const auto rejects = [&](const std::vector<char>& wire) {
        std::string detail;
        return !validate_exact_normalized_response(
            wire, kExactLocalReturn204ResponseNormalized, detail);
    };
    std::vector<char> tail = valid;
    tail.push_back('x');
    std::vector<char> missing_eof = valid;
    missing_eof.resize(missing_eof.size() - 2u);
    std::vector<char> wrong_header = valid;
    const std::string header(wrong_header.begin(), wrong_header.end());
    const size_t connection = header.find("Connection: close");
    if (connection == std::string::npos) {
        error = "#328 wire self-check fixture lost Connection header";
        return false;
    }
    wrong_header[connection] = 'X';
    std::vector<char> body = valid;
    body.push_back('b');
    if (!validate_exact_normalized_response(valid, kExactLocalReturn204ResponseNormalized, error) ||
        !rejects(tail) || !rejects(missing_eof) || !rejects(wrong_header) || !rejects(body)) {
        error = "#328 wire tail/EOF/header/body mutation self-check failed";
        return false;
    }
    return true;
}

static bool validate_bounded_no_content_path_observation(
    const BoundedExactLocalPathOracleObservation& observation,
    u16 backend_port,
    std::string& error) {
    if (observation.wires.size() != 5u || observation.local_accepts != 0u ||
        observation.local_requests != 0u || observation.local_sends != 0u ||
        !observation.local_history.empty()) {
        error = "#328 observation lacked exact five-vector or zero local-upstream evidence";
        return false;
    }
    if (observation.forward_accepts != 3u || observation.forward_requests != 3u ||
        observation.forward_sends != 3u || observation.forward_history.size() != 3u) {
        error = "#328 observation lacked exact three-episode fallback evidence";
        return false;
    }
    for (u32 access_record : observation.access_records) {
        if (access_record != 1u) {
            error = "#328 observation lacked exact five-record access evidence";
            return false;
        }
    }

    const std::vector<char> expected_local(kExactLocalReturn204ResponseNormalized,
                                           kExactLocalReturn204ResponseNormalized + 105u);
    const std::vector<char> expected_fallback(
        kSuccessResponseNormalized,
        kSuccessResponseNormalized + sizeof(kSuccessResponseNormalized) - 1u);
    for (size_t i = 0; i < observation.wires.size(); i++) {
        std::vector<char> normalized = observation.wires[i];
        if (!normalize_date(normalized) ||
            normalized != (i < 2u ? expected_local : expected_fallback)) {
            error = "#328 observation response wire was not the exact 204/fallback baseline";
            return false;
        }
    }

    static constexpr const char* kFallbackTargets[] = {"/healthz/", "/health", "/"};
    std::vector<std::vector<char>> expected_history;
    expected_history.reserve(3u);
    for (const char* target : kFallbackTargets) {
        const std::string request = std::string("GET ") + target + " HTTP/1.1\r\n" +
                                    "Host: 127.0.0.1:" + std::to_string(backend_port) + "\r\n\r\n";
        expected_history.emplace_back(request.begin(), request.end());
    }
    if (observation.forward_history != expected_history) {
        error = "#328 observation fallback history contained a retry, reorder, or wire mismatch";
        return false;
    }
    return true;
}

static bool run_bounded_no_content_path_observation_self_checks(std::string& error) {
    static constexpr u16 kBackendPort = 54321u;
    static constexpr char kObservedDate[] = "Wed, 26 Aug 2026 23:57:18 GMT";
    const auto observed_wire = [](const char* normalized, size_t size) {
        std::vector<char> wire(normalized, normalized + size);
        const std::string marker(29u, 'X');
        const auto offset = std::search(wire.begin(), wire.end(), marker.begin(), marker.end());
        if (offset != wire.end()) std::copy_n(kObservedDate, 29u, offset);
        return wire;
    };
    BoundedExactLocalPathOracleObservation valid;
    valid.order = "exact-before-root";
    valid.wires = {
        observed_wire(kExactLocalReturn204ResponseNormalized, 105u),
        observed_wire(kExactLocalReturn204ResponseNormalized, 105u),
        observed_wire(kSuccessResponseNormalized, sizeof(kSuccessResponseNormalized) - 1u),
        observed_wire(kSuccessResponseNormalized, sizeof(kSuccessResponseNormalized) - 1u),
        observed_wire(kSuccessResponseNormalized, sizeof(kSuccessResponseNormalized) - 1u)};
    valid.forward_accepts = 3u;
    valid.forward_requests = 3u;
    valid.forward_sends = 3u;
    for (u32& access_record : valid.access_records) access_record = 1u;
    for (const char* target : {"/healthz/", "/health", "/"}) {
        const std::string request = std::string("GET ") + target + " HTTP/1.1\r\n" +
                                    "Host: 127.0.0.1:" + std::to_string(kBackendPort) + "\r\n\r\n";
        valid.forward_history.emplace_back(request.begin(), request.end());
    }
    if (!validate_bounded_no_content_path_observation(valid, kBackendPort, error)) return false;

    const auto require_rejection = [&](const char* name,
                                       const BoundedExactLocalPathOracleObservation& mutated) {
        std::string detail;
        if (!validate_bounded_no_content_path_observation(mutated, kBackendPort, detail))
            return true;
        error = std::string("#328 observation mutation accepted: ") + name;
        return false;
    };
    const std::vector<char> retry = valid.forward_history.front();
    BoundedExactLocalPathOracleObservation mutated = valid;
    mutated.local_accepts = 1u;
    if (!require_rejection("local-accept", mutated)) return false;
    mutated = valid;
    mutated.local_requests = 1u;
    if (!require_rejection("local-request", mutated)) return false;
    mutated = valid;
    mutated.local_sends = 1u;
    if (!require_rejection("local-send", mutated)) return false;
    mutated = valid;
    mutated.local_history.push_back(retry);
    if (!require_rejection("local-history", mutated)) return false;
    mutated = valid;
    mutated.forward_accepts = 4u;
    if (!require_rejection("fallback-accept", mutated)) return false;
    mutated = valid;
    mutated.forward_requests = 4u;
    if (!require_rejection("fallback-request", mutated)) return false;
    mutated = valid;
    mutated.forward_sends = 4u;
    if (!require_rejection("fallback-send", mutated)) return false;
    mutated = valid;
    mutated.forward_history.push_back(retry);
    if (!require_rejection("fourth-forward", mutated)) return false;
    mutated = valid;
    mutated.forward_history[1] = retry;
    if (!require_rejection("fallback-retry", mutated)) return false;
    return true;
}

static bool run_pinned_bounded_no_content_path_oracle(
    const std::string& container_prefix,
    BoundedExactLocalPathOracleObservation& exact_first,
    BoundedExactLocalPathOracleObservation& root_first,
    std::string& error) {
    struct ReservedPorts {
        int fds[4];

        ReservedPorts() { std::fill(std::begin(fds), std::end(fds), -1); }
        ~ReservedPorts() {
            for (int fd : fds)
                if (fd >= 0) close(fd);
        }

        bool reserve(size_t index, u16& port) {
            const int fd = socket(AF_INET, SOCK_STREAM | SOCK_CLOEXEC, 0);
            if (fd < 0) return false;
            sockaddr_in addr{};
            addr.sin_family = AF_INET;
            addr.sin_addr.s_addr = htonl(INADDR_LOOPBACK);
            addr.sin_port = 0;
            socklen_t len = sizeof(addr);
            if (bind(fd, reinterpret_cast<sockaddr*>(&addr), sizeof(addr)) != 0 ||
                getsockname(fd, reinterpret_cast<sockaddr*>(&addr), &len) != 0 ||
                ntohs(addr.sin_port) == 0u) {
                close(fd);
                return false;
            }
            fds[index] = fd;
            port = ntohs(addr.sin_port);
            return true;
        }
    } reservations;
    u16 ports[4]{};
    for (size_t i = 0u; i < 4u; i++) {
        if (!reservations.reserve(i, ports[i])) {
            error = "#328 could not bind-reserve four frontend/backend ports";
            return false;
        }
    }
    for (size_t i = 0u; i < 4u; i++) {
        if (reservations.fds[i] < 0 || ports[i] == 0u) {
            error = "#328 did not hold four nonzero frontend/backend ports";
            return false;
        }
        for (size_t j = i + 1u; j < 4u; j++) {
            if (ports[i] == ports[j]) {
                error = "#328 did not hold four distinct frontend/backend ports";
                return false;
            }
        }
    }
    TempDir exact_temp;
    TempDir root_temp;
    if (!exact_temp.create() || !root_temp.create() ||
        strcmp(exact_temp.path, root_temp.path) == 0 ||
        exact_temp.nginx_config == root_temp.nginx_config ||
        exact_temp.nginx_log == root_temp.nginx_log ||
        exact_temp.nginx_access_log == root_temp.nginx_access_log) {
        error = "#328 declaration orders did not receive independent temp/config/log trees";
        return false;
    }
    if (!capture_pinned_bounded_exact_local_path_order(ports[0],
                                                       ports[1],
                                                       exact_temp,
                                                       container_prefix + "-exact-first",
                                                       true,
                                                       true,
                                                       exact_first,
                                                       error,
                                                       &reservations.fds[0],
                                                       &reservations.fds[1]) ||
        !capture_pinned_bounded_exact_local_path_order(ports[2],
                                                       ports[3],
                                                       root_temp,
                                                       container_prefix + "-root-first",
                                                       false,
                                                       true,
                                                       root_first,
                                                       error,
                                                       &reservations.fds[2],
                                                       &reservations.fds[3])) {
        dump_log(exact_temp.nginx_config, "#328 exact-first nginx config");
        dump_log(exact_temp.nginx_log, "#328 exact-first nginx error log");
        dump_log(exact_temp.nginx_access_log, "#328 exact-first nginx access log");
        dump_log(root_temp.nginx_config, "#328 root-first nginx config");
        dump_log(root_temp.nginx_log, "#328 root-first nginx error log");
        dump_log(root_temp.nginx_access_log, "#328 root-first nginx access log");
        return false;
    }
    for (int fd : reservations.fds) {
        if (fd >= 0) {
            error = "#328 pinned oracle did not consume every frontend/backend reservation";
            return false;
        }
    }
    std::string exact_access;
    std::string root_access;
    if (!read_exact_return204_log(
            exact_temp.nginx_access_log, "#328 exact-first access log", exact_access, error) ||
        !read_exact_return204_log(
            root_temp.nginx_access_log, "#328 root-first access log", root_access, error) ||
        !parse_bounded_no_content_path_access_log(
            exact_access,
            "rut-nginx-328-healthz-return204-exact-before-root-" + std::to_string(getpid()) +
                "-scoped",
            ports[1],
            error) ||
        !parse_bounded_no_content_path_access_log(
            root_access,
            "rut-nginx-328-healthz-return204-root-before-exact-" + std::to_string(getpid()) +
                "-scoped",
            ports[3],
            error))
        return false;
    for (size_t i = 0; i < 5u; i++) {
        exact_first.access_records[i] = 1;
        root_first.access_records[i] = 1;
    }

    for (const BoundedExactLocalPathOracleObservation* observation : {&exact_first, &root_first}) {
        if (!validate_bounded_no_content_path_observation(
                *observation, observation == &exact_first ? ports[1] : ports[3], error))
            return false;
    }
    const auto canonical_history = [](const std::vector<std::vector<char>>& history) {
        std::vector<std::vector<char>> result = history;
        for (std::vector<char>& request : result) {
            std::string text(request.begin(), request.end());
            const std::string marker = "\r\nHost: 127.0.0.1:";
            const size_t begin = text.find(marker);
            if (begin == std::string::npos) return std::vector<std::vector<char>>{};
            const size_t digits = begin + marker.size();
            const size_t end = text.find("\r\n", digits);
            if (end == std::string::npos || end == digits) return std::vector<std::vector<char>>{};
            for (size_t i = digits; i < end; i++)
                if (text[i] < '0' || text[i] > '9') return std::vector<std::vector<char>>{};
            text.replace(digits, end - digits, "BACKEND");
            request.assign(text.begin(), text.end());
        }
        return result;
    };
    if (exact_first.forward_history != root_first.forward_history) {
        const auto exact = canonical_history(exact_first.forward_history);
        const auto root = canonical_history(root_first.forward_history);
        if (exact.size() != 3u || exact != root) {
            error =
                "#328 declaration order changed fallback upstream history after port normalization";
            return false;
        }
    }
    for (size_t i = 0; i < 5u; i++) {
        std::vector<char> left = exact_first.wires[i];
        std::vector<char> right = root_first.wires[i];
        if (!normalize_date(left) || !normalize_date(right) || left != right) {
            error = "#328 declaration order changed a Date-normalized response vector";
            return false;
        }
    }
    return true;
}

static bool split_exact_complete_log(const std::string& contents,
                                     size_t expected_records,
                                     const char* label,
                                     std::vector<std::string>& records,
                                     std::string& error) {
    records.clear();
    if (contents.empty() || contents.back() != '\n') {
        error = std::string(label) + " was empty or ended with an incomplete record";
        return false;
    }
    for (size_t start = 0; start < contents.size();) {
        const size_t end = contents.find('\n', start);
        if (end == std::string::npos) {
            error = std::string(label) + " ended with an incomplete record";
            return false;
        }
        if (end == start) {
            error = std::string(label) + " contained a blank record";
            return false;
        }
        records.emplace_back(contents.substr(start, end - start));
        if (records.size() > expected_records) {
            error = std::string(label) + " contained an extra record";
            return false;
        }
        start = end + 1u;
    }
    if (records.size() != expected_records) {
        error = std::string(label) + " did not contain exactly " +
                std::to_string(expected_records) + " complete records";
        return false;
    }
    return true;
}

static bool parse_decimal_field(const std::string& field, size_t& value) {
    if (field.empty()) return false;
    value = 0;
    for (const char byte : field) {
        if (byte < '0' || byte > '9') return false;
        const size_t digit = static_cast<size_t>(byte - '0');
        if (value > (SIZE_MAX - digit) / 10u) return false;
        value = value * 10u + digit;
    }
    return true;
}

static bool decimal_field_equals(const std::string& field, size_t expected) {
    size_t value = 0;
    return parse_decimal_field(field, value) && value == expected;
}

static bool exact_log_duration(const std::string& field) {
    if (field.size() <= 2u || field.compare(field.size() - 2u, 2u, "us") != 0) return false;
    size_t value = 0;
    return parse_decimal_field(field.substr(0, field.size() - 2u), value);
}

static bool exact_log_timestamp(const std::string& field) {
    if (field.size() != 24u || field[4] != '-' || field[7] != '-' || field[10] != 'T' ||
        field[13] != ':' || field[16] != ':' || field[19] != '.' || field[23] != 'Z')
        return false;
    for (size_t i = 0; i < field.size(); i++) {
        if (i == 4u || i == 7u || i == 10u || i == 13u || i == 16u || i == 19u || i == 23u)
            continue;
        if (field[i] < '0' || field[i] > '9') return false;
    }
    return true;
}

static bool split_space_fields(const std::string& record, std::vector<std::string>& fields) {
    fields.clear();
    if (record.empty() || record.front() == ' ' || record.back() == ' ' ||
        record.find("  ") != std::string::npos)
        return false;
    for (size_t start = 0; start < record.size();) {
        size_t end = record.find(' ', start);
        if (end == std::string::npos) end = record.size();
        fields.emplace_back(record.substr(start, end - start));
        start = end + 1u;
    }
    return true;
}

static bool parse_exact_return204_access_log(const std::string& contents,
                                             size_t local_request_size,
                                             size_t fallback_request_size,
                                             size_t fallback_response_size,
                                             std::string& error,
                                             bool query_target = false) {
    std::vector<std::string> records;
    if (!split_exact_complete_log(
            contents, 2u, "converter-generated #324 access log", records, error))
        return false;
    std::vector<std::string> local;
    std::vector<std::string> fallback;
    const char* local_target = query_target ? "/static?x=1" : "/static";
    if (!split_space_fields(records[0], local) || local.size() != 9u ||
        !exact_log_timestamp(local[0]) || local[1] != "GET" || local[2] != local_target ||
        !decimal_field_equals(local[3], 204u) || !exact_log_duration(local[4]) ||
        !decimal_field_equals(local[5], local_request_size) ||
        !decimal_field_equals(local[6], 105u) || local[7] != "127.0.0.1" || local[8] != "s=0") {
        error = "converter-generated #324 local access record was not the exact 9-field shape";
        return false;
    }
    if (!split_space_fields(records[1], fallback) || fallback.size() != 11u ||
        !exact_log_timestamp(fallback[0]) || fallback[1] != "GET" ||
        fallback[2] != "/fallback?q=1" || !decimal_field_equals(fallback[3], 200u) ||
        !exact_log_duration(fallback[4]) ||
        !decimal_field_equals(fallback[5], fallback_request_size) ||
        !decimal_field_equals(fallback[6], fallback_response_size) || fallback[7] != "127.0.0.1" ||
        fallback[8] != "nginx_upstream" || !exact_log_duration(fallback[9]) ||
        fallback[10] != "s=0") {
        error = "converter-generated #324 fallback access record was not the exact 11-field shape";
        return false;
    }
    return true;
}

static bool parse_exact_return204_runtime_log(const std::string& contents,
                                              const std::string& source_path,
                                              const std::string& listener_line,
                                              std::string& error) {
    std::vector<std::string> records;
    if (!split_exact_complete_log(
            contents, 5u, "converter-generated #324 runtime log", records, error))
        return false;
    const std::string loaded = "Loaded program: " + source_path + " (opt O2)";
    if (records[0] != loaded || records[1] != "Backend: io_uring" || records[2] != listener_line ||
        records[3] != "Draining connections (0s)..." || records[4] != "Shutdown complete.") {
        error = "converter-generated #324 runtime log was not the exact five-line clean lifecycle";
        return false;
    }
    return true;
}

static bool run_exact_return204_log_parser_self_checks(std::string& error) {
    static constexpr char kLocal[] =
        "2026-08-26T21:13:05.248Z GET /static 204 361us 68 105 127.0.0.1 s=0\n";
    static constexpr char kFallback[] =
        "2026-08-26T21:13:05.907Z GET /fallback?q=1 200 1577us 77 118 127.0.0.1 "
        "nginx_upstream 243us s=0\n";
    const std::string valid_access = std::string(kLocal) + kFallback;
    const auto rejects_access = [&](const std::string& value) {
        std::string detail;
        return !parse_exact_return204_access_log(value, 68u, 77u, 118u, detail);
    };
    std::string overflow_access = kLocal;
    const size_t local_size = overflow_access.find(" 68 105 ");
    if (local_size == std::string::npos) {
        error = "#324 access-log self-check fixture lost its positional size fields";
        return false;
    }
    overflow_access.replace(local_size + 1u, 2u, "999999999999999999999999999999999");
    if (!parse_exact_return204_access_log(valid_access, 68u, 77u, 118u, error) ||
        !rejects_access(valid_access + kLocal) ||
        !rejects_access(std::string(kLocal) + "\n" + kFallback) ||
        !rejects_access(valid_access + "\n") ||
        !rejects_access(std::string(kLocal).substr(0, sizeof(kLocal) - 2u) + " extra\n" +
                        kFallback) ||
        !rejects_access(std::string(kFallback) + kLocal) ||
        !rejects_access(valid_access.substr(0, valid_access.size() - 1u)) ||
        !rejects_access(overflow_access + kFallback)) {
        error = "#324 access-log parser mutation self-check failed";
        return false;
    }

    const std::string source = "/tmp/exact-324/generated.rut";
    const std::string listener = "Listening on port 54321 with 1 shard(s)";
    const std::string valid_runtime = "Loaded program: " + source +
                                      " (opt O2)\nBackend: io_uring\n" + listener +
                                      "\nDraining connections (0s)...\nShutdown complete.\n";
    const auto rejects_runtime = [&](const std::string& value) {
        std::string detail;
        return !parse_exact_return204_runtime_log(value, source, listener, detail);
    };
    std::string prefixed = valid_runtime;
    prefixed.insert(0, "prefix-");
    std::string suffixed = valid_runtime;
    const size_t loaded_end = suffixed.find('\n');
    suffixed.insert(loaded_end, "-suffix");
    std::string completion_error;
    if (!parse_exact_return204_runtime_log(valid_runtime, source, listener, error) ||
        !rejects_runtime(prefixed) || !rejects_runtime(suffixed) ||
        !rejects_runtime(valid_runtime + "WARN unexpected\n") ||
        !rejects_runtime(valid_runtime + "\n") ||
        bounded_log_reached_eof(kExactReturn204LogLimit,
                                kExactReturn204LogLimit,
                                false,
                                "#324 self-check log",
                                completion_error) ||
        !bounded_log_reached_eof(kExactReturn204LogLimit,
                                 kExactReturn204LogLimit,
                                 true,
                                 "#324 self-check log",
                                 completion_error)) {
        error = "#324 runtime/bounded-log parser mutation self-check failed";
        return false;
    }
    return true;
}

static bool run_converter_exact_return204_query_access_log_self_checks(std::string& error) {
    static constexpr char kLocal[] =
        "2026-08-26T21:13:05.248Z GET /static?x=1 204 361us 77 105 127.0.0.1 s=0\n";
    static constexpr char kFallback[] =
        "2026-08-26T21:13:05.907Z GET /fallback?q=1 200 1577us 86 118 127.0.0.1 "
        "nginx_upstream 243us s=0\n";
    const std::string valid = std::string(kLocal) + kFallback;
    const auto rejects = [&](const std::string& value) {
        std::string detail;
        return !parse_exact_return204_access_log(value, 77u, 86u, 118u, detail, true);
    };
    std::string overflow = kLocal;
    const size_t size_offset = overflow.find(" 77 105 ");
    if (size_offset == std::string::npos) {
        error = "#325 query converter access-log fixture lost request-size field";
        return false;
    }
    overflow.replace(size_offset + 1u, 2u, "999999999999999999999999999999999");
    std::string wrong_target = valid;
    const size_t target_offset = wrong_target.find("/static?x=1");
    if (target_offset == std::string::npos) {
        error = "#325 query converter access-log fixture lost target field";
        return false;
    }
    wrong_target.replace(target_offset, strlen("/static?x=1"), "/static");
    if (!parse_exact_return204_access_log(valid, 77u, 86u, 118u, error, true) ||
        !rejects(valid + kLocal) || !rejects(kFallback + std::string(kLocal)) ||
        !rejects(valid.substr(0, valid.size() - 1u)) || !rejects(wrong_target) ||
        !rejects(overflow + kFallback)) {
        error = "#325 converter query access-log parser mutation self-check failed";
        return false;
    }
    return true;
}

static bool generated_exact_return204_source_is_query_free(const std::string& source) {
    return source.find("?x=1") == std::string::npos &&
           source.find("query-return204.example") == std::string::npos;
}

static bool generated_exact_return204_source_has_normalized_static_selector(
    const std::string& source) {
    const std::string normalized = "route exact slash_normalized GET \"/static\"";
    const size_t offset = source.find(normalized);
    return offset != std::string::npos &&
           source.find(normalized, offset + normalized.size()) == std::string::npos &&
           source.find("route exact GET \"/static\"") == std::string::npos;
}

static bool run_converter_exact_return204_source_validation_self_checks(std::string& error) {
    static constexpr char kCanonical[] =
        "listen :54321\n"
        "route exact slash_normalized GET \"/static\" { return local_response({ status: 204 }) }\n"
        "route GET \"/\" { return forward(nginx_upstream) }\n";
    const std::string query_route =
        std::string(kCanonical) + "route exact GET \"/static?x=1\" { return response() }\n";
    const std::string host_predicate =
        std::string(kCanonical) + "if host == \"query-return204.example\" { return response() }\n";
    const std::string raw_selector =
        std::string(kCanonical) + "route exact GET \"/static\" { return response() }\n";
    if (!generated_exact_return204_source_is_query_free(kCanonical) ||
        !generated_exact_return204_source_has_normalized_static_selector(kCanonical) ||
        generated_exact_return204_source_is_query_free(query_route) ||
        generated_exact_return204_source_is_query_free(host_predicate) ||
        generated_exact_return204_source_has_normalized_static_selector(raw_selector)) {
        error = "#325 generated source query/selector/host mutation was not rejected";
        return false;
    }
    return true;
}

struct ExactLocalReturn204OracleObservation {
    std::string order;
    std::string temp_path;
    std::string config_path;
    std::string log_path;
    std::string container_name;
    std::string access_prefix;
    std::vector<char> local_wire;
    std::vector<char> fallback_wire;
    std::vector<std::vector<char>> fallback_history;
    u32 local_accepts = 0;
    u32 local_requests = 0;
    u32 local_sends = 0;
    u32 fallback_accepts = 0;
    u32 fallback_requests = 0;
    u32 fallback_sends = 0;
    u32 local_access = 0;
    u32 fallback_access = 0;
};

static void dump_exact_local_return204_oracle_observation(
    const ExactLocalReturn204OracleObservation& observation) {
    std::cerr << "#324 exact-local-return204 order=" << observation.order
              << " temp=" << observation.temp_path << " config=" << observation.config_path
              << " log=" << observation.log_path << " container=" << observation.container_name
              << " access=" << observation.local_access << "/" << observation.fallback_access
              << " upstream=" << observation.local_accepts << "/" << observation.local_requests
              << "/" << observation.local_sends << "+" << observation.fallback_accepts << "/"
              << observation.fallback_requests << "/" << observation.fallback_sends << "\n";
    dump_wire("#324 GET /static return 204 oracle", observation.local_wire);
    dump_wire("#324 GET /fallback?q=1 client response", observation.fallback_wire);
    for (size_t i = 0; i < observation.fallback_history.size(); i++) {
        const std::string label = "#324 fallback upstream " + std::to_string(i + 1u);
        dump_wire(label.c_str(), observation.fallback_history[i]);
    }
}

static bool capture_pinned_exact_local_return204_order(
    u16 frontend_port,
    u16 backend_port,
    TempDir& temp,
    const std::string& container_name,
    bool exact_first,
    bool query_target,
    ExactLocalReturn204OracleObservation& observation,
    std::string& error) {
    static constexpr char kLocalRequest[] =
        "GET /static HTTP/1.1\r\n"
        "Host: return204.example\r\n"
        "Connection: close\r\n\r\n";
    static constexpr char kQueryLocalRequest[] =
        "GET /static?x=1 HTTP/1.1\r\n"
        "Host: query-return204.example\r\n"
        "Connection: close\r\n\r\n";
    static constexpr char kFallbackRequest[] =
        "GET /fallback?q=1 HTTP/1.1\r\n"
        "Host: return204.example\r\n"
        "X-324-Vector: fallback\r\n"
        "Connection: close\r\n\r\n";
    static constexpr char kQueryFallbackRequest[] =
        "GET /fallback?q=1 HTTP/1.1\r\n"
        "Host: query-return204.example\r\n"
        "X-324-Vector: fallback\r\n"
        "Connection: close\r\n\r\n";
    const char* local_request = query_target ? kQueryLocalRequest : kLocalRequest;
    const char* fallback_request = query_target ? kQueryFallbackRequest : kFallbackRequest;
    const char* request_host = query_target ? "query-return204.example" : "return204.example";
    for (const char* request : {local_request, fallback_request}) {
        const std::string text(request);
        const size_t headers_end = text.find("\r\n\r\n");
        if (text.rfind("GET /", 0) != 0 || text.find(" HTTP/1.1\r\n") == std::string::npos ||
            text.find("\r\nConnection: close\r\n") == std::string::npos ||
            text.find("\r\nContent-Length:") != std::string::npos ||
            text.find("\r\nTransfer-Encoding:") != std::string::npos ||
            text.find("\r\nTE:") != std::string::npos ||
            text.find("\r\nExpect:") != std::string::npos ||
            text.find("\r\nUpgrade:") != std::string::npos || headers_end == std::string::npos ||
            headers_end + 4u != text.size()) {
            error =
                "#324 oracle request escaped the fresh bodyless origin-form explicit-close "
                "H1.1 GET domain";
            return false;
        }
    }

    observation = ExactLocalReturn204OracleObservation{};
    observation.order = exact_first ? "exact-before-root" : "root-before-exact";
    observation.temp_path = temp.path;
    observation.config_path = temp.nginx_config;
    observation.log_path = temp.nginx_log;
    observation.container_name = container_name;
    const std::string access_prefix = "rut-nginx-" + std::string(query_target ? "325" : "324") +
                                      "-return204-" + observation.order + "-" +
                                      std::to_string(getpid()) + "-scoped";
    observation.access_prefix = access_prefix;
    const std::string exact_location = "    location = /static { return 204; }\n";
    const std::string root_location =
        "    location / { proxy_pass http://127.0.0.1:" + std::to_string(backend_port) + "; }\n";
    const std::string config =
        "error_log stderr notice;\n"
        "events {}\n"
        "http {\n"
        "  log_format exact_local_return204 '" +
        access_prefix + " raw=\"$request\" status=$status bytes=$bytes_sent host=\"$host\"" +
        (query_target ? " upstream_addr=\"$upstream_addr\" upstream_status=$upstream_status" : "") +
        "';\n"
        "  access_log " +
        (query_target ? temp.nginx_access_log : "/dev/stderr") +
        " exact_local_return204;\n"
        "  server {\n"
        "    listen " +
        std::to_string(frontend_port) + ";\n" +
        (exact_first ? exact_location + root_location : root_location + exact_location) +
        "  }\n"
        "}\n";
    const size_t return204 = config.find("return 204;");
    if (config.find("location = /static { return 204; }") == std::string::npos ||
        return204 == std::string::npos ||
        config.find("return 204;", return204 + sizeof("return 204;") - 1u) != std::string::npos ||
        config.find("proxy_set_header") != std::string::npos ||
        !write_file(temp.nginx_config, config.data(), config.size())) {
        error = "#324 failed to preserve/write one literal return 204 nginx config";
        return false;
    }

    const auto recorder_live = [](const Recorder& recorder) {
        return recorder.running.load(std::memory_order_acquire) &&
               recorder.thread_alive.load(std::memory_order_acquire) &&
               !recorder.listener_failed.load(std::memory_order_acquire);
    };
    const auto wait_recorder_live = [&](Recorder& recorder, Child& nginx, const char* phase) {
        const auto deadline = std::chrono::steady_clock::now() + std::chrono::seconds(2);
        while (std::chrono::steady_clock::now() < deadline) {
            if (poll_child(nginx)) {
                error =
                    std::string("#324 pinned nginx exited before ") + phase + " recorder readiness";
                return false;
            }
            if (recorder.listener_failed.load(std::memory_order_acquire) ||
                !recorder.running.load(std::memory_order_acquire)) {
                error = std::string("#324 ") + phase + " recorder failed before readiness";
                return false;
            }
            if (recorder.thread_alive.load(std::memory_order_acquire)) return true;
            usleep(1000);
        }
        error = std::string("#324 ") + phase + " recorder readiness timed out";
        return false;
    };
    const auto observe_count = [&](Recorder& recorder,
                                   Child& nginx,
                                   u32 expected,
                                   const char* phase,
                                   std::chrono::milliseconds duration) {
        const auto deadline = std::chrono::steady_clock::now() + duration;
        for (;;) {
            if (poll_child(nginx) || !recorder_live(recorder)) {
                error = std::string("#324 pinned nginx or recorder failed during ") + phase;
                return false;
            }
            if (recorder.accepted.load(std::memory_order_acquire) != expected ||
                recorder.requests.load(std::memory_order_acquire) != expected ||
                recorder.response_send_all_calls.load(std::memory_order_acquire) != expected) {
                error = std::string("#324 unexpected upstream count during ") + phase;
                return false;
            }
            if (std::chrono::steady_clock::now() >= deadline) return true;
            usleep(5000);
        }
    };
    const auto wait_count = [&](Recorder& recorder, Child& nginx, u32 expected) {
        const auto deadline = std::chrono::steady_clock::now() + std::chrono::seconds(2);
        while (std::chrono::steady_clock::now() < deadline) {
            if (poll_child(nginx) || !recorder_live(recorder)) {
                error = "#324 pinned nginx or fallback recorder stopped awaiting request";
                return false;
            }
            const u32 accepts = recorder.accepted.load(std::memory_order_acquire);
            const u32 requests = recorder.requests.load(std::memory_order_acquire);
            const u32 sends = recorder.response_send_all_calls.load(std::memory_order_acquire);
            if (accepts > expected || requests > expected || sends > expected) {
                error = "#324 fallback recorder observed a retry or extra request";
                return false;
            }
            if (accepts == expected && requests == expected && sends == expected) return true;
            usleep(1000);
        }
        error = "#324 fallback recorder timed out awaiting one complete request";
        return false;
    };
    const auto request_close = [&](Child& nginx,
                                   const char* name,
                                   const char* request,
                                   bool header_only,
                                   const char* expected,
                                   std::vector<char>& wire) {
        struct ClientGuard {
            int fd = -1;
            ~ClientGuard() {
                if (fd >= 0) close(fd);
            }
        } client{connect_once(frontend_port)};
        std::string detail;
        const bool response_ok = client.fd >= 0 && send_all(client.fd, request, strlen(request)) &&
                                 (header_only ? read_head_response(client.fd, wire, detail)
                                              : read_response(client.fd, wire, detail)) &&
                                 read_eof(client.fd, detail);
        if (!response_ok) {
            error = std::string("#324 ") + name + " response/EOF/no-tail failed: " +
                    (detail.empty() ? "connect or send failed" : detail);
            return false;
        }
        if (!validate_exact_normalized_response(wire, expected, detail)) {
            error = std::string("#324 ") + name + " complete response wire mismatch: " + detail;
            return false;
        }
        if (poll_child(nginx)) {
            error = std::string("#324 pinned nginx exited after ") + name;
            return false;
        }
        return true;
    };

    DockerGuard docker(container_name);
    ChildGuard nginx;
    std::vector<std::string> docker_args = {"docker",
                                            "run",
                                            "--pull=never",
                                            "--network",
                                            "host",
                                            "--name",
                                            container_name,
                                            "-v",
                                            temp.nginx_config + ":/etc/nginx/nginx.conf:ro"};
    if (query_target) {
        docker_args.push_back("-v");
        docker_args.push_back(std::string(temp.path) + ":" + std::string(temp.path));
    }
    docker_args.insert(docker_args.end(), {kNginxImage, "nginx", "-g", "daemon off;"});
    Recorder local_recorder;
    local_recorder.observe_extra_requests_until_stop = true;
    if (!local_recorder.setup(backend_port) ||
        !spawn_child(docker_args, temp.nginx_log, nginx.child) ||
        !wait_ready(frontend_port, nginx.child, error) ||
        !wait_recorder_live(local_recorder, nginx.child, "local") ||
        !observe_count(local_recorder,
                       nginx.child,
                       0,
                       "pre-local live zero-upstream window",
                       std::chrono::milliseconds(250)) ||
        !request_close(nginx.child,
                       "strict local return 204",
                       local_request,
                       true,
                       kExactLocalReturn204ResponseNormalized,
                       observation.local_wire) ||
        !observe_count(local_recorder,
                       nginx.child,
                       0,
                       "post-local live zero-upstream window",
                       std::chrono::milliseconds(500))) {
        if (error.empty()) error = "#324 failed to start pinned nginx/local recorder";
        return false;
    }
    const std::string local_text(observation.local_wire.begin(), observation.local_wire.end());
    if (observation.local_wire.size() != 105u ||
        header_end(observation.local_wire) != observation.local_wire.size() ||
        local_text.find("\r\nContent-Type:") != std::string::npos ||
        local_text.find("\r\nContent-Length:") != std::string::npos ||
        local_text.find("\r\nTransfer-Encoding:") != std::string::npos) {
        error = "#324 strict local 204 contained representation/framing fields, body, or tail";
        return false;
    }
    local_recorder.stop();
    observation.local_accepts = local_recorder.accepted.load(std::memory_order_acquire);
    observation.local_requests = local_recorder.requests.load(std::memory_order_acquire);
    observation.local_sends =
        local_recorder.response_send_all_calls.load(std::memory_order_acquire);
    if (local_recorder.thread_alive.load(std::memory_order_acquire) ||
        local_recorder.listener_failed.load(std::memory_order_acquire) ||
        observation.local_accepts != 0 || observation.local_requests != 0 ||
        observation.local_sends != 0 ||
        local_recorder.response_send_succeeded.load(std::memory_order_acquire) ||
        !local_recorder.history.empty() || !local_recorder.request.empty()) {
        error = "#324 local recorder did not settle with zero upstream activity/history";
        return false;
    }

    Recorder fallback_recorder;
    fallback_recorder.observe_extra_requests_until_stop = true;
    if (!fallback_recorder.setup(
            backend_port, 1, kBackendResponse, sizeof(kBackendResponse) - 1u) ||
        !wait_recorder_live(fallback_recorder, nginx.child, "fallback") ||
        !observe_count(fallback_recorder,
                       nginx.child,
                       0,
                       "pre-fallback live zero-upstream window",
                       std::chrono::milliseconds(100)) ||
        !request_close(nginx.child,
                       "root fallback",
                       fallback_request,
                       false,
                       kSuccessResponseNormalized,
                       observation.fallback_wire) ||
        !wait_count(fallback_recorder, nginx.child, 1) ||
        !observe_count(fallback_recorder,
                       nginx.child,
                       1,
                       "fallback live no-second-request window",
                       std::chrono::milliseconds(500)))
        return false;

    if (!stop_child(nginx.child)) {
        error = "#324 pinned nginx did not remain alive until controlled shutdown";
        return false;
    }
    if (!docker.remove()) {
        error = "#324 failed to remove pinned nginx container after controlled shutdown";
        return false;
    }
    fallback_recorder.stop();
    observation.fallback_accepts = fallback_recorder.accepted.load(std::memory_order_acquire);
    observation.fallback_requests = fallback_recorder.requests.load(std::memory_order_acquire);
    observation.fallback_sends =
        fallback_recorder.response_send_all_calls.load(std::memory_order_acquire);
    observation.fallback_history = fallback_recorder.history;
    if (fallback_recorder.thread_alive.load(std::memory_order_acquire) ||
        fallback_recorder.listener_failed.load(std::memory_order_acquire) ||
        !complete_origin_episode_is_exact(fallback_recorder) ||
        observation.fallback_history.size() != 1u) {
        error = "#324 fallback recorder did not settle at exactly one complete episode";
        return false;
    }
    const std::string expected_backend =
        "GET /fallback?q=1 HTTP/1.1\r\nHost: 127.0.0.1:" + std::to_string(backend_port) +
        "\r\nX-324-Vector: fallback\r\n\r\n";
    if (observation.fallback_history[0] !=
        std::vector<char>(expected_backend.begin(), expected_backend.end())) {
        error = "#324 root fallback upstream request was not byte-exact";
        return false;
    }

    const std::string local_marker = "raw=\"GET /static" + std::string(query_target ? "?x=1" : "") +
                                     " HTTP/1.1\" status=204 bytes=105 host=\"" + request_host +
                                     "\"";
    const std::string fallback_marker = "raw=\"GET /fallback?q=1 HTTP/1.1\" status=200 bytes=" +
                                        std::to_string(sizeof(kSuccessResponseNormalized) - 1u) +
                                        " host=\"" + request_host + "\"";
    const std::string access_log_path = query_target ? temp.nginx_access_log : temp.nginx_log;
    u32 total_access = 0;
    if (!log_count_line_with(access_log_path,
                             local_marker.c_str(),
                             access_prefix.c_str(),
                             observation.local_access) ||
        !log_count_line_with(access_log_path,
                             fallback_marker.c_str(),
                             access_prefix.c_str(),
                             observation.fallback_access) ||
        !log_count_line_with(
            access_log_path, access_prefix.c_str(), access_prefix.c_str(), total_access) ||
        observation.local_access != 1 || observation.fallback_access != 1 || total_access != 2 ||
        log_contains(temp.nginx_log, "[warn]") || log_contains(temp.nginx_log, "[error]") ||
        log_contains(temp.nginx_log, "[crit]") || log_contains(temp.nginx_log, "[alert]") ||
        log_contains(temp.nginx_log, "[emerg]")) {
        error =
            "#324 scoped access/error logs did not prove exact two-record wire accounting "
            "and clean nginx operation";
        return false;
    }
    return true;
}

static bool run_pinned_exact_local_return204_oracle(
    const std::string& container_prefix,
    ExactLocalReturn204OracleObservation& exact_first,
    ExactLocalReturn204OracleObservation& root_first,
    std::string& error) {
    u16 ports[4]{};
    bool ports_unique = false;
    for (int attempt = 0; attempt < 8 && !ports_unique; attempt++) {
        ports_unique = true;
        for (u16& port : ports) {
            if (!allocate_port(port)) {
                ports_unique = false;
                break;
            }
        }
        for (size_t i = 0; ports_unique && i < 4; i++) {
            for (size_t j = i + 1u; j < 4; j++) {
                if (ports[i] == ports[j]) {
                    ports_unique = false;
                    break;
                }
            }
        }
    }
    if (!ports_unique) {
        error = "#324 could not allocate four distinct declaration-order ports";
        return false;
    }

    TempDir exact_temp;
    TempDir root_temp;
    if (!exact_temp.create() || !root_temp.create() ||
        strcmp(exact_temp.path, root_temp.path) == 0 ||
        exact_temp.nginx_config == root_temp.nginx_config ||
        exact_temp.nginx_log == root_temp.nginx_log) {
        error = "#324 could not create two independent temp/config/log trees";
        return false;
    }
    const std::string exact_container = container_prefix + "-exact-first";
    const std::string root_container = container_prefix + "-root-first";
    if (exact_container == root_container) {
        error = "#324 declaration-order container names were not independent";
        return false;
    }
    if (!capture_pinned_exact_local_return204_order(
            ports[0], ports[1], exact_temp, exact_container, true, false, exact_first, error)) {
        dump_log(exact_temp.nginx_config, "#324 exact-first pinned nginx config");
        dump_log(exact_temp.nginx_log, "#324 exact-first pinned nginx log");
        return false;
    }
    if (!capture_pinned_exact_local_return204_order(
            ports[2], ports[3], root_temp, root_container, false, false, root_first, error)) {
        dump_log(root_temp.nginx_config, "#324 root-first pinned nginx config");
        dump_log(root_temp.nginx_log, "#324 root-first pinned nginx log");
        return false;
    }
    if (exact_first.temp_path == root_first.temp_path ||
        exact_first.config_path == root_first.config_path ||
        exact_first.log_path == root_first.log_path ||
        exact_first.container_name == root_first.container_name || exact_first.local_wire.empty() ||
        root_first.local_wire.empty() || exact_first.fallback_wire.empty() ||
        root_first.fallback_wire.empty()) {
        error = "#324 declaration orders did not retain independent resources and observations";
        dump_log(exact_temp.nginx_config, "#324 exact-first pinned nginx config");
        dump_log(exact_temp.nginx_log, "#324 exact-first pinned nginx log");
        dump_log(root_temp.nginx_config, "#324 root-first pinned nginx config");
        dump_log(root_temp.nginx_log, "#324 root-first pinned nginx log");
        return false;
    }
    const auto same_normalized_wire = [](const std::vector<char>& left,
                                         const std::vector<char>& right) {
        std::vector<char> normalized_left(left.begin(), left.end());
        std::vector<char> normalized_right(right.begin(), right.end());
        return normalize_date(normalized_left) && normalize_date(normalized_right) &&
               normalized_left == normalized_right;
    };
    if (!same_normalized_wire(exact_first.local_wire, root_first.local_wire) ||
        !same_normalized_wire(exact_first.fallback_wire, root_first.fallback_wire)) {
        error = "#324 declaration order changed a Date-normalized client response";
        dump_log(exact_temp.nginx_config, "#324 exact-first pinned nginx config");
        dump_log(exact_temp.nginx_log, "#324 exact-first pinned nginx log");
        dump_log(root_temp.nginx_config, "#324 root-first pinned nginx config");
        dump_log(root_temp.nginx_log, "#324 root-first pinned nginx log");
        return false;
    }
    const auto canonical_backend = [](const std::vector<char>& wire) {
        std::string result(wire.begin(), wire.end());
        static constexpr char kHostPrefix[] = "\r\nHost: 127.0.0.1:";
        const size_t port_begin = result.find(kHostPrefix);
        const size_t digits_begin = port_begin == std::string::npos
                                        ? std::string::npos
                                        : port_begin + sizeof(kHostPrefix) - 1u;
        const size_t port_end = digits_begin == std::string::npos
                                    ? std::string::npos
                                    : result.find("\r\n", digits_begin);
        if (port_end == std::string::npos) return std::string{};
        result.replace(digits_begin, port_end - digits_begin, "BACKEND");
        return result;
    };
    if (exact_first.fallback_history.size() != 1u || root_first.fallback_history.size() != 1u ||
        canonical_backend(exact_first.fallback_history[0]).empty() ||
        canonical_backend(exact_first.fallback_history[0]) !=
            canonical_backend(root_first.fallback_history[0])) {
        error = "#324 declaration order changed exact fallback history after dynamic-port binding";
        dump_log(exact_temp.nginx_config, "#324 exact-first pinned nginx config");
        dump_log(exact_temp.nginx_log, "#324 exact-first pinned nginx log");
        dump_log(root_temp.nginx_config, "#324 root-first pinned nginx config");
        dump_log(root_temp.nginx_log, "#324 root-first pinned nginx log");
        return false;
    }
    return true;
}

static bool parse_exact_return204_query_access_log(const std::string& contents,
                                                   const std::string& prefix,
                                                   u16 backend_port,
                                                   std::string& error) {
    std::vector<std::string> records;
    if (!split_exact_complete_log(contents, 2u, "#325 query access log", records, error))
        return false;
    const auto parse_record = [&](const std::string& record,
                                  const char* raw_target,
                                  size_t expected_status,
                                  size_t expected_bytes,
                                  bool fallback_record) {
        size_t cursor = prefix.size();
        const auto take = [&](const std::string& literal) {
            if (record.compare(cursor, literal.size(), literal) != 0) return false;
            cursor += literal.size();
            return true;
        };
        const auto take_token = [&](const char* label, std::string& token) {
            if (!take(label)) return false;
            const size_t end = record.find(' ', cursor);
            if (end == std::string::npos) return false;
            token = record.substr(cursor, end - cursor);
            cursor = end;
            return !token.empty();
        };
        if (record.size() < prefix.size() || record.compare(0, prefix.size(), prefix) != 0 ||
            !take(" raw=\"") || !take(raw_target) || !take("\" status="))
            return false;
        std::string status;
        std::string bytes;
        if (!take_token("", status) || !take(" bytes=") || !take_token("", bytes)) return false;
        size_t status_value = 0;
        size_t bytes_value = 0;
        if (!parse_decimal_field(status, status_value) ||
            !parse_decimal_field(bytes, bytes_value) || status != std::to_string(expected_status) ||
            bytes != std::to_string(expected_bytes))
            return false;
        if (!take(" host=\"query-return204.example\" upstream_addr=\"")) return false;
        if (fallback_record) {
            if (!take("127.0.0.1:")) return false;
            const size_t port_end = record.find('"', cursor);
            if (port_end == std::string::npos || port_end == cursor) return false;
            const std::string port = record.substr(cursor, port_end - cursor);
            size_t port_value = 0;
            if (!parse_decimal_field(port, port_value) || port_value > 65535u ||
                port != std::to_string(backend_port))
                return false;
            cursor = port_end;
        } else if (!take("-")) {
            return false;
        }
        if (!take("\" upstream_status=")) return false;
        std::string upstream_status;
        if (cursor >= record.size()) return false;
        upstream_status = record.substr(cursor);
        if (fallback_record) {
            size_t upstream_status_value = 0;
            if (!parse_decimal_field(upstream_status, upstream_status_value) ||
                upstream_status != "200")
                return false;
        } else if (upstream_status != "-") {
            return false;
        }
        return true;
    };
    if (!parse_record(records[0], "GET /static?x=1 HTTP/1.1", 204u, 105u, false) ||
        !parse_record(records[1], "GET /fallback?q=1 HTTP/1.1", 200u, 118u, true)) {
        error = "#325 query access log did not contain the exact ordered raw-target records";
        return false;
    }
    return true;
}

static bool run_exact_return204_query_access_log_self_checks(std::string& error) {
    const std::string prefix = "rut-nginx-325-return204-exact-before-root-123-scoped";
    const std::string local = prefix +
                              " raw=\"GET /static?x=1 HTTP/1.1\" status=204 bytes=105 "
                              "host=\"query-return204.example\" upstream_addr=\"-\" "
                              "upstream_status=-\n";
    const std::string fallback =
        prefix +
        " raw=\"GET /fallback?q=1 HTTP/1.1\" status=200 bytes=118 "
        "host=\"query-return204.example\" upstream_addr=\"127.0.0.1:54321\" "
        "upstream_status=200\n";
    const std::string valid = local + fallback;
    const auto rejects = [&](const std::string& value) {
        std::string detail;
        return !parse_exact_return204_query_access_log(value, prefix, 54321, detail);
    };
    const auto mutate_at =
        [](std::string value, size_t offset, const char* expected, const char* replacement) {
            const size_t width = strlen(expected);
            if (value.compare(offset, width, expected) != 0) return std::string{};
            value.replace(offset, width, replacement);
            return value;
        };
    static constexpr char kOverflow[] = "999999999999999999999999999999999999999999";
    const size_t local_status_offset =
        prefix.size() + strlen(" raw=\"GET /static?x=1 HTTP/1.1\" status=");
    const size_t local_bytes_offset =
        prefix.size() + strlen(" raw=\"GET /static?x=1 HTTP/1.1\" status=204 bytes=");
    const size_t fallback_status_offset =
        prefix.size() + strlen(" raw=\"GET /fallback?q=1 HTTP/1.1\" status=");
    const size_t fallback_bytes_offset =
        prefix.size() + strlen(" raw=\"GET /fallback?q=1 HTTP/1.1\" status=200 bytes=");
    const size_t fallback_port_offset = prefix.size() + strlen(
                                                            " raw=\"GET /fallback?q=1 HTTP/1.1\" "
                                                            "status=200 bytes=118 "
                                                            "host=\"query-return204.example\" "
                                                            "upstream_addr=\"127.0.0.1:");
    const size_t fallback_upstream_status_offset =
        prefix.size() + strlen(
                            " raw=\"GET /fallback?q=1 HTTP/1.1\" status=200 bytes=118 "
                            "host=\"query-return204.example\" upstream_addr=\"127.0.0.1:54321\" "
                            "upstream_status=");
    const std::string overflow_local_status =
        mutate_at(local, local_status_offset, "204", kOverflow);
    const std::string overflow_local_bytes = mutate_at(local, local_bytes_offset, "105", kOverflow);
    const std::string overflow_fallback_status =
        mutate_at(fallback, fallback_status_offset, "200", kOverflow);
    const std::string overflow_fallback_bytes =
        mutate_at(fallback, fallback_bytes_offset, "118", kOverflow);
    const std::string overflow_fallback_port =
        mutate_at(fallback, fallback_port_offset, "54321", kOverflow);
    const std::string overflow_fallback_upstream_status =
        mutate_at(fallback, fallback_upstream_status_offset, "200", kOverflow);
    if (overflow_local_status.empty() || overflow_local_bytes.empty() ||
        overflow_fallback_status.empty() || overflow_fallback_bytes.empty() ||
        overflow_fallback_port.empty() || overflow_fallback_upstream_status.empty() ||
        !parse_exact_return204_query_access_log(valid, prefix, 54321, error) ||
        !rejects(valid + local) || !rejects(fallback + local) ||
        !rejects(valid.substr(0, valid.size() - 1u)) || !rejects(local + "\n" + fallback) ||
        !rejects(local.substr(0, local.size() - 2u) + "x\n" + fallback) ||
        !rejects(overflow_local_status + fallback) || !rejects(overflow_local_bytes + fallback) ||
        !rejects(local + overflow_fallback_status) || !rejects(local + overflow_fallback_bytes) ||
        !rejects(local + overflow_fallback_port) ||
        !rejects(local + overflow_fallback_upstream_status)) {
        error = "#325 query access-log exact-record mutation self-check failed";
        return false;
    }
    return true;
}

static bool run_pinned_exact_local_return204_query_oracle(
    const std::string& container_prefix,
    ExactLocalReturn204OracleObservation& exact_first,
    ExactLocalReturn204OracleObservation& root_first,
    std::string& error) {
    u16 ports[4]{};
    bool ports_unique = false;
    for (int attempt = 0; attempt < 8 && !ports_unique; attempt++) {
        ports_unique = true;
        for (u16& port : ports) {
            if (!allocate_port(port)) {
                ports_unique = false;
                break;
            }
        }
        for (size_t i = 0; ports_unique && i < 4; i++) {
            for (size_t j = i + 1u; j < 4; j++) {
                if (ports[i] == ports[j]) {
                    ports_unique = false;
                    break;
                }
            }
        }
    }
    if (!ports_unique) {
        error = "#325 could not allocate four distinct declaration-order ports";
        return false;
    }

    TempDir exact_temp;
    TempDir root_temp;
    if (!exact_temp.create() || !root_temp.create() ||
        strcmp(exact_temp.path, root_temp.path) == 0 ||
        exact_temp.nginx_config == root_temp.nginx_config ||
        exact_temp.nginx_log == root_temp.nginx_log ||
        exact_temp.nginx_access_log == root_temp.nginx_access_log) {
        error = "#325 could not create two independent temp/config/log trees";
        return false;
    }
    const std::string exact_container = container_prefix + "-exact-first";
    const std::string root_container = container_prefix + "-root-first";
    if (exact_container == root_container) {
        error = "#325 declaration-order container names were not independent";
        return false;
    }
    if (!capture_pinned_exact_local_return204_order(
            ports[0], ports[1], exact_temp, exact_container, true, true, exact_first, error)) {
        dump_log(exact_temp.nginx_config, "#325 exact-first pinned nginx config");
        dump_log(exact_temp.nginx_log, "#325 exact-first pinned nginx error log");
        dump_log(exact_temp.nginx_access_log, "#325 exact-first pinned nginx access log");
        return false;
    }
    if (!capture_pinned_exact_local_return204_order(
            ports[2], ports[3], root_temp, root_container, false, true, root_first, error)) {
        dump_log(root_temp.nginx_config, "#325 root-first pinned nginx config");
        dump_log(root_temp.nginx_log, "#325 root-first pinned nginx error log");
        dump_log(root_temp.nginx_access_log, "#325 root-first pinned nginx access log");
        return false;
    }
    std::string exact_access;
    std::string root_access;
    if (!read_exact_return204_log(
            exact_temp.nginx_access_log, "#325 exact-first access log", exact_access, error) ||
        !read_exact_return204_log(
            root_temp.nginx_access_log, "#325 root-first access log", root_access, error) ||
        !parse_exact_return204_query_access_log(
            exact_access, exact_first.access_prefix, ports[1], error) ||
        !parse_exact_return204_query_access_log(
            root_access, root_first.access_prefix, ports[3], error)) {
        return false;
    }
    const auto same_normalized_wire = [](const std::vector<char>& left,
                                         const std::vector<char>& right) {
        std::vector<char> normalized_left(left.begin(), left.end());
        std::vector<char> normalized_right(right.begin(), right.end());
        return normalize_date(normalized_left) && normalize_date(normalized_right) &&
               normalized_left == normalized_right;
    };
    const std::vector<char> expected_local(kExactLocalReturn204ResponseNormalized,
                                           kExactLocalReturn204ResponseNormalized + 105u);
    const std::vector<char> expected_fallback(
        kSuccessResponseNormalized,
        kSuccessResponseNormalized + sizeof(kSuccessResponseNormalized) - 1u);
    for (const ExactLocalReturn204OracleObservation* observation : {&exact_first, &root_first}) {
        std::vector<char> local = observation->local_wire;
        std::vector<char> fallback = observation->fallback_wire;
        if (local.size() != 105u || fallback.size() != 118u || !normalize_date(local) ||
            !normalize_date(fallback) || local != expected_local || fallback != expected_fallback ||
            observation->local_accepts != 0 || observation->local_requests != 0 ||
            observation->local_sends != 0 || observation->fallback_accepts != 1 ||
            observation->fallback_requests != 1 || observation->fallback_sends != 1 ||
            observation->fallback_history.size() != 1u || observation->local_access != 1 ||
            observation->fallback_access != 1) {
            error = "#325 one declaration order lacked exact wire/zero-upstream/fallback evidence";
            return false;
        }
    }
    if (!same_normalized_wire(exact_first.local_wire, root_first.local_wire) ||
        !same_normalized_wire(exact_first.fallback_wire, root_first.fallback_wire)) {
        error = "#325 declaration order changed a Date-normalized client response";
        return false;
    }
    const auto canonical_backend = [](const std::vector<char>& wire) {
        std::string result(wire.begin(), wire.end());
        static constexpr char kHostPrefix[] = "\r\nHost: 127.0.0.1:";
        const size_t begin = result.find(kHostPrefix);
        if (begin == std::string::npos || result.find(kHostPrefix, begin + 1u) != std::string::npos)
            return std::string{};
        const size_t digits = begin + sizeof(kHostPrefix) - 1u;
        const size_t end = result.find("\r\n", digits);
        if (end == std::string::npos || end == digits) return std::string{};
        for (size_t i = digits; i < end; i++)
            if (result[i] < '0' || result[i] > '9') return std::string{};
        result.replace(digits, end - digits, "BACKEND");
        return result;
    };
    if (canonical_backend(exact_first.fallback_history[0]).empty() ||
        canonical_backend(exact_first.fallback_history[0]) !=
            canonical_backend(root_first.fallback_history[0])) {
        error = "#325 declaration order changed exact fallback history after dynamic-port binding";
        return false;
    }
    return true;
}

static std::string make_exact_local_return204_fragment(u16 frontend_port,
                                                       u16 backend_port,
                                                       bool exact_first) {
    const std::string exact_location = "  location = /static { return 204; }\n";
    const std::string root_location =
        "  location / { proxy_pass http://127.0.0.1:" + std::to_string(backend_port) + "; }\n";
    return "server {\n"
           "  listen " +
           std::to_string(frontend_port) + ";\n" +
           (exact_first ? exact_location + root_location : root_location + exact_location) + "}\n";
}

static bool capture_generated_exact_local_return204_order(
    u16 frontend_port,
    u16 backend_port,
    TempDir& temp,
    const char* rut_path,
    bool exact_first,
    bool query_target,
    ExactLocalReturn204OracleObservation& observation,
    std::string& generated_source,
    std::string& error) {
    if (rut_path == nullptr || rut_path[0] != '/' || access(rut_path, X_OK) != 0) {
        error = std::string("converter-generated #") + (query_target ? "325" : "324") +
                " differential requires an executable absolute RUT path";
        return false;
    }

    std::string fragment =
        make_exact_local_return204_fragment(frontend_port, backend_port, exact_first);
    const auto parsed = rut::nginx::parse({fragment.data(), static_cast<u32>(fragment.size())});
    if (!parsed) {
        error = "#324 accepted literal nginx fragment did not traverse the independent parser";
        return false;
    }
    const auto& server = parsed.value();
    const auto& root = server.location;
    const auto& proxy = root.proxy_pass;
    const auto& exact = server.exact_no_content_return;
    const auto& response = exact.response;
    const size_t root_location_offset = fragment.find("location / {");
    const size_t root_path_offset = fragment.find('/', root_location_offset);
    const size_t exact_location_offset = fragment.find("location = /static");
    const size_t exact_path_offset = fragment.find("/static", exact_location_offset);
    const size_t return_offset = fragment.find("return", exact_location_offset);
    const size_t status_offset = fragment.find("204", return_offset);
    const size_t semicolon_offset = fragment.find(';', status_offset);
    const size_t exact_end = fragment.find('}', semicolon_offset);
    const uintptr_t source_base = reinterpret_cast<uintptr_t>(fragment.data());
    const auto same_source_base = [&](rut::Str value, rut::Span span) {
        return value.ptr != nullptr && span.end >= span.start &&
               span.end - span.start == value.len &&
               reinterpret_cast<uintptr_t>(value.ptr) - span.start == source_base;
    };
    if (root_location_offset == std::string::npos || root_path_offset == std::string::npos ||
        exact_location_offset == std::string::npos || exact_path_offset == std::string::npos ||
        return_offset == std::string::npos || status_offset == std::string::npos ||
        semicolon_offset == std::string::npos || exact_end == std::string::npos ||
        server.span.start != 0 || server.span.end != fragment.size() - 1u ||
        server.listen.port != frontend_port || !root.path.eq(rut::lit_str("/")) ||
        root.path.ptr != fragment.data() + root_path_offset ||
        !same_source_base(root.path, root.path_span) || proxy.has_uri || proxy.address[0] != 127 ||
        proxy.address[1] != 0 || proxy.address[2] != 0 || proxy.address[3] != 1 ||
        proxy.port != backend_port || !exact.present || !exact.path.eq(rut::lit_str("/static")) ||
        exact.path.ptr != fragment.data() + exact_path_offset ||
        !same_source_base(exact.path, exact.path_span) ||
        exact.span.start != exact_location_offset || exact.span.end != exact_end + 1u ||
        response.status != 204 || response.status_span.start != status_offset ||
        response.status_span.end != status_offset + 3u || response.span.start != return_offset ||
        response.span.end != semicolon_offset + 1u ||
        memcmp(fragment.data() + response.status_span.start, "204", 3u) != 0 ||
        server.exact_local_return.present || server.exact_absolute_redirect.present ||
        exact.span.start >= exact.path_span.start || exact.path_span.end > response.span.start ||
        response.span.end >= exact.span.end || root.span.start != root_location_offset) {
        error =
            "#324 fragment did not retain the genuine borrowed no-content action, provenance, "
            "dynamic listen/upstream values, and independent root fallback";
        return false;
    }

    const auto lowered = rut::nginx::lower_to_rut(server);
    if (!lowered) {
        error = "#324 genuine no-content semantic model failed ordinary-RUT lowering";
        return false;
    }
    const rut::Str generated = lowered.value().view();
    generated_source.assign(generated.ptr, generated.len);
    const auto count_literal = [&](const std::string& literal) {
        size_t count = 0;
        for (size_t offset = 0;;) {
            offset = generated_source.find(literal, offset);
            if (offset == std::string::npos) return count;
            count++;
            offset += literal.size();
        }
    };
    const std::string exact_tuple =
        "route exact slash_normalized GET \"/static\" { return local_response({\n"
        "  version: \"HTTP/1.1\", status: 204, reason: \"No Content\", server: "
        "\"nginx/1.29.7\",\n"
        "  date: \"current\", content_type: \"\", connection: \"request\",\n"
        "  head_mode: \"suppress_body\", body: b\"\"\n"
        "}) }\n";
    if (count_literal(exact_tuple) != 1u ||
        count_literal("route exact slash_normalized GET \"/static\"") != 1u ||
        count_literal("route exact GET \"/static\"") != 0u || count_literal("route exact ") != 1u ||
        count_literal("route HEAD \"/\" {") != 1u || count_literal("route GET \"/\" {") != 1u ||
        count_literal("route \"/\" {") != 1u ||
        count_literal("return forward(nginx_upstream") != 3u ||
        count_literal("upstream nginx_upstream at \"127.0.0.1:" + std::to_string(backend_port) +
                      "\"") != 1u ||
        count_literal("listen :" + std::to_string(frontend_port) + "\n") != 1u ||
        generated_source.find("proxy_pass") != std::string::npos ||
        generated_source.find("nginx.conf") != std::string::npos ||
        generated_source.find("propagat") != std::string::npos ||
        generated_source.find("NoContent204") != std::string::npos ||
        generated_source.find("strict_local_response") != std::string::npos ||
        generated_source.find("profile") != std::string::npos ||
        generated_source.find("return 204") != std::string::npos ||
        generated_source.find("nginx::") != std::string::npos ||
        generated_source.find("nginx_compat") != std::string::npos ||
        !generated_exact_return204_source_is_query_free(generated_source) ||
        !generated_exact_return204_source_has_normalized_static_selector(generated_source) ||
        !write_file(temp.source, generated.ptr, generated.len)) {
        error =
            "#324 output was not exactly one public strict /static selector plus the canonical "
            "ordinary root-forward route set";
        return false;
    }

    std::fill(fragment.begin(), fragment.end(), '\0');
    if (!std::all_of(fragment.begin(), fragment.end(), [](char byte) { return byte == '\0'; })) {
        error = "#324 failed to destroy the borrowed nginx source after parse/lower";
        return false;
    }

    observation = ExactLocalReturn204OracleObservation{};
    observation.order = exact_first ? "generated-exact-before-root" : "generated-root-before-exact";
    observation.temp_path = temp.path;
    observation.config_path = temp.source;
    observation.log_path = temp.rut_log;
    observation.container_name = "public-rut-cli-" + observation.order;
    static constexpr char kLocalRequest[] =
        "GET /static HTTP/1.1\r\n"
        "Host: return204.example\r\n"
        "Connection: close\r\n\r\n";
    static constexpr char kQueryLocalRequest[] =
        "GET /static?x=1 HTTP/1.1\r\n"
        "Host: query-return204.example\r\n"
        "Connection: close\r\n\r\n";
    static constexpr char kFallbackRequest[] =
        "GET /fallback?q=1 HTTP/1.1\r\n"
        "Host: return204.example\r\n"
        "X-324-Vector: fallback\r\n"
        "Connection: close\r\n\r\n";
    static constexpr char kQueryFallbackRequest[] =
        "GET /fallback?q=1 HTTP/1.1\r\n"
        "Host: query-return204.example\r\n"
        "X-324-Vector: fallback\r\n"
        "Connection: close\r\n\r\n";
    const char* local_request = query_target ? kQueryLocalRequest : kLocalRequest;
    const char* fallback_request = query_target ? kQueryFallbackRequest : kFallbackRequest;

    const auto recorder_live = [](const Recorder& recorder) {
        return recorder.running.load(std::memory_order_acquire) &&
               recorder.thread_alive.load(std::memory_order_acquire) &&
               !recorder.listener_failed.load(std::memory_order_acquire);
    };
    struct RecorderGuard {
        Recorder* recorder = nullptr;
        ~RecorderGuard() {
            if (recorder != nullptr) recorder->stop();
        }
    };
    ChildGuard runtime;
    if (!spawn_child({rut_path,
                      temp.source,
                      "--shards",
                      "1",
                      "--no-pin",
                      "--drain",
                      "0",
                      "--access-log",
                      temp.rut_access_log},
                     temp.rut_log,
                     runtime.child) ||
        !wait_ready(frontend_port, runtime.child, error)) {
        if (error.empty()) error = "failed to start converter-generated public RUT for #324";
        return false;
    }
    const std::string loaded_record = "Loaded program: " + temp.source + " (opt O2)\n";
    const std::string listener_record =
        "Listening on port " + std::to_string(frontend_port) + " with 1 shard(s)";
    const auto ready_deadline = std::chrono::steady_clock::now() + std::chrono::seconds(2);
    while ((!log_contains(temp.rut_log, loaded_record.c_str()) ||
            !log_contains(temp.rut_log, "Backend: io_uring\n") ||
            !log_contains(temp.rut_log, listener_record.c_str())) &&
           std::chrono::steady_clock::now() < ready_deadline) {
        if (poll_child(runtime.child)) {
            error = "converter-generated #324 RUT exited before public load/io_uring readiness";
            return false;
        }
        usleep(1000);
    }
    if (!log_contains(temp.rut_log, loaded_record.c_str()) ||
        !log_contains(temp.rut_log, "Backend: io_uring\n") ||
        !log_contains(temp.rut_log, listener_record.c_str())) {
        error = "converter-generated #324 RUT lacked exact source-load/listener/io_uring proof";
        return false;
    }
    const std::string destroyed_source =
        std::string("destroyed-after-") + (query_target ? "325" : "324") + "-public-load\n";
    if (!write_file(temp.source, destroyed_source.data(), destroyed_source.size())) {
        error = "failed to destroy #324 generated RUT source after public readiness";
        return false;
    }

    const auto wait_recorder_live = [&](Recorder& recorder, const char* phase) {
        const auto deadline = std::chrono::steady_clock::now() + std::chrono::seconds(2);
        while (std::chrono::steady_clock::now() < deadline) {
            if (poll_child(runtime.child)) {
                error = std::string("converter-generated #324 RUT exited before ") + phase +
                        " recorder readiness";
                return false;
            }
            if (recorder.listener_failed.load(std::memory_order_acquire) ||
                !recorder.running.load(std::memory_order_acquire)) {
                error = std::string("#324 ") + phase + " recorder failed before readiness";
                return false;
            }
            if (recorder.thread_alive.load(std::memory_order_acquire)) return true;
            usleep(1000);
        }
        error = std::string("#324 ") + phase + " recorder readiness timed out";
        return false;
    };
    const auto observe_count = [&](Recorder& recorder,
                                   u32 expected,
                                   const char* phase,
                                   std::chrono::milliseconds duration) {
        const auto deadline = std::chrono::steady_clock::now() + duration;
        for (;;) {
            if (poll_child(runtime.child) || !recorder_live(recorder)) {
                error = std::string("converter-generated #324 RUT/recorder failed during ") + phase;
                return false;
            }
            if (recorder.accepted.load(std::memory_order_acquire) != expected ||
                recorder.requests.load(std::memory_order_acquire) != expected ||
                recorder.response_send_all_calls.load(std::memory_order_acquire) != expected) {
                error =
                    std::string("converter-generated #324 observed unexpected upstream during ") +
                    phase;
                return false;
            }
            if (std::chrono::steady_clock::now() >= deadline) return true;
            usleep(5000);
        }
    };
    const auto request_close = [&](const char* name,
                                   const char* request,
                                   bool header_only,
                                   const char* expected,
                                   std::vector<char>& wire) {
        struct ClientGuard {
            int fd = -1;
            ~ClientGuard() {
                if (fd >= 0) close(fd);
            }
        } client{connect_once(frontend_port)};
        std::string detail;
        if (client.fd < 0 || !send_all(client.fd, request, strlen(request)) ||
            !(header_only ? read_head_response(client.fd, wire, detail)
                          : read_response(client.fd, wire, detail)) ||
            !read_eof(client.fd, detail)) {
            error = std::string("converter-generated #324 ") + name +
                    " response/EOF/no-tail failed: " +
                    (detail.empty() ? "connect or send failed" : detail);
            return false;
        }
        if (!validate_exact_normalized_response(wire, expected, detail)) {
            error = std::string("converter-generated #324 ") + name +
                    " complete response wire mismatch: " + detail;
            return false;
        }
        if (poll_child(runtime.child)) {
            error = std::string("converter-generated #324 RUT exited after ") + name;
            return false;
        }
        return true;
    };

    Recorder zero;
    RecorderGuard zero_guard{&zero};
    zero.observe_extra_requests_until_stop = true;
    if (!zero.setup(backend_port) || !wait_recorder_live(zero, "local") ||
        !observe_count(
            zero, 0, "pre-local live zero-upstream window", std::chrono::milliseconds(250)) ||
        !request_close("strict local return 204",
                       local_request,
                       true,
                       kExactLocalReturn204ResponseNormalized,
                       observation.local_wire) ||
        !observe_count(
            zero, 0, "post-local live zero-upstream window", std::chrono::milliseconds(500)))
        return false;
    const std::string local_text(observation.local_wire.begin(), observation.local_wire.end());
    if (observation.local_wire.size() != 105u ||
        header_end(observation.local_wire) != observation.local_wire.size() ||
        local_text.find("\r\nContent-Type:") != std::string::npos ||
        local_text.find("\r\nContent-Length:") != std::string::npos ||
        local_text.find("\r\nTransfer-Encoding:") != std::string::npos) {
        error = "converter-generated #324 strict 204 gained framing, representation, body, or tail";
        return false;
    }
    zero.stop();
    zero_guard.recorder = nullptr;
    observation.local_accepts = zero.accepted.load(std::memory_order_acquire);
    observation.local_requests = zero.requests.load(std::memory_order_acquire);
    observation.local_sends = zero.response_send_all_calls.load(std::memory_order_acquire);
    if (zero.thread_alive.load(std::memory_order_acquire) ||
        zero.listener_failed.load(std::memory_order_acquire) || observation.local_accepts != 0 ||
        observation.local_requests != 0 || observation.local_sends != 0 ||
        zero.response_send_succeeded.load(std::memory_order_acquire) || !zero.history.empty() ||
        !zero.request.empty()) {
        error = "converter-generated #324 local recorder did not settle with zero activity/history";
        return false;
    }

    Recorder fallback;
    RecorderGuard fallback_guard{&fallback};
    fallback.observe_extra_requests_until_stop = true;
    if (!fallback.setup(backend_port, 1, kBackendResponse, sizeof(kBackendResponse) - 1u) ||
        !wait_recorder_live(fallback, "fallback") ||
        !observe_count(fallback,
                       0,
                       "pre-fallback live zero-upstream window",
                       std::chrono::milliseconds(100)) ||
        !request_close("root fallback",
                       fallback_request,
                       false,
                       kSuccessResponseNormalized,
                       observation.fallback_wire))
        return false;
    const auto count_deadline = std::chrono::steady_clock::now() + std::chrono::seconds(2);
    while (std::chrono::steady_clock::now() < count_deadline) {
        if (poll_child(runtime.child) || !recorder_live(fallback)) {
            error = "converter-generated #324 RUT/fallback recorder stopped awaiting request";
            return false;
        }
        const u32 accepted = fallback.accepted.load(std::memory_order_acquire);
        const u32 requests = fallback.requests.load(std::memory_order_acquire);
        const u32 sends = fallback.response_send_all_calls.load(std::memory_order_acquire);
        if (accepted > 1 || requests > 1 || sends > 1) {
            error = "converter-generated #324 fallback observed retry or extra request";
            return false;
        }
        if (accepted == 1 && requests == 1 && sends == 1) break;
        usleep(1000);
    }
    if (fallback.accepted.load(std::memory_order_acquire) != 1 ||
        fallback.requests.load(std::memory_order_acquire) != 1 ||
        fallback.response_send_all_calls.load(std::memory_order_acquire) != 1 ||
        !observe_count(
            fallback, 1, "fallback live no-second-request window", std::chrono::milliseconds(500)))
        return false;

    if (!stop_child(runtime.child)) {
        error = "converter-generated #324 RUT did not remain live until controlled shutdown";
        return false;
    }
    fallback.stop();
    fallback_guard.recorder = nullptr;
    observation.fallback_accepts = fallback.accepted.load(std::memory_order_acquire);
    observation.fallback_requests = fallback.requests.load(std::memory_order_acquire);
    observation.fallback_sends = fallback.response_send_all_calls.load(std::memory_order_acquire);
    observation.fallback_history = fallback.history;
    if (fallback.thread_alive.load(std::memory_order_acquire) ||
        fallback.listener_failed.load(std::memory_order_acquire) ||
        !complete_origin_episode_is_exact(fallback) || observation.fallback_history.size() != 1u) {
        error = "converter-generated #324 fallback did not settle as one complete episode";
        return false;
    }
    const std::string expected_backend =
        "GET /fallback?q=1 HTTP/1.1\r\nHost: 127.0.0.1:" + std::to_string(backend_port) +
        "\r\nX-324-Vector: fallback\r\n\r\n";
    if (observation.fallback_history[0] !=
        std::vector<char>(expected_backend.begin(), expected_backend.end())) {
        error = "converter-generated #324 fallback upstream request was not byte-exact";
        return false;
    }

    std::string access_contents;
    std::string runtime_contents;
    if (!read_exact_return204_log(
            temp.rut_access_log, "converter-generated #324 access log", access_contents, error) ||
        !parse_exact_return204_access_log(access_contents,
                                          strlen(local_request),
                                          strlen(fallback_request),
                                          sizeof(kSuccessResponseNormalized) - 1u,
                                          error,
                                          query_target) ||
        !read_exact_return204_log(
            temp.rut_log, "converter-generated #324 runtime log", runtime_contents, error) ||
        !parse_exact_return204_runtime_log(runtime_contents, temp.source, listener_record, error)) {
        return false;
    }
    if (strlen(fallback_request) == expected_backend.size()) {
        error =
            "converter-generated #324 fixture no longer distinguishes downstream and rebuilt "
            "request sizes";
        return false;
    }
    std::string swapped_size_error;
    if (parse_exact_return204_access_log(access_contents,
                                         strlen(local_request),
                                         expected_backend.size(),
                                         sizeof(kSuccessResponseNormalized) - 1u,
                                         swapped_size_error,
                                         query_target)) {
        error = "converter-generated #324 access parser accepted rebuilt upstream field 5";
        return false;
    }
    observation.local_access = 1;
    observation.fallback_access = 1;
    return true;
}

static bool run_converter_exact_local_return204_differential(const std::string& container_prefix,
                                                             const char* rut_path,
                                                             bool query_target,
                                                             std::string& error) {
    u16 ports[8]{};
    bool ports_unique = false;
    for (int attempt = 0; attempt < 8 && !ports_unique; attempt++) {
        ports_unique = true;
        for (u16& port : ports) ports_unique = allocate_port(port) && ports_unique;
        for (size_t i = 0; i < 8 && ports_unique; i++) {
            for (size_t j = i + 1u; j < 8; j++) {
                if (ports[i] == ports[j]) ports_unique = false;
            }
        }
    }
    if (!ports_unique) {
        error = std::string("#") + (query_target ? "325" : "324") +
                " could not allocate eight unique four-side frontend/backend ports";
        return false;
    }

    TempDir temps[4];
    for (TempDir& temp : temps) {
        if (!temp.create()) {
            error = std::string("#") + (query_target ? "325" : "324") +
                    " could not create four isolated differential temp trees";
            return false;
        }
    }
    for (size_t i = 0; i < 4; i++) {
        for (size_t j = i + 1u; j < 4; j++) {
            if (strcmp(temps[i].path, temps[j].path) == 0 || temps[i].source == temps[j].source ||
                temps[i].nginx_config == temps[j].nginx_config ||
                temps[i].nginx_log == temps[j].nginx_log || temps[i].rut_log == temps[j].rut_log ||
                temps[i].rut_access_log == temps[j].rut_access_log) {
                error = std::string("#") + (query_target ? "325" : "324") +
                        " four sides shared a temp/config/source/log/access identity";
                return false;
            }
        }
    }

    ExactLocalReturn204OracleObservation observations[4];
    std::string generated_sources[2];
    const std::string containers[2] = {container_prefix + "-nginx-exact-first",
                                       container_prefix + "-nginx-root-first"};
    const auto dump_all = [&]() {
        for (size_t i = 0; i < 4; i++) {
            dump_exact_local_return204_oracle_observation(observations[i]);
            if (i < 2u) {
                dump_log(temps[i].nginx_config,
                         i == 0 ? "#324 exact-first nginx config" : "#324 root-first nginx config");
                dump_log(temps[i].nginx_log,
                         i == 0 ? "#324 exact-first nginx log" : "#324 root-first nginx log");
            } else {
                dump_wire(i == 2 ? "#324 exact-first generated ordinary RUT source"
                                 : "#324 root-first generated ordinary RUT source",
                          std::vector<char>(generated_sources[i - 2u].begin(),
                                            generated_sources[i - 2u].end()));
                dump_log(temps[i].source, "#324 destroyed generated source remnant");
                dump_log(temps[i].rut_log, "#324 generated RUT runtime log");
                dump_log(temps[i].rut_access_log, "#324 generated RUT access log");
            }
        }
    };
    if (containers[0] == containers[1] ||
        !capture_pinned_exact_local_return204_order(ports[0],
                                                    ports[1],
                                                    temps[0],
                                                    containers[0],
                                                    true,
                                                    query_target,
                                                    observations[0],
                                                    error) ||
        !capture_pinned_exact_local_return204_order(ports[2],
                                                    ports[3],
                                                    temps[1],
                                                    containers[1],
                                                    false,
                                                    query_target,
                                                    observations[1],
                                                    error) ||
        !capture_generated_exact_local_return204_order(ports[4],
                                                       ports[5],
                                                       temps[2],
                                                       rut_path,
                                                       true,
                                                       query_target,
                                                       observations[2],
                                                       generated_sources[0],
                                                       error) ||
        !capture_generated_exact_local_return204_order(ports[6],
                                                       ports[7],
                                                       temps[3],
                                                       rut_path,
                                                       false,
                                                       query_target,
                                                       observations[3],
                                                       generated_sources[1],
                                                       error)) {
        dump_all();
        return false;
    }

    for (size_t i = 0; i < 4; i++) {
        if (observations[i].temp_path.empty() || observations[i].config_path.empty() ||
            observations[i].log_path.empty() || observations[i].container_name.empty()) {
            error = "#324 one semantic side did not publish its complete resource identity";
            dump_all();
            return false;
        }
        for (size_t j = i + 1u; j < 4; j++) {
            if (observations[i].temp_path == observations[j].temp_path ||
                observations[i].config_path == observations[j].config_path ||
                observations[i].log_path == observations[j].log_path ||
                observations[i].container_name == observations[j].container_name ||
                observations[i].local_wire.data() == observations[j].local_wire.data() ||
                observations[i].fallback_wire.data() == observations[j].fallback_wire.data()) {
                error = "#324 four semantic sides did not retain independent process/resources";
                dump_all();
                return false;
            }
        }
    }

    const auto replace_once =
        [](std::string& text, const std::string& needle, const char* replacement) {
            const size_t first = text.find(needle);
            if (first == std::string::npos ||
                text.find(needle, first + needle.size()) != std::string::npos)
                return false;
            text.replace(first, needle.size(), replacement);
            return true;
        };
    std::string canonical_source[2] = {generated_sources[0], generated_sources[1]};
    if (!replace_once(
            canonical_source[0], "listen :" + std::to_string(ports[4]), "listen :FRONTEND") ||
        !replace_once(
            canonical_source[0], "127.0.0.1:" + std::to_string(ports[5]), "127.0.0.1:BACKEND") ||
        !replace_once(
            canonical_source[1], "listen :" + std::to_string(ports[6]), "listen :FRONTEND") ||
        !replace_once(
            canonical_source[1], "127.0.0.1:" + std::to_string(ports[7]), "127.0.0.1:BACKEND") ||
        canonical_source[0] != canonical_source[1]) {
        error = "#324 declaration order changed generated RUT beyond verified dynamic bindings";
        dump_all();
        return false;
    }

    const auto normalized = [](const std::vector<char>& wire, std::vector<char>& result) {
        result = wire;
        return normalize_date(result);
    };
    std::vector<char> local[4];
    std::vector<char> fallback[4];
    const std::vector<char> expected_local(kExactLocalReturn204ResponseNormalized,
                                           kExactLocalReturn204ResponseNormalized + 105u);
    const std::vector<char> expected_fallback(
        kSuccessResponseNormalized,
        kSuccessResponseNormalized + sizeof(kSuccessResponseNormalized) - 1u);
    for (size_t i = 0; i < 4; i++) {
        if (!normalized(observations[i].local_wire, local[i]) ||
            !normalized(observations[i].fallback_wire, fallback[i]) || local[i] != expected_local ||
            fallback[i] != expected_fallback || observations[i].local_accepts != 0 ||
            observations[i].local_requests != 0 || observations[i].local_sends != 0 ||
            observations[i].fallback_accepts != 1 || observations[i].fallback_requests != 1 ||
            observations[i].fallback_sends != 1 || observations[i].fallback_history.size() != 1u ||
            observations[i].local_access != 1 || observations[i].fallback_access != 1) {
            error = "#324 one side lacked exact wire/upstream/access evidence";
            dump_all();
            return false;
        }
    }
    if (local[0] != local[2] || local[1] != local[3] || local[0] != local[1] ||
        local[2] != local[3] || fallback[0] != fallback[2] || fallback[1] != fallback[3] ||
        fallback[0] != fallback[1] || fallback[2] != fallback[3]) {
        error = "#324 nginx/generated-RUT pair or declaration order changed a normalized wire";
        dump_all();
        return false;
    }

    const auto canonical_backend = [](const std::vector<char>& wire) {
        std::string result(wire.begin(), wire.end());
        static constexpr char kPrefix[] = "\r\nHost: 127.0.0.1:";
        const size_t begin = result.find(kPrefix);
        if (begin == std::string::npos || result.find(kPrefix, begin + 1u) != std::string::npos)
            return std::string{};
        const size_t digits = begin + sizeof(kPrefix) - 1u;
        const size_t end = result.find("\r\n", digits);
        if (end == std::string::npos) return std::string{};
        result.replace(digits, end - digits, "BACKEND");
        return result;
    };
    const std::string expected_history = canonical_backend(observations[0].fallback_history[0]);
    if (expected_history.empty()) {
        error = "#324 could not narrowly canonicalize the verified nginx backend port";
        dump_all();
        return false;
    }
    for (size_t i = 1; i < 4; i++) {
        if (canonical_backend(observations[i].fallback_history[0]) != expected_history) {
            error = "#324 four byte-verified upstream histories differed after port-only binding";
            dump_all();
            return false;
        }
    }
    return true;
}

static std::string make_bounded_no_content_path_fragment(u16 frontend_port,
                                                         u16 backend_port,
                                                         bool exact_first) {
    const std::string exact_location = "  location = /healthz { return 204; }\n";
    const std::string root_location =
        "  location / { proxy_pass http://127.0.0.1:" + std::to_string(backend_port) + "; }\n";
    return "server {\n"
           "  listen " +
           std::to_string(frontend_port) + ";\n" +
           (exact_first ? exact_location + root_location : root_location + exact_location) + "}\n";
}

static size_t count_text(const std::string& text, const std::string& needle) {
    if (needle.empty()) return 0u;
    size_t count = 0u;
    for (size_t offset = 0u;;) {
        offset = text.find(needle, offset);
        if (offset == std::string::npos) return count;
        count++;
        offset += needle.size();
    }
}

static bool validate_bounded_no_content_generated_source(const std::string& source,
                                                         u16 frontend_port,
                                                         u16 backend_port,
                                                         std::string& error) {
    const std::string exact_tuple =
        "route exact slash_normalized GET \"/healthz\" { return local_response({\n"
        "  version: \"HTTP/1.1\", status: 204, reason: \"No Content\", server: "
        "\"nginx/1.29.7\",\n"
        "  date: \"current\", content_type: \"\", connection: \"request\",\n"
        "  head_mode: \"suppress_body\", body: b\"\"\n"
        "}) }\n";
    const std::string backend =
        "upstream nginx_upstream at \"127.0.0.1:" + std::to_string(backend_port) + "\"";
    const std::string listener = "listen :" + std::to_string(frontend_port) + "\n";
    if (count_text(source, exact_tuple) != 1u ||
        count_text(source, "route exact slash_normalized GET \"/healthz\"") != 1u ||
        count_text(source, "route exact GET \"/healthz\"") != 0u ||
        count_text(source, "route exact ") != 1u ||
        count_text(source, "route HEAD \"/\" {") != 1u ||
        count_text(source, "route GET \"/\" {") != 1u ||
        count_text(source, "route \"/\" {") != 1u ||
        count_text(source, "return forward(nginx_upstream") != 3u ||
        count_text(source, backend) != 1u || count_text(source, listener) != 1u ||
        source.find("?x=1") != std::string::npos ||
        source.find("healthz-return204.example") != std::string::npos ||
        source.find("query-return204.example") != std::string::npos ||
        source.find("proxy_pass") != std::string::npos ||
        source.find("nginx.conf") != std::string::npos ||
        source.find("propagat") != std::string::npos ||
        source.find("NoContent204") != std::string::npos ||
        source.find("strict_local_response") != std::string::npos ||
        source.find("profile") != std::string::npos ||
        source.find("return 204") != std::string::npos ||
        source.find("nginx::") != std::string::npos ||
        source.find("nginx_compat") != std::string::npos) {
        error =
            "#328 generated source was not one public /healthz NoContent204 tuple plus the "
            "canonical ordinary root-forward route set";
        return false;
    }
    return true;
}

static bool parse_bounded_no_content_rut_access_log(const std::string& contents,
                                                    const size_t request_sizes[5],
                                                    std::string& error) {
    static constexpr const char* kTargets[] = {
        "/healthz", "/healthz?x=1", "/healthz/", "/health", "/"};
    std::vector<std::string> records;
    if (!split_exact_complete_log(
            contents, 5u, "converter-generated #328 access log", records, error))
        return false;
    for (size_t i = 0u; i < 5u; i++) {
        std::vector<std::string> fields;
        const size_t expected_fields = i < 2u ? 9u : 11u;
        const size_t expected_status = i < 2u ? 204u : 200u;
        const size_t expected_response = i < 2u ? 105u : 118u;
        if (!split_space_fields(records[i], fields) || fields.size() != expected_fields ||
            !exact_log_timestamp(fields[0]) || fields[1] != "GET" || fields[2] != kTargets[i] ||
            fields[3] != std::to_string(expected_status) ||
            !decimal_field_equals(fields[3], expected_status) || !exact_log_duration(fields[4]) ||
            fields[5] != std::to_string(request_sizes[i]) ||
            !decimal_field_equals(fields[5], request_sizes[i]) ||
            fields[6] != std::to_string(expected_response) ||
            !decimal_field_equals(fields[6], expected_response) || fields[7] != "127.0.0.1" ||
            (i < 2u && fields[8] != "s=0") ||
            (i >= 2u && (fields[8] != "nginx_upstream" || !exact_log_duration(fields[9]) ||
                         fields[10] != "s=0"))) {
            error = "converter-generated #328 access record " + std::to_string(i + 1u) +
                    " lost target/order/status/size/outcome: " + records[i];
            return false;
        }
    }
    return true;
}

static bool canonicalize_unique_port(std::string& source,
                                     const std::string& needle,
                                     const char* replacement) {
    const size_t offset = source.find(needle);
    if (offset == std::string::npos ||
        source.find(needle, offset + needle.size()) != std::string::npos)
        return false;
    source.replace(offset, needle.size(), replacement);
    return true;
}

static bool run_bounded_no_content_differential_parser_self_checks(std::string& error) {
    static constexpr size_t kSizes[] = {77u, 81u, 49u, 47u, 41u};
    static constexpr const char* kTargets[] = {
        "/healthz", "/healthz?x=1", "/healthz/", "/health", "/"};
    std::string access;
    for (size_t i = 0u; i < 5u; i++) {
        access += "2026-08-26T21:13:05.248Z GET " + std::string(kTargets[i]) + " " +
                  (i < 2u ? "204" : "200") + " 361us " + std::to_string(kSizes[i]) + " " +
                  (i < 2u ? "105" : "118") + " 127.0.0.1" +
                  (i < 2u ? " s=0\n" : " nginx_upstream 243us s=0\n");
    }
    const auto rejects_access = [&](const std::string& value) {
        std::string detail;
        return !parse_bounded_no_content_rut_access_log(value, kSizes, detail);
    };
    const auto replace = [](std::string value, const std::string& from, const std::string& to) {
        const size_t offset = value.find(from);
        if (offset == std::string::npos) return std::string{};
        value.replace(offset, from.size(), to);
        return value;
    };
    std::string swapped = access;
    const size_t first = swapped.find('\n');
    const size_t second = swapped.find('\n', first + 1u);
    swapped.replace(
        0u, second + 1u, access.substr(first + 1u, second - first) + access.substr(0u, first + 1u));
    if (!parse_bounded_no_content_rut_access_log(access, kSizes, error) ||
        !rejects_access(access + access.substr(0u, first + 1u)) ||
        !rejects_access(access.substr(0u, access.size() - 1u)) || !rejects_access(swapped) ||
        !rejects_access(replace(access, " 204 ", " 200 ")) ||
        !rejects_access(replace(access, " 105 ", " 106 ")) ||
        !rejects_access(replace(access, " /healthz/ ", " /healthz ")) ||
        !rejects_access(replace(access, " 77 105 ", " 999999999999999999999999999999999 105 ")) ||
        !rejects_access(replace(access, " 204 ", " 0204 ")) ||
        !rejects_access(replace(access, " nginx_upstream ", " other_upstream ")) ||
        !rejects_access(
            replace(access, " nginx_upstream 243us ", " nginx_upstream not-a-duration ")) ||
        !rejects_access(replace(access, " s=0\n", " extra s=0\n")) ||
        !rejects_access(replace(access, " s=0\n", " s=1\n"))) {
        error = "#328 generated access parser mutation self-check failed";
        return false;
    }

    std::string source = make_bounded_no_content_path_fragment(54320u, 54321u, true);
    const auto parsed = rut::nginx::parse({source.data(), static_cast<u32>(source.size())});
    if (!parsed) {
        error = "#328 source self-check fixture did not parse";
        return false;
    }
    const auto lowered = rut::nginx::lower_to_rut(parsed.value());
    if (!lowered) {
        error = "#328 source self-check fixture did not lower";
        return false;
    }
    const rut::Str view = lowered.value().view();
    const std::string canonical(view.ptr, view.len);
    const auto rejects_source = [&](std::string value) {
        std::string detail;
        return !validate_bounded_no_content_generated_source(value, 54320u, 54321u, detail);
    };
    if (!validate_bounded_no_content_generated_source(canonical, 54320u, 54321u, error) ||
        !rejects_source(canonical + "route exact GET \"/healthz?x=1\" { return response() }\n") ||
        !rejects_source(replace(canonical,
                                "route exact slash_normalized GET \"/healthz\"",
                                "route exact GET \"/healthz\"")) ||
        !rejects_source(canonical + "if host == \"healthz-return204.example\" {}\n") ||
        !rejects_source(replace(canonical, "status: 204", "status: 200"))) {
        error = "#328 generated source mutation self-check failed";
        return false;
    }
    std::string normalized = canonical;
    if (!canonicalize_unique_port(normalized, "listen :54320", "listen :FRONTEND") ||
        !canonicalize_unique_port(normalized, "127.0.0.1:54321", "127.0.0.1:BACKEND")) {
        error = "#328 source port normalization valid self-check failed";
        return false;
    }
    std::string missing = canonical;
    missing.erase(missing.find("listen :54320"), strlen("listen :54320"));
    std::string duplicate = canonical + "listen :54320\n";
    if (canonicalize_unique_port(missing, "listen :54320", "listen :FRONTEND") ||
        canonicalize_unique_port(duplicate, "listen :54320", "listen :FRONTEND")) {
        error = "#328 missing/duplicate port normalization mutation was accepted";
        return false;
    }
    return true;
}

static bool capture_generated_bounded_no_content_path_order(
    u16 frontend_port,
    u16 backend_port,
    TempDir& temp,
    const char* rut_path,
    bool exact_first,
    BoundedExactLocalPathOracleObservation& observation,
    std::string& generated_source,
    std::string& error,
    int* frontend_reservation,
    int* backend_reservation) {
    static constexpr const char* kTargets[] = {
        "/healthz", "/healthz?x=1", "/healthz/", "/health", "/"};
    if (rut_path == nullptr || rut_path[0] != '/' || access(rut_path, X_OK) != 0) {
        error = "converter-generated #328 differential requires an executable absolute RUT path";
        return false;
    }
    std::string fragment =
        make_bounded_no_content_path_fragment(frontend_port, backend_port, exact_first);
    const auto parsed = rut::nginx::parse({fragment.data(), static_cast<u32>(fragment.size())});
    if (!parsed) {
        error = "#328 accepted nginx fragment did not traverse the independent parser";
        return false;
    }
    const auto& server = parsed.value();
    const auto& root = server.location;
    const auto& proxy = root.proxy_pass;
    const auto& exact = server.exact_no_content_return;
    const auto& response = exact.response;
    const size_t root_location = fragment.find("location / {");
    const size_t root_path = fragment.find('/', root_location);
    const size_t exact_location = fragment.find("location = /healthz");
    const size_t exact_path = fragment.find("/healthz", exact_location);
    const size_t return_offset = fragment.find("return", exact_location);
    const size_t status_offset = fragment.find("204", return_offset);
    const size_t semicolon = fragment.find(';', status_offset);
    const size_t exact_end = fragment.find('}', semicolon);
    const uintptr_t source_base = reinterpret_cast<uintptr_t>(fragment.data());
    const auto same_source = [&](rut::Str value, rut::Span span) {
        return value.ptr != nullptr && span.end >= span.start &&
               span.end - span.start == value.len &&
               reinterpret_cast<uintptr_t>(value.ptr) - span.start == source_base;
    };
    if (root_location == std::string::npos || root_path == std::string::npos ||
        exact_location == std::string::npos || exact_path == std::string::npos ||
        return_offset == std::string::npos || status_offset == std::string::npos ||
        semicolon == std::string::npos || exact_end == std::string::npos ||
        server.span.start != 0u || server.span.end != fragment.size() - 1u ||
        server.listen.port != frontend_port || !root.path.eq(rut::lit_str("/")) ||
        root.path.ptr != fragment.data() + root_path || !same_source(root.path, root.path_span) ||
        proxy.has_uri || proxy.address[0] != 127u || proxy.address[1] != 0u ||
        proxy.address[2] != 0u || proxy.address[3] != 1u || proxy.port != backend_port ||
        !exact.present || !exact.path.eq(rut::lit_str("/healthz")) ||
        exact.path.ptr != fragment.data() + exact_path ||
        !same_source(exact.path, exact.path_span) || exact.span.start != exact_location ||
        exact.span.end != exact_end + 1u || response.status != 204u ||
        response.status_span.start != status_offset ||
        response.status_span.end != status_offset + 3u || response.span.start != return_offset ||
        response.span.end != semicolon + 1u ||
        memcmp(fragment.data() + response.status_span.start, "204", 3u) != 0 ||
        server.exact_local_return.present || server.exact_absolute_redirect.present ||
        exact.span.start >= exact.path_span.start || exact.path_span.end > response.span.start ||
        response.span.end >= exact.span.end || root.span.start != root_location) {
        error = "#328 fragment lost borrowed /healthz path/status provenance or root fallback";
        return false;
    }
    const auto lowered = rut::nginx::lower_to_rut(server);
    if (!lowered) {
        error = "#328 genuine bounded no-content model failed public ordinary-RUT lowering";
        return false;
    }
    const rut::Str output = lowered.value().view();
    generated_source.assign(output.ptr, output.len);
    if (!validate_bounded_no_content_generated_source(
            generated_source, frontend_port, backend_port, error) ||
        !write_file(temp.source, output.ptr, output.len))
        return false;
    std::fill(fragment.begin(), fragment.end(), '\0');
    if (!std::all_of(fragment.begin(), fragment.end(), [](char byte) { return byte == '\0'; })) {
        error = "#328 failed to destroy borrowed nginx fragment after parse/lower";
        return false;
    }

    observation = BoundedExactLocalPathOracleObservation{};
    observation.order = exact_first ? "generated-exact-before-root" : "generated-root-before-exact";
    observation.temp_path = temp.path;
    observation.config_path = temp.source;
    observation.log_path = temp.rut_log;
    observation.access_path = temp.rut_access_log;
    observation.process_identity =
        std::string(rut_path) + " " + temp.source + " listen:" + std::to_string(frontend_port);
    observation.wires.resize(5u);
    std::string requests[5];
    size_t request_sizes[5]{};
    for (size_t i = 0u; i < 5u; i++) {
        requests[i] = std::string("GET ") + kTargets[i] +
                      " HTTP/1.1\r\nHost: healthz-return204.example\r\nConnection: close\r\n\r\n";
        request_sizes[i] = requests[i].size();
        const size_t header = requests[i].find("\r\n\r\n");
        if (requests[i].rfind(std::string("GET ") + kTargets[i] + " HTTP/1.1\r\n", 0u) != 0u ||
            requests[i].find('#') != std::string::npos ||
            requests[i].find("\r\nContent-Length:") != std::string::npos ||
            requests[i].find("\r\nTransfer-Encoding:") != std::string::npos ||
            requests[i].find("\r\nTE:") != std::string::npos ||
            requests[i].find("\r\nExpect:") != std::string::npos ||
            requests[i].find("\r\nUpgrade:") != std::string::npos || header == std::string::npos ||
            header + 4u != requests[i].size()) {
            error = "#328 generated request escaped the bounded fresh bodyless H1.1 domain";
            return false;
        }
    }

    const auto recorder_live = [](const Recorder& recorder) {
        return recorder.running.load(std::memory_order_acquire) &&
               recorder.thread_alive.load(std::memory_order_acquire) &&
               !recorder.listener_failed.load(std::memory_order_acquire);
    };
    struct RecorderGuard {
        Recorder* value = nullptr;
        ~RecorderGuard() {
            if (value != nullptr) value->stop();
        }
    };
    ChildGuard runtime;
    if (frontend_reservation != nullptr && *frontend_reservation >= 0) {
        close(*frontend_reservation);
        *frontend_reservation = -1;
    }
    if (!spawn_child({rut_path,
                      temp.source,
                      "--shards",
                      "1",
                      "--no-pin",
                      "--drain",
                      "0",
                      "--access-log",
                      temp.rut_access_log},
                     temp.rut_log,
                     runtime.child) ||
        !wait_ready(frontend_port, runtime.child, error)) {
        if (error.empty()) error = "failed to start converter-generated public RUT for #328";
        return false;
    }
    const std::string loaded = "Loaded program: " + temp.source + " (opt O2)\n";
    const std::string listener =
        "Listening on port " + std::to_string(frontend_port) + " with 1 shard(s)";
    const auto ready_deadline = std::chrono::steady_clock::now() + std::chrono::seconds(2);
    while ((!log_contains(temp.rut_log, loaded.c_str()) ||
            !log_contains(temp.rut_log, "Backend: io_uring\n") ||
            !log_contains(temp.rut_log, listener.c_str())) &&
           std::chrono::steady_clock::now() < ready_deadline) {
        if (poll_child(runtime.child)) {
            error = "converter-generated #328 RUT exited before load/io_uring/listener readiness";
            return false;
        }
        usleep(1000);
    }
    if (!log_contains(temp.rut_log, loaded.c_str()) ||
        !log_contains(temp.rut_log, "Backend: io_uring\n") ||
        !log_contains(temp.rut_log, listener.c_str())) {
        error = "converter-generated #328 RUT lacked exact public readiness evidence";
        return false;
    }
    static constexpr char kDestroyed[] = "destroyed-after-328-public-load\n";
    if (!write_file(temp.source, kDestroyed, sizeof(kDestroyed) - 1u)) {
        error = "failed to overwrite #328 generated source after public load";
        return false;
    }
    std::string destroyed;
    if (!read_exact_return204_log(
            temp.source, "#328 destroyed generated source", destroyed, error) ||
        destroyed != kDestroyed) {
        error = "#328 generated source overwrite was not exact before behavioral requests";
        return false;
    }

    const auto wait_live = [&](Recorder& recorder, const char* phase) {
        const auto deadline = std::chrono::steady_clock::now() + std::chrono::seconds(2);
        while (std::chrono::steady_clock::now() < deadline) {
            if (poll_child(runtime.child) || !recorder.running.load(std::memory_order_acquire) ||
                recorder.listener_failed.load(std::memory_order_acquire)) {
                error = std::string("#328 RUT/recorder failed before ") + phase + " readiness";
                return false;
            }
            if (recorder.thread_alive.load(std::memory_order_acquire)) return true;
            usleep(1000);
        }
        error = std::string("#328 recorder readiness timed out: ") + phase;
        return false;
    };
    const auto observe = [&](Recorder& recorder,
                             u32 expected,
                             const char* phase,
                             std::chrono::milliseconds duration) {
        const auto deadline = std::chrono::steady_clock::now() + duration;
        for (;;) {
            if (poll_child(runtime.child) || !recorder_live(recorder) ||
                recorder.accepted.load(std::memory_order_acquire) != expected ||
                recorder.requests.load(std::memory_order_acquire) != expected ||
                recorder.response_send_all_calls.load(std::memory_order_acquire) != expected) {
                error = std::string("#328 unexpected process/upstream state during ") + phase;
                return false;
            }
            if (std::chrono::steady_clock::now() >= deadline) return true;
            usleep(5000);
        }
    };
    const auto request = [&](size_t index, const char* expected) {
        struct ClientGuard {
            int fd = -1;
            ~ClientGuard() {
                if (fd >= 0) close(fd);
            }
        } client{connect_once(frontend_port)};
        std::string detail;
        if (client.fd < 0 || !send_all(client.fd, requests[index].data(), requests[index].size()) ||
            !(index < 2u ? read_head_response(client.fd, observation.wires[index], detail)
                         : read_response(client.fd, observation.wires[index], detail)) ||
            !read_eof(client.fd, detail) ||
            !validate_exact_normalized_response(observation.wires[index], expected, detail)) {
            error = std::string("#328 generated vector ") + kTargets[index] +
                    " exact response/EOF failed: " + detail;
            return false;
        }
        if (poll_child(runtime.child)) {
            error = std::string("#328 generated RUT exited after vector ") + kTargets[index] +
                    " (" + child_status_description(runtime.child) + ")";
            return false;
        }
        return true;
    };

    Recorder zero;
    RecorderGuard zero_guard{&zero};
    zero.observe_extra_requests_until_stop = true;
    if (backend_reservation != nullptr && *backend_reservation >= 0) {
        close(*backend_reservation);
        *backend_reservation = -1;
    }
    if (!zero.setup(backend_port)) {
        error = "#328 generated local recorder could not bind its reserved backend port";
        return false;
    }
    if (!wait_live(zero, "local") ||
        !observe(zero, 0u, "pre-local zero window", std::chrono::milliseconds(250)))
        return false;
    for (size_t i = 0u; i < 2u; i++) {
        if (!request(i, kExactLocalReturn204ResponseNormalized) ||
            !observe(zero, 0u, "local vector zero window", std::chrono::milliseconds(250)))
            return false;
        const std::string text(observation.wires[i].begin(), observation.wires[i].end());
        if (observation.wires[i].size() != 105u ||
            header_end(observation.wires[i]) != observation.wires[i].size() ||
            text.find("\r\nContent-Type:") != std::string::npos ||
            text.find("\r\nContent-Length:") != std::string::npos ||
            text.find("\r\nTransfer-Encoding:") != std::string::npos) {
            error = "#328 generated strict 204 gained framing, representation, body, or tail";
            return false;
        }
    }
    if (!observe(zero, 0u, "post-local zero window", std::chrono::milliseconds(500))) return false;
    zero.stop();
    zero_guard.value = nullptr;
    observation.local_accepts = zero.accepted.load(std::memory_order_acquire);
    observation.local_requests = zero.requests.load(std::memory_order_acquire);
    observation.local_sends = zero.response_send_all_calls.load(std::memory_order_acquire);
    observation.local_history = zero.history;
    if (zero.thread_alive.load(std::memory_order_acquire) ||
        zero.listener_failed.load(std::memory_order_acquire) || observation.local_accepts != 0u ||
        observation.local_requests != 0u || observation.local_sends != 0u ||
        zero.response_send_succeeded.load(std::memory_order_acquire) || !zero.history.empty() ||
        !zero.request.empty()) {
        error = "#328 generated local recorder did not settle at exact zero with empty history";
        return false;
    }

    Recorder fallback;
    RecorderGuard fallback_guard{&fallback};
    fallback.observe_extra_requests_until_stop = true;
    if (!fallback.setup(backend_port, 3u, kBackendResponse, sizeof(kBackendResponse) - 1u)) {
        error = "#328 generated fallback recorder could not bind the released backend port";
        return false;
    }
    if (!wait_live(fallback, "fallback") ||
        !observe(fallback, 0u, "pre-fallback zero window", std::chrono::milliseconds(100)))
        return false;
    for (size_t i = 2u; i < 5u; i++) {
        if (!request(i, kSuccessResponseNormalized)) return false;
        const auto deadline = std::chrono::steady_clock::now() + std::chrono::seconds(2);
        const u32 expected = static_cast<u32>(i - 1u);
        while (std::chrono::steady_clock::now() < deadline) {
            const u32 accepts = fallback.accepted.load(std::memory_order_acquire);
            const u32 requests_seen = fallback.requests.load(std::memory_order_acquire);
            const u32 sends = fallback.response_send_all_calls.load(std::memory_order_acquire);
            if (poll_child(runtime.child) || !recorder_live(fallback) || accepts > expected ||
                requests_seen > expected || sends > expected) {
                error = "#328 generated fallback observed retry/extra request";
                return false;
            }
            if (accepts == expected && requests_seen == expected && sends == expected) break;
            usleep(1000);
        }
        if (fallback.accepted.load(std::memory_order_acquire) != expected ||
            fallback.requests.load(std::memory_order_acquire) != expected ||
            fallback.response_send_all_calls.load(std::memory_order_acquire) != expected) {
            error = "#328 generated fallback timed out awaiting the complete upstream triplet";
            return false;
        }
        if (!observe(fallback, expected, "ordered fallback count", std::chrono::milliseconds(100)))
            return false;
    }
    if (!observe(fallback, 3u, "no-fourth fallback window", std::chrono::milliseconds(500)) ||
        !stop_child(runtime.child)) {
        error = "#328 generated RUT did not survive through controlled shutdown";
        return false;
    }
    fallback.stop();
    fallback_guard.value = nullptr;
    observation.forward_accepts = fallback.accepted.load(std::memory_order_acquire);
    observation.forward_requests = fallback.requests.load(std::memory_order_acquire);
    observation.forward_sends = fallback.response_send_all_calls.load(std::memory_order_acquire);
    observation.forward_history = fallback.history;
    if (fallback.thread_alive.load(std::memory_order_acquire) ||
        fallback.listener_failed.load(std::memory_order_acquire) ||
        observation.forward_accepts != 3u || observation.forward_requests != 3u ||
        observation.forward_sends != 3u || !fallback.response_send_succeeded.load() ||
        !fallback.response_clean_shutdown.load() || !fallback.response_connection_closed.load() ||
        observation.forward_history.size() != 3u) {
        error = "#328 generated fallback recorder lifecycle/count was incomplete";
        return false;
    }
    for (size_t i = 0u; i < 5u; i++) observation.access_records[i] = 1u;
    if (!validate_bounded_no_content_path_observation(observation, backend_port, error))
        return false;

    std::string access_contents;
    std::string runtime_contents;
    if (!read_exact_return204_log(
            temp.rut_access_log, "converter-generated #328 access log", access_contents, error) ||
        !parse_bounded_no_content_rut_access_log(access_contents, request_sizes, error) ||
        !read_exact_return204_log(
            temp.rut_log, "converter-generated #328 runtime log", runtime_contents, error) ||
        !parse_exact_return204_runtime_log(runtime_contents, temp.source, listener, error))
        return false;
    if (request_sizes[2] == observation.forward_history[0].size()) {
        error = "#328 fixture no longer distinguishes downstream and rebuilt request sizes";
        return false;
    }
    size_t swapped_sizes[5];
    std::copy(std::begin(request_sizes), std::end(request_sizes), std::begin(swapped_sizes));
    swapped_sizes[2] = observation.forward_history[0].size();
    std::string swapped_size_error;
    if (parse_bounded_no_content_rut_access_log(
            access_contents, swapped_sizes, swapped_size_error)) {
        error = "#328 access parser accepted rebuilt upstream field 5";
        return false;
    }
    return true;
}

static std::vector<std::vector<char>> canonicalize_bounded_backend_history(
    const std::vector<std::vector<char>>& history) {
    std::vector<std::vector<char>> result = history;
    for (std::vector<char>& request : result) {
        std::string text(request.begin(), request.end());
        static constexpr char kMarker[] = "\r\nHost: 127.0.0.1:";
        const size_t begin = text.find(kMarker);
        if (begin == std::string::npos ||
            text.find(kMarker, begin + sizeof(kMarker) - 1u) != std::string::npos)
            return {};
        const size_t digits = begin + sizeof(kMarker) - 1u;
        const size_t end = text.find("\r\n", digits);
        if (end == std::string::npos || end == digits) return {};
        for (size_t i = digits; i < end; i++)
            if (text[i] < '0' || text[i] > '9') return {};
        text.replace(digits, end - digits, "BACKEND");
        request.assign(text.begin(), text.end());
    }
    return result;
}

static bool validate_bounded_no_content_four_way(
    const BoundedExactLocalPathOracleObservation observations[4],
    const std::string generated_sources[2],
    const u16 ports[8],
    std::string& error) {
    for (size_t i = 0u; i < 8u; i++) {
        if (ports[i] == 0u) {
            error = "#328 four-way validator received a zero dynamic port";
            return false;
        }
        for (size_t j = i + 1u; j < 8u; j++) {
            if (ports[i] == ports[j]) {
                error = "#328 four-way validator received duplicate dynamic ports";
                return false;
            }
        }
    }
    for (size_t i = 0u; i < 4u; i++) {
        if (!validate_bounded_no_content_path_observation(
                observations[i], ports[i * 2u + 1u], error))
            return false;
        if (observations[i].temp_path.empty() || observations[i].config_path.empty() ||
            observations[i].log_path.empty() || observations[i].access_path.empty() ||
            observations[i].process_identity.empty()) {
            error = "#328 one semantic side lacked complete resource identity";
            return false;
        }
        for (size_t j = i + 1u; j < 4u; j++) {
            if (observations[i].temp_path == observations[j].temp_path ||
                observations[i].config_path == observations[j].config_path ||
                observations[i].log_path == observations[j].log_path ||
                observations[i].access_path == observations[j].access_path ||
                observations[i].process_identity == observations[j].process_identity ||
                observations[i].wires.data() == observations[j].wires.data()) {
                error = "#328 four semantic sides shared a process/resource identity";
                return false;
            }
        }
    }
    std::string canonical[2] = {generated_sources[0], generated_sources[1]};
    if (!canonicalize_unique_port(
            canonical[0], "listen :" + std::to_string(ports[4]), "listen :FRONTEND") ||
        !canonicalize_unique_port(
            canonical[0], "127.0.0.1:" + std::to_string(ports[5]), "127.0.0.1:BACKEND") ||
        !canonicalize_unique_port(
            canonical[1], "listen :" + std::to_string(ports[6]), "listen :FRONTEND") ||
        !canonicalize_unique_port(
            canonical[1], "127.0.0.1:" + std::to_string(ports[7]), "127.0.0.1:BACKEND") ||
        canonical[0] != canonical[1]) {
        error = "#328 declaration order changed source or port normalization was not exact";
        return false;
    }
    const auto expected_history =
        canonicalize_bounded_backend_history(observations[0].forward_history);
    if (expected_history.size() != 3u) {
        error = "#328 could not canonicalize the exact three-request backend history";
        return false;
    }
    for (size_t side = 0u; side < 4u; side++) {
        if (canonicalize_bounded_backend_history(observations[side].forward_history) !=
            expected_history) {
            error = "#328 four sides differed in ordered port-canonicalized fallback history";
            return false;
        }
    }
    for (size_t vector = 0u; vector < 5u; vector++) {
        std::vector<char> baseline = observations[0].wires[vector];
        if (!normalize_date(baseline)) {
            error = "#328 pinned baseline Date normalization failed";
            return false;
        }
        for (size_t side = 1u; side < 4u; side++) {
            std::vector<char> candidate = observations[side].wires[vector];
            if (!normalize_date(candidate) || candidate != baseline) {
                error = "#328 four-side Date-normalized wire mismatch at vector " +
                        std::to_string(vector + 1u);
                return false;
            }
        }
    }
    return true;
}

static bool run_bounded_no_content_four_way_self_checks(std::string& error) {
    u16 ports[8] = {54310u, 54311u, 54312u, 54313u, 54314u, 54315u, 54316u, 54317u};
    BoundedExactLocalPathOracleObservation values[4];
    static constexpr char kDate[] = "Wed, 26 Aug 2026 23:57:18 GMT";
    for (size_t side = 0u; side < 4u; side++) {
        values[side].order = std::to_string(side);
        values[side].temp_path = "/tmp/328-" + std::to_string(side);
        values[side].config_path = values[side].temp_path + "/config";
        values[side].log_path = values[side].temp_path + "/log";
        values[side].access_path = values[side].temp_path + "/access";
        values[side].process_identity = "process-" + std::to_string(side);
        for (size_t vector = 0u; vector < 5u; vector++) {
            const char* expected =
                vector < 2u ? kExactLocalReturn204ResponseNormalized : kSuccessResponseNormalized;
            const size_t size = vector < 2u ? 105u : sizeof(kSuccessResponseNormalized) - 1u;
            std::vector<char> wire(expected, expected + size);
            const std::string marker(29u, 'X');
            const auto date = std::search(wire.begin(), wire.end(), marker.begin(), marker.end());
            if (date != wire.end()) std::copy_n(kDate, 29u, date);
            values[side].wires.push_back(std::move(wire));
            values[side].access_records[vector] = 1u;
        }
        values[side].forward_accepts = 3u;
        values[side].forward_requests = 3u;
        values[side].forward_sends = 3u;
        for (const char* target : {"/healthz/", "/health", "/"}) {
            const std::string request =
                std::string("GET ") + target +
                " HTTP/1.1\r\nHost: 127.0.0.1:" + std::to_string(ports[side * 2u + 1u]) +
                "\r\n\r\n";
            values[side].forward_history.emplace_back(request.begin(), request.end());
        }
    }
    std::string sources[2];
    for (size_t i = 0u; i < 2u; i++) {
        std::string fragment =
            make_bounded_no_content_path_fragment(ports[4u + i * 2u], ports[5u + i * 2u], i == 0u);
        const auto parsed = rut::nginx::parse({fragment.data(), static_cast<u32>(fragment.size())});
        if (!parsed) return false;
        const auto lowered = rut::nginx::lower_to_rut(parsed.value());
        if (!lowered) return false;
        const rut::Str view = lowered.value().view();
        sources[i].assign(view.ptr, view.len);
    }
    if (!validate_bounded_no_content_four_way(values, sources, ports, error)) return false;
    const auto rejects = [&](BoundedExactLocalPathOracleObservation mutated[4],
                             std::string changed_sources[2],
                             const char* name) {
        std::string detail;
        if (!validate_bounded_no_content_four_way(mutated, changed_sources, ports, detail))
            return true;
        error = std::string("#328 four-way mutation accepted: ") + name;
        return false;
    };
    BoundedExactLocalPathOracleObservation mutated[4];
    std::copy(std::begin(values), std::end(values), std::begin(mutated));
    std::string changed[2] = {sources[0], sources[1]};
    mutated[1].temp_path = mutated[0].temp_path;
    if (!rejects(mutated, changed, "resource-alias")) return false;
    std::copy(std::begin(values), std::end(values), std::begin(mutated));
    mutated[1].config_path = mutated[0].config_path;
    if (!rejects(mutated, changed, "source-alias")) return false;
    std::copy(std::begin(values), std::end(values), std::begin(mutated));
    mutated[1].log_path = mutated[0].log_path;
    if (!rejects(mutated, changed, "log-alias")) return false;
    std::copy(std::begin(values), std::end(values), std::begin(mutated));
    mutated[1].access_path = mutated[0].access_path;
    if (!rejects(mutated, changed, "access-alias")) return false;
    std::copy(std::begin(values), std::end(values), std::begin(mutated));
    mutated[1].process_identity = mutated[0].process_identity;
    if (!rejects(mutated, changed, "process-alias")) return false;
    std::copy(std::begin(values), std::end(values), std::begin(mutated));
    mutated[2].wires[0].back() = 'x';
    if (!rejects(mutated, changed, "wire")) return false;
    std::copy(std::begin(values), std::end(values), std::begin(mutated));
    mutated[2].wires[0][9] = '5';
    if (!rejects(mutated, changed, "wire-status")) return false;
    std::copy(std::begin(values), std::end(values), std::begin(mutated));
    mutated[2].access_records[0] = 0u;
    if (!rejects(mutated, changed, "access-missing")) return false;
    std::copy(std::begin(values), std::end(values), std::begin(mutated));
    mutated[2].access_records[0] = 2u;
    if (!rejects(mutated, changed, "access-extra")) return false;
    std::copy(std::begin(values), std::end(values), std::begin(mutated));
    mutated[3].local_requests = 1u;
    if (!rejects(mutated, changed, "local-nonzero")) return false;
    std::copy(std::begin(values), std::end(values), std::begin(mutated));
    mutated[3].local_history.push_back(mutated[3].forward_history[0]);
    if (!rejects(mutated, changed, "local-history")) return false;
    std::copy(std::begin(values), std::end(values), std::begin(mutated));
    mutated[2].forward_history.push_back(mutated[2].forward_history[0]);
    if (!rejects(mutated, changed, "fourth/retry")) return false;
    std::copy(std::begin(values), std::end(values), std::begin(mutated));
    changed[1] += "\n# source mismatch";
    if (!rejects(mutated, changed, "source-mismatch")) return false;
    changed[1] = sources[1];
    u16 duplicate_ports[8];
    std::copy(std::begin(ports), std::end(ports), std::begin(duplicate_ports));
    duplicate_ports[7] = duplicate_ports[0];
    std::string detail;
    if (validate_bounded_no_content_four_way(values, sources, duplicate_ports, detail)) {
        error = "#328 four-way duplicate-port mutation was accepted";
        return false;
    }
    return true;
}

static bool run_converter_bounded_no_content_path_differential(const std::string& container_prefix,
                                                               const char* rut_path,
                                                               std::string& error) {
    struct ReservedPorts {
        int fds[8];

        ReservedPorts() { std::fill(std::begin(fds), std::end(fds), -1); }
        ~ReservedPorts() {
            for (int fd : fds)
                if (fd >= 0) close(fd);
        }

        bool reserve(size_t index, u16& port) {
            const int fd = socket(AF_INET, SOCK_STREAM | SOCK_CLOEXEC, 0);
            if (fd < 0) return false;
            sockaddr_in addr{};
            addr.sin_family = AF_INET;
            addr.sin_addr.s_addr = htonl(INADDR_LOOPBACK);
            addr.sin_port = 0;
            socklen_t len = sizeof(addr);
            if (bind(fd, reinterpret_cast<sockaddr*>(&addr), sizeof(addr)) != 0 ||
                getsockname(fd, reinterpret_cast<sockaddr*>(&addr), &len) != 0 ||
                ntohs(addr.sin_port) == 0u) {
                close(fd);
                return false;
            }
            fds[index] = fd;
            port = ntohs(addr.sin_port);
            return true;
        }
    } reservations;
    u16 ports[8]{};
    for (size_t i = 0u; i < 8u; i++) {
        if (!reservations.reserve(i, ports[i])) {
            error = "#328 could not bind-reserve eight unique four-side ports";
            return false;
        }
    }
    TempDir temps[4];
    for (TempDir& temp : temps) {
        if (!temp.create()) {
            error = "#328 could not create four independent temporary resource trees";
            return false;
        }
    }
    for (size_t i = 0u; i < 4u; i++) {
        for (size_t j = i + 1u; j < 4u; j++) {
            if (strcmp(temps[i].path, temps[j].path) == 0 ||
                temps[i].nginx_config == temps[j].nginx_config ||
                temps[i].source == temps[j].source || temps[i].nginx_log == temps[j].nginx_log ||
                temps[i].rut_log == temps[j].rut_log ||
                temps[i].nginx_access_log == temps[j].nginx_access_log ||
                temps[i].rut_access_log == temps[j].rut_access_log) {
                error = "#328 four sides shared a temp/config/source/log/access identity";
                return false;
            }
        }
    }
    BoundedExactLocalPathOracleObservation observations[4];
    std::string sources[2];
    const std::string containers[2] = {container_prefix + "-nginx-exact-first",
                                       container_prefix + "-nginx-root-first"};
    const auto failed_side = [&](const char* side) {
        if (error.empty()) error = std::string("#328 ") + side + " side returned no diagnostic";
        return false;
    };
    if (!capture_pinned_bounded_exact_local_path_order(ports[0],
                                                       ports[1],
                                                       temps[0],
                                                       containers[0],
                                                       true,
                                                       true,
                                                       observations[0],
                                                       error,
                                                       &reservations.fds[0],
                                                       &reservations.fds[1]))
        return failed_side("pinned exact-first");
    if (!capture_pinned_bounded_exact_local_path_order(ports[2],
                                                       ports[3],
                                                       temps[1],
                                                       containers[1],
                                                       false,
                                                       true,
                                                       observations[1],
                                                       error,
                                                       &reservations.fds[2],
                                                       &reservations.fds[3]))
        return failed_side("pinned root-first");
    if (!capture_generated_bounded_no_content_path_order(ports[4],
                                                         ports[5],
                                                         temps[2],
                                                         rut_path,
                                                         true,
                                                         observations[2],
                                                         sources[0],
                                                         error,
                                                         &reservations.fds[4],
                                                         &reservations.fds[5]))
        return failed_side("generated exact-first");
    if (!capture_generated_bounded_no_content_path_order(ports[6],
                                                         ports[7],
                                                         temps[3],
                                                         rut_path,
                                                         false,
                                                         observations[3],
                                                         sources[1],
                                                         error,
                                                         &reservations.fds[6],
                                                         &reservations.fds[7]))
        return failed_side("generated root-first");
    for (size_t side = 0u; side < 2u; side++) {
        std::string access_contents;
        const std::string prefix = "rut-nginx-328-healthz-return204-" + observations[side].order +
                                   "-" + std::to_string(getpid()) + "-scoped";
        if (!read_exact_return204_log(temps[side].nginx_access_log,
                                      "#328 differential pinned access log",
                                      access_contents,
                                      error) ||
            !parse_bounded_no_content_path_access_log(
                access_contents, prefix, ports[side * 2u + 1u], error))
            return false;
        for (u32& access : observations[side].access_records) access = 1u;
    }
    return validate_bounded_no_content_four_way(observations, sources, ports, error);
}

struct NormalizedExactTrailingSlashOracleObservation {
    std::string order;
    std::string temp_path;
    std::string config_path;
    std::string log_path;
    std::string access_path;
    std::string process_identity;
    std::vector<std::vector<char>> wires;
    std::vector<std::vector<char>> local_history;
    std::vector<std::vector<char>> forward_history;
    u32 access_records[5]{};
    u32 local_accepts = 0;
    u32 local_requests = 0;
    u32 local_sends = 0;
    u32 forward_accepts = 0;
    u32 forward_requests = 0;
    u32 forward_sends = 0;
};

struct NormalizedExactTrailingSlashOracleFiles {
    std::string exact_first_config;
    std::string exact_first_log;
    std::string root_first_config;
    std::string root_first_log;

    explicit NormalizedExactTrailingSlashOracleFiles(const char* directory)
        : exact_first_config(std::string(directory) + "/320-exact-first.conf"),
          exact_first_log(std::string(directory) + "/320-exact-first.log"),
          root_first_config(std::string(directory) + "/320-root-first.conf"),
          root_first_log(std::string(directory) + "/320-root-first.log") {}

    ~NormalizedExactTrailingSlashOracleFiles() {
        unlink(exact_first_config.c_str());
        unlink(exact_first_log.c_str());
        unlink(root_first_config.c_str());
        unlink(root_first_log.c_str());
    }
};

static void dump_normalized_exact_trailing_slash_oracle_observation(
    const NormalizedExactTrailingSlashOracleObservation& observation) {
    std::cerr << "normalized-exact-trailing-slash order=" << observation.order
              << " access=" << observation.access_records[0] << "/" << observation.access_records[1]
              << "/" << observation.access_records[2] << "/" << observation.access_records[3] << "/"
              << observation.access_records[4] << " upstream=" << observation.local_requests << "+"
              << observation.forward_requests << "\n";
    static constexpr const char* kLabels[] = {"GET /health/check/",
                                              "GET /health/check/?x=1",
                                              "GET /health/check//",
                                              "GET /health/check",
                                              "GET /"};
    for (size_t i = 0; i < observation.wires.size(); i++) {
        const char* label = i < sizeof(kLabels) / sizeof(kLabels[0]) ? kLabels[i] : "extra vector";
        dump_wire(label, observation.wires[i]);
    }
    for (size_t i = 0; i < observation.forward_history.size(); i++) {
        const std::string label = "#320 oracle upstream " + std::to_string(i + 1u);
        dump_wire(label.c_str(), observation.forward_history[i]);
    }
}

static bool capture_pinned_normalized_exact_trailing_slash_order(
    u16 frontend_port,
    u16 backend_port,
    const std::string& config_path,
    const std::string& log_path,
    const std::string& container_name,
    bool exact_first,
    NormalizedExactTrailingSlashOracleObservation& observation,
    std::string& error,
    bool no_content_return204 = false,
    const std::string* separate_access_path = nullptr,
    int* frontend_reservation = nullptr,
    int* backend_reservation = nullptr) {
    static constexpr const char* kStatus200Targets[] = {
        "/health/check/", "/health/check/?x=1", "/health/check//", "/health/check", "/"};
    static constexpr const char* kStatus204Targets[] = {
        "/healthz/", "/healthz/?x=1", "/healthz//", "/healthz", "/"};
    static constexpr bool kLocal[] = {true, true, true, false, false};
    static_assert(sizeof(kStatus200Targets) / sizeof(kStatus200Targets[0]) ==
                  sizeof(kLocal) / sizeof(kLocal[0]));
    static_assert(sizeof(kStatus204Targets) / sizeof(kStatus204Targets[0]) ==
                  sizeof(kLocal) / sizeof(kLocal[0]));
    const char* const* targets = no_content_return204 ? kStatus204Targets : kStatus200Targets;
    const char* issue = no_content_return204 ? "#329" : "#320";
    const char* host =
        no_content_return204 ? "trailing-return204.example" : "normalized-exact.example";
    if (no_content_return204 &&
        (separate_access_path == nullptr || separate_access_path->empty())) {
        error = "#329 pinned oracle requires a separate bounded access-log path";
        return false;
    }
    if ((frontend_reservation == nullptr) != (backend_reservation == nullptr) ||
        (frontend_reservation != nullptr &&
         (*frontend_reservation < 0 || *backend_reservation < 0))) {
        error = std::string(issue) + " pinned oracle received incomplete port reservations";
        return false;
    }

    const auto make_request = [host](const char* target) {
        return std::string("GET ") + target + " HTTP/1.1\r\nHost: " + host +
               "\r\nConnection: close\r\n\r\n";
    };
    for (size_t i = 0; i < 5u; i++) {
        const char* target = targets[i];
        const std::string request = make_request(target);
        const size_t header_end = request.find("\r\n\r\n");
        if (request.rfind(std::string("GET ") + target + " HTTP/1.1\r\n", 0) != 0 ||
            request.find('#') != std::string::npos ||
            request.find(std::string("\r\nHost: ") + host + "\r\n") == std::string::npos ||
            request.find("\r\nConnection: close\r\n") == std::string::npos ||
            request.find("\r\nContent-Length:") != std::string::npos ||
            request.find("\r\nTransfer-Encoding:") != std::string::npos ||
            request.find("\r\nTE:") != std::string::npos ||
            request.find("\r\nExpect:") != std::string::npos ||
            request.find("\r\nUpgrade:") != std::string::npos || header_end == std::string::npos ||
            header_end + 4u != request.size() || request.rfind("\r\n\r\n") != header_end) {
            error = std::string(issue) +
                    " oracle vector escaped the fresh bodyless GET domain: " + target;
            return false;
        }
    }

    observation = NormalizedExactTrailingSlashOracleObservation{};
    observation.order = exact_first ? "exact-before-root" : "root-before-exact";
    const size_t slash = config_path.rfind('/');
    observation.temp_path =
        slash == std::string::npos ? std::string{} : config_path.substr(0u, slash);
    observation.config_path = config_path;
    observation.log_path = log_path;
    observation.access_path = no_content_return204 ? *separate_access_path : log_path;
    observation.process_identity = container_name;
    observation.wires.resize(5);
    const std::string access_prefix =
        std::string("rut-nginx-") +
        (no_content_return204 ? "329-trailing-return204-" : "320-normalized-exact-") +
        observation.order + "-" + std::to_string(getpid()) + "-scoped";
    const std::string exact_location = no_content_return204
                                           ? "    location = /healthz/ { return 204; }\n"
                                           : "    location = /health/check/ { return 200 "
                                             "\"successor-static\"; }\n";
    const std::string root_location =
        "    location / { proxy_pass http://127.0.0.1:" + std::to_string(backend_port) + "; }\n";
    const std::string config =
        "error_log stderr notice;\n"
        "events {}\n"
        "http {\n"
        "  log_format normalized_exact_trailing_slash '" +
        access_prefix +
        (no_content_return204
             ? " raw=\"$request\" status=$status bytes=$bytes_sent host=\"$host\" "
               "upstream_addr=\"$upstream_addr\" upstream_status=$upstream_status';\n"
             : " $remote_addr - - [$time_local] \"$request\" $status $body_bytes_sent "
               "host=\"$host\"';\n") +
        "  access_log " + (no_content_return204 ? *separate_access_path : "/dev/stderr") +
        " normalized_exact_trailing_slash;\n"
        "  server {\n"
        "    listen " +
        std::to_string(frontend_port) + ";\n" +
        (exact_first ? exact_location + root_location : root_location + exact_location) +
        "  }\n"
        "}\n";
    if (!write_file(config_path, config.data(), config.size())) {
        error = std::string("failed to write ") + issue +
                " normalized exact trailing-slash pinned nginx config";
        return false;
    }

    const auto recorder_live = [](const Recorder& recorder) {
        return recorder.running.load(std::memory_order_acquire) &&
               recorder.thread_alive.load(std::memory_order_acquire) &&
               !recorder.listener_failed.load(std::memory_order_acquire);
    };
    const auto wait_recorder_live = [&](Recorder& recorder, Child& nginx, const char* phase) {
        const auto deadline = std::chrono::steady_clock::now() + std::chrono::seconds(2);
        while (std::chrono::steady_clock::now() < deadline) {
            if (poll_child(nginx)) {
                error = std::string("pinned nginx exited before ") + issue + " " + phase +
                        " recorder readiness";
                return false;
            }
            if (recorder.listener_failed.load(std::memory_order_acquire) ||
                !recorder.running.load(std::memory_order_acquire)) {
                error = std::string(issue) + " " + phase + " recorder failed before readiness";
                return false;
            }
            if (recorder.thread_alive.load(std::memory_order_acquire)) return true;
            usleep(1000);
        }
        error = std::string(issue) + " " + phase + " recorder readiness timed out";
        return false;
    };
    const auto send_vector = [&](Child& nginx, size_t index, const char* expected) {
        const std::string request = make_request(targets[index]);
        struct ClientGuard {
            int fd = -1;
            ~ClientGuard() {
                if (fd >= 0) close(fd);
            }
        } client{connect_once(frontend_port)};
        std::vector<char> wire;
        std::string detail;
        if (client.fd < 0 || !send_all(client.fd, request.data(), request.size())) {
            error = std::string(issue) + " vector " + targets[index] +
                    " response/EOF/zero-tail failed: connect or send failed";
            return false;
        }
        const bool read_ok = no_content_return204 && index < 3u
                                 ? read_head_response(client.fd, wire, detail)
                                 : read_response(client.fd, wire, detail);
        if (!read_ok || !read_eof(client.fd, detail)) {
            error = std::string(issue) + " vector " + targets[index] +
                    " response/EOF/zero-tail failed: " +
                    (detail.empty() ? "connect or send failed" : detail);
            return false;
        }
        if (!validate_exact_normalized_response(wire, expected, detail)) {
            error = std::string(issue) + " vector " + targets[index] +
                    " exact status/reason/headers/body wire mismatch: " + detail;
            return false;
        }
        const std::string wire_text(wire.begin(), wire.end());
        const size_t header_end = wire_text.find("\r\n\r\n");
        if (wire_text.find("\r\nLocation:") != std::string::npos) {
            error = std::string(issue) + " vector unexpectedly emitted Location: " + targets[index];
            return false;
        }
        if (no_content_return204 && index < 3u &&
            (wire.size() != 105u || header_end == std::string::npos ||
             wire_text.size() != header_end + 4u ||
             wire_text.find("\r\nContent-Type:") != std::string::npos ||
             wire_text.find("\r\nContent-Length:") != std::string::npos ||
             wire_text.find("\r\nTransfer-Encoding:") != std::string::npos)) {
            error = std::string(issue) +
                    " local vector contained framing, representation, body, "
                    "or tail: " +
                    targets[index];
            return false;
        }
        if (poll_child(nginx)) {
            error = std::string("pinned nginx exited after ") + issue + " vector " + targets[index];
            return false;
        }
        observation.wires[index] = std::move(wire);
        return true;
    };
    const auto observe_exact_count =
        [&](Recorder& recorder, Child& nginx, u32 expected, const char* phase) {
            const auto deadline = std::chrono::steady_clock::now() + std::chrono::milliseconds(500);
            while (std::chrono::steady_clock::now() < deadline) {
                if (poll_child(nginx) || !recorder_live(recorder)) {
                    error = std::string(issue) + " pinned nginx or recorder failed during " + phase;
                    return false;
                }
                if (recorder.accepted.load(std::memory_order_acquire) != expected ||
                    recorder.requests.load(std::memory_order_acquire) != expected ||
                    recorder.response_send_all_calls.load(std::memory_order_acquire) != expected) {
                    error = std::string(issue) + " unexpected upstream count during " + phase;
                    return false;
                }
                usleep(5000);
            }
            return true;
        };
    const auto wait_exact_count = [&](Recorder& recorder, Child& nginx, u32 expected) {
        const auto deadline = std::chrono::steady_clock::now() + std::chrono::seconds(2);
        while (std::chrono::steady_clock::now() < deadline) {
            if (poll_child(nginx) || !recorder_live(recorder)) {
                error = std::string(issue) +
                        " pinned nginx or forward recorder failed while waiting for count";
                return false;
            }
            const u32 accepts = recorder.accepted.load(std::memory_order_acquire);
            const u32 requests = recorder.requests.load(std::memory_order_acquire);
            const u32 sends = recorder.response_send_all_calls.load(std::memory_order_acquire);
            if (accepts > expected || requests > expected || sends > expected) {
                error = std::string(issue) + " forward recorder exceeded its exact upstream count";
                return false;
            }
            if (accepts == expected && requests == expected && sends == expected) return true;
            usleep(1000);
        }
        error = std::string("timed out waiting for ") + issue + " exact forward upstream count";
        return false;
    };

    Recorder local_recorder;
    local_recorder.observe_extra_requests_until_stop = true;
    if (backend_reservation != nullptr) {
        close(*backend_reservation);
        *backend_reservation = -1;
    }
    if (!local_recorder.setup(backend_port)) {
        error = std::string("failed to start ") + issue + " local zero-upstream recorder";
        return false;
    }
    DockerGuard docker(container_name);
    ChildGuard nginx;
    std::vector<std::string> docker_args = {"docker",
                                            "run",
                                            "--pull=never",
                                            "--network",
                                            "host",
                                            "--name",
                                            container_name,
                                            "-v",
                                            config_path + ":/etc/nginx/nginx.conf:ro"};
    if (no_content_return204) {
        docker_args.push_back("-v");
        docker_args.push_back(observation.temp_path + ":" + observation.temp_path);
    }
    docker_args.insert(docker_args.end(), {kNginxImage, "nginx", "-g", "daemon off;"});
    if (frontend_reservation != nullptr) {
        close(*frontend_reservation);
        *frontend_reservation = -1;
    }
    if (!spawn_child(docker_args, log_path, nginx.child)) {
        error = std::string("failed to start pinned nginx for ") + issue + " oracle";
        return false;
    }
    if (!wait_ready(frontend_port, nginx.child, error) ||
        !wait_recorder_live(local_recorder, nginx.child, "local"))
        return false;

    for (size_t i = 0; i < 3; i++) {
        const char* expected = no_content_return204 ? kExactLocalReturn204ResponseNormalized
                                                    : kExactLocalCloseResponseNormalized;
        if (!kLocal[i] || !send_vector(nginx.child, i, expected)) return false;
        if (local_recorder.accepted.load(std::memory_order_acquire) != 0 ||
            local_recorder.requests.load(std::memory_order_acquire) != 0 ||
            local_recorder.response_send_all_calls.load(std::memory_order_acquire) != 0) {
            error = std::string(issue) +
                    " normalized exact local vector unexpectedly reached upstream: " + targets[i];
            return false;
        }
    }
    if (!observe_exact_count(local_recorder, nginx.child, 0, "live local zero-upstream window"))
        return false;
    local_recorder.stop();
    observation.local_accepts = local_recorder.accepted.load(std::memory_order_acquire);
    observation.local_requests = local_recorder.requests.load(std::memory_order_acquire);
    observation.local_sends =
        local_recorder.response_send_all_calls.load(std::memory_order_acquire);
    observation.local_history = local_recorder.history;
    if (local_recorder.thread_alive.load(std::memory_order_acquire) ||
        local_recorder.listener_failed.load(std::memory_order_acquire) ||
        observation.local_accepts != 0 || observation.local_requests != 0 ||
        observation.local_sends != 0 ||
        local_recorder.response_send_succeeded.load(std::memory_order_acquire) ||
        !local_recorder.history.empty() || !local_recorder.request.empty()) {
        error = std::string(issue) + " local recorder did not settle with zero upstream activity";
        return false;
    }

    Recorder forward_recorder;
    forward_recorder.observe_extra_requests_until_stop = true;
    if (!forward_recorder.setup(backend_port, 2, kBackendResponse, sizeof(kBackendResponse) - 1u) ||
        !wait_recorder_live(forward_recorder, nginx.child, "forward")) {
        if (error.empty()) error = std::string("failed to start ") + issue + " forward recorder";
        return false;
    }
    for (size_t i = 3; i < 5; i++) {
        if (kLocal[i] || !send_vector(nginx.child, i, kSuccessResponseNormalized) ||
            !wait_exact_count(forward_recorder, nginx.child, static_cast<u32>(i - 2u)))
            return false;
    }
    if (!observe_exact_count(forward_recorder, nginx.child, 2, "live no-third-forward window"))
        return false;

    if (!stop_child(nginx.child)) {
        error = std::string("failed to stop pinned nginx after ") + issue + " oracle";
        return false;
    }
    if (!docker.remove()) {
        error = std::string("docker rm -f failed after ") + issue + " oracle";
        return false;
    }
    forward_recorder.stop();
    observation.forward_accepts = forward_recorder.accepted.load(std::memory_order_acquire);
    observation.forward_requests = forward_recorder.requests.load(std::memory_order_acquire);
    observation.forward_sends =
        forward_recorder.response_send_all_calls.load(std::memory_order_acquire);
    observation.forward_history = forward_recorder.history;
    if (forward_recorder.thread_alive.load(std::memory_order_acquire) ||
        forward_recorder.listener_failed.load(std::memory_order_acquire) ||
        observation.forward_accepts != 2 || observation.forward_requests != 2 ||
        observation.forward_sends != 2 ||
        !forward_recorder.response_send_succeeded.load(std::memory_order_acquire) ||
        !forward_recorder.response_clean_shutdown.load(std::memory_order_acquire) ||
        !forward_recorder.response_connection_closed.load(std::memory_order_acquire) ||
        observation.forward_history.size() != 2) {
        error = std::string(issue) +
                " forward recorder did not settle at exactly two upstream episodes";
        return false;
    }

    std::vector<std::vector<char>> expected_history;
    expected_history.reserve(2);
    for (size_t i = 3; i < 5; i++) {
        const std::string request = std::string("GET ") + targets[i] + " HTTP/1.1\r\n" +
                                    "Host: 127.0.0.1:" + std::to_string(backend_port) + "\r\n\r\n";
        expected_history.emplace_back(request.begin(), request.end());
    }
    if (observation.forward_history != expected_history) {
        error = std::string(issue) +
                " root fallbacks did not preserve exact method/request-target/headers/body "
                "histories";
        return false;
    }

    if (no_content_return204) {
        std::string error_log;
        if (!read_exact_return204_log(log_path, "#329 pinned nginx error log", error_log, error))
            return false;
        for (const char* severity : {"[warn]", "[error]", "[crit]", "[alert]", "[emerg]"}) {
            if (error_log.find(severity) != std::string::npos) {
                error = std::string("#329 pinned nginx error log contained ") + severity;
                return false;
            }
        }
        return true;
    }

    bool logs_readable = true;
    for (size_t i = 0; i < 5; i++) {
        const std::string marker = std::string("\"GET ") + targets[i] + " HTTP/1.1\" 200 " +
                                   (i < 3 ? "16" : "2") + " host=\"normalized-exact.example\"";
        logs_readable =
            logs_readable &&
            log_count_line_with(
                log_path, marker.c_str(), access_prefix.c_str(), observation.access_records[i]);
    }
    u32 local_access = 0;
    u32 forward_access = 0;
    u32 total_access = 0;
    u32 connect_failures = 0;
    u32 upstream_failures = 0;
    const std::string upstream_context = "127.0.0.1:" + std::to_string(backend_port);
    logs_readable =
        logs_readable &&
        log_count_line_with(log_path, "200 16 host=", access_prefix.c_str(), local_access) &&
        log_count_line_with(log_path, "200 2 host=", access_prefix.c_str(), forward_access) &&
        log_count_line_with(log_path, access_prefix.c_str(), access_prefix.c_str(), total_access) &&
        log_count_line_with(
            log_path, "connect() failed", upstream_context.c_str(), connect_failures) &&
        log_count_line_with(log_path, "upstream", upstream_context.c_str(), upstream_failures);
    if (!logs_readable || observation.access_records[0] != 1 ||
        observation.access_records[1] != 1 || observation.access_records[2] != 1 ||
        observation.access_records[3] != 1 || observation.access_records[4] != 1 ||
        local_access != 3 || forward_access != 2 || total_access != 5 || connect_failures != 0 ||
        upstream_failures != 0) {
        error =
            "#320 scoped access/error logs did not prove three local 200/16 records, two "
            "forward 200/2 records, five total raw-spelling records, and zero "
            "connect/upstream failures";
        return false;
    }
    return true;
}

static bool run_pinned_normalized_exact_trailing_slash_oracle(
    TempDir& temp,
    const std::string& container_prefix,
    NormalizedExactTrailingSlashOracleObservation& exact_first,
    NormalizedExactTrailingSlashOracleObservation& root_first,
    std::string& error) {
    u16 exact_frontend_port = 0;
    u16 exact_backend_port = 0;
    u16 root_frontend_port = 0;
    u16 root_backend_port = 0;
    bool ports_unique = false;
    for (int attempt = 0; attempt < 8 && !ports_unique; attempt++) {
        if (!allocate_port(exact_frontend_port) || !allocate_port(exact_backend_port) ||
            !allocate_port(root_frontend_port) || !allocate_port(root_backend_port))
            continue;
        ports_unique =
            exact_frontend_port != exact_backend_port &&
            exact_frontend_port != root_frontend_port && exact_frontend_port != root_backend_port &&
            exact_backend_port != root_frontend_port && exact_backend_port != root_backend_port &&
            root_frontend_port != root_backend_port;
    }
    if (!ports_unique) {
        error = "#320 could not allocate four distinct declaration-order ports";
        return false;
    }

    NormalizedExactTrailingSlashOracleFiles files(temp.path);
    if (!capture_pinned_normalized_exact_trailing_slash_order(exact_frontend_port,
                                                              exact_backend_port,
                                                              files.exact_first_config,
                                                              files.exact_first_log,
                                                              container_prefix + "-exact-first",
                                                              true,
                                                              exact_first,
                                                              error) ||
        !capture_pinned_normalized_exact_trailing_slash_order(root_frontend_port,
                                                              root_backend_port,
                                                              files.root_first_config,
                                                              files.root_first_log,
                                                              container_prefix + "-root-first",
                                                              false,
                                                              root_first,
                                                              error))
        return false;
    if (exact_first.wires.size() != 5 || root_first.wires.size() != 5) {
        error = "#320 oracle did not complete the exact five-vector matrix for both orders";
        return false;
    }
    for (size_t i = 0; i < 5; i++) {
        if (exact_first.wires[i].empty() || root_first.wires[i].empty() ||
            exact_first.wires[i].data() == root_first.wires[i].data()) {
            error = "#320 order comparison did not retain independent response buffers";
            return false;
        }
        std::vector<char> exact_wire(exact_first.wires[i].begin(), exact_first.wires[i].end());
        std::vector<char> root_wire(root_first.wires[i].begin(), root_first.wires[i].end());
        if (!normalize_date(exact_wire) || !normalize_date(root_wire) || exact_wire != root_wire) {
            error = "#320 location declaration order changed normalized vector " +
                    std::to_string(i + 1u);
            return false;
        }
    }
    if (exact_first.forward_history.size() != 2 || root_first.forward_history.size() != 2) {
        error = "#320 declaration-order comparison lacks two independent upstream histories";
        return false;
    }
    for (size_t i = 0; i < 2; i++) {
        const auto& exact_request = exact_first.forward_history[i];
        const auto& root_request = root_first.forward_history[i];
        if (exact_request.empty() || root_request.empty() ||
            exact_request.data() == root_request.data()) {
            error = "#320 order comparison did not retain independent upstream buffers";
            return false;
        }
        const auto request_line = [](const std::vector<char>& request) {
            const std::string text(request.begin(), request.end());
            const size_t end = text.find("\r\n");
            return end == std::string::npos ? text : text.substr(0, end);
        };
        if (request_line(exact_request) != request_line(root_request)) {
            error = "#320 declaration order changed ordered upstream request targets";
            return false;
        }
    }
    return true;
}

static void dump_trailing_no_content_oracle_observation(
    const NormalizedExactTrailingSlashOracleObservation& observation) {
    std::cerr << "#329 trailing-no-content order=" << observation.order
              << " temp=" << observation.temp_path << " config=" << observation.config_path
              << " error-log=" << observation.log_path << " access=" << observation.access_path
              << " process=" << observation.process_identity
              << " records=" << observation.access_records[0] << "/"
              << observation.access_records[1] << "/" << observation.access_records[2] << "/"
              << observation.access_records[3] << "/" << observation.access_records[4]
              << " upstream=" << observation.local_requests << "+" << observation.forward_requests
              << "\n";
    static constexpr const char* kLabels[] = {
        "GET /healthz/", "GET /healthz/?x=1", "GET /healthz//", "GET /healthz", "GET /"};
    for (size_t i = 0u; i < observation.wires.size(); i++)
        dump_wire(i < 5u ? kLabels[i] : "#329 extra vector", observation.wires[i]);
    for (size_t i = 0u; i < observation.forward_history.size(); i++) {
        const std::string label = "#329 fallback " + std::to_string(i + 1u);
        dump_wire(label.c_str(), observation.forward_history[i]);
    }
}

static bool parse_trailing_no_content_access_log(const std::string& contents,
                                                 const std::string& prefix,
                                                 u16 backend_port,
                                                 std::string& error) {
    static constexpr const char* kTargets[] = {
        "/healthz/", "/healthz/?x=1", "/healthz//", "/healthz", "/"};
    std::vector<std::string> records;
    if (!split_exact_complete_log(contents, 5u, "#329 bounded access log", records, error))
        return false;
    for (size_t i = 0u; i < records.size(); i++) {
        const std::string& record = records[i];
        size_t cursor = 0u;
        const auto take = [&](const std::string& literal) {
            if (record.compare(cursor, literal.size(), literal) != 0) return false;
            cursor += literal.size();
            return true;
        };
        const auto take_token = [&](const char* literal, std::string& token) {
            if (!take(literal)) return false;
            const size_t end = record.find(' ', cursor);
            if (end == std::string::npos || end == cursor) return false;
            token = record.substr(cursor, end - cursor);
            cursor = end;
            return true;
        };
        const std::string raw = std::string("GET ") + kTargets[i] + " HTTP/1.1";
        if (!take(prefix + " raw=\"" + raw + "\" status=")) {
            error = "#329 access log lost exact raw target or request order";
            return false;
        }
        std::string status;
        std::string bytes;
        if (!take_token("", status) || !take(" bytes=") || !take_token("", bytes)) {
            error = "#329 access log status/size schema mismatch";
            return false;
        }
        const size_t expected_status = i < 3u ? 204u : 200u;
        const size_t expected_bytes = i < 3u ? 105u : 118u;
        size_t status_value = 0u;
        size_t bytes_value = 0u;
        if (!parse_decimal_field(status, status_value) ||
            !parse_decimal_field(bytes, bytes_value) || status_value != expected_status ||
            bytes_value != expected_bytes || status != std::to_string(expected_status) ||
            bytes != std::to_string(expected_bytes) ||
            !take(" host=\"trailing-return204.example\" upstream_addr=\"")) {
            error = "#329 access log status/size/host fields were not exact";
            return false;
        }
        if (i < 3u) {
            if (!take("-\" upstream_status=-")) {
                error = "#329 local access record did not prove zero upstream";
                return false;
            }
        } else {
            if (!take("127.0.0.1:")) {
                error = "#329 fallback access record lost upstream address";
                return false;
            }
            const size_t port_end = record.find('"', cursor);
            if (port_end == std::string::npos || port_end == cursor) {
                error = "#329 fallback access record has malformed upstream port";
                return false;
            }
            const std::string port = record.substr(cursor, port_end - cursor);
            size_t port_value = 0u;
            if (!parse_decimal_field(port, port_value) || port_value > 65535u ||
                port_value != backend_port || port != std::to_string(backend_port) ||
                record.compare(
                    port_end, strlen("\" upstream_status=200"), "\" upstream_status=200") != 0) {
                error = "#329 fallback access record upstream port/status was not exact";
                return false;
            }
            cursor = port_end + strlen("\" upstream_status=200");
        }
        if (cursor != record.size()) {
            error = "#329 access record contained an unexpected tail";
            return false;
        }
    }
    return true;
}

static bool run_trailing_no_content_access_log_self_checks(std::string& error) {
    const std::string prefix = "rut-nginx-329-trailing-return204-exact-before-root-123-scoped";
    static constexpr const char* kTargets[] = {
        "/healthz/", "/healthz/?x=1", "/healthz//", "/healthz", "/"};
    std::string valid;
    for (size_t i = 0u; i < 5u; i++) {
        valid += prefix + " raw=\"GET " + kTargets[i] +
                 " HTTP/1.1\" status=" + (i < 3u ? "204" : "200") +
                 " bytes=" + (i < 3u ? "105" : "118") +
                 " host=\"trailing-return204.example\" upstream_addr=\"" +
                 (i < 3u ? "-\" upstream_status=-" : "127.0.0.1:54321\" upstream_status=200") +
                 "\n";
    }
    const auto replace_once =
        [](std::string value, const std::string& from, const std::string& to) {
            const size_t offset = value.find(from);
            if (offset == std::string::npos) return std::string{};
            value.replace(offset, from.size(), to);
            return value;
        };
    const auto rejects = [&](const std::string& value) {
        std::string detail;
        return !parse_trailing_no_content_access_log(value, prefix, 54321u, detail);
    };
    const size_t first_end = valid.find('\n');
    const size_t second_end = valid.find('\n', first_end + 1u);
    std::string swapped = valid;
    swapped.replace(
        0u,
        second_end + 1u,
        valid.substr(first_end + 1u, second_end - first_end) + valid.substr(0u, first_end + 1u));
    if (!parse_trailing_no_content_access_log(valid, prefix, 54321u, error)) return false;
    const std::pair<const char*, bool> mutations[] = {
        {"extra-record", rejects(valid + valid.substr(0u, first_end + 1u))},
        {"truncated-record", rejects(valid.substr(0u, valid.size() - 1u))},
        {"order", rejects(swapped)},
        {"raw-target", rejects(replace_once(valid, "/healthz//", "/healthz/"))},
        {"local-status", rejects(replace_once(valid, "status=204", "status=200"))},
        {"fallback-size", rejects(replace_once(valid, "bytes=118", "bytes=119"))},
        {"overflow",
         rejects(replace_once(valid, "status=204", "status=999999999999999999999999999999999"))},
        {"local-upstream",
         rejects(replace_once(valid,
                              "upstream_addr=\"-\" upstream_status=-",
                              "upstream_addr=\"127.0.0.1:54321\" upstream_status=200"))},
        {"fallback-upstream",
         rejects(replace_once(
             valid, "127.0.0.1:54321\" upstream_status=200", "-\" upstream_status=-"))},
        {"port", rejects(replace_once(valid, "127.0.0.1:54321", "127.0.0.1:054321"))}};
    for (const auto& mutation : mutations) {
        if (!mutation.second) {
            error = std::string("#329 access mutation accepted: ") + mutation.first;
            return false;
        }
    }
    return true;
}

static bool validate_trailing_no_content_observation(
    const NormalizedExactTrailingSlashOracleObservation& observation,
    u16 backend_port,
    std::string& error) {
    if (observation.wires.size() != 5u || observation.local_accepts != 0u ||
        observation.local_requests != 0u || observation.local_sends != 0u ||
        !observation.local_history.empty()) {
        error = "#329 observation lacked five vectors or settled zero local-upstream evidence";
        return false;
    }
    if (observation.forward_accepts != 2u || observation.forward_requests != 2u ||
        observation.forward_sends != 2u || observation.forward_history.size() != 2u) {
        error = "#329 observation lacked exactly two fallback episodes";
        return false;
    }
    for (u32 access : observation.access_records) {
        if (access != 1u) {
            error = "#329 observation lacked exactly five ordered access records";
            return false;
        }
    }
    const std::vector<char> local(kExactLocalReturn204ResponseNormalized,
                                  kExactLocalReturn204ResponseNormalized + 105u);
    const std::vector<char> fallback(
        kSuccessResponseNormalized,
        kSuccessResponseNormalized + sizeof(kSuccessResponseNormalized) - 1u);
    for (size_t i = 0u; i < observation.wires.size(); i++) {
        std::vector<char> normalized = observation.wires[i];
        if (!normalize_date(normalized) || normalized != (i < 3u ? local : fallback)) {
            error = "#329 observation wire differed from its exact 204/fallback baseline";
            return false;
        }
    }
    std::vector<std::vector<char>> expected_history;
    for (const char* target : {"/healthz", "/"}) {
        const std::string request = std::string("GET ") + target + " HTTP/1.1\r\n" +
                                    "Host: 127.0.0.1:" + std::to_string(backend_port) + "\r\n\r\n";
        expected_history.emplace_back(request.begin(), request.end());
    }
    if (observation.forward_history != expected_history) {
        error = "#329 fallback history contained a retry, reorder, or wire mismatch";
        return false;
    }
    return true;
}

static NormalizedExactTrailingSlashOracleObservation make_trailing_no_content_self_check_value(
    u16 backend_port, const char* order, const char* resource_suffix) {
    static constexpr char kObservedDate[] = "Wed, 26 Aug 2026 23:57:18 GMT";
    const auto observed = [](const char* normalized, size_t size) {
        std::vector<char> wire(normalized, normalized + size);
        const std::string marker(29u, 'X');
        const auto offset = std::search(wire.begin(), wire.end(), marker.begin(), marker.end());
        if (offset != wire.end()) std::copy_n(kObservedDate, 29u, offset);
        return wire;
    };
    NormalizedExactTrailingSlashOracleObservation value;
    value.order = order;
    value.temp_path = std::string("/tmp/329-") + resource_suffix;
    value.config_path = value.temp_path + "/nginx.conf";
    value.log_path = value.temp_path + "/nginx.log";
    value.access_path = value.temp_path + "/access.log";
    value.process_identity = std::string("rut-nginx-329-") + resource_suffix;
    value.wires = {observed(kExactLocalReturn204ResponseNormalized, 105u),
                   observed(kExactLocalReturn204ResponseNormalized, 105u),
                   observed(kExactLocalReturn204ResponseNormalized, 105u),
                   observed(kSuccessResponseNormalized, sizeof(kSuccessResponseNormalized) - 1u),
                   observed(kSuccessResponseNormalized, sizeof(kSuccessResponseNormalized) - 1u)};
    value.forward_accepts = 2u;
    value.forward_requests = 2u;
    value.forward_sends = 2u;
    for (u32& access : value.access_records) access = 1u;
    for (const char* target : {"/healthz", "/"}) {
        const std::string request = std::string("GET ") + target + " HTTP/1.1\r\n" +
                                    "Host: 127.0.0.1:" + std::to_string(backend_port) + "\r\n\r\n";
        value.forward_history.emplace_back(request.begin(), request.end());
    }
    return value;
}

static bool validate_trailing_no_content_pair(
    const NormalizedExactTrailingSlashOracleObservation& exact_first,
    const NormalizedExactTrailingSlashOracleObservation& root_first,
    const u16 ports[4],
    std::string& error) {
    for (size_t i = 0u; i < 4u; i++) {
        if (ports[i] == 0u) {
            error = "#329 pair validator received a zero port";
            return false;
        }
        for (size_t j = i + 1u; j < 4u; j++) {
            if (ports[i] == ports[j]) {
                error = "#329 declaration orders shared a frontend/backend port";
                return false;
            }
        }
    }
    if (!validate_trailing_no_content_observation(exact_first, ports[1], error) ||
        !validate_trailing_no_content_observation(root_first, ports[3], error))
        return false;
    const std::string* resources[] = {&exact_first.temp_path,
                                      &exact_first.config_path,
                                      &exact_first.log_path,
                                      &exact_first.access_path,
                                      &exact_first.process_identity,
                                      &root_first.temp_path,
                                      &root_first.config_path,
                                      &root_first.log_path,
                                      &root_first.access_path,
                                      &root_first.process_identity};
    for (size_t i = 0u; i < 10u; i++) {
        if (resources[i]->empty()) {
            error = "#329 declaration-order resource identity was empty or aliased";
            return false;
        }
        for (size_t j = i + 1u; j < 10u; j++) {
            if (*resources[i] == *resources[j]) {
                error = "#329 declaration-order resource identity was empty or aliased";
                return false;
            }
        }
    }
    for (size_t i = 0u; i < 5u; i++) {
        std::vector<char> left = exact_first.wires[i];
        std::vector<char> right = root_first.wires[i];
        if (!normalize_date(left) || !normalize_date(right) || left != right) {
            error =
                "#329 declaration order changed Date-normalized vector " + std::to_string(i + 1u);
            return false;
        }
    }
    const auto exact_history = canonicalize_bounded_backend_history(exact_first.forward_history);
    const auto root_history = canonicalize_bounded_backend_history(root_first.forward_history);
    if (exact_history.size() != 2u || exact_history != root_history) {
        error = "#329 declaration order changed port-canonical fallback history";
        return false;
    }
    return true;
}

static bool run_trailing_no_content_observation_self_checks(std::string& error) {
    static constexpr u16 kPorts[] = {54320u, 54321u, 54322u, 54323u};
    const auto valid_exact =
        make_trailing_no_content_self_check_value(kPorts[1], "exact-before-root", "exact");
    const auto valid_root =
        make_trailing_no_content_self_check_value(kPorts[3], "root-before-exact", "root");
    if (!validate_trailing_no_content_pair(valid_exact, valid_root, kPorts, error)) return false;
    const auto rejects_observation = [&](const char* name,
                                         NormalizedExactTrailingSlashOracleObservation value) {
        std::string detail;
        if (!validate_trailing_no_content_observation(value, kPorts[1], detail)) return true;
        error = std::string("#329 observation mutation accepted: ") + name;
        return false;
    };
    auto mutated = valid_exact;
    mutated.wires[2].push_back('x');
    if (!rejects_observation("local-wire-tail", mutated)) return false;
    mutated = valid_exact;
    mutated.wires[3] = valid_exact.wires[0];
    if (!rejects_observation("fallback-wire", mutated)) return false;
    mutated = valid_exact;
    mutated.local_accepts = 1u;
    if (!rejects_observation("local-count", mutated)) return false;
    mutated = valid_exact;
    mutated.local_history.push_back(valid_exact.forward_history[0]);
    if (!rejects_observation("local-history", mutated)) return false;
    mutated = valid_exact;
    mutated.forward_requests = 3u;
    if (!rejects_observation("fallback-count", mutated)) return false;
    mutated = valid_exact;
    mutated.forward_history.push_back(valid_exact.forward_history[0]);
    if (!rejects_observation("third/retry", mutated)) return false;
    mutated = valid_exact;
    std::swap(mutated.forward_history[0], mutated.forward_history[1]);
    if (!rejects_observation("fallback-order", mutated)) return false;
    mutated = valid_exact;
    mutated.access_records[4] = 0u;
    if (!rejects_observation("access-count", mutated)) return false;

    const auto rejects_pair = [&](const char* name,
                                  const NormalizedExactTrailingSlashOracleObservation& left,
                                  const NormalizedExactTrailingSlashOracleObservation& right,
                                  const u16 pair_ports[4]) {
        std::string detail;
        if (!validate_trailing_no_content_pair(left, right, pair_ports, detail)) return true;
        error = std::string("#329 pair mutation accepted: ") + name;
        return false;
    };
    auto aliased_root = valid_root;
    aliased_root.access_path = valid_exact.access_path;
    if (!rejects_pair("resource-alias", valid_exact, aliased_root, kPorts)) return false;
    u16 changed_ports[4];
    std::copy(std::begin(kPorts), std::end(kPorts), std::begin(changed_ports));
    changed_ports[3] = changed_ports[0];
    if (!rejects_pair("duplicate-port", valid_exact, valid_root, changed_ports)) return false;
    changed_ports[3] = kPorts[3];
    changed_ports[0] = 0u;
    if (!rejects_pair("zero-port", valid_exact, valid_root, changed_ports)) return false;
    auto changed_root = valid_root;
    changed_root.wires[1].push_back('x');
    if (!rejects_pair("order-wire", valid_exact, changed_root, kPorts)) return false;
    return true;
}

static bool run_pinned_trailing_no_content_oracle(
    const std::string& container_prefix,
    NormalizedExactTrailingSlashOracleObservation& exact_first,
    NormalizedExactTrailingSlashOracleObservation& root_first,
    std::string& error) {
    struct ReservedPorts {
        int fds[4];

        ReservedPorts() { std::fill(std::begin(fds), std::end(fds), -1); }
        ~ReservedPorts() {
            for (int fd : fds)
                if (fd >= 0) close(fd);
        }

        bool reserve(size_t index, u16& port) {
            const int fd = socket(AF_INET, SOCK_STREAM | SOCK_CLOEXEC, 0);
            if (fd < 0) return false;
            sockaddr_in addr{};
            addr.sin_family = AF_INET;
            addr.sin_addr.s_addr = htonl(INADDR_LOOPBACK);
            addr.sin_port = 0;
            socklen_t len = sizeof(addr);
            if (bind(fd, reinterpret_cast<sockaddr*>(&addr), sizeof(addr)) != 0 ||
                getsockname(fd, reinterpret_cast<sockaddr*>(&addr), &len) != 0 ||
                ntohs(addr.sin_port) == 0u) {
                close(fd);
                return false;
            }
            fds[index] = fd;
            port = ntohs(addr.sin_port);
            return true;
        }
    } reservations;
    u16 ports[4]{};
    for (size_t i = 0u; i < 4u; i++) {
        if (!reservations.reserve(i, ports[i])) {
            error = "#329 could not bind-reserve four unique declaration-order ports";
            return false;
        }
    }
    TempDir exact_temp;
    TempDir root_temp;
    if (!exact_temp.create() || !root_temp.create() ||
        strcmp(exact_temp.path, root_temp.path) == 0 ||
        exact_temp.nginx_config == root_temp.nginx_config ||
        exact_temp.nginx_log == root_temp.nginx_log ||
        exact_temp.nginx_access_log == root_temp.nginx_access_log) {
        error = "#329 declaration orders did not receive independent temp/config/log trees";
        return false;
    }
    if (!capture_pinned_normalized_exact_trailing_slash_order(ports[0],
                                                              ports[1],
                                                              exact_temp.nginx_config,
                                                              exact_temp.nginx_log,
                                                              container_prefix + "-exact-first",
                                                              true,
                                                              exact_first,
                                                              error,
                                                              true,
                                                              &exact_temp.nginx_access_log,
                                                              &reservations.fds[0],
                                                              &reservations.fds[1]) ||
        !capture_pinned_normalized_exact_trailing_slash_order(ports[2],
                                                              ports[3],
                                                              root_temp.nginx_config,
                                                              root_temp.nginx_log,
                                                              container_prefix + "-root-first",
                                                              false,
                                                              root_first,
                                                              error,
                                                              true,
                                                              &root_temp.nginx_access_log,
                                                              &reservations.fds[2],
                                                              &reservations.fds[3])) {
        dump_log(exact_temp.nginx_config, "#329 exact-first nginx config");
        dump_log(exact_temp.nginx_log, "#329 exact-first nginx error log");
        dump_log(exact_temp.nginx_access_log, "#329 exact-first nginx access log");
        dump_log(root_temp.nginx_config, "#329 root-first nginx config");
        dump_log(root_temp.nginx_log, "#329 root-first nginx error log");
        dump_log(root_temp.nginx_access_log, "#329 root-first nginx access log");
        return false;
    }
    std::string exact_access;
    std::string root_access;
    if (!read_exact_return204_log(
            exact_temp.nginx_access_log, "#329 exact-first access log", exact_access, error) ||
        !read_exact_return204_log(
            root_temp.nginx_access_log, "#329 root-first access log", root_access, error) ||
        !parse_trailing_no_content_access_log(
            exact_access,
            "rut-nginx-329-trailing-return204-exact-before-root-" + std::to_string(getpid()) +
                "-scoped",
            ports[1],
            error) ||
        !parse_trailing_no_content_access_log(
            root_access,
            "rut-nginx-329-trailing-return204-root-before-exact-" + std::to_string(getpid()) +
                "-scoped",
            ports[3],
            error))
        return false;
    for (u32& access : exact_first.access_records) access = 1u;
    for (u32& access : root_first.access_records) access = 1u;
    return validate_trailing_no_content_pair(exact_first, root_first, ports, error);
}

struct MaxBoundaryNoContentObservation {
    bool trailing = false;
    std::string key;
    std::vector<std::string> targets;
    std::string temp_path;
    std::string config_path;
    std::string log_path;
    std::string access_path;
    std::string process_identity;
    std::vector<std::vector<char>> wires;
    std::vector<std::vector<char>> local_history;
    std::vector<std::vector<char>> forward_history;
    u32 access_records[6]{};
    u32 local_accepts = 0u;
    u32 local_requests = 0u;
    u32 local_sends = 0u;
    u32 forward_accepts = 0u;
    u32 forward_requests = 0u;
    u32 forward_sends = 0u;
};

static std::string max_boundary_prefix() {
    return "/A-Z_a.z~9/more_2/";
}

static std::string max_boundary_raw_key() {
    return max_boundary_prefix() + std::string(44u, 'R');
}

static std::string max_boundary_trailing_key() {
    return max_boundary_prefix() + std::string(43u, 'R') + "/";
}

static std::vector<std::string> max_boundary_targets(bool trailing) {
    const std::string key = trailing ? max_boundary_trailing_key() : max_boundary_raw_key();
    if (trailing) return {key, key + "?x=1", key + "/", key.substr(0u, key.size() - 1u), "/"};
    std::string doubled = key;
    const size_t separator = doubled.find('/', 1u);
    if (separator != std::string::npos) doubled.insert(separator, "/");
    std::string neighbor = key;
    if (!neighbor.empty()) neighbor.back() = 'S';
    return {key, key + "?x=1", doubled, key + "/", neighbor, "/"};
}

static bool parse_max_boundary_access_log(const std::string& contents,
                                          const std::string& prefix,
                                          const MaxBoundaryNoContentObservation& observation,
                                          u16 backend_port,
                                          std::string& error) {
    const size_t vector_count = observation.trailing ? 5u : 6u;
    std::vector<std::string> records;
    if (!split_exact_complete_log(
            contents, vector_count, "#330 bounded access log", records, error))
        return false;
    if (observation.targets.size() != vector_count) {
        error = "#330 access parser received an incomplete target inventory";
        return false;
    }
    for (size_t i = 0u; i < vector_count; i++) {
        const std::string& record = records[i];
        size_t cursor = 0u;
        const auto take = [&](const std::string& literal) {
            if (record.compare(cursor, literal.size(), literal) != 0) return false;
            cursor += literal.size();
            return true;
        };
        const auto take_token = [&](const char* literal, std::string& token) {
            if (!take(literal)) return false;
            const size_t end = record.find(' ', cursor);
            if (end == std::string::npos || end == cursor) return false;
            token = record.substr(cursor, end - cursor);
            cursor = end;
            return true;
        };
        const std::string raw = "GET " + observation.targets[i] + " HTTP/1.1";
        if (!take(prefix + " raw=\"" + raw + "\" status=")) {
            error = "#330 access log lost an exact raw spelling or request order";
            return false;
        }
        std::string status;
        std::string bytes;
        if (!take_token("", status) || !take(" bytes=") || !take_token("", bytes)) {
            error = "#330 access log status/size schema mismatch";
            return false;
        }
        const bool local = i < 3u;
        const size_t expected_status = local ? 204u : 200u;
        const size_t expected_bytes = local ? 105u : 118u;
        size_t status_value = 0u;
        size_t bytes_value = 0u;
        if (!parse_decimal_field(status, status_value) ||
            !parse_decimal_field(bytes, bytes_value) || status_value != expected_status ||
            bytes_value != expected_bytes || status != std::to_string(expected_status) ||
            bytes != std::to_string(expected_bytes) ||
            !take(" host=\"max-boundary.example\" upstream_addr=\"")) {
            error = "#330 access log status/size/host fields were not exact";
            return false;
        }
        if (local) {
            if (!take("-\" upstream_status=-")) {
                error = "#330 local access record did not prove zero upstream";
                return false;
            }
        } else {
            if (!take("127.0.0.1:")) {
                error = "#330 fallback access record lost its upstream address";
                return false;
            }
            const size_t port_end = record.find('"', cursor);
            if (port_end == std::string::npos || port_end == cursor) {
                error = "#330 fallback access record had a malformed upstream port";
                return false;
            }
            const std::string port = record.substr(cursor, port_end - cursor);
            size_t port_value = 0u;
            if (!parse_decimal_field(port, port_value) || port_value > 65535u ||
                port_value != backend_port || port != std::to_string(backend_port) ||
                record.compare(
                    port_end, strlen("\" upstream_status=200"), "\" upstream_status=200") != 0) {
                error = "#330 fallback access record upstream port/status was not exact";
                return false;
            }
            cursor = port_end + strlen("\" upstream_status=200");
        }
        if (cursor != record.size()) {
            error = "#330 access record contained an unexpected tail";
            return false;
        }
    }
    return true;
}

static bool validate_max_boundary_observation(const MaxBoundaryNoContentObservation& observation,
                                              u16 backend_port,
                                              std::string& error) {
    const std::string expected_key =
        observation.trailing ? max_boundary_trailing_key() : max_boundary_raw_key();
    const auto expected_targets = max_boundary_targets(observation.trailing);
    const size_t vector_count = observation.trailing ? 5u : 6u;
    const size_t fallback_count = observation.trailing ? 2u : 3u;
    std::string collapsed_boundary = expected_targets[2];
    const size_t doubled_separator = observation.trailing ? 61u : 10u;
    const size_t inserted_separator = observation.trailing ? 62u : 10u;
    const bool exact_boundary_shape =
        expected_targets[1].size() == 66u && expected_targets[1][62] == '?' &&
        expected_targets[2].size() == 63u && doubled_separator + 1u < expected_targets[2].size() &&
        expected_targets[2][doubled_separator] == '/' &&
        expected_targets[2][doubled_separator + 1u] == '/';
    if (inserted_separator < collapsed_boundary.size())
        collapsed_boundary.erase(inserted_separator, 1u);
    if (max_boundary_prefix().size() != 18u || expected_key.size() != 62u ||
        !exact_boundary_shape || collapsed_boundary != expected_key ||
        observation.key != expected_key || observation.targets != expected_targets ||
        observation.targets.size() != vector_count || observation.wires.size() != vector_count) {
        error = "#330 observation lost its exact 18/62-byte key or raw vector inventory";
        return false;
    }
    if (observation.local_accepts != 0u || observation.local_requests != 0u ||
        observation.local_sends != 0u || !observation.local_history.empty()) {
        error = "#330 observation lacked settled zero local-upstream evidence";
        return false;
    }
    if (observation.forward_accepts != fallback_count ||
        observation.forward_requests != fallback_count ||
        observation.forward_sends != fallback_count ||
        observation.forward_history.size() != fallback_count) {
        error = "#330 observation lacked the exact fallback count/history";
        return false;
    }
    for (size_t i = 0u; i < 6u; i++) {
        const u32 expected = i < vector_count ? 1u : 0u;
        if (observation.access_records[i] != expected) {
            error = "#330 observation access inventory was missing or duplicated";
            return false;
        }
    }
    const std::vector<char> local(kExactLocalReturn204ResponseNormalized,
                                  kExactLocalReturn204ResponseNormalized + 105u);
    const std::vector<char> fallback(
        kSuccessResponseNormalized,
        kSuccessResponseNormalized + sizeof(kSuccessResponseNormalized) - 1u);
    for (size_t i = 0u; i < vector_count; i++) {
        std::vector<char> normalized = observation.wires[i];
        if (!normalize_date(normalized) || normalized != (i < 3u ? local : fallback)) {
            error = "#330 observation wire differed from its exact 204/fallback baseline";
            return false;
        }
    }
    std::vector<std::vector<char>> expected_history;
    for (size_t i = 3u; i < vector_count; i++) {
        const std::string request = "GET " + observation.targets[i] +
                                    " HTTP/1.1\r\nHost: "
                                    "127.0.0.1:" +
                                    std::to_string(backend_port) + "\r\n\r\n";
        expected_history.emplace_back(request.begin(), request.end());
    }
    if (observation.forward_history != expected_history) {
        error = "#330 fallback history contained a retry, reorder, or byte mismatch";
        return false;
    }
    return true;
}

static bool validate_max_boundary_pair(const MaxBoundaryNoContentObservation observations[2],
                                       const u16 ports[4],
                                       std::string& error) {
    for (size_t i = 0u; i < 4u; i++) {
        if (ports[i] == 0u) {
            error = "#330 pair validator received a zero port";
            return false;
        }
        for (size_t j = i + 1u; j < 4u; j++) {
            if (ports[i] == ports[j]) {
                error = "#330 pinned semantic sides shared a dynamic port";
                return false;
            }
        }
    }
    if (observations[0].trailing || !observations[1].trailing ||
        !validate_max_boundary_observation(observations[0], ports[1], error) ||
        !validate_max_boundary_observation(observations[1], ports[3], error))
        return false;
    const std::string* resources[] = {&observations[0].temp_path,
                                      &observations[0].config_path,
                                      &observations[0].log_path,
                                      &observations[0].access_path,
                                      &observations[0].process_identity,
                                      &observations[1].temp_path,
                                      &observations[1].config_path,
                                      &observations[1].log_path,
                                      &observations[1].access_path,
                                      &observations[1].process_identity};
    for (size_t i = 0u; i < 10u; i++) {
        if (resources[i]->empty()) {
            error = "#330 one resource identity was empty";
            return false;
        }
        for (size_t j = i + 1u; j < 10u; j++) {
            if (*resources[i] == *resources[j]) {
                error = "#330 pinned semantic sides shared a resource identity";
                return false;
            }
        }
    }
    return true;
}

static bool capture_pinned_max_boundary_side(u16 frontend_port,
                                             u16 backend_port,
                                             TempDir& temp,
                                             const std::string& container_name,
                                             bool trailing,
                                             MaxBoundaryNoContentObservation& observation,
                                             std::string& error,
                                             int* frontend_reservation,
                                             int* backend_reservation) {
    const std::string key = trailing ? max_boundary_trailing_key() : max_boundary_raw_key();
    const auto targets = max_boundary_targets(trailing);
    const size_t vector_count = trailing ? 5u : 6u;
    const size_t fallback_count = trailing ? 2u : 3u;
    if (max_boundary_prefix().size() != 18u || key.size() != 62u ||
        targets.size() != vector_count || frontend_reservation == nullptr ||
        backend_reservation == nullptr || *frontend_reservation < 0 || *backend_reservation < 0) {
        error = "#330 capture received invalid key lengths, vectors, or reservations";
        return false;
    }
    observation = MaxBoundaryNoContentObservation{};
    observation.trailing = trailing;
    observation.key = key;
    observation.targets = targets;
    observation.temp_path = temp.path;
    observation.config_path = temp.nginx_config;
    observation.log_path = temp.nginx_log;
    observation.access_path = temp.nginx_access_log;
    observation.process_identity = container_name;
    observation.wires.resize(vector_count);
    const std::string side = trailing ? "trailing-root-before-exact" : "raw-exact-before-root";
    const std::string access_prefix =
        "rut-nginx-330-max-boundary-" + side + "-" + std::to_string(getpid()) + "-scoped";
    const std::string exact_location = "    location = " + key + " { return 204; }\n";
    const std::string root_location =
        "    location / { proxy_pass http://127.0.0.1:" + std::to_string(backend_port) + "; }\n";
    const std::string config =
        "error_log stderr notice;\n"
        "events {}\n"
        "http {\n"
        "  log_format max_boundary '" +
        access_prefix +
        " raw=\"$request\" status=$status bytes=$bytes_sent host=\"$host\" "
        "upstream_addr=\"$upstream_addr\" upstream_status=$upstream_status';\n"
        "  access_log " +
        temp.nginx_access_log +
        " max_boundary;\n"
        "  server {\n"
        "    listen " +
        std::to_string(frontend_port) + ";\n" +
        (trailing ? root_location + exact_location : exact_location + root_location) +
        "  }\n"
        "}\n";
    if (!write_file(temp.nginx_config, config.data(), config.size())) {
        error = "#330 failed to write pinned nginx config";
        return false;
    }
    const auto make_request = [](const std::string& target) {
        return "GET " + target +
               " HTTP/1.1\r\nHost: max-boundary.example\r\nConnection: close\r\n\r\n";
    };
    for (const std::string& target : targets) {
        const std::string request = make_request(target);
        const size_t end = request.find("\r\n\r\n");
        if (request.rfind("GET " + target + " HTTP/1.1\r\n", 0u) != 0u ||
            request.find('#') != std::string::npos ||
            request.find("\r\nContent-Length:") != std::string::npos ||
            request.find("\r\nTransfer-Encoding:") != std::string::npos ||
            request.find("\r\nTE:") != std::string::npos ||
            request.find("\r\nExpect:") != std::string::npos ||
            request.find("\r\nUpgrade:") != std::string::npos || end == std::string::npos ||
            end + 4u != request.size()) {
            error = "#330 request escaped the bounded fresh bodyless GET domain";
            return false;
        }
    }

    const auto recorder_live = [](const Recorder& recorder) {
        return recorder.running.load(std::memory_order_acquire) &&
               recorder.thread_alive.load(std::memory_order_acquire) &&
               !recorder.listener_failed.load(std::memory_order_acquire);
    };
    ChildGuard nginx;
    const auto wait_live = [&](Recorder& recorder, const char* phase) {
        const auto deadline = std::chrono::steady_clock::now() + std::chrono::seconds(2);
        while (std::chrono::steady_clock::now() < deadline) {
            if (poll_child(nginx.child) || !recorder.running.load(std::memory_order_acquire) ||
                recorder.listener_failed.load(std::memory_order_acquire)) {
                error = std::string("#330 nginx/recorder failed before ") + phase + " readiness";
                return false;
            }
            if (recorder.thread_alive.load(std::memory_order_acquire)) return true;
            usleep(1000);
        }
        error = std::string("#330 recorder readiness timed out: ") + phase;
        return false;
    };
    const auto observe = [&](Recorder& recorder, u32 expected, const char* phase) {
        const auto deadline = std::chrono::steady_clock::now() + std::chrono::milliseconds(500);
        while (std::chrono::steady_clock::now() < deadline) {
            if (poll_child(nginx.child) || !recorder_live(recorder) ||
                recorder.accepted.load(std::memory_order_acquire) != expected ||
                recorder.requests.load(std::memory_order_acquire) != expected ||
                recorder.response_send_all_calls.load(std::memory_order_acquire) != expected) {
                error = std::string("#330 unexpected process/upstream state during ") + phase;
                return false;
            }
            usleep(5000);
        }
        return true;
    };
    const auto wait_count = [&](Recorder& recorder, u32 expected) {
        const auto deadline = std::chrono::steady_clock::now() + std::chrono::seconds(2);
        while (std::chrono::steady_clock::now() < deadline) {
            if (poll_child(nginx.child) || !recorder_live(recorder)) return false;
            const u32 accepts = recorder.accepted.load(std::memory_order_acquire);
            const u32 requests = recorder.requests.load(std::memory_order_acquire);
            const u32 sends = recorder.response_send_all_calls.load(std::memory_order_acquire);
            if (accepts > expected || requests > expected || sends > expected) return false;
            if (accepts == expected && requests == expected && sends == expected) return true;
            usleep(1000);
        }
        return false;
    };
    const auto request = [&](size_t index, const char* expected) {
        struct ClientGuard {
            int fd = -1;
            ~ClientGuard() {
                if (fd >= 0) close(fd);
            }
        } client{connect_once(frontend_port)};
        const std::string request_text = make_request(targets[index]);
        std::string detail;
        if (client.fd < 0 || !send_all(client.fd, request_text.data(), request_text.size()) ||
            !(index < 3u ? read_head_response(client.fd, observation.wires[index], detail)
                         : read_response(client.fd, observation.wires[index], detail)) ||
            !read_eof(client.fd, detail) ||
            !validate_exact_normalized_response(observation.wires[index], expected, detail)) {
            error = "#330 vector " + targets[index] + " response/EOF failed: " + detail;
            return false;
        }
        const std::string wire(observation.wires[index].begin(), observation.wires[index].end());
        if (wire.find("\r\nLocation:") != std::string::npos ||
            (index < 3u &&
             (observation.wires[index].size() != 105u ||
              header_end(observation.wires[index]) != observation.wires[index].size() ||
              wire.find("\r\nContent-Type:") != std::string::npos ||
              wire.find("\r\nContent-Length:") != std::string::npos ||
              wire.find("\r\nTransfer-Encoding:") != std::string::npos))) {
            error = "#330 local wire gained framing, representation, redirect, body, or tail";
            return false;
        }
        return !poll_child(nginx.child);
    };

    Recorder local;
    local.observe_extra_requests_until_stop = true;
    close(*backend_reservation);
    *backend_reservation = -1;
    if (!local.setup(backend_port)) {
        error = "#330 local recorder could not bind its reserved backend port";
        return false;
    }
    DockerGuard docker(container_name);
    const std::vector<std::string> docker_args = {"docker",
                                                  "run",
                                                  "--pull=never",
                                                  "--network",
                                                  "host",
                                                  "--name",
                                                  container_name,
                                                  "-v",
                                                  temp.nginx_config + ":/etc/nginx/nginx.conf:ro",
                                                  "-v",
                                                  std::string(temp.path) + ":" + temp.path,
                                                  kNginxImage,
                                                  "nginx",
                                                  "-g",
                                                  "daemon off;"};
    close(*frontend_reservation);
    *frontend_reservation = -1;
    if (!spawn_child(docker_args, temp.nginx_log, nginx.child) ||
        !wait_ready(frontend_port, nginx.child, error) || !wait_live(local, "local")) {
        if (error.empty()) error = "#330 failed to start pinned nginx/local recorder";
        return false;
    }
    for (size_t i = 0u; i < 3u; i++) {
        if (!request(i, kExactLocalReturn204ResponseNormalized) ||
            local.accepted.load(std::memory_order_acquire) != 0u ||
            local.requests.load(std::memory_order_acquire) != 0u ||
            local.response_send_all_calls.load(std::memory_order_acquire) != 0u) {
            error = "#330 normalized exact local vector reached upstream";
            return false;
        }
    }
    if (!observe(local, 0u, "live local zero-upstream window")) return false;
    local.stop();
    observation.local_accepts = local.accepted.load(std::memory_order_acquire);
    observation.local_requests = local.requests.load(std::memory_order_acquire);
    observation.local_sends = local.response_send_all_calls.load(std::memory_order_acquire);
    observation.local_history = local.history;
    if (local.thread_alive.load(std::memory_order_acquire) ||
        local.listener_failed.load(std::memory_order_acquire) || observation.local_accepts != 0u ||
        observation.local_requests != 0u || observation.local_sends != 0u ||
        local.response_send_succeeded.load(std::memory_order_acquire) || !local.history.empty() ||
        !local.request.empty()) {
        error = "#330 local recorder did not settle with zero upstream activity";
        return false;
    }

    Recorder forward;
    forward.observe_extra_requests_until_stop = true;
    if (!forward.setup(backend_port,
                       static_cast<u32>(fallback_count),
                       kBackendResponse,
                       sizeof(kBackendResponse) - 1u) ||
        !wait_live(forward, "fallback") || !observe(forward, 0u, "pre-fallback zero window"))
        return false;
    for (size_t i = 3u; i < vector_count; i++) {
        const u32 expected = static_cast<u32>(i - 2u);
        if (!request(i, kSuccessResponseNormalized) || !wait_count(forward, expected) ||
            !observe(forward, expected, "ordered fallback count")) {
            error = "#330 fallback count/order/retry evidence failed";
            return false;
        }
    }
    if (!observe(forward,
                 static_cast<u32>(fallback_count),
                 trailing ? "live no-third-forward window" : "live no-fourth-forward window") ||
        !stop_child(nginx.child) || !docker.remove()) {
        error = "#330 pinned nginx did not complete cleanly";
        return false;
    }
    forward.stop();
    observation.forward_accepts = forward.accepted.load(std::memory_order_acquire);
    observation.forward_requests = forward.requests.load(std::memory_order_acquire);
    observation.forward_sends = forward.response_send_all_calls.load(std::memory_order_acquire);
    observation.forward_history = forward.history;
    if (forward.thread_alive.load(std::memory_order_acquire) ||
        forward.listener_failed.load(std::memory_order_acquire) ||
        observation.forward_accepts != fallback_count ||
        observation.forward_requests != fallback_count ||
        observation.forward_sends != fallback_count ||
        !forward.response_send_succeeded.load(std::memory_order_acquire) ||
        !forward.response_clean_shutdown.load(std::memory_order_acquire) ||
        !forward.response_connection_closed.load(std::memory_order_acquire) ||
        observation.forward_history.size() != fallback_count) {
        error = "#330 fallback recorder lifecycle/count was incomplete";
        return false;
    }
    std::string access_contents;
    std::string error_contents;
    if (!read_exact_return204_log(
            temp.nginx_access_log, "#330 pinned access log", access_contents, error) ||
        !parse_max_boundary_access_log(
            access_contents, access_prefix, observation, backend_port, error) ||
        !read_exact_return204_log(
            temp.nginx_log, "#330 pinned nginx error log", error_contents, error))
        return false;
    for (const char* severity : {"[warn]", "[error]", "[crit]", "[alert]", "[emerg]"}) {
        if (error_contents.find(severity) != std::string::npos) {
            error = std::string("#330 pinned nginx error log contained ") + severity;
            return false;
        }
    }
    for (size_t i = 0u; i < vector_count; i++) observation.access_records[i] = 1u;
    return validate_max_boundary_observation(observation, backend_port, error);
}

static MaxBoundaryNoContentObservation make_max_boundary_self_check(bool trailing,
                                                                    u16 backend_port,
                                                                    const char* suffix) {
    static constexpr char kDate[] = "Wed, 26 Aug 2026 23:57:18 GMT";
    const auto observed = [](const char* normalized, size_t size) {
        std::vector<char> wire(normalized, normalized + size);
        const std::string marker(29u, 'X');
        const auto date = std::search(wire.begin(), wire.end(), marker.begin(), marker.end());
        if (date != wire.end()) std::copy_n(kDate, 29u, date);
        return wire;
    };
    MaxBoundaryNoContentObservation value;
    value.trailing = trailing;
    value.key = trailing ? max_boundary_trailing_key() : max_boundary_raw_key();
    value.targets = max_boundary_targets(trailing);
    value.temp_path = std::string("/tmp/330-") + suffix;
    value.config_path = value.temp_path + "/nginx.conf";
    value.log_path = value.temp_path + "/nginx.log";
    value.access_path = value.temp_path + "/access.log";
    value.process_identity = std::string("rut-nginx-330-") + suffix;
    for (size_t i = 0u; i < value.targets.size(); i++) {
        value.wires.push_back(
            i < 3u ? observed(kExactLocalReturn204ResponseNormalized, 105u)
                   : observed(kSuccessResponseNormalized, sizeof(kSuccessResponseNormalized) - 1u));
        value.access_records[i] = 1u;
    }
    const size_t fallback_count = trailing ? 2u : 3u;
    value.forward_accepts = static_cast<u32>(fallback_count);
    value.forward_requests = static_cast<u32>(fallback_count);
    value.forward_sends = static_cast<u32>(fallback_count);
    for (size_t i = 3u; i < value.targets.size(); i++) {
        const std::string request = "GET " + value.targets[i] +
                                    " HTTP/1.1\r\nHost: 127.0.0.1:" + std::to_string(backend_port) +
                                    "\r\n\r\n";
        value.forward_history.emplace_back(request.begin(), request.end());
    }
    return value;
}

static std::string make_max_boundary_access_fixture(
    const std::string& prefix,
    const MaxBoundaryNoContentObservation& observation,
    u16 backend_port) {
    std::string result;
    for (size_t i = 0u; i < observation.targets.size(); i++) {
        const bool local = i < 3u;
        result += prefix + " raw=\"GET " + observation.targets[i] +
                  " HTTP/1.1\" status=" + (local ? "204" : "200") +
                  " bytes=" + (local ? "105" : "118") +
                  " host=\"max-boundary.example\" upstream_addr=\"" +
                  (local ? "-\" upstream_status=-"
                         : "127.0.0.1:" + std::to_string(backend_port) + "\" upstream_status=200") +
                  "\n";
    }
    return result;
}

static bool run_max_boundary_access_self_checks(std::string& error) {
    static constexpr u16 kPort = 54321u;
    const std::string prefix = "rut-nginx-330-max-boundary-self-check";
    const auto raw = make_max_boundary_self_check(false, kPort, "access-raw");
    const auto trailing = make_max_boundary_self_check(true, kPort, "access-trailing");
    const std::string valid_raw = make_max_boundary_access_fixture(prefix, raw, kPort);
    const std::string valid_trailing = make_max_boundary_access_fixture(prefix, trailing, kPort);
    if (!parse_max_boundary_access_log(valid_raw, prefix, raw, kPort, error) ||
        !parse_max_boundary_access_log(valid_trailing, prefix, trailing, kPort, error))
        return false;
    const auto rejects = [&](const std::string& value,
                             const MaxBoundaryNoContentObservation& observation) {
        std::string detail;
        return !parse_max_boundary_access_log(value, prefix, observation, kPort, detail);
    };
    const auto replace_once =
        [](std::string value, const std::string& from, const std::string& to) {
            const size_t offset = value.find(from);
            if (offset == std::string::npos) return std::string{};
            value.replace(offset, from.size(), to);
            return value;
        };
    const size_t first_end = valid_raw.find('\n');
    const size_t last_begin = valid_raw.rfind('\n', valid_raw.size() - 2u) + 1u;
    const std::pair<const char*, bool> mutations[] = {
        {"missing", rejects(valid_raw.substr(0u, last_begin), raw)},
        {"extra", rejects(valid_raw + valid_raw.substr(0u, first_end + 1u), raw)},
        {"overflow",
         rejects(replace_once(valid_raw, "status=204", "status=999999999999999999999999999999999"),
                 raw)},
        {"raw-spelling",
         rejects(replace_once(valid_raw, "/A-Z_a.z~9//more_2/", "/A-Z_a.z~9/more_2/"), raw)},
        {"query-boundary",
         rejects(replace_once(valid_raw, raw.key + "?x=1", raw.key + "R?x=1"), raw)},
        {"trailing-run",
         rejects(replace_once(valid_trailing, trailing.key + "/", trailing.key), trailing)}};
    for (const auto& mutation : mutations) {
        if (!mutation.second) {
            error = std::string("#330 access mutation accepted: ") + mutation.first;
            return false;
        }
    }
    return true;
}

static bool run_max_boundary_observation_self_checks(std::string& error) {
    static constexpr u16 kPorts[] = {54320u, 54321u, 54322u, 54323u};
    const auto raw = make_max_boundary_self_check(false, kPorts[1], "raw");
    const auto trailing = make_max_boundary_self_check(true, kPorts[3], "trailing");
    const MaxBoundaryNoContentObservation valid[2] = {raw, trailing};
    if (!validate_max_boundary_pair(valid, kPorts, error)) return false;
    const auto rejects_observation =
        [&](const char* name, MaxBoundaryNoContentObservation value, u16 backend_port) {
            std::string detail;
            if (!validate_max_boundary_observation(value, backend_port, detail)) return true;
            error = std::string("#330 observation mutation accepted: ") + name;
            return false;
        };
    auto mutated = raw;
    mutated.key.pop_back();
    if (!rejects_observation("61-byte-key", mutated, kPorts[1])) return false;
    mutated = raw;
    mutated.key.push_back('R');
    if (!rejects_observation("63-byte-key", mutated, kPorts[1])) return false;
    mutated = raw;
    mutated.wires[2] = raw.wires[3];
    if (!rejects_observation("embedded-double-slash-local-wire", mutated, kPorts[1])) return false;
    mutated = raw;
    mutated.access_records[2] = 0u;
    if (!rejects_observation("embedded-double-slash-local-count", mutated, kPorts[1])) return false;
    mutated = raw;
    mutated.targets[1].insert(62u, "R");
    if (!rejects_observation("raw-query-boundary", mutated, kPorts[1])) return false;
    mutated = trailing;
    mutated.targets[2].pop_back();
    if (!rejects_observation("normalized-double-slash", mutated, kPorts[3])) return false;
    mutated = raw;
    mutated.wires[0][9] = '5';
    if (!rejects_observation("wire-status", mutated, kPorts[1])) return false;
    mutated = raw;
    mutated.wires[0].pop_back();
    if (!rejects_observation("wire-size", mutated, kPorts[1])) return false;
    mutated = raw;
    mutated.wires[0].push_back('x');
    if (!rejects_observation("wire-tail", mutated, kPorts[1])) return false;
    mutated = raw;
    mutated.local_requests = 1u;
    if (!rejects_observation("local-nonzero", mutated, kPorts[1])) return false;
    mutated = raw;
    mutated.local_history.push_back(raw.forward_history[0]);
    if (!rejects_observation("local-history", mutated, kPorts[1])) return false;
    mutated = raw;
    mutated.forward_requests = 2u;
    if (!rejects_observation("fallback-count", mutated, kPorts[1])) return false;
    mutated = raw;
    std::swap(mutated.forward_history[0], mutated.forward_history[1]);
    if (!rejects_observation("fallback-order", mutated, kPorts[1])) return false;
    mutated = raw;
    mutated.forward_history.push_back(raw.forward_history[0]);
    if (!rejects_observation("fallback-retry", mutated, kPorts[1])) return false;
    mutated = raw;
    mutated.access_records[0] = 2u;
    if (!rejects_observation("access-extra", mutated, kPorts[1])) return false;

    const auto rejects_pair = [&](const MaxBoundaryNoContentObservation values[2],
                                  const u16 ports[4]) {
        std::string detail;
        return !validate_max_boundary_pair(values, ports, detail);
    };
    MaxBoundaryNoContentObservation changed[2] = {raw, trailing};
    changed[1].access_path = changed[0].access_path;
    if (!rejects_pair(changed, kPorts)) {
        error = "#330 pair resource-alias mutation was accepted";
        return false;
    }
    changed[1] = trailing;
    u16 changed_ports[4];
    std::copy(std::begin(kPorts), std::end(kPorts), std::begin(changed_ports));
    changed_ports[3] = changed_ports[0];
    if (!rejects_pair(changed, changed_ports)) {
        error = "#330 pair duplicate-port mutation was accepted";
        return false;
    }
    changed_ports[3] = kPorts[3];
    changed_ports[0] = 0u;
    if (!rejects_pair(changed, changed_ports)) {
        error = "#330 pair zero-port mutation was accepted";
        return false;
    }
    return true;
}

static bool run_pinned_max_boundary_no_content_oracle(
    const std::string& container_prefix,
    MaxBoundaryNoContentObservation observations[2],
    std::string& error) {
    struct ReservedPorts {
        int fds[4];

        ReservedPorts() { std::fill(std::begin(fds), std::end(fds), -1); }
        ~ReservedPorts() {
            for (int fd : fds)
                if (fd >= 0) close(fd);
        }

        bool reserve(size_t index, u16& port) {
            const int fd = socket(AF_INET, SOCK_STREAM | SOCK_CLOEXEC, 0);
            if (fd < 0) return false;
            sockaddr_in address{};
            address.sin_family = AF_INET;
            address.sin_addr.s_addr = htonl(INADDR_LOOPBACK);
            address.sin_port = 0;
            socklen_t length = sizeof(address);
            if (bind(fd, reinterpret_cast<sockaddr*>(&address), sizeof(address)) != 0 ||
                getsockname(fd, reinterpret_cast<sockaddr*>(&address), &length) != 0 ||
                ntohs(address.sin_port) == 0u) {
                close(fd);
                return false;
            }
            fds[index] = fd;
            port = ntohs(address.sin_port);
            return true;
        }
    } reservations;
    u16 ports[4]{};
    for (size_t i = 0u; i < 4u; i++) {
        if (!reservations.reserve(i, ports[i])) {
            error = "#330 could not bind-reserve four unique pinned-side ports";
            return false;
        }
    }
    TempDir temps[2];
    if (!temps[0].create() || !temps[1].create() || strcmp(temps[0].path, temps[1].path) == 0 ||
        temps[0].nginx_config == temps[1].nginx_config ||
        temps[0].nginx_log == temps[1].nginx_log ||
        temps[0].nginx_access_log == temps[1].nginx_access_log) {
        error = "#330 could not create two independent pinned resource trees";
        return false;
    }
    if (!capture_pinned_max_boundary_side(ports[0],
                                          ports[1],
                                          temps[0],
                                          container_prefix + "-raw-exact-first",
                                          false,
                                          observations[0],
                                          error,
                                          &reservations.fds[0],
                                          &reservations.fds[1]) ||
        !capture_pinned_max_boundary_side(ports[2],
                                          ports[3],
                                          temps[1],
                                          container_prefix + "-trailing-root-first",
                                          true,
                                          observations[1],
                                          error,
                                          &reservations.fds[2],
                                          &reservations.fds[3]))
        return false;
    return validate_max_boundary_pair(observations, ports, error);
}

struct BodyfulNormalizedExactObservation {
    std::string order;
    std::string temp_path;
    std::string config_path;
    std::string log_path;
    std::string access_path;
    std::string process_identity;
    std::vector<std::string> targets;
    std::vector<std::vector<char>> wires;
    std::vector<std::vector<char>> local_history;
    std::vector<std::vector<char>> forward_history;
    u32 access_records[7]{};
    u32 local_accepts = 0u;
    u32 local_requests = 0u;
    u32 local_sends = 0u;
    u32 forward_accepts = 0u;
    u32 forward_requests = 0u;
    u32 forward_sends = 0u;
};

static std::vector<std::string> bodyful_normalized_exact_targets() {
    return {"/a/b", "/a/b?x=1", "/a//b", "/a//b?x=1", "/a/b/", "/a/c", "/"};
}

static bool parse_bodyful_normalized_exact_access_log(
    const std::string& contents,
    const std::string& prefix,
    const BodyfulNormalizedExactObservation& observation,
    u16 backend_port,
    std::string& error) {
    std::vector<std::string> records;
    if (!split_exact_complete_log(contents, 7u, "#331 bounded access log", records, error) ||
        observation.targets != bodyful_normalized_exact_targets()) {
        if (error.empty()) error = "#331 access parser lost its exact seven-vector inventory";
        return false;
    }
    for (size_t i = 0u; i < records.size(); i++) {
        const bool local = i < 4u;
        const std::string expected =
            prefix + " raw=\"GET " + observation.targets[i] +
            " HTTP/1.1\" status=" + (local ? "200" : "201") + " bytes=" + (local ? "144" : "175") +
            " host=\"bodyful-normalized.example\" upstream_addr=\"" +
            (local ? "-\" upstream_status=-"
                   : "127.0.0.1:" + std::to_string(backend_port) + "\" upstream_status=201");
        if (records[i] != expected) {
            error = "#331 access log lost raw spelling, order, status, size, or upstream evidence";
            return false;
        }
    }
    return true;
}

static bool validate_bodyful_normalized_exact_observation(
    const BodyfulNormalizedExactObservation& observation, u16 backend_port, std::string& error) {
    const auto targets = bodyful_normalized_exact_targets();
    if (observation.targets != targets || observation.wires.size() != targets.size()) {
        error = "#331 observation lost its exact seven-vector inventory";
        return false;
    }
    if (observation.local_accepts != 0u || observation.local_requests != 0u ||
        observation.local_sends != 0u || !observation.local_history.empty()) {
        error = "#331 observation lacked settled zero local-upstream evidence";
        return false;
    }
    if (observation.forward_accepts != 3u || observation.forward_requests != 3u ||
        observation.forward_sends != 3u || observation.forward_history.size() != 3u) {
        error = "#331 observation lacked exactly three fallback episodes";
        return false;
    }
    for (u32 count : observation.access_records) {
        if (count != 1u) {
            error = "#331 observation lacked exactly seven ordered access records";
            return false;
        }
    }
    const std::vector<char> local(kBodyfulNormalizedExactResponseNormalized,
                                  kBodyfulNormalizedExactResponseNormalized + 144u);
    const std::vector<char> fallback(kBodyfulNormalizedFallbackResponseNormalized,
                                     kBodyfulNormalizedFallbackResponseNormalized + 175u);
    for (size_t i = 0u; i < observation.wires.size(); i++) {
        std::vector<char> normalized = observation.wires[i];
        if (!normalize_date(normalized) || normalized != (i < 4u ? local : fallback)) {
            error = "#331 observation wire differed from its exact local/fallback baseline";
            return false;
        }
    }
    std::vector<std::vector<char>> expected_history;
    for (size_t i = 4u; i < targets.size(); i++) {
        const std::string request = "GET " + targets[i] +
                                    " HTTP/1.1\r\nHost: 127.0.0.1:" + std::to_string(backend_port) +
                                    "\r\n\r\n";
        expected_history.emplace_back(request.begin(), request.end());
    }
    if (observation.forward_history != expected_history) {
        error = "#331 fallback history contained a retry, reorder, or byte mismatch";
        return false;
    }
    return true;
}

static bool validate_bodyful_normalized_exact_pair(
    const BodyfulNormalizedExactObservation observations[2],
    const u16 ports[4],
    std::string& error) {
    for (size_t i = 0u; i < 4u; i++) {
        if (ports[i] == 0u) {
            error = "#331 pair validator received a zero port";
            return false;
        }
        for (size_t j = i + 1u; j < 4u; j++) {
            if (ports[i] == ports[j]) {
                error = "#331 declaration-order sides shared a dynamic port";
                return false;
            }
        }
    }
    if (observations[0].order != "exact-before-root" ||
        observations[1].order != "root-before-exact" ||
        !validate_bodyful_normalized_exact_observation(observations[0], ports[1], error) ||
        !validate_bodyful_normalized_exact_observation(observations[1], ports[3], error))
        return false;
    const std::string* resources[] = {&observations[0].temp_path,
                                      &observations[0].config_path,
                                      &observations[0].log_path,
                                      &observations[0].access_path,
                                      &observations[0].process_identity,
                                      &observations[1].temp_path,
                                      &observations[1].config_path,
                                      &observations[1].log_path,
                                      &observations[1].access_path,
                                      &observations[1].process_identity};
    for (size_t i = 0u; i < 10u; i++) {
        if (resources[i]->empty()) {
            error = "#331 declaration-order resource identity was empty";
            return false;
        }
        for (size_t j = i + 1u; j < 10u; j++) {
            if (*resources[i] == *resources[j]) {
                error = "#331 declaration-order resource identities were aliased";
                return false;
            }
        }
    }
    for (size_t i = 0u; i < 7u; i++) {
        std::vector<char> left = observations[0].wires[i];
        std::vector<char> right = observations[1].wires[i];
        if (!normalize_date(left) || !normalize_date(right) || left != right) {
            error =
                "#331 declaration order changed Date-normalized vector " + std::to_string(i + 1u);
            return false;
        }
    }
    if (canonicalize_bounded_backend_history(observations[0].forward_history) !=
        canonicalize_bounded_backend_history(observations[1].forward_history)) {
        error = "#331 declaration order changed canonical fallback history";
        return false;
    }
    return true;
}

static bool capture_pinned_bodyful_normalized_exact_side(
    u16 frontend_port,
    u16 backend_port,
    TempDir& temp,
    const std::string& container_name,
    bool exact_first,
    BodyfulNormalizedExactObservation& observation,
    std::string& error,
    int* frontend_reservation,
    int* backend_reservation) {
    const auto targets = bodyful_normalized_exact_targets();
    if (targets.size() != 7u || frontend_reservation == nullptr || backend_reservation == nullptr ||
        *frontend_reservation < 0 || *backend_reservation < 0) {
        error = "#331 capture received incomplete vectors or port reservations";
        return false;
    }
    observation = BodyfulNormalizedExactObservation{};
    observation.order = exact_first ? "exact-before-root" : "root-before-exact";
    observation.temp_path = temp.path;
    observation.config_path = temp.nginx_config;
    observation.log_path = temp.nginx_log;
    observation.access_path = temp.nginx_access_log;
    observation.process_identity = container_name;
    observation.targets = targets;
    observation.wires.resize(targets.size());
    const std::string access_prefix = "rut-nginx-331-bodyful-normalized-" + observation.order +
                                      "-" + std::to_string(getpid()) + "-scoped";
    const std::string exact_location = "    location = /a/b { return 200 \"ok\"; }\n";
    const std::string root_location =
        "    location / { proxy_pass http://127.0.0.1:" + std::to_string(backend_port) + "; }\n";
    const std::string config =
        "error_log stderr notice;\n"
        "events {}\n"
        "http {\n"
        "  log_format bodyful_normalized '" +
        access_prefix +
        " raw=\"$request\" status=$status bytes=$bytes_sent host=\"$host\" "
        "upstream_addr=\"$upstream_addr\" upstream_status=$upstream_status';\n"
        "  access_log " +
        temp.nginx_access_log +
        " bodyful_normalized;\n"
        "  server {\n"
        "    listen " +
        std::to_string(frontend_port) + ";\n" +
        (exact_first ? exact_location + root_location : root_location + exact_location) +
        "  }\n"
        "}\n";
    if (config.find("merge_slashes") != std::string::npos ||
        !write_file(temp.nginx_config, config.data(), config.size())) {
        error = "#331 failed to write a default-merge-slashes pinned nginx config";
        return false;
    }
    const auto make_request = [](const std::string& target) {
        return "GET " + target +
               " HTTP/1.1\r\nHost: bodyful-normalized.example\r\nConnection: close\r\n\r\n";
    };
    for (const std::string& target : targets) {
        const std::string request = make_request(target);
        const size_t end = request.find("\r\n\r\n");
        if (request.rfind("GET " + target + " HTTP/1.1\r\n", 0u) != 0u ||
            request.find('#') != std::string::npos ||
            request.find("\r\nContent-Length:") != std::string::npos ||
            request.find("\r\nTransfer-Encoding:") != std::string::npos ||
            request.find("\r\nTE:") != std::string::npos ||
            request.find("\r\nExpect:") != std::string::npos ||
            request.find("\r\nUpgrade:") != std::string::npos || end == std::string::npos ||
            end + 4u != request.size()) {
            error = "#331 request escaped the fresh bodyless origin-form GET domain";
            return false;
        }
    }

    ChildGuard nginx;
    const auto recorder_live = [](const Recorder& recorder) {
        return recorder.running.load(std::memory_order_acquire) &&
               recorder.thread_alive.load(std::memory_order_acquire) &&
               !recorder.listener_failed.load(std::memory_order_acquire);
    };
    const auto wait_live = [&](Recorder& recorder, const char* phase) {
        const auto deadline = std::chrono::steady_clock::now() + std::chrono::seconds(2);
        while (std::chrono::steady_clock::now() < deadline) {
            if (poll_child(nginx.child) || !recorder.running.load(std::memory_order_acquire) ||
                recorder.listener_failed.load(std::memory_order_acquire)) {
                error = std::string("#331 nginx/recorder failed before ") + phase + " readiness";
                return false;
            }
            if (recorder.thread_alive.load(std::memory_order_acquire)) return true;
            usleep(1000);
        }
        error = std::string("#331 recorder readiness timed out: ") + phase;
        return false;
    };
    const auto observe = [&](Recorder& recorder, u32 expected, const char* phase) {
        const auto deadline = std::chrono::steady_clock::now() + std::chrono::milliseconds(500);
        while (std::chrono::steady_clock::now() < deadline) {
            if (poll_child(nginx.child) || !recorder_live(recorder) ||
                recorder.accepted.load(std::memory_order_acquire) != expected ||
                recorder.requests.load(std::memory_order_acquire) != expected ||
                recorder.response_send_all_calls.load(std::memory_order_acquire) != expected) {
                error = std::string("#331 unexpected process/upstream state during ") + phase;
                return false;
            }
            usleep(5000);
        }
        return true;
    };
    const auto wait_count = [&](Recorder& recorder, u32 expected) {
        const auto deadline = std::chrono::steady_clock::now() + std::chrono::seconds(2);
        while (std::chrono::steady_clock::now() < deadline) {
            if (poll_child(nginx.child) || !recorder_live(recorder)) return false;
            const u32 accepts = recorder.accepted.load(std::memory_order_acquire);
            const u32 requests = recorder.requests.load(std::memory_order_acquire);
            const u32 sends = recorder.response_send_all_calls.load(std::memory_order_acquire);
            if (accepts > expected || requests > expected || sends > expected) return false;
            if (accepts == expected && requests == expected && sends == expected) return true;
            usleep(1000);
        }
        return false;
    };
    const auto request = [&](size_t index, const char* expected) {
        struct ClientGuard {
            int fd = -1;
            ~ClientGuard() {
                if (fd >= 0) close(fd);
            }
        } client{connect_once(frontend_port)};
        const std::string request_text = make_request(targets[index]);
        std::string detail;
        if (client.fd < 0 || !send_all(client.fd, request_text.data(), request_text.size()) ||
            !read_response(client.fd, observation.wires[index], detail) ||
            !read_eof(client.fd, detail) ||
            !validate_exact_normalized_response(observation.wires[index], expected, detail)) {
            error = "#331 vector " + targets[index] + " response/EOF failed: " + detail;
            dump_wire("#331 mismatched response", observation.wires[index]);
            return false;
        }
        const size_t expected_size = index < 4u ? 144u : 175u;
        if (observation.wires[index].size() != expected_size ||
            header_end(observation.wires[index]) + (index < 4u ? 2u : 8u) != expected_size ||
            poll_child(nginx.child)) {
            error = "#331 vector gained a wrong body length, tail, or process state";
            return false;
        }
        return true;
    };

    Recorder local;
    local.observe_extra_requests_until_stop = true;
    close(*backend_reservation);
    *backend_reservation = -1;
    if (!local.setup(backend_port)) {
        error = "#331 local recorder could not bind its reserved backend port";
        return false;
    }
    DockerGuard docker(container_name);
    const std::vector<std::string> docker_args = {"docker",
                                                  "run",
                                                  "--pull=never",
                                                  "--network",
                                                  "host",
                                                  "--name",
                                                  container_name,
                                                  "-v",
                                                  temp.nginx_config + ":/etc/nginx/nginx.conf:ro",
                                                  "-v",
                                                  std::string(temp.path) + ":" + temp.path,
                                                  kNginxImage,
                                                  "nginx",
                                                  "-g",
                                                  "daemon off;"};
    close(*frontend_reservation);
    *frontend_reservation = -1;
    if (!spawn_child(docker_args, temp.nginx_log, nginx.child) ||
        !wait_ready(frontend_port, nginx.child, error) || !wait_live(local, "local")) {
        if (error.empty()) error = "#331 failed to start pinned nginx/local recorder";
        return false;
    }
    for (size_t i = 0u; i < 4u; i++) {
        if (!request(i, kBodyfulNormalizedExactResponseNormalized) ||
            local.accepted.load(std::memory_order_acquire) != 0u ||
            local.requests.load(std::memory_order_acquire) != 0u ||
            local.response_send_all_calls.load(std::memory_order_acquire) != 0u) {
            error = "#331 normalized exact local vector reached upstream";
            return false;
        }
    }
    if (!observe(local, 0u, "live local zero-upstream window")) return false;
    local.stop();
    observation.local_accepts = local.accepted.load(std::memory_order_acquire);
    observation.local_requests = local.requests.load(std::memory_order_acquire);
    observation.local_sends = local.response_send_all_calls.load(std::memory_order_acquire);
    observation.local_history = local.history;
    if (local.thread_alive.load(std::memory_order_acquire) ||
        local.listener_failed.load(std::memory_order_acquire) || observation.local_accepts != 0u ||
        observation.local_requests != 0u || observation.local_sends != 0u ||
        local.response_send_succeeded.load(std::memory_order_acquire) || !local.history.empty() ||
        !local.request.empty()) {
        error = "#331 local recorder did not settle with zero upstream activity";
        return false;
    }

    Recorder forward;
    forward.observe_extra_requests_until_stop = true;
    if (!forward.setup(backend_port,
                       3u,
                       kBodyfulNormalizedFallbackBackendResponse,
                       sizeof(kBodyfulNormalizedFallbackBackendResponse) - 1u) ||
        !wait_live(forward, "fallback") || !observe(forward, 0u, "pre-fallback zero window"))
        return false;
    for (size_t i = 4u; i < targets.size(); i++) {
        const u32 expected = static_cast<u32>(i - 3u);
        if (!request(i, kBodyfulNormalizedFallbackResponseNormalized)) return false;
        if (!wait_count(forward, expected) ||
            !observe(forward, expected, "ordered fallback count")) {
            error = "#331 fallback count/order/retry evidence failed";
            return false;
        }
    }
    if (!observe(forward, 3u, "live no-fourth-forward window") || !stop_child(nginx.child) ||
        !docker.remove()) {
        error = "#331 pinned nginx did not complete cleanly";
        return false;
    }
    forward.stop();
    observation.forward_accepts = forward.accepted.load(std::memory_order_acquire);
    observation.forward_requests = forward.requests.load(std::memory_order_acquire);
    observation.forward_sends = forward.response_send_all_calls.load(std::memory_order_acquire);
    observation.forward_history = forward.history;
    if (forward.thread_alive.load(std::memory_order_acquire) ||
        forward.listener_failed.load(std::memory_order_acquire) ||
        observation.forward_accepts != 3u || observation.forward_requests != 3u ||
        observation.forward_sends != 3u ||
        !forward.response_send_succeeded.load(std::memory_order_acquire) ||
        !forward.response_clean_shutdown.load(std::memory_order_acquire) ||
        !forward.response_connection_closed.load(std::memory_order_acquire) ||
        observation.forward_history.size() != 3u) {
        error = "#331 fallback recorder lifecycle/count was incomplete";
        return false;
    }
    std::string access_contents;
    std::string error_contents;
    if (!read_exact_return204_log(
            temp.nginx_access_log, "#331 pinned access log", access_contents, error) ||
        !parse_bodyful_normalized_exact_access_log(
            access_contents, access_prefix, observation, backend_port, error) ||
        !read_exact_return204_log(
            temp.nginx_log, "#331 pinned nginx error log", error_contents, error))
        return false;
    for (const char* severity : {"[warn]", "[error]", "[crit]", "[alert]", "[emerg]"}) {
        if (error_contents.find(severity) != std::string::npos) {
            error = std::string("#331 pinned nginx error log contained ") + severity;
            return false;
        }
    }
    for (u32& count : observation.access_records) count = 1u;
    return validate_bodyful_normalized_exact_observation(observation, backend_port, error);
}

static BodyfulNormalizedExactObservation make_bodyful_normalized_exact_self_check(
    u16 backend_port, const char* order, const char* suffix) {
    static constexpr char kDate[] = "Wed, 26 Aug 2026 23:57:18 GMT";
    const auto observed = [](const char* normalized, size_t size) {
        std::vector<char> wire(normalized, normalized + size);
        const std::string marker(29u, 'X');
        const auto date = std::search(wire.begin(), wire.end(), marker.begin(), marker.end());
        if (date != wire.end()) std::copy_n(kDate, 29u, date);
        return wire;
    };
    BodyfulNormalizedExactObservation value;
    value.order = order;
    value.temp_path = std::string("/tmp/331-") + suffix;
    value.config_path = value.temp_path + "/nginx.conf";
    value.log_path = value.temp_path + "/nginx.log";
    value.access_path = value.temp_path + "/access.log";
    value.process_identity = std::string("rut-nginx-331-") + suffix;
    value.targets = bodyful_normalized_exact_targets();
    for (size_t i = 0u; i < value.targets.size(); i++) {
        value.wires.push_back(i < 4u
                                  ? observed(kBodyfulNormalizedExactResponseNormalized, 144u)
                                  : observed(kBodyfulNormalizedFallbackResponseNormalized, 175u));
        value.access_records[i] = 1u;
    }
    value.forward_accepts = 3u;
    value.forward_requests = 3u;
    value.forward_sends = 3u;
    for (size_t i = 4u; i < value.targets.size(); i++) {
        const std::string request = "GET " + value.targets[i] +
                                    " HTTP/1.1\r\nHost: 127.0.0.1:" + std::to_string(backend_port) +
                                    "\r\n\r\n";
        value.forward_history.emplace_back(request.begin(), request.end());
    }
    return value;
}

static bool run_bodyful_normalized_exact_self_checks(std::string& error) {
    static constexpr u16 kPorts[] = {54320u, 54321u, 54322u, 54323u};
    const auto exact =
        make_bodyful_normalized_exact_self_check(kPorts[1], "exact-before-root", "exact");
    const auto root =
        make_bodyful_normalized_exact_self_check(kPorts[3], "root-before-exact", "root");
    const BodyfulNormalizedExactObservation valid[2] = {exact, root};
    if (!validate_bodyful_normalized_exact_pair(valid, kPorts, error)) return false;
    const auto rejects_observation = [&](const char* name,
                                         BodyfulNormalizedExactObservation value) {
        std::string detail;
        if (!validate_bodyful_normalized_exact_observation(value, kPorts[1], detail)) return true;
        error = std::string("#331 observation mutation accepted: ") + name;
        return false;
    };
    auto changed = exact;
    changed.wires[2] = exact.wires[4];
    if (!rejects_observation("doubled-slash-selection", changed)) return false;
    changed = exact;
    changed.targets[2] = "/a/b";
    if (!rejects_observation("missing-doubled-slash", changed)) return false;
    changed = exact;
    changed.wires[3] = exact.wires[4];
    if (!rejects_observation("combined-query-slash-fallback-selection", changed)) return false;
    changed = exact;
    changed.targets.erase(changed.targets.begin() + 3);
    changed.wires.erase(changed.wires.begin() + 3);
    if (!rejects_observation("missing-combined-observation", changed)) return false;
    changed = exact;
    changed.targets.insert(changed.targets.begin() + 4, exact.targets[3]);
    changed.wires.insert(changed.wires.begin() + 4, exact.wires[3]);
    if (!rejects_observation("duplicate-combined-observation", changed)) return false;
    changed = exact;
    changed.local_accepts = 1u;
    changed.local_requests = 1u;
    changed.local_sends = 1u;
    const std::string combined_backend =
        "GET /a//b?x=1 HTTP/1.1\r\nHost: 127.0.0.1:" + std::to_string(kPorts[1]) + "\r\n\r\n";
    changed.local_history.emplace_back(combined_backend.begin(), combined_backend.end());
    if (!rejects_observation("combined-unexpected-backend-episode", changed)) return false;
    changed = exact;
    changed.wires[4] = exact.wires[0];
    if (!rejects_observation("fallback-selection", changed)) return false;
    changed = exact;
    changed.access_records[3] = 0u;
    if (!rejects_observation("combined-access-count", changed)) return false;
    changed = exact;
    changed.forward_requests = 2u;
    if (!rejects_observation("backend-count", changed)) return false;
    changed = exact;
    std::swap(changed.forward_history[0], changed.forward_history[1]);
    if (!rejects_observation("backend-order", changed)) return false;
    changed = exact;
    changed.forward_history.push_back(exact.forward_history[0]);
    if (!rejects_observation("backend-retry", changed)) return false;

    const auto rejects_pair = [&](BodyfulNormalizedExactObservation values[2], u16 ports[4]) {
        std::string detail;
        return !validate_bodyful_normalized_exact_pair(values, ports, detail);
    };
    BodyfulNormalizedExactObservation pair[2] = {exact, root};
    u16 ports[4];
    std::copy(std::begin(kPorts), std::end(kPorts), std::begin(ports));
    pair[1].access_path = pair[0].access_path;
    if (!rejects_pair(pair, ports)) {
        error = "#331 resource-alias mutation was accepted";
        return false;
    }
    pair[1] = root;
    ports[3] = ports[0];
    if (!rejects_pair(pair, ports)) {
        error = "#331 duplicate-port mutation was accepted";
        return false;
    }

    const std::string prefix = "rut-nginx-331-self-check";
    std::string access;
    for (size_t i = 0u; i < exact.targets.size(); i++) {
        const bool local = i < 4u;
        access +=
            prefix + " raw=\"GET " + exact.targets[i] +
            " HTTP/1.1\" status=" + (local ? "200" : "201") + " bytes=" + (local ? "144" : "175") +
            " host=\"bodyful-normalized.example\" upstream_addr=\"" +
            (local ? "-\" upstream_status=-" : "127.0.0.1:54321\" upstream_status=201") + "\n";
    }
    if (!parse_bodyful_normalized_exact_access_log(access, prefix, exact, kPorts[1], error))
        return false;
    const size_t first_end = access.find('\n');
    const size_t second_end = access.find('\n', first_end + 1u);
    std::string reordered = access;
    reordered.replace(
        0u,
        second_end + 1u,
        access.substr(first_end + 1u, second_end - first_end) + access.substr(0u, first_end + 1u));
    const auto access_rejects = [&](const std::string& value) {
        std::string detail;
        return !parse_bodyful_normalized_exact_access_log(value, prefix, exact, kPorts[1], detail);
    };
    std::string missing_double = access;
    const size_t doubled = missing_double.find("/a//b");
    if (doubled == std::string::npos) {
        error = "#331 access self-check fixture lacked doubled-slash evidence";
        return false;
    }
    missing_double.erase(doubled + 2u, 1u);
    const std::string combined_record =
        prefix +
        " raw=\"GET /a//b?x=1 HTTP/1.1\" status=200 bytes=144 "
        "host=\"bodyful-normalized.example\" upstream_addr=\"-\" upstream_status=-\n";
    const size_t combined = access.find(combined_record);
    if (combined == std::string::npos) {
        error = "#337 access self-check fixture lacked the combined raw observation";
        return false;
    }
    std::string missing_combined = access;
    missing_combined.erase(combined, combined_record.size());
    std::string duplicate_combined = access;
    duplicate_combined.insert(combined + combined_record.size(), combined_record);
    std::string combined_lost_query = access;
    const size_t combined_lost_query_at = combined_lost_query.find(" /a//b?x=1 ");
    if (combined_lost_query_at == std::string::npos) {
        error = "#337 access self-check fixture lacked the combined query boundary";
        return false;
    }
    combined_lost_query.erase(combined_lost_query_at + strlen(" /a//b"), strlen("?x=1"));
    std::string combined_collapsed = access;
    const size_t combined_collapsed_at = combined_collapsed.find(" /a//b?x=1 ");
    if (combined_collapsed_at == std::string::npos) {
        error = "#337 access self-check fixture lacked the combined slash boundary";
        return false;
    }
    combined_collapsed.erase(combined_collapsed_at + strlen(" /a/"), 1u);
    if (!access_rejects(access.substr(0u, access.size() - 1u)) ||
        !access_rejects(access + access.substr(0u, first_end + 1u)) || !access_rejects(reordered) ||
        !access_rejects(missing_double) || !access_rejects(missing_combined) ||
        !access_rejects(duplicate_combined) || !access_rejects(combined_lost_query) ||
        !access_rejects(combined_collapsed)) {
        error = "#331 access count/order/raw-spelling mutation was accepted";
        return false;
    }
    return true;
}

static bool run_pinned_bodyful_normalized_exact_oracle(
    const std::string& container_prefix,
    BodyfulNormalizedExactObservation observations[2],
    std::string& error) {
    struct ReservedPorts {
        int fds[4];

        ReservedPorts() { std::fill(std::begin(fds), std::end(fds), -1); }
        ~ReservedPorts() {
            for (int fd : fds)
                if (fd >= 0) close(fd);
        }

        bool reserve(size_t index, u16& port) {
            const int fd = socket(AF_INET, SOCK_STREAM | SOCK_CLOEXEC, 0);
            if (fd < 0) return false;
            sockaddr_in address{};
            address.sin_family = AF_INET;
            address.sin_addr.s_addr = htonl(INADDR_LOOPBACK);
            address.sin_port = 0;
            socklen_t length = sizeof(address);
            if (bind(fd, reinterpret_cast<sockaddr*>(&address), sizeof(address)) != 0 ||
                getsockname(fd, reinterpret_cast<sockaddr*>(&address), &length) != 0 ||
                ntohs(address.sin_port) == 0u) {
                close(fd);
                return false;
            }
            fds[index] = fd;
            port = ntohs(address.sin_port);
            return true;
        }
    } reservations;
    u16 ports[4]{};
    for (size_t i = 0u; i < 4u; i++) {
        if (!reservations.reserve(i, ports[i])) {
            error = "#331 could not bind-reserve four unique declaration-order ports";
            return false;
        }
    }
    TempDir temps[2];
    if (!temps[0].create() || !temps[1].create() || strcmp(temps[0].path, temps[1].path) == 0 ||
        temps[0].nginx_config == temps[1].nginx_config ||
        temps[0].nginx_log == temps[1].nginx_log ||
        temps[0].nginx_access_log == temps[1].nginx_access_log) {
        error = "#331 could not create two independent pinned resource trees";
        return false;
    }
    if (!capture_pinned_bodyful_normalized_exact_side(ports[0],
                                                      ports[1],
                                                      temps[0],
                                                      container_prefix + "-exact-first",
                                                      true,
                                                      observations[0],
                                                      error,
                                                      &reservations.fds[0],
                                                      &reservations.fds[1]) ||
        !capture_pinned_bodyful_normalized_exact_side(ports[2],
                                                      ports[3],
                                                      temps[1],
                                                      container_prefix + "-root-first",
                                                      false,
                                                      observations[1],
                                                      error,
                                                      &reservations.fds[2],
                                                      &reservations.fds[3]))
        return false;
    return validate_bodyful_normalized_exact_pair(observations, ports, error);
}

static std::string make_trailing_slash_no_content_fragment(u16 frontend_port,
                                                           u16 backend_port,
                                                           bool exact_first) {
    const std::string exact_location = "  location = /healthz/ { return 204; }\n";
    const std::string root_location =
        "  location / { proxy_pass http://127.0.0.1:" + std::to_string(backend_port) + "; }\n";
    return "server {\n"
           "  listen " +
           std::to_string(frontend_port) + ";\n" +
           (exact_first ? exact_location + root_location : root_location + exact_location) + "}\n";
}

static bool validate_trailing_slash_no_content_generated_source(const std::string& source,
                                                                u16 frontend_port,
                                                                u16 backend_port,
                                                                std::string& error) {
    const std::string exact_tuple =
        "route exact slash_normalized GET \"/healthz/\" { return local_response({\n"
        "  version: \"HTTP/1.1\", status: 204, reason: \"No Content\", server: "
        "\"nginx/1.29.7\",\n"
        "  date: \"current\", content_type: \"\", connection: \"request\",\n"
        "  head_mode: \"suppress_body\", body: b\"\"\n"
        "}) }\n";
    const std::string backend =
        "upstream nginx_upstream at \"127.0.0.1:" + std::to_string(backend_port) + "\"";
    const std::string listener = "listen :" + std::to_string(frontend_port) + "\n";
    if (count_text(source, exact_tuple) != 1u ||
        count_text(source, "route exact slash_normalized GET \"/healthz/\"") != 1u ||
        count_text(source, "route exact ") != 1u || count_text(source, "route exact GET") != 0u ||
        count_text(source, "route HEAD \"/\" {") != 1u ||
        count_text(source, "route GET \"/\" {") != 1u ||
        count_text(source, "route \"/\" {") != 1u ||
        count_text(source, "return forward(nginx_upstream") != 3u ||
        count_text(source, backend) != 1u || count_text(source, listener) != 1u ||
        source.find("?x=1") != std::string::npos || source.find("Host") != std::string::npos ||
        source.find("runtime") != std::string::npos ||
        source.find("trailing-return204.example") != std::string::npos ||
        source.find("query-return204.example") != std::string::npos ||
        source.find("proxy_pass") != std::string::npos ||
        source.find("nginx.conf") != std::string::npos ||
        source.find("propagat") != std::string::npos ||
        source.find("NoContent204") != std::string::npos ||
        source.find("strict_local_response") != std::string::npos ||
        source.find("profile") != std::string::npos ||
        source.find("return 204") != std::string::npos ||
        source.find("nginx::") != std::string::npos ||
        source.find("nginx_compat") != std::string::npos) {
        error =
            "#329 Stage 2 generated source was not one public /healthz/ NoContent204 tuple plus "
            "the "
            "canonical ordinary root-forward route set";
        return false;
    }
    return true;
}

static bool parse_trailing_slash_no_content_rut_access_log(const std::string& contents,
                                                           const size_t request_sizes[5],
                                                           std::string& error) {
    static constexpr const char* kTargets[] = {
        "/healthz/", "/healthz/?x=1", "/healthz//", "/healthz", "/"};
    std::vector<std::string> records;
    if (!split_exact_complete_log(
            contents, 5u, "converter-generated #329 Stage 2 access log", records, error))
        return false;
    for (size_t i = 0u; i < 5u; i++) {
        std::vector<std::string> fields;
        const size_t expected_fields = i < 3u ? 9u : 11u;
        const size_t expected_status = i < 3u ? 204u : 200u;
        const size_t expected_response = i < 3u ? 105u : 118u;
        if (!split_space_fields(records[i], fields) || fields.size() != expected_fields ||
            !exact_log_timestamp(fields[0]) || fields[1] != "GET" || fields[2] != kTargets[i] ||
            fields[3] != std::to_string(expected_status) ||
            !decimal_field_equals(fields[3], expected_status) || !exact_log_duration(fields[4]) ||
            fields[5] != std::to_string(request_sizes[i]) ||
            !decimal_field_equals(fields[5], request_sizes[i]) ||
            fields[6] != std::to_string(expected_response) ||
            !decimal_field_equals(fields[6], expected_response) || fields[7] != "127.0.0.1" ||
            (i < 3u && fields[8] != "s=0") ||
            (i >= 3u && (fields[8] != "nginx_upstream" || !exact_log_duration(fields[9]) ||
                         fields[10] != "s=0"))) {
            error = "converter-generated #329 Stage 2 access record " + std::to_string(i + 1u) +
                    " lost target/order/status/size/outcome: " + records[i];
            return false;
        }
    }
    return true;
}

static bool run_trailing_slash_no_content_differential_parser_self_checks(std::string& error) {
    static constexpr size_t kSizes[] = {79u, 83u, 80u, 48u, 41u};
    static constexpr const char* kTargets[] = {
        "/healthz/", "/healthz/?x=1", "/healthz//", "/healthz", "/"};
    std::string access;
    for (size_t i = 0u; i < 5u; i++) {
        access += "2026-08-26T21:13:05.248Z GET " + std::string(kTargets[i]) + " " +
                  (i < 3u ? "204" : "200") + " 361us " + std::to_string(kSizes[i]) + " " +
                  (i < 3u ? "105" : "118") + " 127.0.0.1" +
                  (i < 3u ? " s=0\n" : " nginx_upstream 243us s=0\n");
    }
    const auto rejects_access = [&](const std::string& value) {
        std::string detail;
        return !parse_trailing_slash_no_content_rut_access_log(value, kSizes, detail);
    };
    const auto replace = [](std::string value, const std::string& from, const std::string& to) {
        const size_t offset = value.find(from);
        if (offset == std::string::npos) return std::string{};
        value.replace(offset, from.size(), to);
        return value;
    };
    std::string swapped = access;
    const size_t first = swapped.find('\n');
    const size_t second = swapped.find('\n', first + 1u);
    swapped.replace(
        0u, second + 1u, access.substr(first + 1u, second - first) + access.substr(0u, first + 1u));
    if (!parse_trailing_slash_no_content_rut_access_log(access, kSizes, error) ||
        !rejects_access(access + access.substr(0u, first + 1u)) ||
        !rejects_access(access.substr(0u, access.size() - 1u)) || !rejects_access(swapped) ||
        !rejects_access(replace(access, " 204 ", " 200 ")) ||
        !rejects_access(replace(access, " 105 ", " 106 ")) ||
        !rejects_access(replace(access, " /healthz/ ", " /healthz ")) ||
        !rejects_access(replace(access, " 79 105 ", " 999999999999999999999999999999999 105 ")) ||
        !rejects_access(replace(access, " 204 ", " 0204 ")) ||
        !rejects_access(replace(access, " nginx_upstream ", " other_upstream ")) ||
        !rejects_access(
            replace(access, " nginx_upstream 243us ", " nginx_upstream not-a-duration ")) ||
        !rejects_access(replace(access, " s=0\n", " extra s=0\n")) ||
        !rejects_access(replace(access, " s=0\n", " s=1\n"))) {
        error = "#329 Stage 2 generated access parser mutation self-check failed";
        return false;
    }

    std::string source = make_trailing_slash_no_content_fragment(54320u, 54321u, true);
    const auto parsed = rut::nginx::parse({source.data(), static_cast<u32>(source.size())});
    if (!parsed) {
        error = "#329 Stage 2 source self-check fixture did not parse";
        return false;
    }
    const auto lowered = rut::nginx::lower_to_rut(parsed.value());
    if (!lowered) {
        error = "#329 Stage 2 source self-check fixture did not lower";
        return false;
    }
    const rut::Str view = lowered.value().view();
    const std::string canonical(view.ptr, view.len);
    const auto rejects_source = [&](std::string value) {
        std::string detail;
        return !validate_trailing_slash_no_content_generated_source(value, 54320u, 54321u, detail);
    };
    if (!validate_trailing_slash_no_content_generated_source(canonical, 54320u, 54321u, error) ||
        !rejects_source(canonical + "route exact GET \"/healthz?x=1\" { return response() }\n") ||
        !rejects_source(canonical + "if host == \"trailing-return204.example\" {}\n") ||
        !rejects_source(replace(canonical, "status: 204", "status: 200"))) {
        error = "#329 Stage 2 generated source mutation self-check failed";
        return false;
    }
    std::string normalized = canonical;
    if (!canonicalize_unique_port(normalized, "listen :54320", "listen :FRONTEND") ||
        !canonicalize_unique_port(normalized, "127.0.0.1:54321", "127.0.0.1:BACKEND")) {
        error = "#329 Stage 2 source port normalization valid self-check failed";
        return false;
    }
    std::string missing = canonical;
    missing.erase(missing.find("listen :54320"), strlen("listen :54320"));
    std::string duplicate = canonical + "listen :54320\n";
    if (canonicalize_unique_port(missing, "listen :54320", "listen :FRONTEND") ||
        canonicalize_unique_port(duplicate, "listen :54320", "listen :FRONTEND")) {
        error = "#329 Stage 2 missing/duplicate port normalization mutation was accepted";
        return false;
    }
    return true;
}

static bool capture_generated_trailing_slash_no_content_order(
    u16 frontend_port,
    u16 backend_port,
    TempDir& temp,
    const char* rut_path,
    bool exact_first,
    NormalizedExactTrailingSlashOracleObservation& observation,
    std::string& generated_source,
    std::string& error,
    int* frontend_reservation,
    int* backend_reservation) {
    static constexpr const char* kTargets[] = {
        "/healthz/", "/healthz/?x=1", "/healthz//", "/healthz", "/"};
    if (rut_path == nullptr || rut_path[0] != '/' || access(rut_path, X_OK) != 0) {
        error =
            "converter-generated #329 Stage 2 differential requires an executable absolute RUT "
            "path";
        return false;
    }
    std::string fragment =
        make_trailing_slash_no_content_fragment(frontend_port, backend_port, exact_first);
    const auto parsed = rut::nginx::parse({fragment.data(), static_cast<u32>(fragment.size())});
    if (!parsed) {
        error = "#329 Stage 2 accepted nginx fragment did not traverse the independent parser";
        return false;
    }
    const auto& server = parsed.value();
    const auto& root = server.location;
    const auto& proxy = root.proxy_pass;
    const auto& exact = server.exact_no_content_return;
    const auto& response = exact.response;
    const size_t root_location = fragment.find("location / {");
    const size_t root_path = fragment.find('/', root_location);
    const size_t exact_location = fragment.find("location = /healthz/");
    const size_t exact_path = fragment.find("/healthz/", exact_location);
    const size_t return_offset = fragment.find("return", exact_location);
    const size_t status_offset = fragment.find("204", return_offset);
    const size_t semicolon = fragment.find(';', status_offset);
    const size_t exact_end = fragment.find('}', semicolon);
    const uintptr_t source_base = reinterpret_cast<uintptr_t>(fragment.data());
    const auto same_source = [&](rut::Str value, rut::Span span) {
        return value.ptr != nullptr && span.end >= span.start &&
               span.end - span.start == value.len &&
               reinterpret_cast<uintptr_t>(value.ptr) - span.start == source_base;
    };
    if (root_location == std::string::npos || root_path == std::string::npos ||
        exact_location == std::string::npos || exact_path == std::string::npos ||
        return_offset == std::string::npos || status_offset == std::string::npos ||
        semicolon == std::string::npos || exact_end == std::string::npos ||
        server.span.start != 0u || server.span.end != fragment.size() - 1u ||
        server.listen.port != frontend_port || !root.path.eq(rut::lit_str("/")) ||
        root.path.ptr != fragment.data() + root_path || !same_source(root.path, root.path_span) ||
        proxy.has_uri || proxy.address[0] != 127u || proxy.address[1] != 0u ||
        proxy.address[2] != 0u || proxy.address[3] != 1u || proxy.port != backend_port ||
        !exact.present || !exact.path.eq(rut::lit_str("/healthz/")) ||
        exact.path.ptr != fragment.data() + exact_path ||
        !same_source(exact.path, exact.path_span) || exact.span.start != exact_location ||
        exact.span.end != exact_end + 1u || response.status != 204u ||
        response.status_span.start != status_offset ||
        response.status_span.end != status_offset + 3u || response.span.start != return_offset ||
        response.span.end != semicolon + 1u ||
        memcmp(fragment.data() + response.status_span.start, "204", 3u) != 0 ||
        server.exact_local_return.present || server.exact_absolute_redirect.present ||
        exact.span.start >= exact.path_span.start || exact.path_span.end > response.span.start ||
        response.span.end >= exact.span.end || root.span.start != root_location) {
        error =
            "#329 Stage 2 fragment lost borrowed /healthz path/status provenance or root fallback";
        return false;
    }
    const auto lowered = rut::nginx::lower_to_rut(server);
    if (!lowered) {
        error = "#329 Stage 2 genuine bounded no-content model failed public ordinary-RUT lowering";
        return false;
    }
    const rut::Str output = lowered.value().view();
    generated_source.assign(output.ptr, output.len);
    if (!validate_trailing_slash_no_content_generated_source(
            generated_source, frontend_port, backend_port, error) ||
        !write_file(temp.source, output.ptr, output.len))
        return false;
    std::fill(fragment.begin(), fragment.end(), '\0');
    if (!std::all_of(fragment.begin(), fragment.end(), [](char byte) { return byte == '\0'; })) {
        error = "#329 Stage 2 failed to destroy borrowed nginx fragment after parse/lower";
        return false;
    }

    observation = NormalizedExactTrailingSlashOracleObservation{};
    observation.order = exact_first ? "generated-exact-before-root" : "generated-root-before-exact";
    observation.temp_path = temp.path;
    observation.config_path = temp.source;
    observation.log_path = temp.rut_log;
    observation.access_path = temp.rut_access_log;
    observation.process_identity =
        std::string(rut_path) + " " + temp.source + " listen:" + std::to_string(frontend_port);
    observation.wires.resize(5u);
    std::string requests[5];
    size_t request_sizes[5]{};
    for (size_t i = 0u; i < 5u; i++) {
        requests[i] = std::string("GET ") + kTargets[i] +
                      " HTTP/1.1\r\nHost: trailing-return204.example\r\nConnection: close\r\n\r\n";
        request_sizes[i] = requests[i].size();
        const size_t header = requests[i].find("\r\n\r\n");
        if (requests[i].rfind(std::string("GET ") + kTargets[i] + " HTTP/1.1\r\n", 0u) != 0u ||
            requests[i].find('#') != std::string::npos ||
            requests[i].find("\r\nContent-Length:") != std::string::npos ||
            requests[i].find("\r\nTransfer-Encoding:") != std::string::npos ||
            requests[i].find("\r\nTE:") != std::string::npos ||
            requests[i].find("\r\nExpect:") != std::string::npos ||
            requests[i].find("\r\nUpgrade:") != std::string::npos || header == std::string::npos ||
            header + 4u != requests[i].size()) {
            error = "#329 Stage 2 generated request escaped the bounded fresh bodyless H1.1 domain";
            return false;
        }
    }

    const auto recorder_live = [](const Recorder& recorder) {
        return recorder.running.load(std::memory_order_acquire) &&
               recorder.thread_alive.load(std::memory_order_acquire) &&
               !recorder.listener_failed.load(std::memory_order_acquire);
    };
    struct RecorderGuard {
        Recorder* value = nullptr;
        ~RecorderGuard() {
            if (value != nullptr) value->stop();
        }
    };
    ChildGuard runtime;
    if (frontend_reservation != nullptr && *frontend_reservation >= 0) {
        close(*frontend_reservation);
        *frontend_reservation = -1;
    }
    if (!spawn_child({rut_path,
                      temp.source,
                      "--shards",
                      "1",
                      "--no-pin",
                      "--drain",
                      "0",
                      "--access-log",
                      temp.rut_access_log},
                     temp.rut_log,
                     runtime.child) ||
        !wait_ready(frontend_port, runtime.child, error)) {
        if (error.empty())
            error = "failed to start converter-generated public RUT for #329 Stage 2";
        return false;
    }
    const std::string loaded = "Loaded program: " + temp.source + " (opt O2)\n";
    const std::string listener =
        "Listening on port " + std::to_string(frontend_port) + " with 1 shard(s)";
    const auto ready_deadline = std::chrono::steady_clock::now() + std::chrono::seconds(2);
    while ((!log_contains(temp.rut_log, loaded.c_str()) ||
            !log_contains(temp.rut_log, "Backend: io_uring\n") ||
            !log_contains(temp.rut_log, listener.c_str())) &&
           std::chrono::steady_clock::now() < ready_deadline) {
        if (poll_child(runtime.child)) {
            error =
                "converter-generated #329 Stage 2 RUT exited before load/io_uring/listener "
                "readiness";
            return false;
        }
        usleep(1000);
    }
    if (!log_contains(temp.rut_log, loaded.c_str()) ||
        !log_contains(temp.rut_log, "Backend: io_uring\n") ||
        !log_contains(temp.rut_log, listener.c_str())) {
        error = "converter-generated #329 Stage 2 RUT lacked exact public readiness evidence";
        return false;
    }
    static constexpr char kDestroyed[] = "destroyed-after-329-public-load\n";
    if (!write_file(temp.source, kDestroyed, sizeof(kDestroyed) - 1u)) {
        error = "failed to overwrite #329 Stage 2 generated source after public load";
        return false;
    }
    std::string destroyed;
    if (!read_exact_return204_log(
            temp.source, "#329 Stage 2 destroyed generated source", destroyed, error) ||
        destroyed != kDestroyed) {
        error = "#329 Stage 2 generated source overwrite was not exact before behavioral requests";
        return false;
    }

    const auto wait_live = [&](Recorder& recorder, const char* phase) {
        const auto deadline = std::chrono::steady_clock::now() + std::chrono::seconds(2);
        while (std::chrono::steady_clock::now() < deadline) {
            if (poll_child(runtime.child) || !recorder.running.load(std::memory_order_acquire) ||
                recorder.listener_failed.load(std::memory_order_acquire)) {
                error =
                    std::string("#329 Stage 2 RUT/recorder failed before ") + phase + " readiness";
                return false;
            }
            if (recorder.thread_alive.load(std::memory_order_acquire)) return true;
            usleep(1000);
        }
        error = std::string("#329 Stage 2 recorder readiness timed out: ") + phase;
        return false;
    };
    const auto observe = [&](Recorder& recorder,
                             u32 expected,
                             const char* phase,
                             std::chrono::milliseconds duration) {
        const auto deadline = std::chrono::steady_clock::now() + duration;
        for (;;) {
            if (poll_child(runtime.child) || !recorder_live(recorder) ||
                recorder.accepted.load(std::memory_order_acquire) != expected ||
                recorder.requests.load(std::memory_order_acquire) != expected ||
                recorder.response_send_all_calls.load(std::memory_order_acquire) != expected) {
                error =
                    std::string("#329 Stage 2 unexpected process/upstream state during ") + phase;
                return false;
            }
            if (std::chrono::steady_clock::now() >= deadline) return true;
            usleep(5000);
        }
    };
    const auto request = [&](size_t index, const char* expected) {
        struct ClientGuard {
            int fd = -1;
            ~ClientGuard() {
                if (fd >= 0) close(fd);
            }
        } client{connect_once(frontend_port)};
        std::string detail;
        if (client.fd < 0 || !send_all(client.fd, requests[index].data(), requests[index].size()) ||
            !(index < 3u ? read_head_response(client.fd, observation.wires[index], detail)
                         : read_response(client.fd, observation.wires[index], detail)) ||
            !read_eof(client.fd, detail) ||
            !validate_exact_normalized_response(observation.wires[index], expected, detail)) {
            error = std::string("#329 Stage 2 generated vector ") + kTargets[index] +
                    " exact response/EOF failed: " + detail;
            return false;
        }
        if (poll_child(runtime.child)) {
            error = std::string("#329 Stage 2 generated RUT exited after vector ") +
                    kTargets[index] + " (" + child_status_description(runtime.child) + ")";
            return false;
        }
        return true;
    };

    Recorder zero;
    RecorderGuard zero_guard{&zero};
    zero.observe_extra_requests_until_stop = true;
    if (backend_reservation != nullptr && *backend_reservation >= 0) {
        close(*backend_reservation);
        *backend_reservation = -1;
    }
    if (!zero.setup(backend_port)) {
        error = "#329 Stage 2 generated local recorder could not bind its reserved backend port";
        return false;
    }
    if (!wait_live(zero, "local") ||
        !observe(zero, 0u, "pre-local zero window", std::chrono::milliseconds(250)))
        return false;
    for (size_t i = 0u; i < 3u; i++) {
        if (!request(i, kExactLocalReturn204ResponseNormalized) ||
            !observe(zero, 0u, "local vector zero window", std::chrono::milliseconds(250)))
            return false;
        const std::string text(observation.wires[i].begin(), observation.wires[i].end());
        if (observation.wires[i].size() != 105u ||
            header_end(observation.wires[i]) != observation.wires[i].size() ||
            text.find("\r\nContent-Type:") != std::string::npos ||
            text.find("\r\nContent-Length:") != std::string::npos ||
            text.find("\r\nTransfer-Encoding:") != std::string::npos) {
            error =
                "#329 Stage 2 generated strict 204 gained framing, representation, body, or tail";
            return false;
        }
    }
    if (!observe(zero, 0u, "post-local zero window", std::chrono::milliseconds(500))) return false;
    zero.stop();
    zero_guard.value = nullptr;
    observation.local_accepts = zero.accepted.load(std::memory_order_acquire);
    observation.local_requests = zero.requests.load(std::memory_order_acquire);
    observation.local_sends = zero.response_send_all_calls.load(std::memory_order_acquire);
    observation.local_history = zero.history;
    if (zero.thread_alive.load(std::memory_order_acquire) ||
        zero.listener_failed.load(std::memory_order_acquire) || observation.local_accepts != 0u ||
        observation.local_requests != 0u || observation.local_sends != 0u ||
        zero.response_send_succeeded.load(std::memory_order_acquire) || !zero.history.empty() ||
        !zero.request.empty()) {
        error =
            "#329 Stage 2 generated local recorder did not settle at exact zero with empty history";
        return false;
    }

    Recorder fallback;
    RecorderGuard fallback_guard{&fallback};
    fallback.observe_extra_requests_until_stop = true;
    if (!fallback.setup(backend_port, 2u, kBackendResponse, sizeof(kBackendResponse) - 1u)) {
        error = "#329 Stage 2 generated fallback recorder could not bind the released backend port";
        return false;
    }
    if (!wait_live(fallback, "fallback") ||
        !observe(fallback, 0u, "pre-fallback zero window", std::chrono::milliseconds(100)))
        return false;
    for (size_t i = 3u; i < 5u; i++) {
        if (!request(i, kSuccessResponseNormalized)) return false;
        const auto deadline = std::chrono::steady_clock::now() + std::chrono::seconds(2);
        const u32 expected = static_cast<u32>(i - 2u);
        while (std::chrono::steady_clock::now() < deadline) {
            const u32 accepts = fallback.accepted.load(std::memory_order_acquire);
            const u32 requests_seen = fallback.requests.load(std::memory_order_acquire);
            const u32 sends = fallback.response_send_all_calls.load(std::memory_order_acquire);
            if (poll_child(runtime.child) || !recorder_live(fallback) || accepts > expected ||
                requests_seen > expected || sends > expected) {
                error = "#329 Stage 2 generated fallback observed retry/extra request";
                return false;
            }
            if (accepts == expected && requests_seen == expected && sends == expected) break;
            usleep(1000);
        }
        if (fallback.accepted.load(std::memory_order_acquire) != expected ||
            fallback.requests.load(std::memory_order_acquire) != expected ||
            fallback.response_send_all_calls.load(std::memory_order_acquire) != expected) {
            error =
                "#329 Stage 2 generated fallback timed out awaiting the complete upstream episode";
            return false;
        }
        if (!observe(fallback, expected, "ordered fallback count", std::chrono::milliseconds(100)))
            return false;
    }
    if (!observe(fallback, 2u, "no-third fallback window", std::chrono::milliseconds(500)) ||
        !stop_child(runtime.child)) {
        error = "#329 Stage 2 generated RUT did not survive through controlled shutdown";
        return false;
    }
    fallback.stop();
    fallback_guard.value = nullptr;
    observation.forward_accepts = fallback.accepted.load(std::memory_order_acquire);
    observation.forward_requests = fallback.requests.load(std::memory_order_acquire);
    observation.forward_sends = fallback.response_send_all_calls.load(std::memory_order_acquire);
    observation.forward_history = fallback.history;
    if (fallback.thread_alive.load(std::memory_order_acquire) ||
        fallback.listener_failed.load(std::memory_order_acquire) ||
        observation.forward_accepts != 2u || observation.forward_requests != 2u ||
        observation.forward_sends != 2u || !fallback.response_send_succeeded.load() ||
        !fallback.response_clean_shutdown.load() || !fallback.response_connection_closed.load() ||
        observation.forward_history.size() != 2u) {
        error = "#329 Stage 2 generated fallback recorder lifecycle/count was incomplete";
        return false;
    }
    for (size_t i = 0u; i < 5u; i++) observation.access_records[i] = 1u;
    if (!validate_trailing_no_content_observation(observation, backend_port, error)) return false;

    std::string access_contents;
    std::string runtime_contents;
    if (!read_exact_return204_log(temp.rut_access_log,
                                  "converter-generated #329 Stage 2 access log",
                                  access_contents,
                                  error) ||
        !parse_trailing_slash_no_content_rut_access_log(access_contents, request_sizes, error) ||
        !read_exact_return204_log(temp.rut_log,
                                  "converter-generated #329 Stage 2 runtime log",
                                  runtime_contents,
                                  error) ||
        !parse_exact_return204_runtime_log(runtime_contents, temp.source, listener, error))
        return false;
    if (request_sizes[3] == observation.forward_history[0].size()) {
        error = "#329 fixture no longer distinguishes downstream and rebuilt request sizes";
        return false;
    }
    size_t swapped_sizes[5];
    std::copy(std::begin(request_sizes), std::end(request_sizes), std::begin(swapped_sizes));
    swapped_sizes[3] = observation.forward_history[0].size();
    std::string swapped_size_error;
    if (parse_trailing_slash_no_content_rut_access_log(
            access_contents, swapped_sizes, swapped_size_error)) {
        error = "#329 access parser accepted rebuilt upstream field 5";
        return false;
    }
    return true;
}

static std::vector<std::vector<char>> canonicalize_trailing_no_content_backend_history(
    const std::vector<std::vector<char>>& history) {
    std::vector<std::vector<char>> result = history;
    for (std::vector<char>& request : result) {
        std::string text(request.begin(), request.end());
        static constexpr char kMarker[] = "\r\nHost: 127.0.0.1:";
        const size_t begin = text.find(kMarker);
        if (begin == std::string::npos ||
            text.find(kMarker, begin + sizeof(kMarker) - 1u) != std::string::npos)
            return {};
        const size_t digits = begin + sizeof(kMarker) - 1u;
        const size_t end = text.find("\r\n", digits);
        if (end == std::string::npos || end == digits) return {};
        for (size_t i = digits; i < end; i++)
            if (text[i] < '0' || text[i] > '9') return {};
        text.replace(digits, end - digits, "BACKEND");
        request.assign(text.begin(), text.end());
    }
    return result;
}

static bool validate_trailing_slash_no_content_four_way(
    const NormalizedExactTrailingSlashOracleObservation observations[4],
    const std::string generated_sources[2],
    const u16 ports[8],
    std::string& error) {
    for (size_t i = 0u; i < 8u; i++) {
        if (ports[i] == 0u) {
            error = "#329 Stage 2 four-way validator received a zero dynamic port";
            return false;
        }
        for (size_t j = i + 1u; j < 8u; j++) {
            if (ports[i] == ports[j]) {
                error = "#329 Stage 2 four-way validator received duplicate dynamic ports";
                return false;
            }
        }
    }
    for (size_t i = 0u; i < 4u; i++) {
        if (!validate_trailing_no_content_observation(observations[i], ports[i * 2u + 1u], error))
            return false;
        if (observations[i].temp_path.empty() || observations[i].config_path.empty() ||
            observations[i].log_path.empty() || observations[i].access_path.empty() ||
            observations[i].process_identity.empty()) {
            error = "#329 Stage 2 one semantic side lacked complete resource identity";
            return false;
        }
        for (size_t j = i + 1u; j < 4u; j++) {
            if (observations[i].temp_path == observations[j].temp_path ||
                observations[i].config_path == observations[j].config_path ||
                observations[i].log_path == observations[j].log_path ||
                observations[i].access_path == observations[j].access_path ||
                observations[i].process_identity == observations[j].process_identity ||
                observations[i].wires.data() == observations[j].wires.data()) {
                error = "#329 Stage 2 four semantic sides shared a process/resource identity";
                return false;
            }
        }
    }
    std::vector<std::string> resource_identities;
    resource_identities.reserve(20u);
    for (const auto& observation : std::span(observations, 4u)) {
        resource_identities.insert(resource_identities.end(),
                                   {observation.temp_path,
                                    observation.config_path,
                                    observation.log_path,
                                    observation.access_path,
                                    observation.process_identity});
    }
    for (size_t i = 0u; i < resource_identities.size(); i++) {
        for (size_t j = i + 1u; j < resource_identities.size(); j++) {
            if (resource_identities[i] == resource_identities[j]) {
                error = "#329 Stage 2 resource/process identities were not globally isolated";
                return false;
            }
        }
    }
    if (!validate_trailing_slash_no_content_generated_source(
            generated_sources[0], ports[4], ports[5], error) ||
        !validate_trailing_slash_no_content_generated_source(
            generated_sources[1], ports[6], ports[7], error))
        return false;
    std::string canonical[2] = {generated_sources[0], generated_sources[1]};
    if (!canonicalize_unique_port(
            canonical[0], "listen :" + std::to_string(ports[4]), "listen :FRONTEND") ||
        !canonicalize_unique_port(
            canonical[0], "127.0.0.1:" + std::to_string(ports[5]), "127.0.0.1:BACKEND") ||
        !canonicalize_unique_port(
            canonical[1], "listen :" + std::to_string(ports[6]), "listen :FRONTEND") ||
        !canonicalize_unique_port(
            canonical[1], "127.0.0.1:" + std::to_string(ports[7]), "127.0.0.1:BACKEND") ||
        canonical[0] != canonical[1]) {
        error = "#329 Stage 2 declaration order changed source or port normalization was not exact";
        return false;
    }
    const auto expected_history =
        canonicalize_trailing_no_content_backend_history(observations[0].forward_history);
    if (expected_history.size() != 2u) {
        error = "#329 Stage 2 could not canonicalize the exact two-request backend history";
        return false;
    }
    for (size_t side = 0u; side < 4u; side++) {
        if (canonicalize_trailing_no_content_backend_history(observations[side].forward_history) !=
            expected_history) {
            error =
                "#329 Stage 2 four sides differed in ordered port-canonicalized fallback history";
            return false;
        }
    }
    for (size_t vector = 0u; vector < 5u; vector++) {
        std::vector<char> baseline = observations[0].wires[vector];
        if (!normalize_date(baseline)) {
            error = "#329 Stage 2 pinned baseline Date normalization failed";
            return false;
        }
        for (size_t side = 1u; side < 4u; side++) {
            std::vector<char> candidate = observations[side].wires[vector];
            if (!normalize_date(candidate) || candidate != baseline) {
                error = "#329 Stage 2 four-side Date-normalized wire mismatch at vector " +
                        std::to_string(vector + 1u);
                return false;
            }
        }
    }
    return true;
}

static bool run_trailing_slash_no_content_four_way_self_checks(std::string& error) {
    u16 ports[8] = {54310u, 54311u, 54312u, 54313u, 54314u, 54315u, 54316u, 54317u};
    NormalizedExactTrailingSlashOracleObservation values[4];
    static constexpr char kDate[] = "Wed, 26 Aug 2026 23:57:18 GMT";
    for (size_t side = 0u; side < 4u; side++) {
        values[side].order = std::to_string(side);
        values[side].temp_path = "/tmp/329-stage2-" + std::to_string(side);
        values[side].config_path = values[side].temp_path + "/config";
        values[side].log_path = values[side].temp_path + "/log";
        values[side].access_path = values[side].temp_path + "/access";
        values[side].process_identity = "process-" + std::to_string(side);
        for (size_t vector = 0u; vector < 5u; vector++) {
            const char* expected =
                vector < 3u ? kExactLocalReturn204ResponseNormalized : kSuccessResponseNormalized;
            const size_t size = vector < 3u ? 105u : sizeof(kSuccessResponseNormalized) - 1u;
            std::vector<char> wire(expected, expected + size);
            const std::string marker(29u, 'X');
            const auto date = std::search(wire.begin(), wire.end(), marker.begin(), marker.end());
            if (date != wire.end()) std::copy_n(kDate, 29u, date);
            values[side].wires.push_back(std::move(wire));
            values[side].access_records[vector] = 1u;
        }
        values[side].forward_accepts = 2u;
        values[side].forward_requests = 2u;
        values[side].forward_sends = 2u;
        for (const char* target : {"/healthz", "/"}) {
            const std::string request =
                std::string("GET ") + target +
                " HTTP/1.1\r\nHost: 127.0.0.1:" + std::to_string(ports[side * 2u + 1u]) +
                "\r\n\r\n";
            values[side].forward_history.emplace_back(request.begin(), request.end());
        }
    }
    std::string sources[2];
    for (size_t i = 0u; i < 2u; i++) {
        std::string fragment = make_trailing_slash_no_content_fragment(
            ports[4u + i * 2u], ports[5u + i * 2u], i == 0u);
        const auto parsed = rut::nginx::parse({fragment.data(), static_cast<u32>(fragment.size())});
        if (!parsed) return false;
        const auto lowered = rut::nginx::lower_to_rut(parsed.value());
        if (!lowered) return false;
        const rut::Str view = lowered.value().view();
        sources[i].assign(view.ptr, view.len);
    }
    if (!validate_trailing_slash_no_content_four_way(values, sources, ports, error)) return false;
    const auto rejects = [&](NormalizedExactTrailingSlashOracleObservation mutated[4],
                             std::string changed_sources[2],
                             const char* name) {
        std::string detail;
        if (!validate_trailing_slash_no_content_four_way(mutated, changed_sources, ports, detail))
            return true;
        error = std::string("#329 Stage 2 four-way mutation accepted: ") + name;
        return false;
    };
    NormalizedExactTrailingSlashOracleObservation mutated[4];
    std::copy(std::begin(values), std::end(values), std::begin(mutated));
    std::string changed[2] = {sources[0], sources[1]};
    mutated[1].temp_path = mutated[0].temp_path;
    if (!rejects(mutated, changed, "resource-alias")) return false;
    std::copy(std::begin(values), std::end(values), std::begin(mutated));
    mutated[1].config_path = mutated[0].config_path;
    if (!rejects(mutated, changed, "source-alias")) return false;
    std::copy(std::begin(values), std::end(values), std::begin(mutated));
    mutated[1].log_path = mutated[0].log_path;
    if (!rejects(mutated, changed, "log-alias")) return false;
    std::copy(std::begin(values), std::end(values), std::begin(mutated));
    mutated[1].access_path = mutated[0].access_path;
    if (!rejects(mutated, changed, "access-alias")) return false;
    std::copy(std::begin(values), std::end(values), std::begin(mutated));
    mutated[1].process_identity = mutated[0].process_identity;
    if (!rejects(mutated, changed, "process-alias")) return false;
    std::copy(std::begin(values), std::end(values), std::begin(mutated));
    mutated[2].wires[0].back() = 'x';
    if (!rejects(mutated, changed, "wire")) return false;
    std::copy(std::begin(values), std::end(values), std::begin(mutated));
    mutated[2].wires[0][9] = '5';
    if (!rejects(mutated, changed, "wire-status")) return false;
    std::copy(std::begin(values), std::end(values), std::begin(mutated));
    mutated[2].access_records[0] = 0u;
    if (!rejects(mutated, changed, "access-missing")) return false;
    std::copy(std::begin(values), std::end(values), std::begin(mutated));
    mutated[2].access_records[0] = 2u;
    if (!rejects(mutated, changed, "access-extra")) return false;
    std::copy(std::begin(values), std::end(values), std::begin(mutated));
    mutated[3].local_requests = 1u;
    if (!rejects(mutated, changed, "local-nonzero")) return false;
    std::copy(std::begin(values), std::end(values), std::begin(mutated));
    mutated[3].local_history.push_back(mutated[3].forward_history[0]);
    if (!rejects(mutated, changed, "local-history")) return false;
    std::copy(std::begin(values), std::end(values), std::begin(mutated));
    mutated[2].forward_history.push_back(mutated[2].forward_history[0]);
    if (!rejects(mutated, changed, "third/retry")) return false;
    std::copy(std::begin(values), std::end(values), std::begin(mutated));
    changed[1] += "\n# source mismatch";
    if (!rejects(mutated, changed, "source-mismatch")) return false;
    changed[1] = sources[1];
    u16 duplicate_ports[8];
    std::copy(std::begin(ports), std::end(ports), std::begin(duplicate_ports));
    duplicate_ports[7] = duplicate_ports[0];
    std::string detail;
    if (validate_trailing_slash_no_content_four_way(values, sources, duplicate_ports, detail)) {
        error = "#329 Stage 2 four-way duplicate-port mutation was accepted";
        return false;
    }
    duplicate_ports[7] = ports[7];
    duplicate_ports[0] = 0u;
    if (validate_trailing_slash_no_content_four_way(values, sources, duplicate_ports, detail)) {
        error = "#329 Stage 2 four-way zero-port mutation was accepted";
        return false;
    }
    return true;
}

static bool run_converter_trailing_slash_no_content_differential(
    const std::string& container_prefix, const char* rut_path, std::string& error) {
    struct ReservedPorts {
        int fds[8];

        ReservedPorts() { std::fill(std::begin(fds), std::end(fds), -1); }
        ~ReservedPorts() {
            for (int fd : fds)
                if (fd >= 0) close(fd);
        }

        bool reserve(size_t index, u16& port) {
            const int fd = socket(AF_INET, SOCK_STREAM | SOCK_CLOEXEC, 0);
            if (fd < 0) return false;
            sockaddr_in addr{};
            addr.sin_family = AF_INET;
            addr.sin_addr.s_addr = htonl(INADDR_LOOPBACK);
            addr.sin_port = 0;
            socklen_t len = sizeof(addr);
            if (bind(fd, reinterpret_cast<sockaddr*>(&addr), sizeof(addr)) != 0 ||
                getsockname(fd, reinterpret_cast<sockaddr*>(&addr), &len) != 0 ||
                ntohs(addr.sin_port) == 0u) {
                close(fd);
                return false;
            }
            fds[index] = fd;
            port = ntohs(addr.sin_port);
            return true;
        }
    } reservations;
    u16 ports[8]{};
    for (size_t i = 0u; i < 8u; i++) {
        if (!reservations.reserve(i, ports[i])) {
            error = "#329 Stage 2 could not bind-reserve eight unique four-side ports";
            return false;
        }
    }
    TempDir temps[4];
    for (TempDir& temp : temps) {
        if (!temp.create()) {
            error = "#329 Stage 2 could not create four independent temporary resource trees";
            return false;
        }
    }
    for (size_t i = 0u; i < 4u; i++) {
        for (size_t j = i + 1u; j < 4u; j++) {
            if (strcmp(temps[i].path, temps[j].path) == 0 ||
                temps[i].nginx_config == temps[j].nginx_config ||
                temps[i].source == temps[j].source || temps[i].nginx_log == temps[j].nginx_log ||
                temps[i].rut_log == temps[j].rut_log ||
                temps[i].nginx_access_log == temps[j].nginx_access_log ||
                temps[i].rut_access_log == temps[j].rut_access_log) {
                error = "#329 Stage 2 four sides shared a temp/config/source/log/access identity";
                return false;
            }
        }
    }
    NormalizedExactTrailingSlashOracleObservation observations[4];
    std::string sources[2];
    const std::string containers[2] = {container_prefix + "-nginx-exact-first",
                                       container_prefix + "-nginx-root-first"};
    const auto failed_side = [&](const char* side) {
        if (error.empty())
            error = std::string("#329 Stage 2 ") + side + " side returned no diagnostic";
        return false;
    };
    if (!capture_pinned_normalized_exact_trailing_slash_order(ports[0],
                                                              ports[1],
                                                              temps[0].nginx_config,
                                                              temps[0].nginx_log,
                                                              containers[0],
                                                              true,
                                                              observations[0],
                                                              error,
                                                              true,
                                                              &temps[0].nginx_access_log,
                                                              &reservations.fds[0],
                                                              &reservations.fds[1]))
        return failed_side("pinned exact-first");
    if (!capture_pinned_normalized_exact_trailing_slash_order(ports[2],
                                                              ports[3],
                                                              temps[1].nginx_config,
                                                              temps[1].nginx_log,
                                                              containers[1],
                                                              false,
                                                              observations[1],
                                                              error,
                                                              true,
                                                              &temps[1].nginx_access_log,
                                                              &reservations.fds[2],
                                                              &reservations.fds[3]))
        return failed_side("pinned root-first");
    if (!capture_generated_trailing_slash_no_content_order(ports[4],
                                                           ports[5],
                                                           temps[2],
                                                           rut_path,
                                                           true,
                                                           observations[2],
                                                           sources[0],
                                                           error,
                                                           &reservations.fds[4],
                                                           &reservations.fds[5]))
        return failed_side("generated exact-first");
    if (!capture_generated_trailing_slash_no_content_order(ports[6],
                                                           ports[7],
                                                           temps[3],
                                                           rut_path,
                                                           false,
                                                           observations[3],
                                                           sources[1],
                                                           error,
                                                           &reservations.fds[6],
                                                           &reservations.fds[7]))
        return failed_side("generated root-first");
    for (size_t side = 0u; side < 2u; side++) {
        std::string access_contents;
        const std::string prefix = "rut-nginx-329-trailing-return204-" + observations[side].order +
                                   "-" + std::to_string(getpid()) + "-scoped";
        if (!read_exact_return204_log(temps[side].nginx_access_log,
                                      "#329 Stage 2 differential pinned access log",
                                      access_contents,
                                      error) ||
            !parse_trailing_no_content_access_log(
                access_contents, prefix, ports[side * 2u + 1u], error))
            return false;
        for (u32& access : observations[side].access_records) access = 1u;
    }
    return validate_trailing_slash_no_content_four_way(observations, sources, ports, error);
}

static std::string make_max_boundary_no_content_fragment(u16 frontend_port,
                                                         u16 backend_port,
                                                         bool trailing) {
    const std::string key = trailing ? max_boundary_trailing_key() : max_boundary_raw_key();
    const std::string exact_location = "  location = " + key + " { return 204; }\n";
    const std::string root_location =
        "  location / { proxy_pass http://127.0.0.1:" + std::to_string(backend_port) + "; }\n";
    return "server {\n"
           "  listen " +
           std::to_string(frontend_port) + ";\n" +
           (trailing ? root_location + exact_location : exact_location + root_location) + "}\n";
}

static bool validate_max_boundary_generated_source(const std::string& source,
                                                   u16 frontend_port,
                                                   u16 backend_port,
                                                   bool trailing,
                                                   std::string& error) {
    const std::string key = trailing ? max_boundary_trailing_key() : max_boundary_raw_key();
    const std::string other_key = trailing ? max_boundary_raw_key() : max_boundary_trailing_key();
    const std::string exact_tuple =
        "route exact slash_normalized GET \"" + key +
        "\" { return local_response({\n"
        "  version: \"HTTP/1.1\", status: 204, reason: \"No Content\", server: "
        "\"nginx/1.29.7\",\n"
        "  date: \"current\", content_type: \"\", connection: \"request\",\n"
        "  head_mode: \"suppress_body\", body: b\"\"\n"
        "}) }\n";
    const std::string backend =
        "upstream nginx_upstream at \"127.0.0.1:" + std::to_string(backend_port) + "\"";
    const std::string listener = "listen :" + std::to_string(frontend_port) + "\n";
    if (count_text(source, exact_tuple) != 1u ||
        count_text(source, "route exact slash_normalized GET \"" + key + "\"") != 1u ||
        count_text(source, "route exact slash_normalized GET") != 1u ||
        count_text(source, "route exact ") != 1u || count_text(source, "route exact GET") != 0u ||
        count_text(source, other_key) != 0u || count_text(source, "route HEAD \"/\" {") != 1u ||
        count_text(source, "route GET \"/\" {") != 1u ||
        count_text(source, "route \"/\" {") != 1u ||
        count_text(source, "return forward(nginx_upstream") != 3u ||
        count_text(source, backend) != 1u || count_text(source, listener) != 1u ||
        source.find("?x=1") != std::string::npos || source.find("Host") != std::string::npos ||
        source.find("max-boundary.example") != std::string::npos ||
        source.find("runtime") != std::string::npos ||
        source.find("proxy_pass") != std::string::npos ||
        source.find("nginx.conf") != std::string::npos ||
        source.find("propagat") != std::string::npos ||
        source.find("NoContent204") != std::string::npos ||
        source.find("strict_local_response") != std::string::npos ||
        source.find("profile") != std::string::npos ||
        source.find("return 204") != std::string::npos ||
        source.find("nginx::") != std::string::npos ||
        source.find("nginx_compat") != std::string::npos) {
        error =
            "#330 Stage 4 generated source was not one exact maximum-boundary public "
            "SlashNormalized NoContent204 tuple plus the canonical root forwards";
        return false;
    }
    return true;
}

static bool parse_max_boundary_rut_access_log(const std::string& contents,
                                              const MaxBoundaryNoContentObservation& observation,
                                              const std::vector<size_t>& request_sizes,
                                              std::string& error) {
    const size_t vector_count = observation.trailing ? 5u : 6u;
    std::vector<std::string> records;
    if (observation.targets.size() != vector_count || request_sizes.size() != vector_count ||
        !split_exact_complete_log(
            contents, vector_count, "converter-generated #330 Stage 4 access log", records, error))
        return false;
    for (size_t i = 0u; i < vector_count; i++) {
        std::vector<std::string> fields;
        const size_t expected_fields = i < 3u ? 9u : 11u;
        const size_t expected_status = i < 3u ? 204u : 200u;
        const size_t expected_response = i < 3u ? 105u : 118u;
        if (!split_space_fields(records[i], fields) || fields.size() != expected_fields ||
            !exact_log_timestamp(fields[0]) || fields[1] != "GET" ||
            fields[2] != observation.targets[i] || fields[3] != std::to_string(expected_status) ||
            !decimal_field_equals(fields[3], expected_status) || !exact_log_duration(fields[4]) ||
            fields[5] != std::to_string(request_sizes[i]) ||
            !decimal_field_equals(fields[5], request_sizes[i]) ||
            fields[6] != std::to_string(expected_response) ||
            !decimal_field_equals(fields[6], expected_response) || fields[7] != "127.0.0.1" ||
            (i < 3u && fields[8] != "s=0") ||
            (i >= 3u && (fields[8] != "nginx_upstream" || !exact_log_duration(fields[9]) ||
                         fields[10] != "s=0"))) {
            error = "converter-generated #330 Stage 4 access record " + std::to_string(i + 1u) +
                    " lost raw target/order/status/size/upstream outcome: " + records[i];
            return false;
        }
    }
    return true;
}

static bool run_max_boundary_generated_parser_self_checks(std::string& error) {
    const auto replace_once =
        [](std::string value, const std::string& from, const std::string& to) {
            const size_t offset = value.find(from);
            if (offset == std::string::npos) return std::string{};
            value.replace(offset, from.size(), to);
            return value;
        };
    for (const bool trailing : {false, true}) {
        MaxBoundaryNoContentObservation observation;
        observation.trailing = trailing;
        observation.key = trailing ? max_boundary_trailing_key() : max_boundary_raw_key();
        observation.targets = max_boundary_targets(trailing);
        const size_t vector_count = trailing ? 5u : 6u;
        std::vector<size_t> sizes(vector_count);
        std::string access;
        for (size_t i = 0u; i < vector_count; i++) {
            sizes[i] = 70u + observation.targets[i].size();
            access += "2026-08-26T21:13:05.248Z GET " + observation.targets[i] + " " +
                      (i < 3u ? "204" : "200") + " 361us " + std::to_string(sizes[i]) + " " +
                      (i < 3u ? "105" : "118") + " 127.0.0.1" +
                      (i < 3u ? " s=0\n" : " nginx_upstream 243us s=0\n");
        }
        const auto rejects_access = [&](const std::string& value) {
            std::string detail;
            return !parse_max_boundary_rut_access_log(value, observation, sizes, detail);
        };
        const size_t first = access.find('\n');
        const size_t second = access.find('\n', first + 1u);
        std::string swapped = access;
        swapped.replace(0u,
                        second + 1u,
                        access.substr(first + 1u, second - first) + access.substr(0u, first + 1u));
        if (!parse_max_boundary_rut_access_log(access, observation, sizes, error) ||
            !rejects_access(access + access.substr(0u, first + 1u)) ||
            !rejects_access(access.substr(0u, access.size() - 1u)) || !rejects_access(swapped) ||
            !rejects_access(replace_once(access, " 204 ", " 200 ")) ||
            !rejects_access(replace_once(access, " 105 ", " 106 ")) ||
            !rejects_access(replace_once(access,
                                         " " + observation.targets[0] + " ",
                                         " " + observation.targets.back() + " ")) ||
            !rejects_access(replace_once(access,
                                         " " + std::to_string(sizes[0]) + " 105 ",
                                         " 999999999999999999999999999999999 105 ")) ||
            !rejects_access(replace_once(access, " 204 ", " 0204 ")) ||
            !rejects_access(replace_once(access, " nginx_upstream ", " other_upstream ")) ||
            !rejects_access(replace_once(
                access, " nginx_upstream 243us ", " nginx_upstream not-a-duration ")) ||
            !rejects_access(replace_once(access, " s=0\n", " extra s=0\n")) ||
            !rejects_access(replace_once(access, " s=0\n", " s=1\n"))) {
            error = "#330 Stage 4 generated access parser mutation self-check failed";
            return false;
        }

        std::string fragment = make_max_boundary_no_content_fragment(54330u, 54331u, trailing);
        const auto parsed = rut::nginx::parse({fragment.data(), static_cast<u32>(fragment.size())});
        if (!parsed) {
            error = "#330 Stage 4 source self-check fixture did not parse";
            return false;
        }
        const auto lowered = rut::nginx::lower_to_rut(parsed.value());
        if (!lowered) {
            error = "#330 Stage 4 source self-check fixture did not lower";
            return false;
        }
        const rut::Str view = lowered.value().view();
        const std::string canonical(view.ptr, view.len);
        const auto rejects_source = [&](std::string value) {
            std::string detail;
            return !validate_max_boundary_generated_source(value, 54330u, 54331u, trailing, detail);
        };
        const std::string selector = "route exact slash_normalized GET \"" + observation.key + "\"";
        if (!validate_max_boundary_generated_source(canonical, 54330u, 54331u, trailing, error) ||
            !rejects_source(
                replace_once(canonical, selector, "route exact GET \"" + observation.key + "\"")) ||
            !rejects_source(canonical + "route exact GET \"" + observation.key +
                            "?x=1\" { return response() }\n") ||
            !rejects_source(canonical + "if Host == \"max-boundary.example\" {}\n") ||
            !rejects_source(replace_once(canonical, "status: 204", "status: 200")) ||
            !rejects_source(
                replace_once(canonical,
                             observation.key,
                             trailing ? max_boundary_raw_key() : max_boundary_trailing_key()))) {
            error = "#330 Stage 4 generated source mutation self-check failed";
            return false;
        }
        std::string normalized = canonical;
        if (!canonicalize_unique_port(normalized, "listen :54330", "listen :FRONTEND") ||
            !canonicalize_unique_port(normalized, "127.0.0.1:54331", "127.0.0.1:BACKEND")) {
            error = "#330 Stage 4 source port normalization valid self-check failed";
            return false;
        }
        std::string missing = canonical;
        missing.erase(missing.find("listen :54330"), strlen("listen :54330"));
        std::string duplicate = canonical + "listen :54330\n";
        if (canonicalize_unique_port(missing, "listen :54330", "listen :FRONTEND") ||
            canonicalize_unique_port(duplicate, "listen :54330", "listen :FRONTEND")) {
            error = "#330 Stage 4 missing/duplicate port normalization mutation was accepted";
            return false;
        }
    }
    return true;
}

static bool capture_generated_max_boundary_side(u16 frontend_port,
                                                u16 backend_port,
                                                TempDir& temp,
                                                const char* rut_path,
                                                bool trailing,
                                                MaxBoundaryNoContentObservation& observation,
                                                std::string& generated_source,
                                                std::string& error,
                                                int* frontend_reservation,
                                                int* backend_reservation) {
    const std::string key = trailing ? max_boundary_trailing_key() : max_boundary_raw_key();
    const std::vector<std::string> targets = max_boundary_targets(trailing);
    const size_t vector_count = trailing ? 5u : 6u;
    const size_t fallback_count = trailing ? 2u : 3u;
    if (rut_path == nullptr || rut_path[0] != '/' || access(rut_path, X_OK) != 0 ||
        key.size() != 62u || targets.size() != vector_count || frontend_reservation == nullptr ||
        backend_reservation == nullptr || *frontend_reservation < 0 || *backend_reservation < 0) {
        error =
            "converter-generated #330 Stage 4 requires an executable absolute RUT path, "
            "exact maximum-boundary vectors, and held port reservations";
        return false;
    }
    std::string fragment =
        make_max_boundary_no_content_fragment(frontend_port, backend_port, trailing);
    const auto parsed = rut::nginx::parse({fragment.data(), static_cast<u32>(fragment.size())});
    if (!parsed) {
        error = "#330 Stage 4 accepted nginx fragment did not traverse the independent parser";
        return false;
    }
    const auto& server = parsed.value();
    const auto& root = server.location;
    const auto& proxy = root.proxy_pass;
    const auto& exact = server.exact_no_content_return;
    const auto& response = exact.response;
    const size_t root_location = fragment.find("location / {");
    const size_t root_path = fragment.find('/', root_location);
    const std::string exact_marker = "location = " + key;
    const size_t exact_location = fragment.find(exact_marker);
    const size_t exact_path = fragment.find(key, exact_location);
    const size_t return_offset = fragment.find("return", exact_location);
    const size_t status_offset = fragment.find("204", return_offset);
    const size_t semicolon = fragment.find(';', status_offset);
    const size_t exact_end = fragment.find('}', semicolon);
    const uintptr_t source_base = reinterpret_cast<uintptr_t>(fragment.data());
    const auto same_source = [&](rut::Str value, rut::Span span) {
        return value.ptr != nullptr && span.end >= span.start &&
               span.end - span.start == value.len &&
               reinterpret_cast<uintptr_t>(value.ptr) - span.start == source_base;
    };
    const rut::Str expected_path{key.data(), static_cast<u32>(key.size())};
    if (root_location == std::string::npos || root_path == std::string::npos ||
        exact_location == std::string::npos || exact_path == std::string::npos ||
        return_offset == std::string::npos || status_offset == std::string::npos ||
        semicolon == std::string::npos || exact_end == std::string::npos ||
        server.span.start != 0u || server.span.end != fragment.size() - 1u ||
        server.listen.port != frontend_port || !root.path.eq(rut::lit_str("/")) ||
        root.path.ptr != fragment.data() + root_path || !same_source(root.path, root.path_span) ||
        proxy.has_uri || proxy.address[0] != 127u || proxy.address[1] != 0u ||
        proxy.address[2] != 0u || proxy.address[3] != 1u || proxy.port != backend_port ||
        !exact.present || !exact.path.eq(expected_path) ||
        exact.path.ptr != fragment.data() + exact_path ||
        !same_source(exact.path, exact.path_span) || exact.span.start != exact_location ||
        exact.span.end != exact_end + 1u || response.status != 204u ||
        response.status_span.start != status_offset ||
        response.status_span.end != status_offset + 3u || response.span.start != return_offset ||
        response.span.end != semicolon + 1u ||
        memcmp(fragment.data() + response.status_span.start, "204", 3u) != 0 ||
        server.exact_local_return.present || server.exact_absolute_redirect.present ||
        exact.span.start >= exact.path_span.start || exact.path_span.end > response.span.start ||
        response.span.end >= exact.span.end || root.span.start != root_location) {
        error = "#330 Stage 4 fragment lost borrowed 62-byte path/status provenance or root role";
        return false;
    }
    const auto lowered = rut::nginx::lower_to_rut(server);
    if (!lowered) {
        error = "#330 Stage 4 genuine bounded model failed public ordinary-RUT lowering";
        return false;
    }
    const rut::Str output = lowered.value().view();
    generated_source.assign(output.ptr, output.len);
    if (!validate_max_boundary_generated_source(
            generated_source, frontend_port, backend_port, trailing, error) ||
        !write_file(temp.source, output.ptr, output.len))
        return false;
    std::fill(fragment.begin(), fragment.end(), '\0');
    if (!std::all_of(fragment.begin(), fragment.end(), [](char byte) { return byte == '\0'; })) {
        error = "#330 Stage 4 failed to destroy the borrowed nginx source after lowering";
        return false;
    }

    observation = MaxBoundaryNoContentObservation{};
    observation.trailing = trailing;
    observation.key = key;
    observation.targets = targets;
    observation.temp_path = temp.path;
    observation.config_path = temp.source;
    observation.log_path = temp.rut_log;
    observation.access_path = temp.rut_access_log;
    observation.process_identity =
        std::string(rut_path) + " " + temp.source + " listen:" + std::to_string(frontend_port);
    observation.wires.resize(vector_count);
    std::vector<std::string> requests(vector_count);
    std::vector<size_t> request_sizes(vector_count);
    for (size_t i = 0u; i < vector_count; i++) {
        requests[i] = "GET " + targets[i] +
                      " HTTP/1.1\r\nHost: max-boundary.example\r\nConnection: close\r\n\r\n";
        request_sizes[i] = requests[i].size();
        const size_t header = requests[i].find("\r\n\r\n");
        if (requests[i].rfind("GET " + targets[i] + " HTTP/1.1\r\n", 0u) != 0u ||
            requests[i].find('#') != std::string::npos ||
            requests[i].find("\r\nContent-Length:") != std::string::npos ||
            requests[i].find("\r\nTransfer-Encoding:") != std::string::npos ||
            requests[i].find("\r\nTE:") != std::string::npos ||
            requests[i].find("\r\nExpect:") != std::string::npos ||
            requests[i].find("\r\nUpgrade:") != std::string::npos || header == std::string::npos ||
            header + 4u != requests[i].size()) {
            error = "#330 Stage 4 generated request escaped the fresh bodyless H1.1 domain";
            return false;
        }
    }

    const auto recorder_live = [](const Recorder& recorder) {
        return recorder.running.load(std::memory_order_acquire) &&
               recorder.thread_alive.load(std::memory_order_acquire) &&
               !recorder.listener_failed.load(std::memory_order_acquire);
    };
    struct RecorderGuard {
        Recorder* value = nullptr;
        ~RecorderGuard() {
            if (value != nullptr) value->stop();
        }
    };
    ChildGuard runtime;
    close(*frontend_reservation);
    *frontend_reservation = -1;
    if (!spawn_child({rut_path,
                      temp.source,
                      "--shards",
                      "1",
                      "--no-pin",
                      "--drain",
                      "0",
                      "--access-log",
                      temp.rut_access_log},
                     temp.rut_log,
                     runtime.child) ||
        !wait_ready(frontend_port, runtime.child, error)) {
        if (error.empty()) error = "failed to start converter-generated RUT for #330 Stage 4";
        return false;
    }
    const std::string loaded = "Loaded program: " + temp.source + " (opt O2)\n";
    const std::string listener =
        "Listening on port " + std::to_string(frontend_port) + " with 1 shard(s)";
    const auto ready_deadline = std::chrono::steady_clock::now() + std::chrono::seconds(2);
    while ((!log_contains(temp.rut_log, loaded.c_str()) ||
            !log_contains(temp.rut_log, "Backend: io_uring\n") ||
            !log_contains(temp.rut_log, listener.c_str())) &&
           std::chrono::steady_clock::now() < ready_deadline) {
        if (poll_child(runtime.child)) {
            error = "#330 Stage 4 RUT exited before exact public readiness evidence";
            return false;
        }
        usleep(1000);
    }
    if (!log_contains(temp.rut_log, loaded.c_str()) ||
        !log_contains(temp.rut_log, "Backend: io_uring\n") ||
        !log_contains(temp.rut_log, listener.c_str())) {
        error = "#330 Stage 4 RUT lacked load/io_uring/listener readiness evidence";
        return false;
    }
    static constexpr char kDestroyed[] = "destroyed-after-330-stage4-public-load\n";
    if (!write_file(temp.source, kDestroyed, sizeof(kDestroyed) - 1u)) {
        error = "#330 Stage 4 failed to overwrite generated source after public load";
        return false;
    }
    std::string destroyed;
    if (!read_exact_return204_log(
            temp.source, "#330 Stage 4 destroyed generated source", destroyed, error) ||
        destroyed != kDestroyed) {
        error = "#330 Stage 4 generated source overwrite/readback was not exact";
        return false;
    }

    const auto wait_live = [&](Recorder& recorder, const char* phase) {
        const auto deadline = std::chrono::steady_clock::now() + std::chrono::seconds(2);
        while (std::chrono::steady_clock::now() < deadline) {
            if (poll_child(runtime.child) || !recorder.running.load(std::memory_order_acquire) ||
                recorder.listener_failed.load(std::memory_order_acquire)) {
                error =
                    std::string("#330 Stage 4 RUT/recorder failed before ") + phase + " readiness";
                return false;
            }
            if (recorder.thread_alive.load(std::memory_order_acquire)) return true;
            usleep(1000);
        }
        error = std::string("#330 Stage 4 recorder readiness timed out: ") + phase;
        return false;
    };
    const auto observe = [&](Recorder& recorder,
                             u32 expected,
                             const char* phase,
                             std::chrono::milliseconds duration) {
        const auto deadline = std::chrono::steady_clock::now() + duration;
        for (;;) {
            if (poll_child(runtime.child) || !recorder_live(recorder) ||
                recorder.accepted.load(std::memory_order_acquire) != expected ||
                recorder.requests.load(std::memory_order_acquire) != expected ||
                recorder.response_send_all_calls.load(std::memory_order_acquire) != expected) {
                error =
                    std::string("#330 Stage 4 unexpected process/upstream state during ") + phase;
                return false;
            }
            if (std::chrono::steady_clock::now() >= deadline) return true;
            usleep(5000);
        }
    };
    const auto request = [&](size_t index, const char* expected) {
        struct ClientGuard {
            int fd = -1;
            ~ClientGuard() {
                if (fd >= 0) close(fd);
            }
        } client{connect_once(frontend_port)};
        std::string detail;
        if (client.fd < 0 || !send_all(client.fd, requests[index].data(), requests[index].size()) ||
            !(index < 3u ? read_head_response(client.fd, observation.wires[index], detail)
                         : read_response(client.fd, observation.wires[index], detail)) ||
            !read_eof(client.fd, detail) ||
            !validate_exact_normalized_response(observation.wires[index], expected, detail)) {
            error = "#330 Stage 4 generated vector " + targets[index] +
                    " exact response/EOF failed: " + detail;
            return false;
        }
        if (poll_child(runtime.child)) {
            error = "#330 Stage 4 generated RUT exited after vector " + targets[index] + " (" +
                    child_status_description(runtime.child) + ")";
            return false;
        }
        return true;
    };

    Recorder zero;
    RecorderGuard zero_guard{&zero};
    zero.observe_extra_requests_until_stop = true;
    close(*backend_reservation);
    *backend_reservation = -1;
    if (!zero.setup(backend_port) || !wait_live(zero, "local") ||
        !observe(zero, 0u, "pre-local zero window", std::chrono::milliseconds(250))) {
        if (error.empty())
            error = "#330 Stage 4 local recorder could not bind the reserved backend port";
        return false;
    }
    for (size_t i = 0u; i < 3u; i++) {
        if (!request(i, kExactLocalReturn204ResponseNormalized) ||
            !observe(zero, 0u, "local vector zero window", std::chrono::milliseconds(250)))
            return false;
        const std::string text(observation.wires[i].begin(), observation.wires[i].end());
        if (observation.wires[i].size() != 105u ||
            header_end(observation.wires[i]) != observation.wires[i].size() ||
            text.find("\r\nContent-Type:") != std::string::npos ||
            text.find("\r\nContent-Length:") != std::string::npos ||
            text.find("\r\nTransfer-Encoding:") != std::string::npos ||
            text.find("\r\nLocation:") != std::string::npos) {
            error = "#330 Stage 4 generated strict 204 gained framing/body/tail/redirect";
            return false;
        }
    }
    if (!observe(zero, 0u, "post-local zero window", std::chrono::milliseconds(500))) return false;
    zero.stop();
    zero_guard.value = nullptr;
    observation.local_accepts = zero.accepted.load(std::memory_order_acquire);
    observation.local_requests = zero.requests.load(std::memory_order_acquire);
    observation.local_sends = zero.response_send_all_calls.load(std::memory_order_acquire);
    observation.local_history = zero.history;
    if (zero.thread_alive.load(std::memory_order_acquire) ||
        zero.listener_failed.load(std::memory_order_acquire) || observation.local_accepts != 0u ||
        observation.local_requests != 0u || observation.local_sends != 0u ||
        zero.response_send_succeeded.load(std::memory_order_acquire) || !zero.history.empty() ||
        !zero.request.empty()) {
        error = "#330 Stage 4 local recorder did not settle at exact zero";
        return false;
    }

    Recorder fallback;
    RecorderGuard fallback_guard{&fallback};
    fallback.observe_extra_requests_until_stop = true;
    if (!fallback.setup(backend_port,
                        static_cast<u32>(fallback_count),
                        kBackendResponse,
                        sizeof(kBackendResponse) - 1u) ||
        !wait_live(fallback, "fallback") ||
        !observe(fallback, 0u, "pre-fallback zero window", std::chrono::milliseconds(100))) {
        if (error.empty()) error = "#330 Stage 4 fallback recorder failed readiness";
        return false;
    }
    for (size_t i = 3u; i < vector_count; i++) {
        if (!request(i, kSuccessResponseNormalized)) return false;
        const u32 expected = static_cast<u32>(i - 2u);
        const auto deadline = std::chrono::steady_clock::now() + std::chrono::seconds(2);
        while (std::chrono::steady_clock::now() < deadline) {
            const u32 accepts = fallback.accepted.load(std::memory_order_acquire);
            const u32 requests_seen = fallback.requests.load(std::memory_order_acquire);
            const u32 sends = fallback.response_send_all_calls.load(std::memory_order_acquire);
            if (poll_child(runtime.child) || !recorder_live(fallback) || accepts > expected ||
                requests_seen > expected || sends > expected) {
                error = "#330 Stage 4 generated fallback observed retry/extra request";
                return false;
            }
            if (accepts == expected && requests_seen == expected && sends == expected) break;
            usleep(1000);
        }
        if (fallback.accepted.load(std::memory_order_acquire) != expected ||
            fallback.requests.load(std::memory_order_acquire) != expected ||
            fallback.response_send_all_calls.load(std::memory_order_acquire) != expected ||
            !observe(
                fallback, expected, "ordered fallback count", std::chrono::milliseconds(100))) {
            error = "#330 Stage 4 fallback episode count did not settle exactly";
            return false;
        }
    }
    if (!observe(fallback,
                 static_cast<u32>(fallback_count),
                 "no-additional-fallback window",
                 std::chrono::milliseconds(500)) ||
        !stop_child(runtime.child)) {
        error = "#330 Stage 4 generated RUT did not survive controlled shutdown";
        return false;
    }
    fallback.stop();
    fallback_guard.value = nullptr;
    observation.forward_accepts = fallback.accepted.load(std::memory_order_acquire);
    observation.forward_requests = fallback.requests.load(std::memory_order_acquire);
    observation.forward_sends = fallback.response_send_all_calls.load(std::memory_order_acquire);
    observation.forward_history = fallback.history;
    if (fallback.thread_alive.load(std::memory_order_acquire) ||
        fallback.listener_failed.load(std::memory_order_acquire) ||
        observation.forward_accepts != fallback_count ||
        observation.forward_requests != fallback_count ||
        observation.forward_sends != fallback_count || !fallback.response_send_succeeded.load() ||
        !fallback.response_clean_shutdown.load() || !fallback.response_connection_closed.load() ||
        observation.forward_history.size() != fallback_count) {
        error = "#330 Stage 4 fallback recorder lifecycle/count was incomplete";
        return false;
    }
    for (size_t i = 0u; i < vector_count; i++) observation.access_records[i] = 1u;
    if (!validate_max_boundary_observation(observation, backend_port, error)) return false;

    std::string access_contents;
    std::string runtime_contents;
    if (!read_exact_return204_log(temp.rut_access_log,
                                  "converter-generated #330 Stage 4 access log",
                                  access_contents,
                                  error) ||
        !parse_max_boundary_rut_access_log(access_contents, observation, request_sizes, error) ||
        !read_exact_return204_log(temp.rut_log,
                                  "converter-generated #330 Stage 4 runtime log",
                                  runtime_contents,
                                  error) ||
        !parse_exact_return204_runtime_log(runtime_contents, temp.source, listener, error))
        return false;
    if (request_sizes[3] == observation.forward_history[0].size()) {
        error = "#330 fixture no longer distinguishes downstream and rebuilt request sizes";
        return false;
    }
    auto swapped_sizes = request_sizes;
    swapped_sizes[3] = observation.forward_history[0].size();
    std::string swapped_size_error;
    if (parse_max_boundary_rut_access_log(
            access_contents, observation, swapped_sizes, swapped_size_error)) {
        error = "#330 access parser accepted rebuilt upstream field 5";
        return false;
    }
    return true;
}

static bool canonicalize_max_boundary_source(std::string& source,
                                             u16 frontend_port,
                                             u16 backend_port,
                                             const std::string& key) {
    return canonicalize_unique_port(
               source, "listen :" + std::to_string(frontend_port), "listen :FRONTEND") &&
           canonicalize_unique_port(
               source, "127.0.0.1:" + std::to_string(backend_port), "127.0.0.1:BACKEND") &&
           canonicalize_unique_port(source, key, "MAX_BOUNDARY_KEY");
}

static bool validate_max_boundary_four_way(const MaxBoundaryNoContentObservation observations[4],
                                           const std::string generated_sources[2],
                                           const u16 ports[8],
                                           std::string& error) {
    for (size_t i = 0u; i < 8u; i++) {
        if (ports[i] == 0u) {
            error = "#330 Stage 4 four-way validator received a zero dynamic port";
            return false;
        }
        for (size_t j = i + 1u; j < 8u; j++) {
            if (ports[i] == ports[j]) {
                error = "#330 Stage 4 four-way validator received duplicate dynamic ports";
                return false;
            }
        }
    }
    if (observations[0].trailing || observations[1].trailing || !observations[2].trailing ||
        !observations[3].trailing) {
        error = "#330 Stage 4 profile identities crossed non_trailing/trailing sides";
        return false;
    }
    size_t total_wires = 0u;
    u32 total_access = 0u;
    std::vector<std::string> resources;
    resources.reserve(20u);
    for (size_t side = 0u; side < 4u; side++) {
        if (!validate_max_boundary_observation(observations[side], ports[side * 2u + 1u], error))
            return false;
        total_wires += observations[side].wires.size();
        for (u32 count : observations[side].access_records) total_access += count;
        resources.insert(resources.end(),
                         {observations[side].temp_path,
                          observations[side].config_path,
                          observations[side].log_path,
                          observations[side].access_path,
                          observations[side].process_identity});
        if (observations[side].wires.data() == nullptr) {
            error = "#330 Stage 4 one side lacked owned wire observation storage";
            return false;
        }
        for (size_t other = side + 1u; other < 4u; other++) {
            if (observations[side].wires.data() == observations[other].wires.data()) {
                error = "#330 Stage 4 two sides aliased wire observation storage";
                return false;
            }
        }
    }
    if (total_wires != 22u || total_access != 22u) {
        error = "#330 Stage 4 did not retain exactly 22 wire/access observations";
        return false;
    }
    for (size_t i = 0u; i < resources.size(); i++) {
        if (resources[i].empty()) {
            error = "#330 Stage 4 one resource identity was empty";
            return false;
        }
        for (size_t j = i + 1u; j < resources.size(); j++) {
            if (resources[i] == resources[j]) {
                error = "#330 Stage 4 resource/process identities were not globally isolated";
                return false;
            }
        }
    }
    if (!validate_max_boundary_generated_source(
            generated_sources[0], ports[2], ports[3], false, error) ||
        !validate_max_boundary_generated_source(
            generated_sources[1], ports[6], ports[7], true, error))
        return false;
    std::string canonical[2] = {generated_sources[0], generated_sources[1]};
    if (!canonicalize_max_boundary_source(
            canonical[0], ports[2], ports[3], max_boundary_raw_key()) ||
        !canonicalize_max_boundary_source(
            canonical[1], ports[6], ports[7], max_boundary_trailing_key()) ||
        canonical[0] != canonical[1]) {
        error = "#330 Stage 4 profile lowering differed after exact endpoint/key canonicalization";
        return false;
    }
    for (const size_t profile : {0u, 2u}) {
        const auto pinned_history =
            canonicalize_trailing_no_content_backend_history(observations[profile].forward_history);
        const auto generated_history = canonicalize_trailing_no_content_backend_history(
            observations[profile + 1u].forward_history);
        const size_t expected_count = profile == 0u ? 3u : 2u;
        if (pinned_history.size() != expected_count || generated_history != pinned_history) {
            error = "#330 Stage 4 pinned/generated ordered backend histories differed by profile";
            return false;
        }
        for (size_t vector = 0u; vector < observations[profile].wires.size(); vector++) {
            std::vector<char> pinned = observations[profile].wires[vector];
            std::vector<char> generated = observations[profile + 1u].wires[vector];
            if (!normalize_date(pinned) || !normalize_date(generated) || generated != pinned) {
                error = "#330 Stage 4 pinned/generated Date-normalized wire mismatch at profile " +
                        std::to_string(profile / 2u) + " vector " + std::to_string(vector + 1u);
                return false;
            }
        }
    }
    return true;
}

static bool run_max_boundary_four_way_self_checks(std::string& error) {
    u16 ports[8] = {54340u, 54341u, 54342u, 54343u, 54344u, 54345u, 54346u, 54347u};
    MaxBoundaryNoContentObservation values[4] = {
        make_max_boundary_self_check(false, ports[1], "stage4-pinned-non-trailing"),
        make_max_boundary_self_check(false, ports[3], "stage4-generated-non-trailing"),
        make_max_boundary_self_check(true, ports[5], "stage4-pinned-trailing"),
        make_max_boundary_self_check(true, ports[7], "stage4-generated-trailing")};
    std::string sources[2];
    for (size_t i = 0u; i < 2u; i++) {
        const bool trailing = i == 1u;
        std::string fragment =
            make_max_boundary_no_content_fragment(ports[2u + i * 4u], ports[3u + i * 4u], trailing);
        const auto parsed = rut::nginx::parse({fragment.data(), static_cast<u32>(fragment.size())});
        if (!parsed) {
            error = "#330 Stage 4 four-way self-check fragment did not parse";
            return false;
        }
        const auto lowered = rut::nginx::lower_to_rut(parsed.value());
        if (!lowered) {
            error = "#330 Stage 4 four-way self-check fragment did not lower";
            return false;
        }
        const rut::Str view = lowered.value().view();
        sources[i].assign(view.ptr, view.len);
    }
    if (!validate_max_boundary_four_way(values, sources, ports, error)) return false;
    const auto rejects = [&](MaxBoundaryNoContentObservation mutated[4],
                             std::string changed_sources[2],
                             const char* name) {
        std::string detail;
        if (!validate_max_boundary_four_way(mutated, changed_sources, ports, detail)) return true;
        error = std::string("#330 Stage 4 four-way mutation accepted: ") + name;
        return false;
    };
    MaxBoundaryNoContentObservation mutated[4];
    std::string changed[2] = {sources[0], sources[1]};
    std::copy(std::begin(values), std::end(values), std::begin(mutated));
    mutated[1].temp_path = mutated[0].temp_path;
    if (!rejects(mutated, changed, "resource-alias")) return false;
    std::copy(std::begin(values), std::end(values), std::begin(mutated));
    mutated[1].process_identity = mutated[0].process_identity;
    if (!rejects(mutated, changed, "process-alias")) return false;
    std::copy(std::begin(values), std::end(values), std::begin(mutated));
    mutated[1].wires[0][9] = '5';
    if (!rejects(mutated, changed, "wire-status")) return false;
    std::copy(std::begin(values), std::end(values), std::begin(mutated));
    mutated[1].wires[0].push_back('x');
    if (!rejects(mutated, changed, "wire-tail")) return false;
    std::copy(std::begin(values), std::end(values), std::begin(mutated));
    mutated[1].local_requests = 1u;
    if (!rejects(mutated, changed, "local-nonzero")) return false;
    std::copy(std::begin(values), std::end(values), std::begin(mutated));
    mutated[1].forward_history[0] = mutated[1].forward_history[1];
    if (!rejects(mutated, changed, "history-order-target")) return false;
    std::copy(std::begin(values), std::end(values), std::begin(mutated));
    mutated[3].forward_history.push_back(mutated[3].forward_history[0]);
    mutated[3].forward_accepts++;
    mutated[3].forward_requests++;
    mutated[3].forward_sends++;
    if (!rejects(mutated, changed, "retry-history-count")) return false;
    std::copy(std::begin(values), std::end(values), std::begin(mutated));
    mutated[1].access_records[0] = 0u;
    if (!rejects(mutated, changed, "access-truncation")) return false;
    std::copy(std::begin(values), std::end(values), std::begin(mutated));
    mutated[3].trailing = false;
    if (!rejects(mutated, changed, "profile-cross-wire")) return false;
    std::copy(std::begin(values), std::end(values), std::begin(mutated));
    changed[0] = sources[0];
    const std::string selector = "route exact slash_normalized GET";
    const size_t selector_offset = changed[0].find(selector);
    if (selector_offset == std::string::npos) {
        error = "#330 Stage 4 self-check could not find generated selector";
        return false;
    }
    changed[0].replace(selector_offset, selector.size(), "route exact GET");
    if (!rejects(mutated, changed, "SlashNormalized-to-Raw")) return false;
    std::copy(std::begin(values), std::end(values), std::begin(mutated));
    changed[0] = sources[0];
    changed[1] = sources[1] + "# mismatch\n";
    if (!rejects(mutated, changed, "source-mismatch")) return false;
    u16 changed_ports[8];
    std::copy(std::begin(ports), std::end(ports), std::begin(changed_ports));
    std::string detail;
    changed_ports[7] = changed_ports[0];
    if (validate_max_boundary_four_way(values, sources, changed_ports, detail)) {
        error = "#330 Stage 4 duplicate-port mutation was accepted";
        return false;
    }
    changed_ports[7] = ports[7];
    changed_ports[0] = 0u;
    if (validate_max_boundary_four_way(values, sources, changed_ports, detail)) {
        error = "#330 Stage 4 zero-port mutation was accepted";
        return false;
    }
    return true;
}

static bool run_converter_max_boundary_no_content_differential(const std::string& container_prefix,
                                                               const char* rut_path,
                                                               std::string& error) {
    struct ReservedPorts {
        int fds[8];
        ReservedPorts() { std::fill(std::begin(fds), std::end(fds), -1); }
        ~ReservedPorts() {
            for (int fd : fds)
                if (fd >= 0) close(fd);
        }
        bool reserve(size_t index, u16& port) {
            const int fd = socket(AF_INET, SOCK_STREAM | SOCK_CLOEXEC, 0);
            if (fd < 0) return false;
            sockaddr_in addr{};
            addr.sin_family = AF_INET;
            addr.sin_addr.s_addr = htonl(INADDR_LOOPBACK);
            addr.sin_port = 0;
            socklen_t len = sizeof(addr);
            if (bind(fd, reinterpret_cast<sockaddr*>(&addr), sizeof(addr)) != 0 ||
                getsockname(fd, reinterpret_cast<sockaddr*>(&addr), &len) != 0 ||
                ntohs(addr.sin_port) == 0u) {
                close(fd);
                return false;
            }
            fds[index] = fd;
            port = ntohs(addr.sin_port);
            return true;
        }
    } reservations;
    u16 ports[8]{};
    for (size_t i = 0u; i < 8u; i++) {
        if (!reservations.reserve(i, ports[i])) {
            error = "#330 Stage 4 could not simultaneously reserve eight unique ports";
            return false;
        }
    }
    TempDir temps[4];
    for (TempDir& temp : temps) {
        if (!temp.create()) {
            error = "#330 Stage 4 could not create four independent resource trees";
            return false;
        }
    }
    for (size_t i = 0u; i < 4u; i++) {
        for (size_t j = i + 1u; j < 4u; j++) {
            if (strcmp(temps[i].path, temps[j].path) == 0 ||
                temps[i].nginx_config == temps[j].nginx_config ||
                temps[i].source == temps[j].source || temps[i].nginx_log == temps[j].nginx_log ||
                temps[i].rut_log == temps[j].rut_log ||
                temps[i].nginx_access_log == temps[j].nginx_access_log ||
                temps[i].rut_access_log == temps[j].rut_access_log) {
                error = "#330 Stage 4 four sides shared a temp/config/source/log/access path";
                return false;
            }
        }
    }
    MaxBoundaryNoContentObservation observations[4];
    std::string sources[2];
    const auto failed_side = [&](const char* side) {
        if (error.empty()) error = std::string("#330 Stage 4 ") + side + " returned no diagnostic";
        return false;
    };
    if (!capture_pinned_max_boundary_side(ports[0],
                                          ports[1],
                                          temps[0],
                                          container_prefix + "-nginx-non-trailing",
                                          false,
                                          observations[0],
                                          error,
                                          &reservations.fds[0],
                                          &reservations.fds[1]))
        return failed_side("pinned non_trailing");
    if (!capture_generated_max_boundary_side(ports[2],
                                             ports[3],
                                             temps[1],
                                             rut_path,
                                             false,
                                             observations[1],
                                             sources[0],
                                             error,
                                             &reservations.fds[2],
                                             &reservations.fds[3]))
        return failed_side("generated non_trailing");
    if (!capture_pinned_max_boundary_side(ports[4],
                                          ports[5],
                                          temps[2],
                                          container_prefix + "-nginx-trailing",
                                          true,
                                          observations[2],
                                          error,
                                          &reservations.fds[4],
                                          &reservations.fds[5]))
        return failed_side("pinned trailing");
    if (!capture_generated_max_boundary_side(ports[6],
                                             ports[7],
                                             temps[3],
                                             rut_path,
                                             true,
                                             observations[3],
                                             sources[1],
                                             error,
                                             &reservations.fds[6],
                                             &reservations.fds[7]))
        return failed_side("generated trailing");
    return validate_max_boundary_four_way(observations, sources, ports, error);
}

struct ExactLocalBodySpaceOracleObservation {
    std::string order;
    std::string temp_path;
    std::string config_path;
    std::string log_path;
    std::string container_name;
    std::vector<char> wire;
    u32 upstream_accepts = 0;
    u32 upstream_requests = 0;
    u32 upstream_sends = 0;
    u32 access_records = 0;
};

static void dump_exact_local_body_space_oracle_observation(
    const ExactLocalBodySpaceOracleObservation& observation) {
    std::cerr << "exact-local-body-space order=" << observation.order
              << " temp=" << observation.temp_path << " config=" << observation.config_path
              << " log=" << observation.log_path << " container=" << observation.container_name
              << " access=" << observation.access_records
              << " upstream=" << observation.upstream_accepts << "/"
              << observation.upstream_requests << "/" << observation.upstream_sends << "\n";
    dump_wire("GET /static body-space oracle", observation.wire);
}

static void dump_exact_local_body_multiple_space_oracle_observation(
    const char* body_case, const ExactLocalBodySpaceOracleObservation& observation) {
    std::cerr << "#322 exact-local-body-multiple-space body=" << body_case
              << " order=" << observation.order << " temp=" << observation.temp_path
              << " config=" << observation.config_path << " log=" << observation.log_path
              << " container=" << observation.container_name
              << " access=" << observation.access_records
              << " upstream=" << observation.upstream_accepts << "/"
              << observation.upstream_requests << "/" << observation.upstream_sends << "\n";
    dump_wire("#322 GET /static multiple-body-space oracle", observation.wire);
}

struct ExactLocalBodySpaceOracleSpec {
    const char* issue;
    const char* request;
    const char* host;
    const char* body;
    const char* expected_response;
    const char* access_prefix;
    const char* log_format;
    u32 content_length;
    bool reject_failure_levels;
};

static bool capture_pinned_exact_local_body_space_order_with_spec(
    u16 frontend_port,
    u16 backend_port,
    TempDir& temp,
    const std::string& container_name,
    const ExactLocalBodySpaceOracleSpec& spec,
    bool exact_first,
    ExactLocalBodySpaceOracleObservation& observation,
    std::string& error) {
    const std::string issue(spec.issue);
    const std::string request(spec.request);
    const size_t header_end = request.find("\r\n\r\n");
    if (strlen(spec.body) != spec.content_length || spec.content_length == 0 ||
        request.rfind("GET /static HTTP/1.1\r\n", 0) != 0 ||
        request.find("\r\nHost: " + std::string(spec.host) + "\r\n") == std::string::npos ||
        request.find("\r\nConnection: close\r\n") == std::string::npos ||
        request.find("\r\nContent-Length:") != std::string::npos ||
        request.find("\r\nTransfer-Encoding:") != std::string::npos ||
        request.find("\r\nTE:") != std::string::npos ||
        request.find("\r\nExpect:") != std::string::npos ||
        request.find("\r\nUpgrade:") != std::string::npos || header_end == std::string::npos ||
        header_end + 4u != request.size()) {
        error = issue +
                " oracle request escaped the one fresh bodyless origin-form explicit-close "
                "H1.1 GET domain";
        return false;
    }

    observation = ExactLocalBodySpaceOracleObservation{};
    observation.order = exact_first ? "exact-before-root" : "root-before-exact";
    observation.temp_path = temp.path;
    observation.config_path = temp.nginx_config;
    observation.log_path = temp.nginx_log;
    observation.container_name = container_name;
    const std::string access_prefix = std::string(spec.access_prefix) + "-" + observation.order +
                                      "-" + std::to_string(getpid()) + "-scoped";
    const std::string exact_location =
        "    location = /static { return 200 \"" + std::string(spec.body) + "\"; }\n";
    const std::string root_location =
        "    location / { proxy_pass http://127.0.0.1:" + std::to_string(backend_port) + "; }\n";
    const std::string config =
        "error_log stderr notice;\n"
        "events {}\n"
        "http {\n"
        "  log_format " +
        std::string(spec.log_format) + " '" + access_prefix +
        " raw=\"$request\" status=$status bytes=$body_bytes_sent host=\"$host\"';\n"
        "  access_log /dev/stderr " +
        std::string(spec.log_format) +
        ";\n"
        "  server {\n"
        "    listen " +
        std::to_string(frontend_port) + ";\n" +
        (exact_first ? exact_location + root_location : root_location + exact_location) +
        "  }\n"
        "}\n";
    if (!write_file(temp.nginx_config, config.data(), config.size())) {
        error = "failed to write " + issue + " exact local body-space pinned nginx config";
        return false;
    }

    const auto recorder_live = [](const Recorder& recorder) {
        return recorder.running.load(std::memory_order_acquire) &&
               recorder.thread_alive.load(std::memory_order_acquire) &&
               !recorder.listener_failed.load(std::memory_order_acquire);
    };
    const auto wait_recorder_live = [&](Recorder& recorder, Child& nginx) {
        const auto deadline = std::chrono::steady_clock::now() + std::chrono::seconds(2);
        while (std::chrono::steady_clock::now() < deadline) {
            if (poll_child(nginx)) {
                error = "pinned nginx exited before " + issue + " recorder readiness";
                return false;
            }
            if (recorder.listener_failed.load(std::memory_order_acquire) ||
                !recorder.running.load(std::memory_order_acquire)) {
                error = issue + " recorder failed before readiness";
                return false;
            }
            if (recorder.thread_alive.load(std::memory_order_acquire)) return true;
            usleep(1000);
        }
        error = issue + " recorder readiness timed out";
        return false;
    };
    const auto observe_live_zero = [&](Recorder& recorder, Child& nginx, const char* phase) {
        const auto deadline = std::chrono::steady_clock::now() + std::chrono::milliseconds(500);
        while (std::chrono::steady_clock::now() < deadline) {
            if (poll_child(nginx) || !recorder_live(recorder)) {
                error = issue + " pinned nginx or recorder failed during " + phase;
                return false;
            }
            if (recorder.accepted.load(std::memory_order_acquire) != 0 ||
                recorder.requests.load(std::memory_order_acquire) != 0 ||
                recorder.response_send_all_calls.load(std::memory_order_acquire) != 0) {
                error = issue + " observed upstream activity during " + phase;
                return false;
            }
            usleep(5000);
        }
        return true;
    };

    Recorder recorder;
    recorder.observe_extra_requests_until_stop = true;
    if (!recorder.setup(backend_port)) {
        error = "failed to start " + issue + " zero-upstream recorder";
        return false;
    }
    DockerGuard docker(container_name);
    ChildGuard nginx;
    if (!spawn_child({"docker",
                      "run",
                      "--pull=never",
                      "--network",
                      "host",
                      "--name",
                      container_name,
                      "-v",
                      temp.nginx_config + ":/etc/nginx/nginx.conf:ro",
                      kNginxImage,
                      "nginx",
                      "-g",
                      "daemon off;"},
                     temp.nginx_log,
                     nginx.child)) {
        error = "failed to start pinned nginx for " + issue + " oracle";
        return false;
    }
    if (!wait_ready(frontend_port, nginx.child, error) ||
        !wait_recorder_live(recorder, nginx.child) ||
        !observe_live_zero(recorder, nginx.child, "pre-request live zero-upstream window"))
        return false;

    struct ClientGuard {
        int fd = -1;
        ~ClientGuard() {
            if (fd >= 0) close(fd);
        }
    } client{connect_once(frontend_port)};
    std::string detail;
    if (client.fd < 0 || !send_all(client.fd, spec.request, strlen(spec.request)) ||
        !read_response(client.fd, observation.wire, detail) || !read_eof(client.fd, detail)) {
        error = issue + " response/EOF/zero-tail failed: " +
                (detail.empty() ? std::string("connect or send failed") : detail);
        return false;
    }
    if (!validate_exact_normalized_response(observation.wire, spec.expected_response, detail)) {
        error = issue + " exact status/reason/header-order/body wire mismatch: " + detail;
        return false;
    }
    const std::string wire_text(observation.wire.begin(), observation.wire.end());
    if (wire_text.find("\r\nLocation:") != std::string::npos) {
        error = issue + " exact local body-space response unexpectedly emitted Location";
        return false;
    }
    if (!observe_live_zero(recorder, nginx.child, "post-request live zero-upstream window"))
        return false;

    if (!stop_child(nginx.child)) {
        error = "failed to stop pinned nginx after " + issue + " oracle";
        return false;
    }
    if (!docker.remove()) {
        error = "docker rm -f failed after " + issue + " oracle";
        return false;
    }
    recorder.stop();
    observation.upstream_accepts = recorder.accepted.load(std::memory_order_acquire);
    observation.upstream_requests = recorder.requests.load(std::memory_order_acquire);
    observation.upstream_sends = recorder.response_send_all_calls.load(std::memory_order_acquire);
    if (recorder.thread_alive.load(std::memory_order_acquire) ||
        recorder.listener_failed.load(std::memory_order_acquire) ||
        observation.upstream_accepts != 0 || observation.upstream_requests != 0 ||
        observation.upstream_sends != 0 ||
        recorder.response_send_succeeded.load(std::memory_order_acquire) ||
        !recorder.history.empty() || !recorder.request.empty()) {
        error = issue + " recorder did not settle with zero accepts/requests/sends/history";
        return false;
    }

    const std::string marker =
        "raw=\"GET /static HTTP/1.1\" status=200 bytes=" + std::to_string(spec.content_length) +
        " host=\"" + spec.host + "\"";
    u32 total_access = 0;
    u32 connect_failures = 0;
    u32 upstream_failures = 0;
    const std::string upstream_context = "127.0.0.1:" + std::to_string(backend_port);
    if (!log_count_line_with(
            temp.nginx_log, marker.c_str(), access_prefix.c_str(), observation.access_records) ||
        !log_count_line_with(
            temp.nginx_log, access_prefix.c_str(), access_prefix.c_str(), total_access) ||
        !log_count_line_with(
            temp.nginx_log, "connect() failed", upstream_context.c_str(), connect_failures) ||
        !log_count_line_with(
            temp.nginx_log, "upstream", upstream_context.c_str(), upstream_failures) ||
        observation.access_records != 1 || total_access != 1 || connect_failures != 0 ||
        upstream_failures != 0 ||
        (spec.reject_failure_levels &&
         (log_contains(temp.nginx_log, "[emerg]") || log_contains(temp.nginx_log, "[alert]") ||
          log_contains(temp.nginx_log, "[crit]") || log_contains(temp.nginx_log, "[error]")))) {
        error = issue +
                " scoped logs did not prove one boundary-safe raw /static record and zero "
                "nginx/connect/upstream failures";
        return false;
    }
    return true;
}

static bool capture_pinned_exact_local_body_space_order(
    u16 frontend_port,
    u16 backend_port,
    TempDir& temp,
    const std::string& container_name,
    bool exact_first,
    ExactLocalBodySpaceOracleObservation& observation,
    std::string& error) {
    const ExactLocalBodySpaceOracleSpec spec = {"#321",
                                                kExactLocalBodySpaceRequest,
                                                "body-space.example",
                                                "hello world",
                                                kExactLocalBodySpaceResponseNormalized,
                                                "rut-nginx-321-body-space",
                                                "exact_local_body_space",
                                                11u,
                                                false};
    return capture_pinned_exact_local_body_space_order_with_spec(
        frontend_port, backend_port, temp, container_name, spec, exact_first, observation, error);
}

static bool run_pinned_exact_local_body_space_oracle(
    const std::string& container_prefix,
    ExactLocalBodySpaceOracleObservation& exact_first,
    ExactLocalBodySpaceOracleObservation& root_first,
    std::string& error) {
    u16 exact_frontend_port = 0;
    u16 exact_backend_port = 0;
    u16 root_frontend_port = 0;
    u16 root_backend_port = 0;
    bool ports_unique = false;
    for (int attempt = 0; attempt < 8 && !ports_unique; attempt++) {
        if (!allocate_port(exact_frontend_port) || !allocate_port(exact_backend_port) ||
            !allocate_port(root_frontend_port) || !allocate_port(root_backend_port))
            continue;
        ports_unique =
            exact_frontend_port != exact_backend_port &&
            exact_frontend_port != root_frontend_port && exact_frontend_port != root_backend_port &&
            exact_backend_port != root_frontend_port && exact_backend_port != root_backend_port &&
            root_frontend_port != root_backend_port;
    }
    if (!ports_unique) {
        error = "#321 could not allocate four distinct declaration-order ports";
        return false;
    }

    TempDir exact_temp;
    TempDir root_temp;
    if (!exact_temp.create() || !root_temp.create() ||
        strcmp(exact_temp.path, root_temp.path) == 0 ||
        exact_temp.nginx_config == root_temp.nginx_config ||
        exact_temp.nginx_log == root_temp.nginx_log) {
        error = "#321 could not create independent declaration-order temp/config/log paths";
        return false;
    }
    const std::string exact_container = container_prefix + "-exact-first";
    const std::string root_container = container_prefix + "-root-first";
    if (exact_container == root_container) {
        error = "#321 declaration-order container names were not independent";
        return false;
    }
    if (!capture_pinned_exact_local_body_space_order(exact_frontend_port,
                                                     exact_backend_port,
                                                     exact_temp,
                                                     exact_container,
                                                     true,
                                                     exact_first,
                                                     error)) {
        dump_log(exact_temp.nginx_config, "#321 exact-first pinned nginx config");
        dump_log(exact_temp.nginx_log, "#321 exact-first pinned nginx log");
        return false;
    }
    if (!capture_pinned_exact_local_body_space_order(root_frontend_port,
                                                     root_backend_port,
                                                     root_temp,
                                                     root_container,
                                                     false,
                                                     root_first,
                                                     error)) {
        dump_log(root_temp.nginx_config, "#321 root-first pinned nginx config");
        dump_log(root_temp.nginx_log, "#321 root-first pinned nginx log");
        return false;
    }
    if (exact_first.temp_path == root_first.temp_path ||
        exact_first.config_path == root_first.config_path ||
        exact_first.log_path == root_first.log_path ||
        exact_first.container_name == root_first.container_name || exact_first.wire.empty() ||
        root_first.wire.empty() || exact_first.wire.data() == root_first.wire.data()) {
        error =
            "#321 declaration orders did not retain independent resources and response "
            "buffers";
        return false;
    }
    std::vector<char> exact_wire(exact_first.wire.begin(), exact_first.wire.end());
    std::vector<char> root_wire(root_first.wire.begin(), root_first.wire.end());
    if (!normalize_date(exact_wire) || !normalize_date(root_wire) || exact_wire != root_wire) {
        error = "#321 location declaration order changed the exact Date-normalized response";
        return false;
    }
    return true;
}

static bool run_pinned_exact_local_body_multiple_space_oracle(
    const std::string& container_prefix,
    ExactLocalBodySpaceOracleObservation& consecutive_exact_first,
    ExactLocalBodySpaceOracleObservation& consecutive_root_first,
    ExactLocalBodySpaceOracleObservation& separated_exact_first,
    ExactLocalBodySpaceOracleObservation& separated_root_first,
    std::string& error) {
    u16 ports[8]{};
    bool ports_unique = false;
    for (int attempt = 0; attempt < 8 && !ports_unique; attempt++) {
        ports_unique = true;
        for (u16& port : ports) {
            if (!allocate_port(port)) {
                ports_unique = false;
                break;
            }
        }
        for (size_t i = 0; ports_unique && i < 8; i++) {
            for (size_t j = i + 1u; j < 8; j++) {
                if (ports[i] == ports[j]) {
                    ports_unique = false;
                    break;
                }
            }
        }
    }
    if (!ports_unique) {
        error = "#322 could not allocate eight distinct body/order frontend/backend ports";
        return false;
    }

    TempDir consecutive_exact_temp;
    TempDir consecutive_root_temp;
    TempDir separated_exact_temp;
    TempDir separated_root_temp;
    TempDir* temps[] = {&consecutive_exact_temp,
                        &consecutive_root_temp,
                        &separated_exact_temp,
                        &separated_root_temp};
    for (TempDir* temp : temps) {
        if (!temp->create()) {
            error = "#322 could not create four independent body/order temp trees";
            return false;
        }
    }
    for (size_t i = 0; i < 4; i++) {
        for (size_t j = i + 1u; j < 4; j++) {
            if (strcmp(temps[i]->path, temps[j]->path) == 0 ||
                temps[i]->nginx_config == temps[j]->nginx_config ||
                temps[i]->nginx_log == temps[j]->nginx_log) {
                error = "#322 body/order temp, config, or log paths were not independent";
                return false;
            }
        }
    }

    const std::string containers[] = {container_prefix + "-consecutive-exact-first",
                                      container_prefix + "-consecutive-root-first",
                                      container_prefix + "-separated-exact-first",
                                      container_prefix + "-separated-root-first"};
    for (size_t i = 0; i < 4; i++) {
        for (size_t j = i + 1u; j < 4; j++) {
            if (containers[i] == containers[j]) {
                error = "#322 body/order container names were not independent";
                return false;
            }
        }
    }

    struct Side {
        const char* body_case;
        const char* body;
        u32 content_length;
        const char* expected_response;
        const char* access_prefix;
        bool exact_first;
        ExactLocalBodySpaceOracleObservation* observation;
    } sides[] = {{"consecutive",
                  "hello  world",
                  12u,
                  kExactLocalBodyConsecutiveSpaceResponseNormalized,
                  "rut-nginx-322-body-multiple-space-consecutive",
                  true,
                  &consecutive_exact_first},
                 {"consecutive",
                  "hello  world",
                  12u,
                  kExactLocalBodyConsecutiveSpaceResponseNormalized,
                  "rut-nginx-322-body-multiple-space-consecutive",
                  false,
                  &consecutive_root_first},
                 {"separated",
                  "hello world again",
                  17u,
                  kExactLocalBodySeparatedSpaceResponseNormalized,
                  "rut-nginx-322-body-multiple-space-separated",
                  true,
                  &separated_exact_first},
                 {"separated",
                  "hello world again",
                  17u,
                  kExactLocalBodySeparatedSpaceResponseNormalized,
                  "rut-nginx-322-body-multiple-space-separated",
                  false,
                  &separated_root_first}};
    for (size_t i = 0; i < 4; i++) {
        const ExactLocalBodySpaceOracleSpec spec = {"#322",
                                                    kExactLocalBodyMultipleSpaceRequest,
                                                    "multiple-body-space.example",
                                                    sides[i].body,
                                                    sides[i].expected_response,
                                                    sides[i].access_prefix,
                                                    "exact_local_body_multiple_space",
                                                    sides[i].content_length,
                                                    true};
        if (!capture_pinned_exact_local_body_space_order_with_spec(ports[i * 2u],
                                                                   ports[i * 2u + 1u],
                                                                   *temps[i],
                                                                   containers[i],
                                                                   spec,
                                                                   sides[i].exact_first,
                                                                   *sides[i].observation,
                                                                   error)) {
            dump_log(temps[i]->nginx_config, "#322 pinned nginx config");
            dump_log(temps[i]->nginx_log, "#322 pinned nginx log");
            return false;
        }
    }

    for (size_t i = 0; i < 4; i++) {
        const auto& left = *sides[i].observation;
        if (left.wire.empty()) {
            error = "#322 body/order side did not retain its response buffer";
            return false;
        }
        for (size_t j = i + 1u; j < 4; j++) {
            const auto& right = *sides[j].observation;
            if (left.temp_path == right.temp_path || left.config_path == right.config_path ||
                left.log_path == right.log_path || left.container_name == right.container_name ||
                (!right.wire.empty() && left.wire.data() == right.wire.data())) {
                error = "#322 four body/order sides did not retain independent test state";
                return false;
            }
        }
    }
    const auto same_normalized_wire = [&](const std::vector<char>& left,
                                          const std::vector<char>& right) {
        std::vector<char> normalized_left(left.begin(), left.end());
        std::vector<char> normalized_right(right.begin(), right.end());
        return normalize_date(normalized_left) && normalize_date(normalized_right) &&
               normalized_left == normalized_right;
    };
    if (!same_normalized_wire(consecutive_exact_first.wire, consecutive_root_first.wire)) {
        error = "#322 location declaration order changed the consecutive-space response";
        return false;
    }
    if (!same_normalized_wire(separated_exact_first.wire, separated_root_first.wire)) {
        error = "#322 location declaration order changed the separated-space response";
        return false;
    }
    return true;
}

static std::string make_exact_local_body_space_fragment(u16 frontend_port,
                                                        u16 backend_port,
                                                        bool exact_first) {
    const std::string exact_location = "  location = /static { return 200 \"hello world\"; }\n";
    const std::string root_location =
        "  location / { proxy_pass http://127.0.0.1:" + std::to_string(backend_port) + "; }\n";
    return "server {\n"
           "  listen " +
           std::to_string(frontend_port) + ";\n" +
           (exact_first ? exact_location + root_location : root_location + exact_location) + "}\n";
}

static std::string canonical_generated_bodyful_exact_route(const char* path, const char* body) {
    return "route exact slash_normalized \"" + std::string(path) +
           "\" { return local_response({\n"
           "  version: \"HTTP/1.1\", status: 200, reason: \"OK\", server: \"nginx/1.29.7\",\n"
           "  date: \"current\", content_type: \"text/plain\", connection: \"request\",\n"
           "  head_mode: \"suppress_body\", body: b\"" +
           std::string(body) + "\"\n}) }\n";
}

