struct RutExactIpv4Reservations {
    int frontend = -1;
    int guard = -1;
    int backend = -1;
    u16 frontend_port = 0;
    u16 backend_port = 0;

    ~RutExactIpv4Reservations() {
        if (frontend >= 0) close(frontend);
        if (guard >= 0) close(guard);
        if (backend >= 0) close(backend);
    }

    static bool bind_exact(u32 address, u16 requested_port, int& fd, u16& actual_port) {
        fd = socket(AF_INET, SOCK_STREAM | SOCK_CLOEXEC, 0);
        if (fd < 0) return false;
        sockaddr_in bind_address{};
        bind_address.sin_family = AF_INET;
        bind_address.sin_addr.s_addr = htonl(address);
        bind_address.sin_port = htons(requested_port);
        if (bind(fd, reinterpret_cast<sockaddr*>(&bind_address), sizeof(bind_address)) != 0) {
            close(fd);
            fd = -1;
            return false;
        }
        sockaddr_in observed{};
        socklen_t observed_len = sizeof(observed);
        int socket_type = 0;
        socklen_t socket_type_len = sizeof(socket_type);
        int accepting = -1;
        socklen_t accepting_len = sizeof(accepting);
        const int fd_flags = fcntl(fd, F_GETFD);
        if (getsockname(fd, reinterpret_cast<sockaddr*>(&observed), &observed_len) != 0 ||
            observed_len != sizeof(observed) || observed.sin_family != AF_INET ||
            ntohl(observed.sin_addr.s_addr) != address || ntohs(observed.sin_port) == 0u ||
            (requested_port != 0u && ntohs(observed.sin_port) != requested_port) || fd_flags < 0 ||
            (fd_flags & FD_CLOEXEC) == 0 ||
            getsockopt(fd, SOL_SOCKET, SO_TYPE, &socket_type, &socket_type_len) != 0 ||
            socket_type_len != sizeof(socket_type) || socket_type != SOCK_STREAM ||
            getsockopt(fd, SOL_SOCKET, SO_ACCEPTCONN, &accepting, &accepting_len) != 0 ||
            accepting_len != sizeof(accepting) || accepting != 0) {
            close(fd);
            fd = -1;
            return false;
        }
        actual_port = ntohs(observed.sin_port);
        return true;
    }

    bool reserve(std::string& error) {
        if (!bind_exact(0x7F000001u, 0u, frontend, frontend_port)) {
            error = "#345 failed to reserve exact 127.0.0.1 frontend";
            return false;
        }
        u16 guard_port = 0;
        if (!bind_exact(0x7F000002u, frontend_port, guard, guard_port) ||
            guard_port != frontend_port) {
            error = "#345 failed to reserve same-port 127.0.0.2 anti-wildcard guard";
            return false;
        }
        if (!bind_exact(0x7F000001u, 0u, backend, backend_port) || backend_port == frontend_port) {
            error = "#345 failed to reserve an independent exact backend";
            return false;
        }
        return true;
    }

    bool release_frontend(std::string& error) {
        if (frontend < 0 || close(frontend) != 0) {
            error = "#345 exact frontend handoff close failed";
            return false;
        }
        frontend = -1;
        return validate_exact_loopback_guard_fd(guard, frontend_port, error);
    }

    bool reacquire_frontend(std::string& error) {
        if (frontend >= 0) {
            error = "#345 exact frontend was already reserved";
            return false;
        }
        u16 actual = 0;
        if (!bind_exact(0x7F000001u, frontend_port, frontend, actual) || actual != frontend_port ||
            !validate_exact_loopback_guard_fd(guard, frontend_port, error)) {
            if (error.empty()) error = "#345 failed to reacquire exact frontend after mutation";
            return false;
        }
        return true;
    }
};

static bool validate_rut_exact_ipv4_source(const std::string& source,
                                           u16 frontend_port,
                                           u16 backend_port,
                                           bool wildcard,
                                           std::string& error) {
    const std::string listener = wildcard
                                     ? "listen :" + std::to_string(frontend_port) + "\n"
                                     : "listen 127.0.0.1:" + std::to_string(frontend_port) + "\n";
    const std::string other_listener =
        wildcard ? "listen 127.0.0.1:" + std::to_string(frontend_port) + "\n"
                 : "listen :" + std::to_string(frontend_port) + "\n";
    const std::string upstream =
        "upstream exact_backend at \"127.0.0.1:" + std::to_string(backend_port) + "\"\n";
    if (source.rfind(listener, 0u) != 0u || count_text(source, listener) != 1u ||
        source.find(other_listener) != std::string::npos ||
        wildcard_listen_source_declarations(source, "listen") != 1u ||
        count_text(source, upstream) != 1u ||
        wildcard_listen_source_declarations(source, "upstream") != 1u ||
        count_text(source, "route GET \"/\" {\n") != 1u ||
        wildcard_listen_source_declarations(source, "route") != 1u ||
        count_text(source, "return forward(exact_backend,") != 1u ||
        source.find("127.0.0.2") != std::string::npos ||
        source.find("0.0.0.0") != std::string::npos || source.find("*:") != std::string::npos ||
        source.find("nginx") != std::string::npos ||
        source.find("converter") != std::string::npos ||
        source.find("workaround") != std::string::npos ||
        source.find("bind_address") != std::string::npos ||
        source.find("local_address") != std::string::npos) {
        error = "#345 ordinary RUT source inventory/address scope was not exact";
        return false;
    }
    return true;
}

static bool validate_rut_exact_ipv4_runtime_log(const std::string& contents,
                                                const std::string& source_path,
                                                u16 frontend_port,
                                                std::string& error) {
    std::vector<std::string> records;
    if (!split_exact_complete_log(contents, 5u, "#345 RUT exact IPv4 runtime log", records, error))
        return false;
    const std::string loaded = "Loaded program: " + source_path + " (opt O2)";
    const std::string listening =
        "Listening on port " + std::to_string(frontend_port) + " with 1 shard(s)";
    if (records[0] != loaded || records[1] != "Backend: io_uring" || records[2] != listening ||
        records[3] != "Draining connections (0s)..." || records[4] != "Shutdown complete.") {
        error = "#345 runtime log was not the exact ordered five-line public lifecycle";
        return false;
    }
    return true;
}

static bool validate_rut_exact_ipv4_access(const std::string& contents,
                                           size_t downstream_request_size,
                                           size_t downstream_response_wire_size,
                                           std::string& error) {
    std::vector<std::string> records;
    if (!split_exact_complete_log(contents, 1u, "#345 RUT exact IPv4 access log", records, error))
        return false;
    std::vector<std::string> fields;
    if (!split_space_fields(records[0], fields) || fields.size() != 11u ||
        !exact_log_timestamp(fields[0]) || fields[1] != "GET" || fields[2] != "/scope?q=1" ||
        fields[3] != "200" || !decimal_field_equals(fields[3], 200u) ||
        !exact_log_duration(fields[4]) ||
        !decimal_field_equals(fields[5], downstream_request_size) ||
        !decimal_field_equals(fields[6], downstream_response_wire_size) ||
        fields[7] != "127.0.0.1" || fields[8] != "exact_backend" ||
        !exact_log_duration(fields[9]) || fields[10] != "s=0") {
        error =
            "#345 access record lost raw target/status/original downstream request size/"
            "downstream response size/upstream/outcome evidence";
        return false;
    }
    return true;
}

static bool run_rut_exact_ipv4_production_self_checks(std::string& error) {
    static constexpr u16 kFrontend = 54321u;
    static constexpr u16 kBackend = 54322u;
    const std::string exact =
        "listen 127.0.0.1:54321\n"
        "upstream exact_backend at \"127.0.0.1:54322\"\n"
        "route GET \"/\" {\n  return forward(exact_backend,\n"
        "    request_policy: { version: \"HTTP/1.1\", host: \"upstream\", connection: \"omit\",\n"
        "      strip_headers: [\"Connection\"] },\n"
        "    response_policy: { version: \"HTTP/1.1\", framing: \"content_length\",\n"
        "      connection: \"request\", server: \"rut-stage4\", date: \"current\",\n"
        "      hide_headers: [\"Date\", \"Server\"] })\n}\n";
    if (!validate_rut_exact_ipv4_source(exact, kFrontend, kBackend, false, error)) return false;
    for (const std::pair<std::string, std::string>& mutation :
         {std::pair{std::string("listen 127.0.0.1:54321\n"), std::string("listen :54321\n")},
          std::pair{std::string("listen 127.0.0.1:54321\n"),
                    std::string("listen 127.0.0.2:54321\n")},
          std::pair{std::string("listen 127.0.0.1:54321\n"),
                    std::string("listen 127.0.0.1:54320\n")},
          std::pair{std::string("listen 127.0.0.1:54321\n"), std::string()},
          std::pair{std::string("route GET \"/\" {\n"),
                    std::string("route GET \"/\" {\nroute GET \"/\" { return 204 }\n")}}) {
        std::string candidate = exact;
        const size_t offset = candidate.find(mutation.first);
        if (offset == std::string::npos ||
            candidate.find(mutation.first, offset + mutation.first.size()) != std::string::npos) {
            error = "#345 source self-check mutation target was absent or duplicate";
            return false;
        }
        candidate.replace(offset, mutation.first.size(), mutation.second);
        std::string mutation_error;
        if (candidate == exact ||
            validate_rut_exact_ipv4_source(candidate, kFrontend, kBackend, false, mutation_error)) {
            error = "#345 source validator accepted a changed invalid address/inventory";
            return false;
        }
    }
    std::string absent_guard_error;
    if (validate_exact_loopback_guard_fd(-1, kFrontend, absent_guard_error) ||
        absent_guard_error.empty()) {
        error = "#345 guard validator accepted a released/absent reservation";
        return false;
    }
    const std::string runtime =
        "Loaded program: /tmp/stage4.rut (opt O2)\nBackend: io_uring\n"
        "Listening on port 54321 with 1 shard(s)\n"
        "Draining connections (0s)...\nShutdown complete.\n";
    if (!validate_rut_exact_ipv4_runtime_log(runtime, "/tmp/stage4.rut", kFrontend, error))
        return false;
    for (const std::string& mutation :
         {"Loaded program: /tmp/other.rut (opt O2)\nBackend: io_uring\nListening on port "
          "54321 with 1 shard(s)\nDraining connections (0s)...\nShutdown complete.\n",
          "Loaded program: /tmp/stage4.rut (opt O2)\nBackend: epoll\nListening on port "
          "54321 with 1 shard(s)\nDraining connections (0s)...\nShutdown complete.\n",
          "Loaded program: /tmp/stage4.rut (opt O2)\nBackend: io_uring\nListening on port "
          "54322 with 1 shard(s)\nDraining connections (0s)...\nShutdown complete.\n",
          "Loaded program: /tmp/stage4.rut (opt O2)\nBackend: io_uring\nListening on port "
          "54321 with 1 shard(s)\nShutdown complete.\n",
          "Loaded program: /tmp/stage4.rut (opt O2)\nBackend: io_uring\nListening on port "
          "54321 with 1 shard(s)\nDraining connections (0s)...\n",
          "Loaded program: /tmp/stage4.rut (opt O2)\nBackend: io_uring\nListening on port "
          "54321 with 1 shard(s)\nDraining connections (1s)...\nShutdown complete.\n",
          "Loaded program: /tmp/stage4.rut (opt O2)\nBackend: io_uring\nListening on port "
          "54321 with 1 shard(s)\nDraining connections (0s)...\nShutdown incomplete.\n",
          "Loaded program: /tmp/stage4.rut (opt O2)\nBackend: io_uring\nListening on port "
          "54321 with 1 shard(s)\nDraining connections (0s)...\nDraining connections (0s)...\n"
          "Shutdown complete.\n",
          "Loaded program: /tmp/stage4.rut (opt O2)\nBackend: io_uring\nListening on port "
          "54321 with 1 shard(s)\nDraining connections (0s)...\nShutdown complete.\n"
          "Shutdown complete.\n",
          "Loaded program: /tmp/stage4.rut (opt O2)\nBackend: io_uring\nListening on port "
          "54321 with 1 shard(s)\nShutdown complete.\nDraining connections (0s)...\n"}) {
        std::string mutation_error;
        if (validate_rut_exact_ipv4_runtime_log(
                mutation, "/tmp/stage4.rut", kFrontend, mutation_error)) {
            error = "#345 runtime-log validator accepted a missing public evidence record";
            return false;
        }
    }
    const std::string access =
        "2026-08-28T01:02:03.456Z GET /scope?q=1 200 7us 77 112 127.0.0.1 "
        "exact_backend 3us s=0\n";
    if (!validate_rut_exact_ipv4_access(access, 77u, 112u, error)) return false;
    for (const std::string& mutation :
         {access + access,
          std::string("2026-08-28T01:02:03.456Z GET /other 200 7us 77 112 127.0.0.1 "
                      "exact_backend 3us s=0\n"),
          std::string("2026-08-28T01:02:03.456Z GET /scope?q=1 200 7us 77 112 127.0.0.2 "
                      "exact_backend 3us s=0\n"),
          std::string("2026-08-28T01:02:03.456Z GET /scope?q=1 502 7us 77 112 127.0.0.1 "
                      "exact_backend 3us s=0\n"),
          std::string("2026-08-28T01:02:03.456Z GET /scope?q=1 200 7us 78 112 127.0.0.1 "
                      "exact_backend 3us s=0\n"),
          std::string("2026-08-28T01:02:03.456Z GET /scope?q=1 200 7us 77 113 127.0.0.1 "
                      "exact_backend 3us s=0\n"),
          std::string("2026-08-28T01:02:03.456Z GET /scope?q=1 200 7us 77 112 127.0.0.1 "
                      "other 3us s=0\n")}) {
        std::string mutation_error;
        if (validate_rut_exact_ipv4_access(mutation, 77u, 112u, mutation_error)) {
            error = "#345 access validator accepted duplicate or mutated evidence";
            return false;
        }
    }
    return true;
}

static bool run_rut_exact_ipv4_listener_production(TempDir& temp,
                                                   const char* rut_path,
                                                   std::string& error) {
    if (rut_path == nullptr || rut_path[0] != '/' || access(rut_path, X_OK) != 0) {
        error = "#345 public capability evidence requires an executable absolute RUT path";
        return false;
    }
    RutExactIpv4Reservations reservations;
    if (!reservations.reserve(error)) return false;
    const u16 frontend_port = reservations.frontend_port;
    const u16 backend_port = reservations.backend_port;
    const auto make_source = [&](bool wildcard) {
        return std::string(wildcard ? "listen :" : "listen 127.0.0.1:") +
               std::to_string(frontend_port) + "\n" +
               "upstream exact_backend at \"127.0.0.1:" + std::to_string(backend_port) + "\"\n" +
               R"rut(route GET "/" {
  return forward(exact_backend,
    request_policy: { version: "HTTP/1.1", host: "upstream", connection: "omit",
      strip_headers: ["Connection", "Keep-Alive", "TE", "Expect", "Upgrade"] },
    response_policy: { version: "HTTP/1.1", framing: "content_length",
      connection: "request", server: "rut-stage4", date: "current",
      hide_headers: ["Date", "Server"] })
}
)rut";
    };
    const std::string exact_source = make_source(false);
    const std::string wildcard_source = make_source(true);
    if (exact_source == wildcard_source ||
        !validate_rut_exact_ipv4_source(exact_source, frontend_port, backend_port, false, error) ||
        !validate_rut_exact_ipv4_source(wildcard_source, frontend_port, backend_port, true, error))
        return false;
    const std::string exact_listener = "listen 127.0.0.1:" + std::to_string(frontend_port) + "\n";
    const std::string wildcard_listener = "listen :" + std::to_string(frontend_port) + "\n";
    std::string listener_only_mutation = exact_source;
    const size_t listener_offset = listener_only_mutation.find(exact_listener);
    if (listener_offset == std::string::npos ||
        listener_only_mutation.find(exact_listener, listener_offset + exact_listener.size()) !=
            std::string::npos) {
        error = "#345 exact source lacked one unique listener mutation target";
        return false;
    }
    listener_only_mutation.replace(listener_offset, exact_listener.size(), wildcard_listener);
    if (listener_only_mutation != wildcard_source) {
        error = "#345 wildcard mutation changed bytes beyond the listener address";
        return false;
    }

    struct ExtraPaths {
        std::string runtime;
        std::string access;
        ~ExtraPaths() {
            unlink(runtime.c_str());
            unlink(access.c_str());
        }
    } wildcard_paths{std::string(temp.path) + "/wildcard-runtime.log",
                     std::string(temp.path) + "/wildcard-access.log"};

    struct RecorderGuard {
        Recorder* recorder = nullptr;
        ~RecorderGuard() {
            if (recorder != nullptr) recorder->stop();
        }
    } recorder_guard;
    Recorder backend;
    recorder_guard.recorder = &backend;
    backend.observe_extra_requests_until_stop = true;
    close(reservations.backend);
    reservations.backend = -1;
    if (!backend.setup(backend_port, 1u, kBackendResponse, sizeof(kBackendResponse) - 1u)) {
        error = "#345 recorder could not bind the held backend endpoint";
        return false;
    }
    const auto recorder_live = [&]() {
        return backend.running.load(std::memory_order_acquire) &&
               backend.thread_alive.load(std::memory_order_acquire) &&
               !backend.listener_failed.load(std::memory_order_acquire);
    };
    const auto recorder_deadline = std::chrono::steady_clock::now() + std::chrono::seconds(2);
    while (!recorder_live() && std::chrono::steady_clock::now() < recorder_deadline) usleep(1000);
    if (!recorder_live()) {
        error = "#345 recorder failed before the public mutation gate";
        return false;
    }
    const auto exact_counts = [&](u32 expected,
                                  std::chrono::milliseconds duration,
                                  Child* monitored_child) {
        const auto deadline = std::chrono::steady_clock::now() + duration;
        for (;;) {
            if (monitored_child != nullptr && poll_child(*monitored_child)) return false;
            if (!recorder_live() || backend.accepted.load(std::memory_order_acquire) != expected ||
                backend.requests.load(std::memory_order_acquire) != expected ||
                backend.response_send_all_calls.load(std::memory_order_acquire) != expected)
                return false;
            if (std::chrono::steady_clock::now() >= deadline) return true;
            usleep(5000);
        }
    };

    if (!write_file(temp.source, wildcard_source.data(), wildcard_source.size()) ||
        !reservations.release_frontend(error)) {
        if (error.empty()) error = "#345 failed to write/handoff the wildcard mutation";
        return false;
    }
    ChildGuard wildcard_child;
    if (!spawn_child({rut_path,
                      temp.source,
                      std::to_string(frontend_port),
                      "--shards",
                      "1",
                      "--no-pin",
                      "--drain",
                      "0",
                      "--access-log",
                      wildcard_paths.access},
                     wildcard_paths.runtime,
                     wildcard_child.child) ||
        !wait_child(wildcard_child.child, 3000)) {
        error = "#345 wildcard mutation did not fail within the bounded startup window";
        return false;
    }
    if (!wildcard_child.child.status_valid || !WIFEXITED(wildcard_child.child.status) ||
        WEXITSTATUS(wildcard_child.child.status) == 0) {
        error = "#345 wildcard mutation did not exit with a startup failure";
        return false;
    }
    wildcard_child.child.pid = -1;
    std::string wildcard_log;
    if (!read_exact_return204_log(
            wildcard_paths.runtime, "#345 wildcard mutation runtime log", wildcard_log, error) ||
        count_text(wildcard_log, "Loaded program: " + temp.source + " (opt O2)\n") != 1u ||
        count_text(wildcard_log, "Backend: io_uring\n") != 1u ||
        count_text(wildcard_log, "Failed to create listen socket for shard 0") != 1u ||
        wildcard_log.find("errno=98") == std::string::npos ||
        wildcard_log.find("Listening on port ") != std::string::npos ||
        !validate_exact_loopback_guard_fd(reservations.guard, frontend_port, error) ||
        !exact_loopback_negative_connect_fails(frontend_port, error) ||
        !exact_counts(0u, std::chrono::milliseconds(150), nullptr)) {
        if (error.empty())
            error = "#345 wildcard public mutation lacked exact bind-failure evidence";
        return false;
    }
    std::string wildcard_access;
    const int wildcard_access_fd = open(wildcard_paths.access.c_str(), O_RDONLY);
    if (wildcard_access_fd >= 0) {
        char buffer[256];
        for (;;) {
            const ssize_t count = read(wildcard_access_fd, buffer, sizeof(buffer));
            if (count > 0) {
                wildcard_access.append(buffer, static_cast<size_t>(count));
                continue;
            }
            if (count < 0 && errno == EINTR) continue;
            if (count < 0) {
                close(wildcard_access_fd);
                error = "#345 wildcard access log read failed";
                return false;
            }
            break;
        }
        close(wildcard_access_fd);
    } else if (errno != ENOENT) {
        error = "#345 wildcard access log could not be checked";
        return false;
    }
    if (!wildcard_access.empty() || !reservations.reacquire_frontend(error) ||
        !write_file(temp.source, exact_source.data(), exact_source.size())) {
        if (error.empty()) error = "#345 wildcard mutation produced access or exact restore failed";
        return false;
    }

    ChildGuard runtime;
    if (!reservations.release_frontend(error) ||
        !spawn_child({rut_path,
                      temp.source,
                      std::to_string(frontend_port),
                      "--shards",
                      "1",
                      "--no-pin",
                      "--drain",
                      "0",
                      "--access-log",
                      temp.rut_access_log},
                     temp.rut_log,
                     runtime.child) ||
        !wait_ready(frontend_port, runtime.child, error)) {
        if (error.empty()) error = "#345 exact public RUT failed before readiness";
        return false;
    }
    const std::string loaded = "Loaded program: " + temp.source + " (opt O2)\n";
    const std::string listener =
        "Listening on port " + std::to_string(frontend_port) + " with 1 shard(s)\n";
    const auto log_deadline = std::chrono::steady_clock::now() + std::chrono::seconds(2);
    while ((!log_contains(temp.rut_log, loaded.c_str()) ||
            !log_contains(temp.rut_log, "Backend: io_uring\n") ||
            !log_contains(temp.rut_log, listener.c_str())) &&
           std::chrono::steady_clock::now() < log_deadline) {
        if (poll_child(runtime.child)) {
            error = "#345 exact public RUT exited before load/io_uring/listener proof";
            return false;
        }
        usleep(1000);
    }
    if (poll_child(runtime.child) ||
        !validate_exact_loopback_guard_fd(reservations.guard, frontend_port, error) ||
        !exact_loopback_negative_connect_fails(frontend_port, error) ||
        !exact_counts(0u, std::chrono::milliseconds(150), &runtime.child)) {
        if (error.empty()) error = "#345 pre-request address scope or zero episode failed";
        return false;
    }
    static constexpr char kDestroyedSource[] = "invalid-after-owned-exact-listener-load\n";
    if (!write_file(temp.source, kDestroyedSource, sizeof(kDestroyedSource) - 1u)) {
        error = "#345 failed to overwrite source after public readiness";
        return false;
    }
    std::string destroyed_readback;
    if (!read_exact_return204_log(
            temp.source, "#345 destroyed owned source", destroyed_readback, error) ||
        destroyed_readback != kDestroyedSource) {
        error = "#345 source overwrite/readback was not exact";
        return false;
    }

    static constexpr char kRequest[] =
        "GET /scope?q=1 HTTP/1.1\r\n"
        "Host: exact-listener.example\r\n"
        "X-Stage4: owned\r\n"
        "Connection: close\r\n\r\n";
    const std::string request_text(kRequest, sizeof(kRequest) - 1u);
    if (request_text.rfind("GET /scope?q=1 HTTP/1.1\r\n", 0u) != 0u ||
        request_text.find("\r\nConnection: close\r\n") == std::string::npos ||
        request_text.find("\r\nContent-Length:") != std::string::npos ||
        request_text.find("\r\nTransfer-Encoding:") != std::string::npos ||
        request_text.rfind("\r\n\r\n") != request_text.size() - 4u) {
        error = "#345 request escaped the exact fresh bodyless explicit-close H1.1 scope";
        return false;
    }
    static constexpr char kResponseNormalized[] =
        "HTTP/1.1 200 OK\r\n"
        "Server: rut-stage4\r\n"
        "Date: XXXXXXXXXXXXXXXXXXXXXXXXXXXXX\r\n"
        "Content-Length: 2\r\n"
        "Connection: close\r\n\r\nok";
    struct ClientGuard {
        int fd = -1;
        ~ClientGuard() {
            if (fd >= 0) close(fd);
        }
    } client{connect_once(frontend_port)};
    std::vector<char> wire;
    std::string detail;
    if (client.fd < 0 || !send_all(client.fd, kRequest, sizeof(kRequest) - 1u) ||
        !read_response(client.fd, wire, detail) || !read_eof(client.fd, detail)) {
        error = "#345 exact response/zero-tail/EOF failed: " +
                (detail.empty() ? std::string("connect or send failed") : detail);
        return false;
    }
    std::vector<char> normalized = wire;
    if (!normalize_date(normalized) || normalized.size() != sizeof(kResponseNormalized) - 1u ||
        memcmp(normalized.data(), kResponseNormalized, sizeof(kResponseNormalized) - 1u) != 0) {
        error = "#345 downstream response was not the exact Date-normalized expected wire";
        return false;
    }
    const auto episode_deadline = std::chrono::steady_clock::now() + std::chrono::seconds(2);
    while (std::chrono::steady_clock::now() < episode_deadline && recorder_live() &&
           !poll_child(runtime.child)) {
        if (backend.accepted.load(std::memory_order_acquire) > 1u ||
            backend.requests.load(std::memory_order_acquire) > 1u ||
            backend.response_send_all_calls.load(std::memory_order_acquire) > 1u ||
            (backend.accepted.load(std::memory_order_acquire) == 1u &&
             backend.requests.load(std::memory_order_acquire) == 1u &&
             backend.response_send_all_calls.load(std::memory_order_acquire) == 1u))
            break;
        usleep(1000);
    }
    if (!exact_counts(1u, std::chrono::milliseconds(500), &runtime.child) ||
        !validate_exact_loopback_guard_fd(reservations.guard, frontend_port, error) ||
        !exact_loopback_negative_connect_fails(frontend_port, error) ||
        !exact_counts(1u, std::chrono::milliseconds(150), &runtime.child) ||
        !stop_child(runtime.child)) {
        if (error.empty())
            error = "#345 post-request exact address/no-retry/clean-stop proof failed";
        return false;
    }
    backend.stop();
    recorder_guard.recorder = nullptr;
    if (backend.thread_alive.load(std::memory_order_acquire) ||
        backend.listener_failed.load(std::memory_order_acquire) ||
        !complete_origin_episode_is_exact(backend) || backend.history.size() != 1u) {
        error = "#345 recorder did not settle at one complete origin episode";
        return false;
    }
    const std::string rewritten_upstream_wire =
        "GET /scope?q=1 HTTP/1.1\r\nHost: 127.0.0.1:" + std::to_string(backend_port) +
        "\r\nX-Stage4: owned\r\n\r\n";
    if (request_text.size() == rewritten_upstream_wire.size()) {
        error =
            "#345 fixture no longer distinguishes downstream access size from rebuilt upstream "
            "wire size";
        return false;
    }
    if (backend.history[0] !=
        std::vector<char>(rewritten_upstream_wire.begin(), rewritten_upstream_wire.end())) {
        error = "#345 upstream method/target/H1.1/Host/Connection wire was not exact";
        return false;
    }
    std::string runtime_contents;
    std::string access_contents;
    if (!read_exact_return204_log(
            temp.rut_log, "#345 exact RUT runtime log", runtime_contents, error) ||
        !validate_rut_exact_ipv4_runtime_log(runtime_contents, temp.source, frontend_port, error) ||
        !read_exact_return204_log(
            temp.rut_access_log, "#345 exact RUT access log", access_contents, error) ||
        !validate_rut_exact_ipv4_access(access_contents, request_text.size(), wire.size(), error))
        return false;
    return validate_exact_loopback_guard_fd(reservations.guard, frontend_port, error);
}

static std::string make_request_length_oracle_config(u16 frontend_port,
                                                     u16 backend_port,
                                                     const std::string& access_path) {
    return "error_log stderr notice;\n"
           "events {}\n"
           "http {\n"
           "  log_format compat \"$request_length\";\n"
           "  access_log " +
           access_path +
           " compat;\n"
           "  server {\n"
           "    listen 127.0.0.1:" +
           std::to_string(frontend_port) +
           ";\n"
           "    location / {\n"
           "      proxy_pass http://127.0.0.1:" +
           std::to_string(backend_port) +
           ";\n"
           "    }\n"
           "  }\n"
           "}\n";
}

static bool validate_request_length_oracle_config(const std::string& config,
                                                  u16 frontend_port,
                                                  u16 backend_port,
                                                  const std::string& access_path,
                                                  std::string& error) {
    const std::string expected =
        make_request_length_oracle_config(frontend_port, backend_port, access_path);
    if (frontend_port == 0u || backend_port < 1024u || backend_port > 9999u ||
        frontend_port == backend_port || access_path.empty() || config != expected ||
        count_text(config, "error_log ") != 1u ||
        count_text(config, "error_log stderr notice;\n") != 1u ||
        count_text(config, "events {}") != 1u || count_text(config, "http {") != 1u ||
        count_text(config, "log_format ") != 1u ||
        count_text(config, "log_format compat \"$request_length\";") != 1u ||
        count_text(config, "$request_length") != 1u || count_text(config, "$") != 1u ||
        count_text(config, "access_log ") != 1u ||
        count_text(config, "access_log " + access_path + " compat;") != 1u ||
        count_text(config, access_path) != 1u || count_text(config, "server {") != 1u ||
        count_text(config, "listen ") != 1u ||
        count_text(config, "listen 127.0.0.1:" + std::to_string(frontend_port) + ";") != 1u ||
        count_text(config, "location / {") != 1u || count_text(config, "location ") != 1u ||
        count_text(config, "proxy_pass ") != 1u ||
        count_text(config, "proxy_pass http://127.0.0.1:" + std::to_string(backend_port) + ";") !=
            1u ||
        config.find("buffer=") != std::string::npos || config.find("flush=") != std::string::npos ||
        config.find("gzip") != std::string::npos || config.find("syslog:") != std::string::npos ||
        config.find("open_log_file_cache") != std::string::npos ||
        config.find("access_log off") != std::string::npos ||
        config.find("proxy_set_header") != std::string::npos ||
        config.find("proxy_http_version") != std::string::npos ||
        config.find("include ") != std::string::npos) {
        error = "#362 config escaped the exact unbuffered request-length root-proxy inventory";
        return false;
    }
    return true;
}

static bool validate_request_length_access_bytes(const std::string& contents, std::string& error) {
    if (contents != "102\n") {
        error = "#362 access file was not exactly the downstream request length 102 plus newline";
        return false;
    }
    return true;
}

static bool read_request_length_access_file(const std::string& path,
                                            std::string& contents,
                                            std::string& error) {
    contents.clear();
    const int fd = open(path.c_str(), O_RDONLY);
    if (fd < 0) {
        if (errno == ENOENT) return true;
        error = "#362 could not open the access file";
        return false;
    }
    char bytes[32];
    for (;;) {
        const ssize_t n = read(fd, bytes, sizeof(bytes));
        if (n > 0) {
            contents.append(bytes, static_cast<size_t>(n));
            if (contents.size() > sizeof(bytes)) {
                close(fd);
                error = "#362 access file exceeded the bounded oracle size";
                return false;
            }
            continue;
        }
        if (n < 0 && errno == EINTR) continue;
        if (n < 0) {
            close(fd);
            error = "#362 access file read failed";
            return false;
        }
        break;
    }
    if (close(fd) != 0) {
        error = "#362 access file close failed";
        return false;
    }
    return true;
}

static bool run_request_length_oracle_self_checks(std::string& error) {
    const std::string request(kRequestLengthOracleClientRequest);
    if (request !=
            "GET /ledger?q=raw HTTP/1.1\r\n"
            "Host: client.example.with.a.long.name\r\n"
            "Connection: close\r\n"
            "X-Test: keep\r\n"
            "\r\n" ||
        request.size() != 102u || count_text(request, "\r\nHost:") != 1u ||
        count_text(request, "\r\nConnection: close\r\n") != 1u ||
        count_text(request, "\r\nX-Test: keep\r\n") != 1u ||
        request.find('\t') != std::string::npos ||
        request.find("\r\nContent-Length:") != std::string::npos ||
        request.find("\r\nTransfer-Encoding:") != std::string::npos ||
        request.find("\r\nExpect:") != std::string::npos ||
        request.find("\r\nUpgrade:") != std::string::npos) {
        error = "#362 request self-check escaped the exact bodyless H1.1 domain";
        return false;
    }

    std::string detail;
    if (!validate_request_length_access_bytes("102\n", detail)) {
        error = "#362 exact access self-check rejected its valid record";
        return false;
    }
    for (const char* mutation : {"", "102", "101\n", "66\n", "102\n102\n", "105\n"}) {
        detail.clear();
        if (validate_request_length_access_bytes(mutation, detail)) {
            error = "#362 access self-check accepted a semantic mutation";
            return false;
        }
    }

    static constexpr u16 kFrontendPort = 18080u;
    static constexpr u16 kBackendPort = 9000u;
    static constexpr const char* kAccessPath = "/tmp/rut-nginx-362-self/access.log";
    const std::string valid =
        make_request_length_oracle_config(kFrontendPort, kBackendPort, kAccessPath);
    detail.clear();
    if (!validate_request_length_oracle_config(
            valid, kFrontendPort, kBackendPort, kAccessPath, detail)) {
        error = "#362 config self-check rejected its valid exact inventory";
        return false;
    }
    const auto replace_once = [&](const char* from, const char* to) {
        std::string changed = valid;
        const size_t at = changed.find(from);
        if (at == std::string::npos || changed.find(from, at + strlen(from)) != std::string::npos)
            return std::string{};
        changed.replace(at, strlen(from), to);
        return changed;
    };
    const std::vector<std::string> mutations = {
        replace_once("$request_length", "$bytes_sent"),
        replace_once("\"$request_length\"", "\"$request_length $status\""),
        replace_once(" compat;\n  server", " compat buffer=32k;\n  server"),
        replace_once(" compat;\n  server", " compat flush=1s;\n  server"),
        replace_once("access_log ", "access_log syslog:server=127.0.0.1 "),
        valid + "gzip on;\n",
        valid + "log_format adjacent \"$request_length\";\n",
        valid + "access_log /tmp/adjacent.log compat;\n",
        valid + "server { listen 127.0.0.1:18081; }\n",
        valid + "location /adjacent { proxy_pass http://127.0.0.1:9000; }\n",
    };
    for (const auto& mutation : mutations) {
        if (mutation.empty()) {
            error = "#362 config self-check could not construct a mutation";
            return false;
        }
        detail.clear();
        if (validate_request_length_oracle_config(
                mutation, kFrontendPort, kBackendPort, kAccessPath, detail)) {
            error = "#362 config self-check accepted an adjacent directive/option mutation";
            return false;
        }
    }
    return true;
}

static bool validate_request_length_split_header(const std::string& first,
                                                 const std::string& second,
                                                 std::chrono::milliseconds quiet_elapsed,
                                                 bool nginx_live,
                                                 bool recorder_live,
                                                 u32 accepted,
                                                 u32 requests,
                                                 u32 response_sends,
                                                 bool access_quiet,
                                                 bool client_quiet,
                                                 std::string& error) {
    const std::string exact_first(kRequestLengthSplitHeaderFirstSend);
    const std::string exact_second(kRequestLengthSplitHeaderSecondSend);
    const std::string combined = first + second;
    const std::vector<char> first_bytes(first.begin(), first.end());
    const std::vector<char> combined_bytes(combined.begin(), combined.end());
    if (first.empty() || second.empty() || first != exact_first || second != exact_second ||
        first.size() != 45u || second.size() != 57u ||
        first.find("\r\n\r\n") != std::string::npos || header_end(first_bytes) != 0u ||
        first.rfind("client.exam") != first.size() - strlen("client.exam") ||
        second.rfind("ple.with.a.long.name\r\n", 0u) != 0u ||
        combined != kRequestLengthOracleClientRequest || combined.size() != 102u ||
        header_end(combined_bytes) != combined.size() ||
        quiet_elapsed < std::chrono::milliseconds(500) || !nginx_live || !recorder_live ||
        accepted != 0u || requests != 0u || response_sends != 0u || !access_quiet ||
        !client_quiet) {
        error = "#370 split escaped exact 45/57 incomplete-header bytes or quiet witnesses";
        return false;
    }
    return true;
}

static bool run_request_length_split_header_self_checks(std::string& error) {
    const std::string first(kRequestLengthSplitHeaderFirstSend);
    const std::string second(kRequestLengthSplitHeaderSecondSend);
    const std::string combined = first + second;
    if (!validate_request_length_split_header(first,
                                              second,
                                              std::chrono::milliseconds(500),
                                              true,
                                              true,
                                              0u,
                                              0u,
                                              0u,
                                              true,
                                              true,
                                              error))
        return false;

    std::vector<std::pair<std::string, std::string>> mutations = {
        {combined.substr(0u, 44u), combined.substr(44u)},  // 44/58
        {combined.substr(0u, 46u), combined.substr(46u)},  // 46/56
        {combined.substr(0u, 67u), combined.substr(67u)},  // complete Host-line boundary
        {second, first},
        {first + second.substr(0u, 1u), second},  // overlap
        {first, second.substr(1u)},               // omission
        {first, second + second},                 // duplicate suffix
        {first, second + "x"},                    // extra byte
        {first, second + "GET /successor HTTP/1.1\r\nHost: successor\r\n\r\n"},
        {first, ""},     // empty suffix
        {combined, ""},  // complete prefix
        {combined, second},
        {first.substr(0u, 41u) + "\r\n\r\n", second},  // prefix terminator
    };
    std::string changed_first = first;
    changed_first[0] = 'P';
    mutations.push_back({changed_first, second});
    std::string changed_second = second;
    changed_second[0] = 'X';
    mutations.push_back({first, changed_second});
    for (const auto& mutation : mutations) {
        std::string detail;
        if (validate_request_length_split_header(mutation.first,
                                                 mutation.second,
                                                 std::chrono::milliseconds(500),
                                                 true,
                                                 true,
                                                 0u,
                                                 0u,
                                                 0u,
                                                 true,
                                                 true,
                                                 detail)) {
            error = "#370 split self-check accepted a boundary/order/byte mutation";
            return false;
        }
    }

    struct QuietEvidence {
        bool nginx_live;
        bool recorder_live;
        u32 accepted;
        u32 requests;
        u32 sends;
        bool access_quiet;
        bool client_quiet;
    };
    const QuietEvidence invalid_evidence[] = {
        {false, true, 0u, 0u, 0u, true, true},
        {true, false, 0u, 0u, 0u, true, true},
        {true, true, 1u, 0u, 0u, true, true},
        {true, true, 0u, 1u, 0u, true, true},
        {true, true, 0u, 0u, 1u, true, true},
        {true, true, 0u, 0u, 0u, false, true},
        {true, true, 0u, 0u, 0u, true, false},
    };
    for (const auto& evidence : invalid_evidence) {
        std::string detail;
        if (validate_request_length_split_header(first,
                                                 second,
                                                 std::chrono::milliseconds(500),
                                                 evidence.nginx_live,
                                                 evidence.recorder_live,
                                                 evidence.accepted,
                                                 evidence.requests,
                                                 evidence.sends,
                                                 evidence.access_quiet,
                                                 evidence.client_quiet,
                                                 detail)) {
            error = "#370 split self-check accepted a false final quiet witness";
            return false;
        }
    }
    std::string detail;
    if (validate_request_length_split_header(first,
                                             second,
                                             std::chrono::milliseconds(499),
                                             true,
                                             true,
                                             0u,
                                             0u,
                                             0u,
                                             true,
                                             true,
                                             detail)) {
        error = "#370 split self-check accepted a shortened quiet window";
        return false;
    }
    return true;
}

static bool run_pinned_request_length_oracle(TempDir& temp,
                                             const std::string& container_name,
                                             std::string& error) {
    HeldLoopbackPorts reservations;
    u16 frontend_port = 0u;
    u16 backend_port = 0u;
    if (!reservations.reserve(0u, frontend_port) ||
        !reservations.reserve_four_digit(1u, backend_port) || frontend_port == backend_port ||
        !validate_held_loopback_port(
            reservations.fds[0], frontend_port, "#362 frontend handoff", error) ||
        !validate_held_loopback_port(
            reservations.fds[1], backend_port, "#362 backend handoff", error)) {
        if (error.empty()) error = "#362 could not hold distinct frontend/P4 backend ports";
        return false;
    }

    const std::string config =
        make_request_length_oracle_config(frontend_port, backend_port, temp.nginx_access_log);
    if (!validate_request_length_oracle_config(
            config, frontend_port, backend_port, temp.nginx_access_log, error) ||
        !write_file(temp.nginx_config, config.data(), config.size())) {
        if (error.empty()) error = "#362 could not persist its exact nginx config";
        return false;
    }

    struct RecorderGuard {
        Recorder* recorder;
        ~RecorderGuard() {
            if (recorder != nullptr) recorder->stop();
        }
    };
    Recorder backend;
    RecorderGuard backend_guard{&backend};
    backend.observe_extra_requests_until_stop = true;
    if (!handoff_held_loopback_port(
            &reservations.fds[1], backend_port, "#362 Recorder bind", error) ||
        !backend.setup(backend_port, 1u, kBackendResponse, sizeof(kBackendResponse) - 1u)) {
        if (error.empty()) error = "#362 Recorder could not bind the held P4 backend port";
        return false;
    }
    const auto recorder_ready_deadline = std::chrono::steady_clock::now() + std::chrono::seconds(2);
    while ((!backend.running.load(std::memory_order_acquire) ||
            !backend.thread_alive.load(std::memory_order_acquire)) &&
           std::chrono::steady_clock::now() < recorder_ready_deadline) {
        if (backend.listener_failed.load(std::memory_order_acquire)) break;
        usleep(1000);
    }
    if (!backend.running.load(std::memory_order_acquire) ||
        !backend.thread_alive.load(std::memory_order_acquire) ||
        backend.listener_failed.load(std::memory_order_acquire)) {
        error = "#362 Recorder was not live before frontend handoff";
        return false;
    }

    ChildGuard nginx;
    DockerGuard docker(container_name);
    if (!handoff_held_loopback_port(
            &reservations.fds[0], frontend_port, "#362 pinned nginx bind", error) ||
        !spawn_child({"docker",
                      "run",
                      "--pull=never",
                      "--network",
                      "host",
                      "--name",
                      container_name,
                      "-v",
                      temp.nginx_config + ":/etc/nginx/nginx.conf:ro",
                      "-v",
                      std::string(temp.path) + ":" + temp.path,
                      kNginxImage,
                      "nginx",
                      "-g",
                      "daemon off;"},
                     temp.nginx_log,
                     nginx.child) ||
        !wait_ready(frontend_port, nginx.child, error)) {
        if (error.empty()) error = "#362 pinned nginx failed before readiness";
        return false;
    }

    const auto live_with_counts = [&](u32 expected) {
        return !poll_child(nginx.child) && backend.running.load(std::memory_order_acquire) &&
               backend.thread_alive.load(std::memory_order_acquire) &&
               !backend.listener_failed.load(std::memory_order_acquire) &&
               backend.accepted.load(std::memory_order_acquire) == expected &&
               backend.requests.load(std::memory_order_acquire) == expected &&
               backend.response_send_all_calls.load(std::memory_order_acquire) == expected;
    };
    const auto quiet_deadline = std::chrono::steady_clock::now() + std::chrono::milliseconds(150);
    while (std::chrono::steady_clock::now() < quiet_deadline) {
        std::string access;
        if (!live_with_counts(0u) ||
            !read_request_length_access_file(temp.nginx_access_log, access, error) ||
            !access.empty()) {
            if (error.empty())
                error = "#362 pre-request window was not live and access/upstream quiet";
            return false;
        }
        usleep(5000);
    }

    struct ClientGuard {
        int fd = -1;
        ~ClientGuard() {
            if (fd >= 0) close(fd);
        }
    } client;
    client.fd = connect_once(frontend_port);
    std::vector<char> response;
    if (client.fd < 0 ||
        !send_all(client.fd,
                  kRequestLengthOracleClientRequest,
                  sizeof(kRequestLengthOracleClientRequest) - 1u) ||
        !read_response(client.fd, response, error) || !read_eof(client.fd, error) ||
        !validate_exact_normalized_response(response, kSuccessResponseNormalized, error)) {
        if (error.empty()) error = "#362 exact client request/response episode failed";
        return false;
    }
    close(client.fd);
    client.fd = -1;
    if (!wait_for_live_complete_origin_episode(backend, nginx.child, "#362 pinned nginx", error))
        return false;

    const std::string expected_upstream =
        "GET /ledger?q=raw HTTP/1.1\r\nHost: 127.0.0.1:" + std::to_string(backend_port) +
        "\r\nX-Test: keep\r\n\r\n";
    const std::vector<char> expected_upstream_wire(expected_upstream.begin(),
                                                   expected_upstream.end());
    const std::string actual_upstream =
        backend.history.size() == 1u
            ? std::string(backend.history[0].begin(), backend.history[0].end())
            : std::string{};
    if (backend_port < 1024u || backend_port > 9999u || expected_upstream.size() != 66u ||
        sizeof(kRequestLengthOracleClientRequest) - 1u == expected_upstream.size() ||
        backend.history.size() != 1u || backend.history[0] != expected_upstream_wire ||
        count_text(actual_upstream, "Host: 127.0.0.1:") != 1u ||
        count_text(actual_upstream, "X-Test: keep\r\n") != 1u ||
        actual_upstream.find("client.example") != std::string::npos ||
        actual_upstream.find("Connection:") != std::string::npos ||
        actual_upstream.find('\t') != std::string::npos) {
        if (!backend.history.empty()) dump_wire("#362 actual backend wire", backend.history[0]);
        error =
            "#362 backend wire was not exact 66-byte Host-rebuilt canonical request "
            "(actual size " +
            std::to_string(backend.history.empty() ? 0u : backend.history[0].size()) + ")";
        return false;
    }

    static constexpr char kExpectedAccess[] = "102\n";
    static_assert(sizeof(kExpectedAccess) - 1u == 4u);
    const auto access_deadline = std::chrono::steady_clock::now() + std::chrono::seconds(2);
    for (;;) {
        std::string access;
        if (!live_with_counts(1u) ||
            !read_request_length_access_file(temp.nginx_access_log, access, error)) {
            if (error.empty()) error = "#362 process/Recorder failed while awaiting live access";
            return false;
        }
        if (access.size() > sizeof(kExpectedAccess) - 1u ||
            memcmp(kExpectedAccess, access.data(), access.size()) != 0) {
            error = "#362 live access bytes were not a prefix of exact downstream value 102";
            return false;
        }
        if (access.size() == sizeof(kExpectedAccess) - 1u) break;
        if (std::chrono::steady_clock::now() >= access_deadline) {
            error = "#362 live access record did not become visible before shutdown";
            return false;
        }
        usleep(1000);
    }

    const auto stable_deadline = std::chrono::steady_clock::now() + std::chrono::milliseconds(500);
    while (std::chrono::steady_clock::now() < stable_deadline) {
        std::string access;
        if (!live_with_counts(1u) ||
            !read_request_length_access_file(temp.nginx_access_log, access, error) ||
            !validate_request_length_access_bytes(access, error)) {
            if (error.empty()) error = "#362 live access/backend evidence was not stable";
            return false;
        }
        usleep(5000);
    }

    if (!stop_child(nginx.child) || !docker.remove()) {
        error = "#362 pinned nginx did not stop and remove cleanly";
        return false;
    }
    backend.stop();
    backend_guard.recorder = nullptr;
    std::string final_access;
    if (backend.thread_alive.load(std::memory_order_acquire) ||
        backend.listener_failed.load(std::memory_order_acquire) ||
        !complete_origin_episode_is_exact(backend) || backend.history.size() != 1u ||
        backend.history[0] != expected_upstream_wire ||
        !read_request_length_access_file(temp.nginx_access_log, final_access, error) ||
        !validate_request_length_access_bytes(final_access, error)) {
        if (error.empty()) error = "#362 final recorder/access evidence was not exact";
        return false;
    }
    for (const char* severity : {"[warn]", "[error]", "[crit]", "[alert]", "[emerg]"}) {
        if (log_contains(temp.nginx_log, severity)) {
            error = "#362 nginx emitted warn-or-higher diagnostics";
            return false;
        }
    }
    return true;
}

static bool run_pinned_request_length_split_header_oracle(TempDir& temp,
                                                          const std::string& container_name,
                                                          std::string& error) {
    HeldLoopbackPorts reservations;
    u16 frontend_port = 0u;
    u16 backend_port = 0u;
    if (!reservations.reserve(0u, frontend_port) ||
        !reservations.reserve_four_digit(1u, backend_port) || frontend_port == backend_port ||
        !validate_held_loopback_port(
            reservations.fds[0], frontend_port, "#370 frontend handoff", error) ||
        !validate_held_loopback_port(
            reservations.fds[1], backend_port, "#370 backend handoff", error)) {
        if (error.empty()) error = "#370 could not hold distinct frontend/P4 backend ports";
        return false;
    }

    const std::string config =
        make_request_length_oracle_config(frontend_port, backend_port, temp.nginx_access_log);
    if (!validate_request_length_oracle_config(
            config, frontend_port, backend_port, temp.nginx_access_log, error) ||
        !write_file(temp.nginx_config, config.data(), config.size())) {
        if (error.empty()) error = "#370 could not persist the exact #362 nginx config";
        return false;
    }

    struct RecorderGuard {
        Recorder* recorder;
        ~RecorderGuard() {
            if (recorder != nullptr) recorder->stop();
        }
    };
    Recorder backend;
    RecorderGuard backend_guard{&backend};
    backend.wait_response_peer_close = true;
    backend.observe_extra_requests_until_stop = true;
    if (!handoff_held_loopback_port(
            &reservations.fds[1], backend_port, "#370 Recorder bind", error) ||
        !backend.setup(backend_port, 1u, kBackendResponse, sizeof(kBackendResponse) - 1u)) {
        if (error.empty()) error = "#370 Recorder could not bind the held P4 backend port";
        return false;
    }
    const auto recorder_ready_deadline = std::chrono::steady_clock::now() + std::chrono::seconds(2);
    while ((!backend.running.load(std::memory_order_acquire) ||
            !backend.thread_alive.load(std::memory_order_acquire)) &&
           std::chrono::steady_clock::now() < recorder_ready_deadline) {
        if (backend.listener_failed.load(std::memory_order_acquire)) break;
        usleep(1000);
    }
    if (!backend.running.load(std::memory_order_acquire) ||
        !backend.thread_alive.load(std::memory_order_acquire) ||
        backend.listener_failed.load(std::memory_order_acquire)) {
        error = "#370 Recorder was not live before frontend handoff";
        return false;
    }

    ChildGuard nginx;
    DockerGuard docker(container_name);
    if (!handoff_held_loopback_port(
            &reservations.fds[0], frontend_port, "#370 pinned nginx bind", error) ||
        !spawn_child({"docker",
                      "run",
                      "--pull=never",
                      "--network",
                      "host",
                      "--name",
                      container_name,
                      "-v",
                      temp.nginx_config + ":/etc/nginx/nginx.conf:ro",
                      "-v",
                      std::string(temp.path) + ":" + temp.path,
                      kNginxImage,
                      "nginx",
                      "-g",
                      "daemon off;"},
                     temp.nginx_log,
                     nginx.child) ||
        !wait_ready(frontend_port, nginx.child, error)) {
        if (error.empty()) error = "#370 pinned nginx failed before readiness";
        return false;
    }
    const auto nginx_live = [&]() { return !poll_child(nginx.child); };
    const auto recorder_live = [&]() {
        return backend.running.load(std::memory_order_acquire) &&
               backend.thread_alive.load(std::memory_order_acquire) &&
               !backend.listener_failed.load(std::memory_order_acquire);
    };
    const auto exact_atomic_counts = [&](u32 expected) {
        return backend.accepted.load(std::memory_order_acquire) == expected &&
               backend.requests.load(std::memory_order_acquire) == expected &&
               backend.response_send_all_calls.load(std::memory_order_acquire) == expected;
    };
    const auto pre_request_deadline =
        std::chrono::steady_clock::now() + std::chrono::milliseconds(150);
    while (std::chrono::steady_clock::now() < pre_request_deadline) {
        std::string access;
        if (!nginx_live() || !recorder_live() || !exact_atomic_counts(0u) ||
            !read_request_length_access_file(temp.nginx_access_log, access, error) ||
            !access.empty()) {
            if (error.empty()) error = "#370 pre-request state was not live and quiet";
            return false;
        }
        usleep(5000);
    }

    struct ClientGuard {
        int fd = -1;
        ~ClientGuard() {
            if (fd >= 0) close(fd);
        }
    } client{connect_once(frontend_port)};
    if (client.fd < 0 || !send_all(client.fd,
                                   kRequestLengthSplitHeaderFirstSend,
                                   sizeof(kRequestLengthSplitHeaderFirstSend) - 1u)) {
        error = "#370 client connect or exact 45-byte first application send failed";
        return false;
    }
    const auto quiet_started = std::chrono::steady_clock::now();
    const auto quiet_deadline = quiet_started + std::chrono::milliseconds(500);
    for (;;) {
        std::string access;
        if (!nginx_live() || !recorder_live() || !exact_atomic_counts(0u) ||
            !read_request_length_access_file(temp.nginx_access_log, access, error) ||
            !access.empty() || !observe_client_open_and_quiet_nonconsuming(client.fd, 25, error)) {
            if (error.empty())
                error = "#370 incomplete-header process/backend/access/client state was not quiet";
            return false;
        }
        if (std::chrono::steady_clock::now() >= quiet_deadline) break;
    }

    // The final causal snapshot is deliberately ordered access, nonblocking
    // client peek, then process/Recorder atomics last. No Recorder containers
    // are read until its thread is joined below.
    std::string final_quiet_access_bytes;
    const bool final_access_quiet =
        read_request_length_access_file(temp.nginx_access_log, final_quiet_access_bytes, error) &&
        final_quiet_access_bytes.empty();
    const bool final_client_quiet = observe_client_open_and_quiet_nonconsuming(client.fd, 0, error);
    const bool final_nginx_live = nginx_live();
    const bool final_recorder_live = recorder_live();
    const u32 final_accepted = backend.accepted.load(std::memory_order_acquire);
    const u32 final_requests = backend.requests.load(std::memory_order_acquire);
    const u32 final_response_sends =
        backend.response_send_all_calls.load(std::memory_order_acquire);
    const auto quiet_elapsed = std::chrono::duration_cast<std::chrono::milliseconds>(
        std::chrono::steady_clock::now() - quiet_started);
    if (!validate_request_length_split_header(kRequestLengthSplitHeaderFirstSend,
                                              kRequestLengthSplitHeaderSecondSend,
                                              quiet_elapsed,
                                              final_nginx_live,
                                              final_recorder_live,
                                              final_accepted,
                                              final_requests,
                                              final_response_sends,
                                              final_access_quiet,
                                              final_client_quiet,
                                              error) ||
        !send_all(client.fd,
                  kRequestLengthSplitHeaderSecondSend,
                  sizeof(kRequestLengthSplitHeaderSecondSend) - 1u)) {
        if (error.empty()) error = "#370 exact 57-byte suffix application send failed";
        return false;
    }

    std::vector<char> response;
    if (!read_response(client.fd, response, error) || !read_eof(client.fd, error) ||
        !validate_exact_normalized_response(response, kSuccessResponseNormalized, error)) {
        if (error.empty()) error = "#370 exact response/EOF episode failed";
        return false;
    }
    close(client.fd);
    client.fd = -1;
    if (!wait_for_live_complete_origin_episode(backend, nginx.child, "#370 pinned nginx", error))
        return false;
    const u64 response_sent_ns = backend.response_sent_ns.load(std::memory_order_acquire);
    const u64 response_peer_closed_ns =
        backend.response_peer_closed_ns.load(std::memory_order_acquire);
    if (!nginx_live() || !recorder_live() || !exact_atomic_counts(1u) || response_sent_ns == 0u ||
        !backend.response_peer_closed.load(std::memory_order_acquire) ||
        response_peer_closed_ns < response_sent_ns ||
        response_peer_closed_ns - response_sent_ns > 2'000'000'000ull ||
        backend.response_peer_unexpected_data.load(std::memory_order_acquire) ||
        backend.response_peer_observation_failed.load(std::memory_order_acquire)) {
        error = "#370 origin lacked prompt post-send peer-close/no-late-byte evidence";
        return false;
    }

    static constexpr char kExpectedAccess[] = "102\n";
    static_assert(sizeof(kExpectedAccess) - 1u == 4u);
    const auto access_deadline = std::chrono::steady_clock::now() + std::chrono::seconds(2);
    for (;;) {
        std::string access;
        if (!nginx_live() || !recorder_live() || !exact_atomic_counts(1u) ||
            !read_request_length_access_file(temp.nginx_access_log, access, error)) {
            if (error.empty()) error = "#370 failed while awaiting live access publication";
            return false;
        }
        if (access.size() > sizeof(kExpectedAccess) - 1u ||
            memcmp(kExpectedAccess, access.data(), access.size()) != 0) {
            error = "#370 live access bytes were not a prefix of exact downstream value 102";
            return false;
        }
        if (access.size() == sizeof(kExpectedAccess) - 1u) break;
        if (std::chrono::steady_clock::now() >= access_deadline) {
            error = "#370 live access record did not become visible before shutdown";
            return false;
        }
        usleep(1000);
    }
    const auto stable_deadline = std::chrono::steady_clock::now() + std::chrono::milliseconds(500);
    while (std::chrono::steady_clock::now() < stable_deadline) {
        std::string access;
        const u64 stable_sent_ns = backend.response_sent_ns.load(std::memory_order_acquire);
        const u64 stable_closed_ns =
            backend.response_peer_closed_ns.load(std::memory_order_acquire);
        if (!nginx_live() || !recorder_live() || !exact_atomic_counts(1u) ||
            stable_sent_ns != response_sent_ns || stable_closed_ns != response_peer_closed_ns ||
            !backend.response_peer_closed.load(std::memory_order_acquire) ||
            backend.response_peer_unexpected_data.load(std::memory_order_acquire) ||
            backend.response_peer_observation_failed.load(std::memory_order_acquire) ||
            !read_request_length_access_file(temp.nginx_access_log, access, error) ||
            !validate_request_length_access_bytes(access, error)) {
            if (error.empty()) error = "#370 live completion/access evidence was not stable";
            return false;
        }
        usleep(5000);
    }

    if (!stop_child(nginx.child) || !docker.remove()) {
        error = "#370 pinned nginx did not stop and remove cleanly";
        return false;
    }
    backend.stop();
    backend_guard.recorder = nullptr;
    const std::string expected_upstream =
        "GET /ledger?q=raw HTTP/1.1\r\nHost: 127.0.0.1:" + std::to_string(backend_port) +
        "\r\nX-Test: keep\r\n\r\n";
    const std::vector<char> expected_wire(expected_upstream.begin(), expected_upstream.end());
    std::string final_access;
    if (backend.thread_alive.load(std::memory_order_acquire) ||
        backend.listener_failed.load(std::memory_order_acquire) ||
        !complete_origin_episode_is_exact(backend) || backend.history.size() != 1u ||
        backend.request != expected_wire || backend.history[0] != expected_wire ||
        expected_upstream.size() != 66u ||
        sizeof(kRequestLengthOracleClientRequest) - 1u == expected_upstream.size() ||
        !backend.response_peer_closed.load(std::memory_order_acquire) ||
        backend.response_peer_unexpected_data.load(std::memory_order_acquire) ||
        backend.response_peer_observation_failed.load(std::memory_order_acquire) ||
        !read_request_length_access_file(temp.nginx_access_log, final_access, error) ||
        !validate_request_length_access_bytes(final_access, error)) {
        if (error.empty()) error = "#370 final Recorder/upstream/access evidence was not exact";
        return false;
    }
    for (const char* severity : {"[warn]", "[error]", "[crit]", "[alert]", "[emerg]"}) {
        if (log_contains(temp.nginx_log, severity)) {
            error = "#370 nginx emitted warn-or-higher diagnostics";
            return false;
        }
    }
    return true;
}

static bool validate_request_length_fixed_body_access(const std::string& contents,
                                                      std::string& error) {
    if (contents != "135\n") {
        error = "#367 access file was not exactly the downstream request length 135 plus newline";
        return false;
    }
    return true;
}

static bool read_request_length_fixed_body_access(const std::string& path,
                                                  std::string& contents,
                                                  std::string& error) {
    contents.clear();
    const int fd = open(path.c_str(), O_RDONLY);
    if (fd < 0) {
        if (errno == ENOENT) return true;
        error = "#367 could not open the access file";
        return false;
    }
    char bytes[32];
    for (;;) {
        const ssize_t n = read(fd, bytes, sizeof(bytes));
        if (n > 0) {
            contents.append(bytes, static_cast<size_t>(n));
            if (contents.size() > sizeof(bytes)) {
                close(fd);
                error = "#367 access file exceeded the bounded oracle size";
                return false;
            }
            continue;
        }
        if (n < 0 && errno == EINTR) continue;
        if (n < 0) {
            close(fd);
            error = "#367 access file read failed";
            return false;
        }
        break;
    }
    if (close(fd) != 0) {
        error = "#367 access file close failed";
        return false;
    }
    return true;
}

static bool validate_request_length_fixed_body_client(const std::string& request,
                                                      std::string& error) {
    const std::string exact(kRequestLengthFixedBodyClientRequest);
    const std::vector<char> bytes(request.begin(), request.end());
    const size_t end = header_end(bytes);
    if (request != exact || request.size() != 135u || end != 123u || request.size() - end != 12u ||
        request.compare(end, 12u, kRequestLengthFixedBody, 12u) != 0 ||
        count_text(request, kRequestLengthFixedBody) != 1u ||
        count_text(request, "\r\nHost:") != 1u ||
        count_text(request, "\r\nConnection: close\r\n") != 1u ||
        count_text(request, "\r\nContent-Length: 12\r\n") != 1u ||
        count_text(request, "\r\nX-Test: keep\r\n") != 1u ||
        request.find("\r\nTransfer-Encoding:") != std::string::npos ||
        request.find("\r\nExpect:") != std::string::npos ||
        request.find("\r\nUpgrade:") != std::string::npos) {
        error = "#367 client request escaped the exact fixed-Content-Length bodyful slice";
        return false;
    }
    return true;
}

static bool run_request_length_fixed_body_self_checks(std::string& error) {
    const std::string valid(kRequestLengthFixedBodyClientRequest);
    if (!validate_request_length_fixed_body_client(valid, error)) return false;
    const std::string upstream(kRequestLengthFixedBodyUpstreamP4Request);
    const std::vector<char> upstream_bytes(upstream.begin(), upstream.end());
    const size_t upstream_header_end = header_end(upstream_bytes);
    if (upstream_header_end != 87u || upstream.size() != 99u || valid.size() == upstream.size() ||
        upstream.size() - upstream_header_end != 12u ||
        upstream.compare(upstream_header_end, 12u, kRequestLengthFixedBody, 12u) != 0 ||
        count_text(upstream, kRequestLengthFixedBody) != 1u ||
        count_text(upstream, "Host: 127.0.0.1:9000\r\n") != 1u ||
        count_text(upstream, "Content-Length: 12\r\n") != 1u ||
        count_text(upstream, "X-Test: keep\r\n") != 1u ||
        upstream.find("client.example") != std::string::npos ||
        upstream.find("Connection:") != std::string::npos) {
        error = "#367 upstream-candidate self-check escaped the exact 87/99-byte shape";
        return false;
    }
    const auto replace_once = [&](const std::string& from, const std::string& to) {
        std::string changed = valid;
        const size_t at = changed.find(from);
        if (at == std::string::npos || changed.find(from, at + from.size()) != std::string::npos)
            return std::string{};
        changed.replace(at, from.size(), to);
        return changed;
    };
    const std::vector<std::string> mutations = {
        replace_once("Content-Length: 12", "Content-Length: 0"),
        replace_once("Content-Length: 12", "Content-Length: 11"),
        replace_once("Content-Length: 12", "Content-Length: 13"),
        valid.substr(0u, valid.size() - 1u),
        valid + "x",
        valid + kRequestLengthFixedBody,
        replace_once("Content-Length: 12\r\n", "Content-Length: 12\r\nContent-Length: 12\r\n"),
        replace_once("Content-Length: 12\r\n", "Content-Length: 12\r\nContent-Length: 13\r\n"),
        replace_once("Content-Length: 12\r\n", "Transfer-Encoding: chunked\r\n"),
        replace_once("X-Test: keep\r\n", "Expect: 100-continue\r\nX-Test: keep\r\n"),
        replace_once("Connection: close", "Connection: keep-alive"),
        valid + "GET /successor HTTP/1.1\r\nHost: successor\r\n\r\n",
    };
    for (const std::string& mutation : mutations) {
        std::string detail;
        if (mutation.empty() || validate_request_length_fixed_body_client(mutation, detail)) {
            error = "#367 client-request self-check accepted a framing/body mutation";
            return false;
        }
    }
    if (!validate_request_length_fixed_body_access("135\n", error)) return false;
    for (const char* mutation : {"", "135", "134\n", "99\n", "102\n", "135\n135\n"}) {
        std::string detail;
        if (validate_request_length_fixed_body_access(mutation, detail)) {
            error = "#367 access self-check accepted a downstream-size mutation";
            return false;
        }
    }
    return true;
}

static bool validate_request_length_fixed_body_split(const std::string& first,
                                                     const std::string& second,
                                                     std::chrono::milliseconds quiet_elapsed,
                                                     bool backend_quiet,
                                                     bool client_quiet,
                                                     bool access_quiet,
                                                     std::string& error) {
    const std::string exact_first(kRequestLengthFixedBodyFirstSend);
    const std::string exact_second(kRequestLengthFixedBodySecondSend);
    const std::string combined = first + second;
    std::string request_error;
    if (first != exact_first || second != exact_second || first.size() != 128u ||
        second.size() != 7u || header_end(std::vector<char>(first.begin(), first.end())) != 123u ||
        first.compare(123u, 5u, "hello", 5u) != 0 || combined.size() != 135u ||
        !validate_request_length_fixed_body_client(combined, request_error) ||
        quiet_elapsed < std::chrono::milliseconds(500) || !backend_quiet || !client_quiet ||
        !access_quiet) {
        error = "#369 split escaped exact 128/7 bytes, 500ms quiet, or pre-suffix quiet evidence";
        return false;
    }
    return true;
}

static bool run_request_length_split_fixed_body_self_checks(std::string& error) {
    const std::string first(kRequestLengthFixedBodyFirstSend);
    const std::string second(kRequestLengthFixedBodySecondSend);
    if (!validate_request_length_fixed_body_split(
            first, second, std::chrono::milliseconds(500), true, true, true, error))
        return false;

    std::vector<std::pair<std::string, std::string>> mutations;
    const std::string combined = first + second;
    mutations.push_back({combined.substr(0u, 127u), combined.substr(127u)});  // 4/8 body split
    mutations.push_back({combined.substr(0u, 129u), combined.substr(129u)});  // 6/6 body split
    mutations.push_back({second, first});
    std::string changed = first;
    changed.back() = 'X';
    mutations.push_back({changed, second});
    mutations.push_back({first + second.substr(0u, 1u), second});  // overlap
    mutations.push_back({first, second.substr(1u)});               // omission
    mutations.push_back({first, second + "x"});                    // extra
    mutations.push_back({first, second + second});                 // duplicate
    mutations.push_back({first, second + "GET /successor HTTP/1.1\r\nHost: successor\r\n\r\n"});
    for (const auto& mutation : mutations) {
        std::string detail;
        if (validate_request_length_fixed_body_split(mutation.first,
                                                     mutation.second,
                                                     std::chrono::milliseconds(500),
                                                     true,
                                                     true,
                                                     true,
                                                     detail)) {
            error = "#369 split self-check accepted a boundary/order/body mutation";
            return false;
        }
    }
    for (const auto evidence : {std::array<bool, 3>{false, true, true},
                                std::array<bool, 3>{true, false, true},
                                std::array<bool, 3>{true, true, false}}) {
        std::string detail;
        if (validate_request_length_fixed_body_split(first,
                                                     second,
                                                     std::chrono::milliseconds(500),
                                                     evidence[0],
                                                     evidence[1],
                                                     evidence[2],
                                                     detail)) {
            error = "#369 split self-check accepted premature pre-suffix activity";
            return false;
        }
    }
    std::string detail;
    if (validate_request_length_fixed_body_split(
            first, second, std::chrono::milliseconds(499), true, true, true, detail)) {
        error = "#369 split self-check accepted a shortened quiet window";
        return false;
    }
    return true;
}

static bool run_pinned_request_length_fixed_body_oracle_impl(TempDir& temp,
                                                             const std::string& container_name,
                                                             bool split_delivery,
                                                             std::string& error) {
    HeldLoopbackPorts reservations;
    u16 frontend_port = 0u;
    u16 backend_port = 0u;
    if (!reservations.reserve(0u, frontend_port) ||
        !reservations.reserve_four_digit(1u, backend_port) || frontend_port == backend_port ||
        !validate_held_loopback_port(
            reservations.fds[0], frontend_port, "#367 frontend handoff", error) ||
        !validate_held_loopback_port(
            reservations.fds[1], backend_port, "#367 backend handoff", error)) {
        if (error.empty()) error = "#367 could not hold distinct frontend/P4 backend ports";
        return false;
    }
    const std::string config =
        make_request_length_oracle_config(frontend_port, backend_port, temp.nginx_access_log);
    if (!validate_request_length_oracle_config(
            config, frontend_port, backend_port, temp.nginx_access_log, error) ||
        !write_file(temp.nginx_config, config.data(), config.size())) {
        if (error.empty()) error = "#367 could not persist its exact nginx config";
        return false;
    }

    struct RecorderGuard {
        Recorder* recorder;
        ~RecorderGuard() {
            if (recorder != nullptr) recorder->stop();
        }
    };
    Recorder backend;
    RecorderGuard backend_guard{&backend};
    backend.read_exact_content_length_12_body = true;
    backend.wait_response_peer_close = true;
    backend.observe_extra_requests_until_stop = true;
    if (!handoff_held_loopback_port(
            &reservations.fds[1], backend_port, "#367 Recorder bind", error) ||
        !backend.setup(backend_port, 1u, kBackendResponse, sizeof(kBackendResponse) - 1u)) {
        if (error.empty()) error = "#367 Recorder could not bind the held P4 backend port";
        return false;
    }
    const auto recorder_deadline = std::chrono::steady_clock::now() + std::chrono::seconds(2);
    while ((!backend.running.load(std::memory_order_acquire) ||
            !backend.thread_alive.load(std::memory_order_acquire)) &&
           std::chrono::steady_clock::now() < recorder_deadline) {
        if (backend.listener_failed.load(std::memory_order_acquire)) break;
        usleep(1000);
    }
    if (!backend.running.load(std::memory_order_acquire) ||
        !backend.thread_alive.load(std::memory_order_acquire) ||
        backend.listener_failed.load(std::memory_order_acquire)) {
        error = "#367 Recorder was not live before frontend handoff";
        return false;
    }

    ChildGuard nginx;
    DockerGuard docker(container_name);
    if (!handoff_held_loopback_port(
            &reservations.fds[0], frontend_port, "#367 pinned nginx bind", error) ||
        !spawn_child({"docker",
                      "run",
                      "--pull=never",
                      "--network",
                      "host",
                      "--name",
                      container_name,
                      "-v",
                      temp.nginx_config + ":/etc/nginx/nginx.conf:ro",
                      "-v",
                      std::string(temp.path) + ":" + temp.path,
                      kNginxImage,
                      "nginx",
                      "-g",
                      "daemon off;"},
                     temp.nginx_log,
                     nginx.child) ||
        !wait_ready(frontend_port, nginx.child, error)) {
        if (error.empty()) error = "#367 pinned nginx failed before readiness";
        return false;
    }
    const auto live_with_counts = [&](u32 expected) {
        return !poll_child(nginx.child) && backend.running.load(std::memory_order_acquire) &&
               backend.thread_alive.load(std::memory_order_acquire) &&
               !backend.listener_failed.load(std::memory_order_acquire) &&
               backend.accepted.load(std::memory_order_acquire) == expected &&
               backend.requests.load(std::memory_order_acquire) == expected &&
               backend.response_send_all_calls.load(std::memory_order_acquire) == expected;
    };
    const auto quiet_deadline = std::chrono::steady_clock::now() + std::chrono::milliseconds(150);
    while (std::chrono::steady_clock::now() < quiet_deadline) {
        std::string access;
        if (!live_with_counts(0u) ||
            !read_request_length_fixed_body_access(temp.nginx_access_log, access, error) ||
            !access.empty()) {
            if (error.empty()) error = "#367 pre-request state was not live and quiet";
            return false;
        }
        usleep(5000);
    }

    struct ClientGuard {
        int fd = -1;
        ~ClientGuard() {
            if (fd >= 0) close(fd);
        }
    } client{connect_once(frontend_port)};
    std::vector<char> response;
    if (client.fd < 0) {
        error = split_delivery ? "#369 client connect failed" : "#367 client connect failed";
        return false;
    }
    if (split_delivery) {
        if (!send_all(client.fd,
                      kRequestLengthFixedBodyFirstSend,
                      sizeof(kRequestLengthFixedBodyFirstSend) - 1u)) {
            error = "#369 exact 128-byte first application send failed";
            return false;
        }
        const auto quiet_started = std::chrono::steady_clock::now();
        const auto quiet_deadline = quiet_started + std::chrono::milliseconds(500);
        for (;;) {
            std::string access;
            // Recorder publishes accepted before it can read or mutate request/history.
            // Keeping accepted at zero therefore proves those non-atomic containers untouched.
            if (!live_with_counts(0u) ||
                !read_request_length_fixed_body_access(temp.nginx_access_log, access, error) ||
                !access.empty() ||
                !observe_client_open_and_quiet_nonconsuming(client.fd, 25, error)) {
                if (error.empty())
                    error = "#369 pre-suffix process/backend/access/client state was not quiet";
                return false;
            }
            if (std::chrono::steady_clock::now() >= quiet_deadline) break;
        }
        // The last 25ms client observation can outlive the preceding backend/access
        // snapshot. Take one mandatory, nonblocking final snapshot immediately before
        // validating and sending the suffix.
        const bool final_backend_quiet = live_with_counts(0u);
        std::string final_quiet_access;
        const bool final_access_quiet = read_request_length_fixed_body_access(
                                            temp.nginx_access_log, final_quiet_access, error) &&
                                        final_quiet_access.empty();
        const bool final_client_quiet =
            observe_client_open_and_quiet_nonconsuming(client.fd, 0, error);
        const auto quiet_elapsed = std::chrono::duration_cast<std::chrono::milliseconds>(
            std::chrono::steady_clock::now() - quiet_started);
        if (!validate_request_length_fixed_body_split(kRequestLengthFixedBodyFirstSend,
                                                      kRequestLengthFixedBodySecondSend,
                                                      quiet_elapsed,
                                                      final_backend_quiet,
                                                      final_client_quiet,
                                                      final_access_quiet,
                                                      error) ||
            !send_all(client.fd,
                      kRequestLengthFixedBodySecondSend,
                      sizeof(kRequestLengthFixedBodySecondSend) - 1u)) {
            if (error.empty()) error = "#369 exact 7-byte second application send failed";
            return false;
        }
    } else if (!send_all(client.fd,
                         kRequestLengthFixedBodyClientRequest,
                         sizeof(kRequestLengthFixedBodyClientRequest) - 1u)) {
        error = "#367 one application send failed";
        return false;
    }
    if (!read_response(client.fd, response, error) || !read_eof(client.fd, error) ||
        !validate_exact_normalized_response(response, kSuccessResponseNormalized, error)) {
        if (error.empty())
            error = split_delivery ? "#369 split response/EOF episode failed"
                                   : "#367 one application send/response/EOF episode failed";
        return false;
    }
    close(client.fd);
    client.fd = -1;
    if (!wait_for_live_complete_origin_episode(backend, nginx.child, "#367 pinned nginx", error))
        return false;

    const std::string expected_header =
        "POST /ledger?q=raw HTTP/1.1\r\nHost: 127.0.0.1:" + std::to_string(backend_port) +
        "\r\nContent-Length: 12\r\nX-Test: keep\r\n\r\n";
    const std::string expected_upstream = expected_header + kRequestLengthFixedBody;
    const std::vector<char> expected_wire(expected_upstream.begin(), expected_upstream.end());
    const std::string actual =
        backend.history.size() == 1u
            ? std::string(backend.history[0].begin(), backend.history[0].end())
            : std::string{};
    const std::vector<char> actual_bytes(actual.begin(), actual.end());
    const size_t actual_header_end = header_end(actual_bytes);
    if (expected_header.size() != 87u || expected_upstream.size() != 99u ||
        sizeof(kRequestLengthFixedBodyClientRequest) - 1u == expected_upstream.size() ||
        backend.history.size() != 1u || backend.history[0] != expected_wire ||
        actual_header_end != 87u || actual.size() - actual_header_end != 12u ||
        count_text(actual, "Host: 127.0.0.1:") != 1u ||
        count_text(actual, "Content-Length: 12\r\n") != 1u ||
        count_text(actual, "X-Test: keep\r\n") != 1u ||
        count_text(actual, kRequestLengthFixedBody) != 1u ||
        actual.find("client.example") != std::string::npos ||
        actual.find("Connection:") != std::string::npos || actual.find('\t') != std::string::npos) {
        if (!backend.history.empty()) dump_wire("#367 actual backend wire", backend.history[0]);
        error = "#367 pinned nginx upstream was not the exact 87-header/99-total candidate";
        return false;
    }
    if (!backend.response_peer_closed.load(std::memory_order_acquire) ||
        backend.response_peer_unexpected_data.load(std::memory_order_acquire) ||
        backend.response_peer_observation_failed.load(std::memory_order_acquire)) {
        error = "#367 origin did not observe exact peer-close/no-late-byte evidence";
        return false;
    }

    static constexpr char kExpectedAccess[] = "135\n";
    static_assert(sizeof(kExpectedAccess) - 1u == 4u);
    const auto access_deadline = std::chrono::steady_clock::now() + std::chrono::seconds(2);
    for (;;) {
        std::string access;
        if (!live_with_counts(1u) ||
            !read_request_length_fixed_body_access(temp.nginx_access_log, access, error)) {
            if (error.empty()) error = "#367 process/Recorder failed while awaiting live access";
            return false;
        }
        if (access.size() > sizeof(kExpectedAccess) - 1u ||
            memcmp(kExpectedAccess, access.data(), access.size()) != 0) {
            error = "#367 live access bytes were not a prefix of exact downstream value 135";
            return false;
        }
        if (access.size() == sizeof(kExpectedAccess) - 1u) break;
        if (std::chrono::steady_clock::now() >= access_deadline) {
            error = "#367 live access record did not become visible before shutdown";
            return false;
        }
        usleep(1000);
    }
    const auto stable_deadline = std::chrono::steady_clock::now() + std::chrono::milliseconds(500);
    while (std::chrono::steady_clock::now() < stable_deadline) {
        std::string access;
        if (!live_with_counts(1u) || !complete_origin_episode_is_exact(backend) ||
            !backend.response_peer_closed.load(std::memory_order_acquire) ||
            backend.response_peer_unexpected_data.load(std::memory_order_acquire) ||
            backend.response_peer_observation_failed.load(std::memory_order_acquire) ||
            !read_request_length_fixed_body_access(temp.nginx_access_log, access, error) ||
            !validate_request_length_fixed_body_access(access, error)) {
            if (error.empty()) error = "#367 live access/backend evidence was not stable";
            return false;
        }
        usleep(5000);
    }
    if (!stop_child(nginx.child) || !docker.remove()) {
        error = "#367 pinned nginx did not stop and remove cleanly";
        return false;
    }
    backend.stop();
    backend_guard.recorder = nullptr;
    std::string final_access;
    if (backend.thread_alive.load(std::memory_order_acquire) ||
        backend.listener_failed.load(std::memory_order_acquire) ||
        !complete_origin_episode_is_exact(backend) || backend.history.size() != 1u ||
        backend.history[0] != expected_wire ||
        !backend.response_peer_closed.load(std::memory_order_acquire) ||
        backend.response_peer_unexpected_data.load(std::memory_order_acquire) ||
        backend.response_peer_observation_failed.load(std::memory_order_acquire) ||
        !read_request_length_fixed_body_access(temp.nginx_access_log, final_access, error) ||
        !validate_request_length_fixed_body_access(final_access, error)) {
        if (error.empty()) error = "#367 final recorder/access evidence was not exact";
        return false;
    }
    for (const char* severity : {"[warn]", "[error]", "[crit]", "[alert]", "[emerg]"}) {
        if (log_contains(temp.nginx_log, severity)) {
            error = "#367 nginx emitted warn-or-higher diagnostics";
            return false;
        }
    }
    return true;
}

static bool run_pinned_request_length_fixed_body_oracle(TempDir& temp,
                                                        const std::string& container_name,
                                                        std::string& error) {
    return run_pinned_request_length_fixed_body_oracle_impl(temp, container_name, false, error);
}

static bool run_pinned_request_length_split_fixed_body_oracle(TempDir& temp,
                                                              const std::string& container_name,
                                                              std::string& error) {
    return run_pinned_request_length_fixed_body_oracle_impl(temp, container_name, true, error);
}

static std::string make_converter_request_length_profile(u16 frontend_port,
                                                         u16 backend_port,
                                                         const std::string& access_path) {
    return "http {\n"
           "  log_format compat \"$request_length\";\n"
           "  access_log " +
           access_path +
           " compat;\n"
           "  server {\n"
           "    listen 127.0.0.1:" +
           std::to_string(frontend_port) +
           ";\n"
           "    location / {\n"
           "      proxy_pass http://127.0.0.1:" +
           std::to_string(backend_port) +
           ";\n"
           "    }\n"
           "  }\n"
           "}\n";
}

static bool validate_converter_request_length_source(const std::string& source,
                                                     u16 frontend_port,
                                                     u16 backend_port,
                                                     const std::string& access_path,
                                                     std::string& error) {
    const std::string declaration = "accessLog { path: \"" + access_path +
                                    "\", format: downstreamRequestBytes, publication: live }\n";
    const std::string listener = "listen 127.0.0.1:" + std::to_string(frontend_port) + "\n";
    const std::string upstream =
        "upstream nginx_upstream at \"127.0.0.1:" + std::to_string(backend_port) + "\"\n";
    if (frontend_port == 0u || backend_port < 1024u || backend_port > 9999u ||
        frontend_port == backend_port || access_path.empty() ||
        source.rfind(declaration, 0u) != 0u || count_text(source, "accessLog {") != 1u ||
        count_text(source, declaration) != 1u || count_text(source, access_path) != 1u ||
        count_text(source, listener) != 1u || count_text(source, upstream) != 1u ||
        count_text(source, "route GET \"/\"") != 1u ||
        count_text(source, "return forward(nginx_upstream,") != 3u ||
        count_text(source, "format: downstreamRequestBytes") != 1u ||
        count_text(source, "publication: live") != 1u ||
        source.find("$request_length") != std::string::npos ||
        source.find("log_format") != std::string::npos ||
        source.find("access_log") != std::string::npos ||
        source.find("nginx.conf") != std::string::npos ||
        source.find("--access-log") != std::string::npos) {
        error = "#362 converter-generated ordinary RUT inventory was not exact";
        return false;
    }
    return true;
}

static bool build_owned_converter_request_length_source(u16 frontend_port,
                                                        u16 backend_port,
                                                        const std::string& access_path,
                                                        std::string& owned,
                                                        std::string& error) {
    std::string profile =
        make_converter_request_length_profile(frontend_port, backend_port, access_path);
    const std::string exact_profile = profile;
    {
        const auto parsed =
            rut::nginx::parse_http_profile({profile.data(), static_cast<u32>(profile.size())});
        if (!parsed) {
            error = "#362 parse_http_profile rejected the exact converter differential input";
            return false;
        }
        auto lowered = rut::nginx::lower_to_rut(parsed.value());
        if (!lowered) {
            error = "#362 lower_to_rut(HttpProfile) rejected the exact parsed model";
            return false;
        }
        owned.assign(lowered.value().data, lowered.value().len);
        if (!validate_converter_request_length_source(
                owned, frontend_port, backend_port, access_path, error))
            return false;
        memset(lowered.value().data, 'L', lowered.value().len);
    }
    std::fill(profile.begin(), profile.end(), 'P');
    if (profile == exact_profile || !validate_converter_request_length_source(
                                        owned, frontend_port, backend_port, access_path, error)) {
        if (error.empty())
            error = "#362 generated source did not survive frontend owner destruction";
        return false;
    }
    return true;
}

static bool run_converter_request_length_self_checks(std::string& error) {
    static constexpr u16 kFrontendPort = 18080u;
    static constexpr u16 kBackendPort = 9000u;
    static constexpr const char* kAccessPath = "/tmp/rut-nginx-362-converter/access.log";
    std::string source;
    if (!build_owned_converter_request_length_source(
            kFrontendPort, kBackendPort, kAccessPath, source, error))
        return false;
    const auto replace_once = [&](const std::string& from, const std::string& to) {
        std::string changed = source;
        const size_t at = changed.find(from);
        if (at == std::string::npos || changed.find(from, at + from.size()) != std::string::npos)
            return std::string{};
        changed.replace(at, from.size(), to);
        return changed;
    };
    const std::vector<std::string> mutations = {
        replace_once("format: downstreamRequestBytes", "format: defaultText"),
        replace_once("publication: live", "publication: periodic"),
        replace_once(kAccessPath, "/tmp/rut-nginx-362-converter/other.log"),
        replace_once("accessLog {", "accessLogDisabled {"),
        replace_once("listen 127.0.0.1:18080", "listen 127.0.0.1:18081"),
        replace_once("127.0.0.1:9000", "127.0.0.1:9001"),
        source + source.substr(0u, source.find('\n') + 1u),
    };
    for (const std::string& mutation : mutations) {
        std::string detail;
        if (mutation.empty() || validate_converter_request_length_source(
                                    mutation, kFrontendPort, kBackendPort, kAccessPath, detail)) {
            error = "#362 generated-source self-check accepted a semantic mutation";
            return false;
        }
    }
    return true;
}

static bool run_converter_request_length_rut_side(TempDir& temp,
                                                  const char* rut_path,
                                                  HeldLoopbackPorts& reservations,
                                                  u16 frontend_port,
                                                  u16 backend_port,
                                                  bool split_header_delivery,
                                                  std::string& error) {
    if (rut_path == nullptr || rut_path[0] != '/' || access(rut_path, X_OK) != 0) {
        error = "#362 converter differential requires an executable absolute RUT path";
        return false;
    }
    if (frontend_port == backend_port ||
        !validate_held_loopback_port(
            reservations.fds[0], frontend_port, "#362 generated RUT frontend handoff", error) ||
        !validate_held_loopback_port(
            reservations.fds[1], backend_port, "#362 generated RUT backend handoff", error)) {
        if (error.empty()) error = "#362 could not hold distinct generated-RUT ports";
        return false;
    }

    std::string generated;
    if (!build_owned_converter_request_length_source(
            frontend_port, backend_port, temp.rut_access_log, generated, error) ||
        !write_file(temp.source, generated.data(), generated.size())) {
        if (error.empty()) error = "#362 could not persist converter-generated ordinary RUT";
        return false;
    }
    std::fill(generated.begin(), generated.end(), 'G');
    std::string persisted;
    if (!read_exact_return204_log(temp.source, "#362 persisted generated RUT", persisted, error) ||
        !validate_converter_request_length_source(
            persisted, frontend_port, backend_port, temp.rut_access_log, error))
        return false;
    persisted.clear();
    persisted.shrink_to_fit();

    struct RecorderGuard {
        Recorder* recorder;
        ~RecorderGuard() {
            if (recorder != nullptr) recorder->stop();
        }
    };
    Recorder backend;
    RecorderGuard backend_guard{&backend};
    backend.wait_response_peer_close = split_header_delivery;
    backend.observe_extra_requests_until_stop = true;
    if (!handoff_held_loopback_port(
            &reservations.fds[1], backend_port, "#362 generated RUT Recorder bind", error) ||
        !backend.setup(backend_port, 1u, kBackendResponse, sizeof(kBackendResponse) - 1u)) {
        if (error.empty()) error = "#362 generated-RUT Recorder could not bind held backend";
        return false;
    }
    const auto recorder_deadline = std::chrono::steady_clock::now() + std::chrono::seconds(2);
    while ((!backend.running.load(std::memory_order_acquire) ||
            !backend.thread_alive.load(std::memory_order_acquire)) &&
           std::chrono::steady_clock::now() < recorder_deadline) {
        if (backend.listener_failed.load(std::memory_order_acquire)) break;
        usleep(1000);
    }
    if (!backend.running.load(std::memory_order_acquire) ||
        !backend.thread_alive.load(std::memory_order_acquire) ||
        backend.listener_failed.load(std::memory_order_acquire)) {
        error = "#362 generated-RUT Recorder was not live before frontend handoff";
        return false;
    }

    ChildGuard runtime;
    if (!handoff_held_loopback_port(
            &reservations.fds[0], frontend_port, "#362 generated RUT public bind", error) ||
        !spawn_child({rut_path, temp.source, "--shards", "1", "--no-pin", "--drain", "0"},
                     temp.rut_log,
                     runtime.child) ||
        !wait_ready(frontend_port, runtime.child, error)) {
        if (error.empty()) error = "#362 generated ordinary RUT failed before readiness";
        return false;
    }
    if (split_header_delivery) {
        static constexpr char kPoison[] = "invalid-after-owned-issue370-source-load\n";
        std::string overwritten;
        if (!write_file(temp.source, kPoison, sizeof(kPoison) - 1u) ||
            !read_exact_return204_log(
                temp.source, "#370 overwritten generated source", overwritten, error) ||
            overwritten != kPoison || poll_child(runtime.child)) {
            if (error.empty())
                error = "#370 generated RUT did not retain its loaded source after overwrite";
            return false;
        }
    }
    const auto live_with_counts = [&](u32 expected) {
        return !poll_child(runtime.child) && backend.running.load(std::memory_order_acquire) &&
               backend.thread_alive.load(std::memory_order_acquire) &&
               !backend.listener_failed.load(std::memory_order_acquire) &&
               backend.accepted.load(std::memory_order_acquire) == expected &&
               backend.requests.load(std::memory_order_acquire) == expected &&
               backend.response_send_all_calls.load(std::memory_order_acquire) == expected;
    };
    const auto quiet_deadline = std::chrono::steady_clock::now() + std::chrono::milliseconds(150);
    while (std::chrono::steady_clock::now() < quiet_deadline) {
        std::string access_bytes;
        if (!live_with_counts(0u) ||
            !read_request_length_access_file(temp.rut_access_log, access_bytes, error) ||
            !access_bytes.empty()) {
            if (error.empty()) error = "#362 generated-RUT pre-request state was not quiet";
            return false;
        }
        usleep(5000);
    }

    struct ClientGuard {
        int fd = -1;
        ~ClientGuard() {
            if (fd >= 0) close(fd);
        }
    } client{connect_once(frontend_port)};
    if (client.fd < 0) {
        error = split_header_delivery ? "#370 generated-RUT client connect failed"
                                      : "#362 generated-RUT client connect failed";
        return false;
    }
    if (split_header_delivery) {
        if (!send_all(client.fd,
                      kRequestLengthSplitHeaderFirstSend,
                      sizeof(kRequestLengthSplitHeaderFirstSend) - 1u)) {
            error = "#370 generated RUT exact 45-byte first application send failed";
            return false;
        }
        const auto split_quiet_started = std::chrono::steady_clock::now();
        const auto split_quiet_deadline = split_quiet_started + std::chrono::milliseconds(500);
        for (;;) {
            std::string access_bytes;
            if (!live_with_counts(0u) ||
                !read_request_length_access_file(temp.rut_access_log, access_bytes, error) ||
                !access_bytes.empty() ||
                !observe_client_open_and_quiet_nonconsuming(client.fd, 25, error)) {
                if (error.empty())
                    error = "#370 generated incomplete-header state was not live and quiet";
                return false;
            }
            if (std::chrono::steady_clock::now() >= split_quiet_deadline) break;
        }

        // Mandatory final causal snapshot: access, non-consuming client peek,
        // child/Recorder liveness, and Recorder atomics last. Send the suffix
        // immediately after validating these actual observations.
        std::string final_quiet_access;
        const bool final_access_quiet =
            read_request_length_access_file(temp.rut_access_log, final_quiet_access, error) &&
            final_quiet_access.empty();
        const bool final_client_quiet =
            observe_client_open_and_quiet_nonconsuming(client.fd, 0, error);
        const bool final_child_live = !poll_child(runtime.child);
        const bool final_recorder_live = backend.running.load(std::memory_order_acquire) &&
                                         backend.thread_alive.load(std::memory_order_acquire) &&
                                         !backend.listener_failed.load(std::memory_order_acquire);
        const u32 final_accepted = backend.accepted.load(std::memory_order_acquire);
        const u32 final_requests = backend.requests.load(std::memory_order_acquire);
        const u32 final_response_sends =
            backend.response_send_all_calls.load(std::memory_order_acquire);
        const auto quiet_elapsed = std::chrono::duration_cast<std::chrono::milliseconds>(
            std::chrono::steady_clock::now() - split_quiet_started);
        if (!validate_request_length_split_header(kRequestLengthSplitHeaderFirstSend,
                                                  kRequestLengthSplitHeaderSecondSend,
                                                  quiet_elapsed,
                                                  final_child_live,
                                                  final_recorder_live,
                                                  final_accepted,
                                                  final_requests,
                                                  final_response_sends,
                                                  final_access_quiet,
                                                  final_client_quiet,
                                                  error) ||
            !send_all(client.fd,
                      kRequestLengthSplitHeaderSecondSend,
                      sizeof(kRequestLengthSplitHeaderSecondSend) - 1u)) {
            if (error.empty()) error = "#370 generated RUT exact 57-byte suffix send failed";
            return false;
        }
    } else if (!send_all(client.fd,
                         kRequestLengthOracleClientRequest,
                         sizeof(kRequestLengthOracleClientRequest) - 1u)) {
        error = "#362 generated RUT exact 102-byte application send failed";
        return false;
    }
    std::vector<char> response;
    if (!read_response(client.fd, response, error) || !read_eof(client.fd, error) ||
        !validate_exact_normalized_response(response, kSuccessResponseNormalized, error)) {
        if (error.empty())
            error = split_header_delivery
                        ? "#370 generated-RUT split request/response episode failed"
                        : "#362 generated-RUT exact request/response episode failed";
        return false;
    }
    close(client.fd);
    client.fd = -1;
    if (!wait_for_live_complete_origin_episode(
            backend,
            runtime.child,
            split_header_delivery ? "#370 generated RUT" : "#362 generated RUT",
            error))
        return false;

    const std::string expected_upstream =
        "GET /ledger?q=raw HTTP/1.1\r\nHost: 127.0.0.1:" + std::to_string(backend_port) +
        "\r\nX-Test: keep\r\n\r\n";
    const std::vector<char> expected_wire(expected_upstream.begin(), expected_upstream.end());
    const u64 response_sent_ns = backend.response_sent_ns.load(std::memory_order_acquire);
    const u64 response_peer_closed_ns =
        backend.response_peer_closed_ns.load(std::memory_order_acquire);
    if (split_header_delivery &&
        (!live_with_counts(1u) || response_sent_ns == 0u ||
         !backend.response_peer_closed.load(std::memory_order_acquire) ||
         response_peer_closed_ns < response_sent_ns ||
         response_peer_closed_ns - response_sent_ns > 2'000'000'000ull ||
         backend.response_peer_unexpected_data.load(std::memory_order_acquire) ||
         backend.response_peer_observation_failed.load(std::memory_order_acquire))) {
        error = "#370 generated RUT lacked prompt live origin FIN/no-late-byte evidence";
        return false;
    }

    static constexpr char kExpectedAccess[] = "102\n";
    const auto access_deadline = std::chrono::steady_clock::now() + std::chrono::seconds(2);
    for (;;) {
        std::string access_bytes;
        if (!live_with_counts(1u) ||
            !read_request_length_access_file(temp.rut_access_log, access_bytes, error)) {
            if (error.empty()) error = "#362 generated RUT failed while awaiting live access";
            return false;
        }
        if (access_bytes.size() > sizeof(kExpectedAccess) - 1u ||
            memcmp(kExpectedAccess, access_bytes.data(), access_bytes.size()) != 0) {
            error = "#362 generated-RUT access bytes escaped the exact `102\\n` prefix";
            return false;
        }
        if (access_bytes.size() == sizeof(kExpectedAccess) - 1u) break;
        if (std::chrono::steady_clock::now() >= access_deadline) {
            error = "#362 generated-RUT access record was not visible before shutdown";
            return false;
        }
        usleep(1000);
    }
    const auto stable_deadline = std::chrono::steady_clock::now() + std::chrono::milliseconds(500);
    while (std::chrono::steady_clock::now() < stable_deadline) {
        std::string access_bytes;
        const u64 stable_sent_ns = backend.response_sent_ns.load(std::memory_order_acquire);
        const u64 stable_closed_ns =
            backend.response_peer_closed_ns.load(std::memory_order_acquire);
        if (!live_with_counts(1u) ||
            (split_header_delivery &&
             (stable_sent_ns != response_sent_ns || stable_closed_ns != response_peer_closed_ns ||
              !backend.response_peer_closed.load(std::memory_order_acquire) ||
              backend.response_peer_unexpected_data.load(std::memory_order_acquire) ||
              backend.response_peer_observation_failed.load(std::memory_order_acquire))) ||
            !read_request_length_access_file(temp.rut_access_log, access_bytes, error) ||
            !validate_request_length_access_bytes(access_bytes, error)) {
            if (error.empty())
                error = split_header_delivery ? "#370 generated-RUT live evidence was not stable"
                                              : "#362 generated-RUT live evidence was not stable";
            return false;
        }
        usleep(5000);
    }
    if (!stop_child(runtime.child) || !runtime.child.status_valid ||
        !WIFEXITED(runtime.child.status) || WEXITSTATUS(runtime.child.status) != 0) {
        error = "#362 generated RUT did not shut down cleanly";
        return false;
    }
    backend.stop();
    backend_guard.recorder = nullptr;
    const std::string actual =
        backend.history.size() == 1u
            ? std::string(backend.history[0].begin(), backend.history[0].end())
            : std::string{};
    std::string final_access;
    std::string runtime_log;
    if (backend.thread_alive.load(std::memory_order_acquire) ||
        backend.listener_failed.load(std::memory_order_acquire) ||
        !complete_origin_episode_is_exact(backend) || backend.history.size() != 1u ||
        backend.request != expected_wire || backend.history[0] != expected_wire ||
        expected_upstream.size() != 66u ||
        sizeof(kRequestLengthOracleClientRequest) - 1u == expected_upstream.size() ||
        count_text(actual, "Host: 127.0.0.1:") != 1u ||
        count_text(actual, "X-Test: keep\r\n") != 1u ||
        actual.find("client.example") != std::string::npos ||
        actual.find("Connection:") != std::string::npos || actual.find('\t') != std::string::npos ||
        (split_header_delivery &&
         (!backend.response_peer_closed.load(std::memory_order_acquire) ||
          backend.response_peer_unexpected_data.load(std::memory_order_acquire) ||
          backend.response_peer_observation_failed.load(std::memory_order_acquire))) ||
        !read_request_length_access_file(temp.rut_access_log, final_access, error) ||
        !validate_request_length_access_bytes(final_access, error) ||
        !read_exact_return204_log(
            temp.rut_log, "#362 generated RUT runtime log", runtime_log, error) ||
        !validate_rut_exact_ipv4_runtime_log(runtime_log, temp.source, frontend_port, error)) {
        if (!backend.history.empty())
            dump_wire(split_header_delivery ? "#370 generated RUT backend wire"
                                            : "#362 generated RUT backend wire",
                      backend.history[0]);
        if (error.empty())
            error = split_header_delivery
                        ? "#370 generated-RUT final lifecycle evidence was not exact"
                        : "#362 generated-RUT final lifecycle evidence was not exact";
        return false;
    }
    return true;
}

static bool run_converter_request_length_differential(TempDir& temp,
                                                      const std::string& container_name,
                                                      const char* rut_path,
                                                      std::string& error) {
    HeldLoopbackPorts rut_reservations;
    u16 rut_frontend_port = 0u;
    u16 rut_backend_port = 0u;
    if (!rut_reservations.reserve(0u, rut_frontend_port) ||
        !rut_reservations.reserve_four_digit(1u, rut_backend_port) ||
        rut_frontend_port == rut_backend_port) {
        error = "#362 could not pre-hold isolated generated-RUT frontend/backend ports";
        return false;
    }
    if (!run_pinned_request_length_oracle(temp, container_name, error)) return false;
    return run_converter_request_length_rut_side(
        temp, rut_path, rut_reservations, rut_frontend_port, rut_backend_port, false, error);
}

static bool run_converter_request_length_split_header_differential(
    TempDir& temp, const std::string& container_name, const char* rut_path, std::string& error) {
    HeldLoopbackPorts rut_reservations;
    u16 rut_frontend_port = 0u;
    u16 rut_backend_port = 0u;
    if (!rut_reservations.reserve(0u, rut_frontend_port) ||
        !rut_reservations.reserve_four_digit(1u, rut_backend_port) ||
        rut_frontend_port == rut_backend_port) {
        error = "#370 could not pre-hold isolated generated-RUT frontend/backend ports";
        return false;
    }
    if (!run_pinned_request_length_split_header_oracle(temp, container_name, error)) return false;
    return run_converter_request_length_rut_side(
        temp, rut_path, rut_reservations, rut_frontend_port, rut_backend_port, true, error);
}

static bool validate_converter_request_length_fixed_body_source(const std::string& source,
                                                                u16 frontend_port,
                                                                u16 backend_port,
                                                                const std::string& access_path,
                                                                std::string& error) {
    const std::string declaration = "accessLog { path: \"" + access_path +
                                    "\", format: downstreamRequestBytes, publication: live }\n";
    const std::string listener = "listen 127.0.0.1:" + std::to_string(frontend_port) + "\n";
    const std::string upstream =
        "upstream nginx_upstream at \"127.0.0.1:" + std::to_string(backend_port) + "\"\n";
    if (frontend_port == 0u || backend_port < 1024u || backend_port > 9999u ||
        frontend_port == backend_port || access_path.empty() ||
        source.rfind(declaration, 0u) != 0u || count_text(source, declaration) != 1u ||
        count_text(source, "accessLog {") != 1u || count_text(source, access_path) != 1u ||
        count_text(source, listener) != 1u || count_text(source, upstream) != 1u ||
        count_text(source, "\nroute ") != 3u || count_text(source, "route HEAD \"/\" {") != 1u ||
        count_text(source, "route GET \"/\" {") != 1u ||
        count_text(source, "\nroute \"/\" {") != 1u ||
        count_text(source, "return forward(nginx_upstream,") != 3u ||
        count_text(source, "format: downstreamRequestBytes") != 1u ||
        count_text(source, "publication: live") != 1u ||
        source.find("route POST ") != std::string::npos ||
        source.find("$request_length") != std::string::npos ||
        source.find("log_format") != std::string::npos ||
        source.find("access_log") != std::string::npos ||
        source.find("nginx.conf") != std::string::npos ||
        source.find("--access-log") != std::string::npos) {
        error =
            "#367 converter-generated ordinary RUT inventory was not exact "
            "accessLog/listen/upstream/HEAD/GET/Any";
        return false;
    }
    return true;
}

static bool build_owned_converter_request_length_fixed_body_source(u16 frontend_port,
                                                                   u16 backend_port,
                                                                   const std::string& access_path,
                                                                   std::string& owned,
                                                                   std::string& error) {
    if (!build_owned_converter_request_length_source(
            frontend_port, backend_port, access_path, owned, error))
        return false;
    return validate_converter_request_length_fixed_body_source(
        owned, frontend_port, backend_port, access_path, error);
}

static bool run_converter_request_length_fixed_body_self_checks(std::string& error) {
    static constexpr u16 kFrontendPort = 18080u;
    static constexpr u16 kBackendPort = 9000u;
    static constexpr const char* kAccessPath = "/tmp/rut-nginx-367-converter/access.log";
    std::string source;
    if (!build_owned_converter_request_length_fixed_body_source(
            kFrontendPort, kBackendPort, kAccessPath, source, error))
        return false;
    const auto replace_once = [&](const std::string& from, const std::string& to) {
        std::string changed = source;
        const size_t at = changed.find(from);
        if (at == std::string::npos || changed.find(from, at + from.size()) != std::string::npos)
            return std::string{};
        changed.replace(at, from.size(), to);
        return changed;
    };
    const std::vector<std::string> mutations = {
        replace_once("format: downstreamRequestBytes", "format: defaultText"),
        replace_once("publication: live", "publication: periodic"),
        replace_once(kAccessPath, "/tmp/rut-nginx-367-converter/other.log"),
        replace_once("listen 127.0.0.1:18080", "listen 127.0.0.1:18081"),
        replace_once("127.0.0.1:9000", "127.0.0.1:9001"),
        replace_once("route HEAD \"/\" {", "route POST \"/\" {"),
        replace_once("route GET \"/\" {", "route PUT \"/\" {"),
        replace_once("\nroute \"/\" {", "\nroute POST \"/\" {"),
        source + source.substr(0u, source.find('\n') + 1u),
    };
    for (const std::string& mutation : mutations) {
        std::string detail;
        if (mutation.empty() || validate_converter_request_length_fixed_body_source(
                                    mutation, kFrontendPort, kBackendPort, kAccessPath, detail)) {
            error = "#367 generated-source self-check accepted a semantic mutation";
            return false;
        }
    }
    return true;
}

static bool run_converter_request_length_fixed_body_rut_side(TempDir& temp,
                                                             const char* rut_path,
                                                             HeldLoopbackPorts& reservations,
                                                             u16 frontend_port,
                                                             u16 backend_port,
                                                             bool split_delivery,
                                                             std::string& error) {
    if (rut_path == nullptr || rut_path[0] != '/' || access(rut_path, X_OK) != 0) {
        error = "#367 converter differential requires an executable absolute RUT path";
        return false;
    }
    if (frontend_port == backend_port ||
        !validate_held_loopback_port(
            reservations.fds[0], frontend_port, "#367 generated RUT frontend handoff", error) ||
        !validate_held_loopback_port(
            reservations.fds[1], backend_port, "#367 generated RUT backend handoff", error)) {
        if (error.empty()) error = "#367 could not hold distinct generated-RUT ports";
        return false;
    }

    std::string generated;
    if (!build_owned_converter_request_length_fixed_body_source(
            frontend_port, backend_port, temp.rut_access_log, generated, error) ||
        !write_file(temp.source, generated.data(), generated.size())) {
        if (error.empty()) error = "#367 could not persist converter-generated ordinary RUT";
        return false;
    }
    std::fill(generated.begin(), generated.end(), 'G');
    std::string persisted;
    if (!read_exact_return204_log(temp.source, "#367 persisted generated RUT", persisted, error) ||
        !validate_converter_request_length_fixed_body_source(
            persisted, frontend_port, backend_port, temp.rut_access_log, error))
        return false;
    persisted.clear();
    persisted.shrink_to_fit();

    struct RecorderGuard {
        Recorder* recorder;
        ~RecorderGuard() {
            if (recorder != nullptr) recorder->stop();
        }
    };
    Recorder backend;
    RecorderGuard backend_guard{&backend};
    backend.read_exact_content_length_12_body = true;
    backend.wait_response_peer_close = true;
    backend.observe_extra_requests_until_stop = true;
    if (!handoff_held_loopback_port(
            &reservations.fds[1], backend_port, "#367 generated RUT Recorder bind", error) ||
        !backend.setup(backend_port, 1u, kBackendResponse, sizeof(kBackendResponse) - 1u)) {
        if (error.empty()) error = "#367 generated-RUT Recorder could not bind held backend";
        return false;
    }
    const auto recorder_deadline = std::chrono::steady_clock::now() + std::chrono::seconds(2);
    while ((!backend.running.load(std::memory_order_acquire) ||
            !backend.thread_alive.load(std::memory_order_acquire)) &&
           std::chrono::steady_clock::now() < recorder_deadline) {
        if (backend.listener_failed.load(std::memory_order_acquire)) break;
        usleep(1000);
    }
    if (!backend.running.load(std::memory_order_acquire) ||
        !backend.thread_alive.load(std::memory_order_acquire) ||
        backend.listener_failed.load(std::memory_order_acquire)) {
        error = "#367 generated-RUT Recorder was not live before frontend handoff";
        return false;
    }

    ChildGuard runtime;
    if (!handoff_held_loopback_port(
            &reservations.fds[0], frontend_port, "#367 generated RUT public bind", error) ||
        !spawn_child({rut_path, temp.source, "--shards", "1", "--no-pin", "--drain", "0"},
                     temp.rut_log,
                     runtime.child) ||
        !wait_ready(frontend_port, runtime.child, error)) {
        if (error.empty()) error = "#367 generated ordinary RUT failed before readiness";
        return false;
    }
    const auto live_with_counts = [&](u32 expected) {
        return !poll_child(runtime.child) && backend.running.load(std::memory_order_acquire) &&
               backend.thread_alive.load(std::memory_order_acquire) &&
               !backend.listener_failed.load(std::memory_order_acquire) &&
               backend.accepted.load(std::memory_order_acquire) == expected &&
               backend.requests.load(std::memory_order_acquire) == expected &&
               backend.response_send_all_calls.load(std::memory_order_acquire) == expected;
    };
    const auto quiet_deadline = std::chrono::steady_clock::now() + std::chrono::milliseconds(150);
    while (std::chrono::steady_clock::now() < quiet_deadline) {
        std::string access_bytes;
        if (!live_with_counts(0u) ||
            !read_request_length_fixed_body_access(temp.rut_access_log, access_bytes, error) ||
            !access_bytes.empty()) {
            if (error.empty()) error = "#367 generated-RUT pre-request state was not quiet";
            return false;
        }
        usleep(5000);
    }

    struct ClientGuard {
        int fd = -1;
        ~ClientGuard() {
            if (fd >= 0) close(fd);
        }
    } client{connect_once(frontend_port)};
    std::vector<char> response;
    if (client.fd < 0) {
        error = split_delivery ? "#369 generated-RUT client connect failed"
                               : "#367 generated-RUT client connect failed";
        return false;
    }
    if (split_delivery) {
        if (!send_all(client.fd,
                      kRequestLengthFixedBodyFirstSend,
                      sizeof(kRequestLengthFixedBodyFirstSend) - 1u)) {
            error = "#369 generated-RUT exact 128-byte first application send failed";
            return false;
        }
        const auto quiet_started = std::chrono::steady_clock::now();
        const auto split_quiet_deadline = quiet_started + std::chrono::milliseconds(500);
        for (;;) {
            std::string access_bytes;
            // Recorder publishes accepted before it can read or mutate request/history.
            // Keeping accepted at zero therefore proves those non-atomic containers untouched.
            if (!live_with_counts(0u) ||
                !read_request_length_fixed_body_access(temp.rut_access_log, access_bytes, error) ||
                !access_bytes.empty() ||
                !observe_client_open_and_quiet_nonconsuming(client.fd, 25, error)) {
                if (error.empty())
                    error =
                        "#369 generated-RUT pre-suffix backend/access/client state was not quiet";
                return false;
            }
            if (std::chrono::steady_clock::now() >= split_quiet_deadline) break;
        }
        // Close the gap after the last blocking client observation with one
        // mandatory all-sides snapshot immediately before the suffix.
        const bool final_backend_quiet = live_with_counts(0u);
        std::string final_quiet_access;
        const bool final_access_quiet =
            read_request_length_fixed_body_access(temp.rut_access_log, final_quiet_access, error) &&
            final_quiet_access.empty();
        const bool final_client_quiet =
            observe_client_open_and_quiet_nonconsuming(client.fd, 0, error);
        const auto quiet_elapsed = std::chrono::duration_cast<std::chrono::milliseconds>(
            std::chrono::steady_clock::now() - quiet_started);
        if (!validate_request_length_fixed_body_split(kRequestLengthFixedBodyFirstSend,
                                                      kRequestLengthFixedBodySecondSend,
                                                      quiet_elapsed,
                                                      final_backend_quiet,
                                                      final_client_quiet,
                                                      final_access_quiet,
                                                      error) ||
            !send_all(client.fd,
                      kRequestLengthFixedBodySecondSend,
                      sizeof(kRequestLengthFixedBodySecondSend) - 1u)) {
            if (error.empty()) error = "#369 generated-RUT exact 7-byte second send failed";
            return false;
        }
    } else if (!send_all(client.fd,
                         kRequestLengthFixedBodyClientRequest,
                         sizeof(kRequestLengthFixedBodyClientRequest) - 1u)) {
        error = "#367 generated-RUT one application send failed";
        return false;
    }
    if (!read_response(client.fd, response, error) || !read_eof(client.fd, error) ||
        !validate_exact_normalized_response(response, kSuccessResponseNormalized, error)) {
        if (error.empty())
            error = split_delivery ? "#369 generated-RUT split request/response/EOF failed"
                                   : "#367 generated-RUT one-send request/response/EOF failed";
        return false;
    }
    close(client.fd);
    client.fd = -1;
    if (!wait_for_live_complete_origin_episode(backend, runtime.child, "#367 generated RUT", error))
        return false;

    const std::string expected_header =
        "POST /ledger?q=raw HTTP/1.1\r\nHost: 127.0.0.1:" + std::to_string(backend_port) +
        "\r\nContent-Length: 12\r\nX-Test: keep\r\n\r\n";
    const std::string expected_upstream = expected_header + kRequestLengthFixedBody;
    const std::vector<char> expected_wire(expected_upstream.begin(), expected_upstream.end());
    const std::string actual =
        backend.history.size() == 1u
            ? std::string(backend.history[0].begin(), backend.history[0].end())
            : std::string{};
    const std::vector<char> actual_bytes(actual.begin(), actual.end());
    const size_t actual_header_end = header_end(actual_bytes);
    if (expected_header.size() != 87u || expected_upstream.size() != 99u ||
        sizeof(kRequestLengthFixedBodyClientRequest) - 1u == expected_upstream.size() ||
        backend.history.size() != 1u || backend.history[0] != expected_wire ||
        actual_header_end != 87u || actual.size() - actual_header_end != 12u ||
        count_text(actual, "Host: 127.0.0.1:") != 1u ||
        count_text(actual, "Content-Length: 12\r\n") != 1u ||
        count_text(actual, "X-Test: keep\r\n") != 1u ||
        count_text(actual, kRequestLengthFixedBody) != 1u ||
        actual.find("client.example") != std::string::npos ||
        actual.find("Connection:") != std::string::npos || actual.find('\t') != std::string::npos) {
        if (!backend.history.empty())
            dump_wire("#367 generated RUT backend wire", backend.history[0]);
        error = "#367 generated RUT upstream was not exact 87-header/99-total fixed-body wire";
        return false;
    }
    if (!backend.response_peer_closed.load(std::memory_order_acquire) ||
        backend.response_peer_unexpected_data.load(std::memory_order_acquire) ||
        backend.response_peer_observation_failed.load(std::memory_order_acquire)) {
        error = "#367 generated RUT origin lacked exact peer-close/no-late-byte evidence";
        return false;
    }

    static constexpr char kExpectedAccess[] = "135\n";
    const auto access_deadline = std::chrono::steady_clock::now() + std::chrono::seconds(2);
    for (;;) {
        std::string access_bytes;
        if (!live_with_counts(1u) ||
            !read_request_length_fixed_body_access(temp.rut_access_log, access_bytes, error)) {
            if (error.empty()) error = "#367 generated RUT failed while awaiting live access";
            return false;
        }
        if (access_bytes.size() > sizeof(kExpectedAccess) - 1u ||
            memcmp(kExpectedAccess, access_bytes.data(), access_bytes.size()) != 0) {
            error = "#367 generated-RUT access escaped the exact `135\\n` prefix";
            return false;
        }
        if (access_bytes.size() == sizeof(kExpectedAccess) - 1u) break;
        if (std::chrono::steady_clock::now() >= access_deadline) {
            error = "#367 generated-RUT access record was not visible before shutdown";
            return false;
        }
        usleep(1000);
    }
    const auto stable_deadline = std::chrono::steady_clock::now() + std::chrono::milliseconds(500);
    while (std::chrono::steady_clock::now() < stable_deadline) {
        std::string access_bytes;
        if (!live_with_counts(1u) || !complete_origin_episode_is_exact(backend) ||
            !backend.response_peer_closed.load(std::memory_order_acquire) ||
            backend.response_peer_unexpected_data.load(std::memory_order_acquire) ||
            backend.response_peer_observation_failed.load(std::memory_order_acquire) ||
            !read_request_length_fixed_body_access(temp.rut_access_log, access_bytes, error) ||
            !validate_request_length_fixed_body_access(access_bytes, error)) {
            if (error.empty()) error = "#367 generated-RUT live evidence was not stable";
            return false;
        }
        usleep(5000);
    }
    if (!stop_child(runtime.child) || !runtime.child.status_valid ||
        !WIFEXITED(runtime.child.status) || WEXITSTATUS(runtime.child.status) != 0) {
        error = "#367 generated RUT did not shut down cleanly";
        return false;
    }
    backend.stop();
    backend_guard.recorder = nullptr;
    std::string final_access;
    std::string runtime_log;
    if (backend.thread_alive.load(std::memory_order_acquire) ||
        backend.listener_failed.load(std::memory_order_acquire) ||
        !complete_origin_episode_is_exact(backend) || backend.history.size() != 1u ||
        backend.history[0] != expected_wire ||
        !backend.response_peer_closed.load(std::memory_order_acquire) ||
        backend.response_peer_unexpected_data.load(std::memory_order_acquire) ||
        backend.response_peer_observation_failed.load(std::memory_order_acquire) ||
        !read_request_length_fixed_body_access(temp.rut_access_log, final_access, error) ||
        !validate_request_length_fixed_body_access(final_access, error) ||
        !read_exact_return204_log(
            temp.rut_log, "#367 generated RUT runtime log", runtime_log, error) ||
        !validate_rut_exact_ipv4_runtime_log(runtime_log, temp.source, frontend_port, error)) {
        if (error.empty()) error = "#367 generated-RUT final lifecycle evidence was not exact";
        return false;
    }
    return true;
}

