static std::string make_rut_initial_header_split_source(u16 frontend_port,
                                                        u16 backend_port,
                                                        const std::string& access_path) {
    return "accessLog {\n"
           "  path: \"" +
           access_path +
           "\",\n"
           "  format: downstreamRequestBytes,\n"
           "  publication: live\n"
           "}\n"
           "listen 127.0.0.1:" +
           std::to_string(frontend_port) +
           "\n"
           "upstream issue371_backend at \"127.0.0.1:" +
           std::to_string(backend_port) +
           "\"\n"
           R"rut(route GET "/" {
  return forward(issue371_backend,
    request_policy: { version: "HTTP/1.1", host: "upstream", connection: "omit",
      strip_headers: ["Connection", "Keep-Alive", "TE", "Expect", "Upgrade"] },
    response_policy: { version: "HTTP/1.1", framing: "content_length",
      connection: "request", server: "rut-stage4", date: "current",
      hide_headers: ["Date", "Server"] })
}
)rut";
}

static bool validate_rut_initial_header_split_source(const std::string& source,
                                                     u16 frontend_port,
                                                     u16 backend_port,
                                                     const std::string& access_path,
                                                     std::string& error) {
    const std::string expected =
        make_rut_initial_header_split_source(frontend_port, backend_port, access_path);
    const std::string listener = "listen 127.0.0.1:" + std::to_string(frontend_port) + "\n";
    const std::string upstream =
        "upstream issue371_backend at \"127.0.0.1:" + std::to_string(backend_port) + "\"\n";
    const std::string sink = "accessLog {\n  path: \"" + access_path +
                             "\",\n  format: downstreamRequestBytes,\n"
                             "  publication: live\n}\n";
    if (source != expected || source.rfind(sink, 0u) != 0u || count_text(source, sink) != 1u ||
        count_text(source, "accessLog {") != 1u || count_text(source, listener) != 1u ||
        count_text(source, "listen ") != 1u || count_text(source, upstream) != 1u ||
        count_text(source, "upstream ") != 1u || count_text(source, "route GET \"/\" {") != 1u ||
        count_text(source, "route ") != 1u ||
        count_text(source, "return forward(issue371_backend,") != 1u ||
        count_text(source, "format: downstreamRequestBytes") != 1u ||
        count_text(source, "publication: live") != 1u ||
        count_text(source, "host: \"upstream\"") != 1u ||
        count_text(source, "connection: \"omit\"") != 1u ||
        count_text(source, "framing: \"content_length\"") != 1u ||
        count_text(source, "connection: \"request\"") != 1u ||
        count_text(source, "server: \"rut-stage4\"") != 1u ||
        count_text(source, "date: \"current\"") != 1u ||
        source.find("log_format") != std::string::npos ||
        source.find("access_log") != std::string::npos ||
        source.find("--access-log") != std::string::npos ||
        source.find("server {") != std::string::npos ||
        source.find("http {") != std::string::npos) {
        error = "#371 hand-authored ordinary-RUT source inventory was not exact";
        return false;
    }
    return true;
}

static bool validate_rut_initial_header_split_quiet(std::chrono::milliseconds quiet_elapsed,
                                                    bool child_live,
                                                    bool recorder_live,
                                                    u32 accepted,
                                                    u32 requests,
                                                    u32 response_sends,
                                                    bool access_quiet,
                                                    bool client_quiet,
                                                    std::string& error) {
    std::string detail;
    if (!validate_request_length_split_header(kRequestLengthSplitHeaderFirstSend,
                                              kRequestLengthSplitHeaderSecondSend,
                                              quiet_elapsed,
                                              child_live,
                                              recorder_live,
                                              accepted,
                                              requests,
                                              response_sends,
                                              access_quiet,
                                              client_quiet,
                                              detail)) {
        error = "#371 exact delayed initial-header split or final quiet snapshot failed";
        return false;
    }
    return true;
}

static bool run_rut_initial_header_split_self_checks(std::string& error) {
    if (!run_request_length_split_header_self_checks(error)) return false;
    static constexpr u16 kFrontend = 18080u;
    static constexpr u16 kBackend = 9000u;
    static constexpr char kAccess[] = "/tmp/rut-371/access.log";
    const std::string source = make_rut_initial_header_split_source(kFrontend, kBackend, kAccess);
    if (!validate_rut_initial_header_split_source(source, kFrontend, kBackend, kAccess, error))
        return false;
    const std::pair<const char*, const char*> mutations[] = {
        {"format: downstreamRequestBytes", "format: legacy"},
        {"publication: live", "publication: periodic"},
        {"listen 127.0.0.1:18080", "listen :18080"},
        {"127.0.0.1:9000", "127.0.0.1:9001"},
        {"route GET \"/\"", "route POST \"/\""},
        {"host: \"upstream\"", "host: \"preserve\""},
        {"connection: \"omit\"", "connection: \"close\""},
        {"framing: \"content_length\"", "framing: \"close\""},
        {"server: \"rut-stage4\"", "server: \"changed\""},
        {"date: \"current\"", "date: \"omit\""},
        {"hide_headers: [\"Date\", \"Server\"]", "hide_headers: [\"Date\"]"},
    };
    for (const auto& mutation : mutations) {
        std::string changed = source;
        const size_t at = changed.find(mutation.first);
        if (at == std::string::npos ||
            changed.find(mutation.first, at + strlen(mutation.first)) != std::string::npos) {
            error = "#371 source mutation target was absent or ambiguous";
            return false;
        }
        changed.replace(at, strlen(mutation.first), mutation.second);
        std::string detail;
        if (validate_rut_initial_header_split_source(
                changed, kFrontend, kBackend, kAccess, detail)) {
            error = "#371 source validator accepted a sink/listener/route/policy mutation";
            return false;
        }
    }
    for (const std::string& changed :
         {source + "listen 127.0.0.1:18081\n", source + "route GET \"/x\" { return 204 }\n"}) {
        std::string detail;
        if (validate_rut_initial_header_split_source(
                changed, kFrontend, kBackend, kAccess, detail)) {
            error = "#371 source validator accepted an extra listener/route";
            return false;
        }
    }
    std::string detail;
    if (!validate_request_length_access_bytes("102\n", detail)) {
        error = "#371 exact SourceLive access self-check rejected `102\\n`";
        return false;
    }
    for (const char* access : {"66\n", "101\n", "102", "102\n102\n"}) {
        detail.clear();
        if (validate_request_length_access_bytes(access, detail)) {
            error = "#371 SourceLive access self-check accepted a semantic mutation";
            return false;
        }
    }
    const std::string expected_upstream =
        "GET /ledger?q=raw HTTP/1.1\r\nHost: 127.0.0.1:9000\r\nX-Test: keep\r\n\r\n";
    if (expected_upstream.size() != 66u ||
        strlen(kRutInitialHeaderSplitResponseNormalized) != 116u ||
        count_text(expected_upstream, "Host: 127.0.0.1:9000\r\n") != 1u ||
        count_text(expected_upstream, "X-Test: keep\r\n") != 1u ||
        expected_upstream.find("Connection:") != std::string::npos ||
        expected_upstream.find("client.example") != std::string::npos) {
        error = "#371 exact upstream/response wire self-check failed";
        return false;
    }
    if (!validate_rut_initial_header_split_quiet(
            std::chrono::milliseconds(500), true, true, 0u, 0u, 0u, true, true, error))
        return false;
    return true;
}

static bool run_rut_initial_header_split_public(TempDir& temp,
                                                const char* rut_path,
                                                std::string& error) {
    if (rut_path == nullptr || rut_path[0] != '/' || access(rut_path, X_OK) != 0) {
        error = "#371 public witness requires an executable absolute RUT path";
        return false;
    }
    HeldLoopbackPorts reservations;
    u16 frontend_port = 0u;
    u16 backend_port = 0u;
    if (!reservations.reserve(0u, frontend_port) ||
        !reservations.reserve_four_digit(1u, backend_port) || frontend_port == backend_port ||
        !validate_held_loopback_port(
            reservations.fds[0], frontend_port, "#371 RUT frontend handoff", error) ||
        !validate_held_loopback_port(
            reservations.fds[1], backend_port, "#371 Recorder handoff", error)) {
        if (error.empty()) error = "#371 could not hold distinct exact-loopback/P4 ports";
        return false;
    }
    const std::string source =
        make_rut_initial_header_split_source(frontend_port, backend_port, temp.rut_access_log);
    if (!validate_rut_initial_header_split_source(
            source, frontend_port, backend_port, temp.rut_access_log, error) ||
        !write_file(temp.source, source.data(), source.size())) {
        if (error.empty()) error = "#371 could not persist exact hand-authored ordinary RUT";
        return false;
    }
    std::string persisted;
    if (!read_exact_return204_log(temp.source, "#371 persisted ordinary RUT", persisted, error) ||
        !validate_rut_initial_header_split_source(
            persisted, frontend_port, backend_port, temp.rut_access_log, error))
        return false;
    persisted.clear();
    persisted.shrink_to_fit();

    struct RecorderGuard {
        Recorder* recorder;
        ~RecorderGuard() {
            if (recorder != nullptr) recorder->stop();
        }
    };
    Recorder backend;
    RecorderGuard backend_guard{&backend};
    backend.wait_response_peer_close = true;
    backend.observe_extra_requests_until_stop = true;
    if (!handoff_held_loopback_port(
            &reservations.fds[1], backend_port, "#371 Recorder bind", error) ||
        !backend.setup(backend_port, 1u, kBackendResponse, sizeof(kBackendResponse) - 1u)) {
        if (error.empty()) error = "#371 Recorder could not bind the held P4 backend";
        return false;
    }
    const auto recorder_deadline = std::chrono::steady_clock::now() + std::chrono::seconds(2);
    while ((!backend.running.load(std::memory_order_acquire) ||
            !backend.thread_alive.load(std::memory_order_acquire)) &&
           std::chrono::steady_clock::now() < recorder_deadline) {
        if (backend.listener_failed.load(std::memory_order_acquire)) break;
        usleep(1000);
    }
    if (!backend.running.load(std::memory_order_acquire) ||
        !backend.thread_alive.load(std::memory_order_acquire) ||
        backend.listener_failed.load(std::memory_order_acquire)) {
        error = "#371 Recorder was not live before public runtime handoff";
        return false;
    }

    ChildGuard runtime;
    if (!handoff_held_loopback_port(
            &reservations.fds[0], frontend_port, "#371 public RUT bind", error) ||
        !spawn_child({rut_path, temp.source, "--shards", "1", "--no-pin", "--drain", "0"},
                     temp.rut_log,
                     runtime.child) ||
        !wait_ready(frontend_port, runtime.child, error)) {
        if (error.empty()) error = "#371 ordinary RUT failed before public readiness";
        return false;
    }
    static constexpr char kPoison[] = "invalid-after-owned-issue371-source-load\n";
    std::string overwritten;
    if (!write_file(temp.source, kPoison, sizeof(kPoison) - 1u) ||
        !read_exact_return204_log(temp.source, "#371 overwritten source", overwritten, error) ||
        overwritten != kPoison || poll_child(runtime.child)) {
        if (error.empty()) error = "#371 runtime did not retain its loaded source after overwrite";
        return false;
    }
    const auto child_live = [&]() { return !poll_child(runtime.child); };
    const auto recorder_live = [&]() {
        return backend.running.load(std::memory_order_acquire) &&
               backend.thread_alive.load(std::memory_order_acquire) &&
               !backend.listener_failed.load(std::memory_order_acquire);
    };
    const auto exact_atomic_counts = [&](u32 expected) {
        return backend.accepted.load(std::memory_order_acquire) == expected &&
               backend.requests.load(std::memory_order_acquire) == expected &&
               backend.response_send_all_calls.load(std::memory_order_acquire) == expected;
    };
    const auto pre_request_deadline =
        std::chrono::steady_clock::now() + std::chrono::milliseconds(150);
    while (std::chrono::steady_clock::now() < pre_request_deadline) {
        std::string access_bytes;
        if (!child_live() || !recorder_live() || !exact_atomic_counts(0u) ||
            !read_request_length_access_file(temp.rut_access_log, access_bytes, error) ||
            !access_bytes.empty()) {
            if (error.empty()) error = "#371 pre-request runtime/backend/access was not quiet";
            return false;
        }
        usleep(5000);
    }

    struct ClientGuard {
        int fd = -1;
        ~ClientGuard() {
            if (fd >= 0) close(fd);
        }
    } client{connect_once(frontend_port)};
    if (client.fd < 0 || !send_all(client.fd,
                                   kRequestLengthSplitHeaderFirstSend,
                                   sizeof(kRequestLengthSplitHeaderFirstSend) - 1u)) {
        error = "#371 client connect or exact 45-byte first application send failed";
        return false;
    }
    const auto quiet_started = std::chrono::steady_clock::now();
    const auto quiet_deadline = quiet_started + std::chrono::milliseconds(500);
    for (;;) {
        std::string access_bytes;
        if (!child_live() || !recorder_live() || !exact_atomic_counts(0u) ||
            !read_request_length_access_file(temp.rut_access_log, access_bytes, error) ||
            !access_bytes.empty() ||
            !observe_client_open_and_quiet_nonconsuming(client.fd, 25, error)) {
            if (error.empty())
                error = "#371 incomplete-header runtime/backend/access/client was not quiet";
            return false;
        }
        if (std::chrono::steady_clock::now() >= quiet_deadline) break;
    }

    // Mandatory final causal snapshot: access, non-consuming client peek,
    // then child/Recorder liveness and atomic counters last. The suffix is
    // sent immediately after these actual witnesses validate.
    std::string final_quiet_access_bytes;
    const bool final_access_quiet =
        read_request_length_access_file(temp.rut_access_log, final_quiet_access_bytes, error) &&
        final_quiet_access_bytes.empty();
    const bool final_client_quiet = observe_client_open_and_quiet_nonconsuming(client.fd, 0, error);
    const bool final_child_live = child_live();
    const bool final_recorder_live = recorder_live();
    const u32 final_accepted = backend.accepted.load(std::memory_order_acquire);
    const u32 final_requests = backend.requests.load(std::memory_order_acquire);
    const u32 final_response_sends =
        backend.response_send_all_calls.load(std::memory_order_acquire);
    const auto quiet_elapsed = std::chrono::duration_cast<std::chrono::milliseconds>(
        std::chrono::steady_clock::now() - quiet_started);
    if (!validate_rut_initial_header_split_quiet(quiet_elapsed,
                                                 final_child_live,
                                                 final_recorder_live,
                                                 final_accepted,
                                                 final_requests,
                                                 final_response_sends,
                                                 final_access_quiet,
                                                 final_client_quiet,
                                                 error) ||
        !send_all(client.fd,
                  kRequestLengthSplitHeaderSecondSend,
                  sizeof(kRequestLengthSplitHeaderSecondSend) - 1u)) {
        if (error.empty()) error = "#371 exact 57-byte suffix application send failed";
        return false;
    }

    std::vector<char> response;
    if (!read_response(client.fd, response, error) || !read_eof(client.fd, error) ||
        !validate_exact_normalized_response(
            response, kRutInitialHeaderSplitResponseNormalized, error)) {
        if (error.empty()) error = "#371 exact 116-byte response/EOF episode failed";
        return false;
    }
    close(client.fd);
    client.fd = -1;
    if (!wait_for_live_complete_origin_episode(backend, runtime.child, "#371 ordinary RUT", error))
        return false;
    const u64 response_sent_ns = backend.response_sent_ns.load(std::memory_order_acquire);
    const u64 response_peer_closed_ns =
        backend.response_peer_closed_ns.load(std::memory_order_acquire);
    if (!child_live() || !recorder_live() || !exact_atomic_counts(1u) || response_sent_ns == 0u ||
        !backend.response_peer_closed.load(std::memory_order_acquire) ||
        response_peer_closed_ns < response_sent_ns ||
        response_peer_closed_ns - response_sent_ns > 2'000'000'000ull ||
        backend.response_peer_unexpected_data.load(std::memory_order_acquire) ||
        backend.response_peer_observation_failed.load(std::memory_order_acquire)) {
        error = "#371 origin lacked prompt live peer-close/no-late-byte evidence";
        return false;
    }

    static constexpr char kExpectedAccess[] = "102\n";
    const auto access_deadline = std::chrono::steady_clock::now() + std::chrono::seconds(2);
    for (;;) {
        std::string access_bytes;
        if (!child_live() || !recorder_live() || !exact_atomic_counts(1u) ||
            !read_request_length_access_file(temp.rut_access_log, access_bytes, error)) {
            if (error.empty()) error = "#371 failed while awaiting live SourceLive publication";
            return false;
        }
        if (access_bytes.size() > sizeof(kExpectedAccess) - 1u ||
            std::string_view(kExpectedAccess, sizeof(kExpectedAccess) - 1u)
                    .substr(0u, access_bytes.size()) != access_bytes) {
            error = "#371 live access escaped the exact `102\\n` prefix set";
            return false;
        }
        if (access_bytes.size() == sizeof(kExpectedAccess) - 1u) break;
        if (std::chrono::steady_clock::now() >= access_deadline) {
            error = "#371 live `102\\n` access record was not visible before shutdown";
            return false;
        }
        usleep(1000);
    }
    const auto stable_deadline = std::chrono::steady_clock::now() + std::chrono::milliseconds(500);
    while (std::chrono::steady_clock::now() < stable_deadline) {
        std::string access_bytes;
        const u64 stable_sent_ns = backend.response_sent_ns.load(std::memory_order_acquire);
        const u64 stable_closed_ns =
            backend.response_peer_closed_ns.load(std::memory_order_acquire);
        if (!child_live() || !recorder_live() || !exact_atomic_counts(1u) ||
            stable_sent_ns != response_sent_ns || stable_closed_ns != response_peer_closed_ns ||
            !backend.response_peer_closed.load(std::memory_order_acquire) ||
            backend.response_peer_unexpected_data.load(std::memory_order_acquire) ||
            backend.response_peer_observation_failed.load(std::memory_order_acquire) ||
            !read_request_length_access_file(temp.rut_access_log, access_bytes, error) ||
            !validate_request_length_access_bytes(access_bytes, error)) {
            if (error.empty()) error = "#371 live completion/access evidence was not stable";
            return false;
        }
        usleep(5000);
    }

    if (!stop_child(runtime.child) || !runtime.child.status_valid ||
        !WIFEXITED(runtime.child.status) || WEXITSTATUS(runtime.child.status) != 0) {
        error = "#371 public RUT did not stop normally with exit status 0";
        return false;
    }
    backend.stop();
    backend_guard.recorder = nullptr;
    const std::string expected_upstream =
        "GET /ledger?q=raw HTTP/1.1\r\nHost: 127.0.0.1:" + std::to_string(backend_port) +
        "\r\nX-Test: keep\r\n\r\n";
    const std::vector<char> expected_wire(expected_upstream.begin(), expected_upstream.end());
    const std::string actual =
        backend.history.size() == 1u
            ? std::string(backend.history[0].begin(), backend.history[0].end())
            : std::string{};
    std::string final_access;
    std::string runtime_log;
    if (backend.thread_alive.load(std::memory_order_acquire) ||
        backend.listener_failed.load(std::memory_order_acquire) ||
        !complete_origin_episode_is_exact(backend) || backend.history.size() != 1u ||
        backend.request != expected_wire || backend.history[0] != expected_wire ||
        expected_upstream.size() != 66u ||
        sizeof(kRequestLengthOracleClientRequest) - 1u == expected_upstream.size() ||
        count_text(actual, "Host: 127.0.0.1:") != 1u ||
        count_text(actual, "X-Test: keep\r\n") != 1u ||
        actual.find("client.example") != std::string::npos ||
        actual.find("Connection:") != std::string::npos || actual.find('\t') != std::string::npos ||
        !backend.response_peer_closed.load(std::memory_order_acquire) ||
        backend.response_peer_unexpected_data.load(std::memory_order_acquire) ||
        backend.response_peer_observation_failed.load(std::memory_order_acquire) ||
        !read_request_length_access_file(temp.rut_access_log, final_access, error) ||
        !validate_request_length_access_bytes(final_access, error) ||
        !read_exact_return204_log(
            temp.rut_log, "#371 public RUT runtime log", runtime_log, error) ||
        !validate_rut_exact_ipv4_runtime_log(runtime_log, temp.source, frontend_port, error)) {
        if (!backend.history.empty()) dump_wire("#371 actual backend wire", backend.history[0]);
        if (error.empty()) error = "#371 final upstream/access/lifecycle evidence was not exact";
        return false;
    }
    return true;
}

struct ProxyHideHeaderGeneratedSourceEvidence {
    std::string fragment;
    std::string source;
    std::string order;
    u16 frontend_port = 0u;
    u16 backend_port = 0u;
};

static bool validate_proxy_hide_header_generated_source(const std::string& source,
                                                        u16 frontend_port,
                                                        u16 backend_port,
                                                        std::string& error) {
    const std::string listener = "listen 127.0.0.1:" + std::to_string(frontend_port) + "\n";
    const std::string upstream =
        "upstream nginx_upstream at \"127.0.0.1:" + std::to_string(backend_port) + "\"\n";
    const std::string four_headers =
        "hide_headers: [\"Date\", \"Server\", \"X-Pad\", \"X-Compat-Hidden\"]";
    const std::string three_headers = "hide_headers: [\"Date\", \"Server\", \"X-Pad\"]";
    const u32 routes =
        (source.rfind("route ", 0u) == 0u ? 1u : 0u) + count_text(source, "\nroute ");
    const u32 forwards = count_text(source, "return forward(nginx_upstream");
    if (source.empty() || source.size() != 5366u || source.find('\0') != std::string::npos ||
        source.size() + 1u > rut::nginx::RutSource::kCapacity ||
        rut::nginx::RutSource::kCapacity - source.size() - 1u != 1661u ||
        count_text(source, listener) != 1u || count_text(source, upstream) != 1u || routes != 3u ||
        forwards != 3u || count_text(source, "route HEAD \"/\" {") != 1u ||
        count_text(source, "route GET \"/\" {") != 1u ||
        count_text(source, "route \"/\" {") != 1u || count_text(source, "return redirect(") != 0u ||
        count_text(source, four_headers) != 3u || count_text(source, "X-Compat-Hidden") != 3u ||
        count_text(source, three_headers) != 0u ||
        source.find("target_transform") != std::string::npos ||
        source.find("strip_prefix") != std::string::npos ||
        source.find("replace_prefix") != std::string::npos ||
        source.find("proxy_hide_header") != std::string::npos ||
        source.find("nginx.conf") != std::string::npos ||
        source.find("nginx::") != std::string::npos ||
        source.find("nginx_compat") != std::string::npos ||
        source.find("workaround") != std::string::npos ||
        source.find("accessLog") != std::string::npos) {
        error = "#373 generated source failed exact 5366-byte policy/route/ownership validation";
        return false;
    }
    return true;
}

static bool validate_proxy_hide_header_generated_model(const std::string& fragment,
                                                       u16 frontend_port,
                                                       u16 backend_port,
                                                       bool listen_first,
                                                       std::string& source,
                                                       std::string& error) {
    if (fragment.empty() ||
        fragment != make_static_query_proxy_fragment(
                        frontend_port, backend_port, listen_first, kProxyHideHeaderOracleProfile)) {
        error = "#373 fragment was not the exact side-specific declaration order";
        return false;
    }
    const auto parsed = rut::nginx::parse({fragment.data(), static_cast<u32>(fragment.size())});
    if (!parsed) {
        error = "#373 exact fragment failed genuine nginx parsing";
        return false;
    }
    const auto& server = parsed.value();
    const auto& location = server.location;
    const auto& proxy = location.proxy_pass;
    const auto& hidden = location.proxy_hide_header;
    const uintptr_t base = reinterpret_cast<uintptr_t>(fragment.data());
    const auto borrowed = [&](rut::Str value, rut::Span span) {
        return value.ptr != nullptr && span.end >= span.start &&
               span.end - span.start == value.len &&
               reinterpret_cast<uintptr_t>(value.ptr) == base + span.start;
    };
    const std::string listen_value = "127.0.0.1:" + std::to_string(frontend_port);
    const auto lowered = rut::nginx::lower_to_rut(server);
    if (server.listen.address != rut::ListenerAddress::IPv4Exact ||
        server.listen.ipv4_host != 0x7f000001u || server.listen.port != frontend_port ||
        !server.listen.value.eq({listen_value.data(), static_cast<u32>(listen_value.size())}) ||
        !borrowed(server.listen.value, server.listen.value_span) ||
        !location.path.eq(rut::lit_str("/")) || !borrowed(location.path, location.path_span) ||
        proxy.has_uri || proxy.uri.ptr != nullptr || proxy.uri.len != 0u ||
        proxy.uri_span.start != 0u || proxy.uri_span.end != 0u || proxy.port != backend_port ||
        proxy.address[0] != 127u || proxy.address[1] != 0u || proxy.address[2] != 0u ||
        proxy.address[3] != 1u || location.proxy_read_timeout.present ||
        location.proxy_read_timeout.milliseconds != 0u || server.exact_local_return.present ||
        server.exact_no_content_return.present || server.exact_absolute_redirect.present ||
        !hidden.present ||
        server.pre_route_trace.profile !=
            rut::nginx::ImplicitPreRouteProfile::Nginx1297PreLocationTrace405 ||
        server.pre_route_trace.span.start != server.span.start ||
        server.pre_route_trace.span.end != server.span.end ||
        server.pre_route_trace.span.line != server.span.line ||
        server.pre_route_trace.span.col != server.span.col ||
        !hidden.name.eq(rut::lit_str("X-Compat-Hidden")) ||
        !borrowed(hidden.name, hidden.name_span) || hidden.span.end <= hidden.span.start ||
        hidden.name_span.start < hidden.span.start || hidden.name_span.end >= hidden.span.end ||
        hidden.span.end > fragment.size() ||
        fragment.compare(hidden.span.start, 17u, "proxy_hide_header") != 0 ||
        fragment[hidden.span.end - 1u] != ';' || !lowered) {
        error =
            "#373 parsed model lost exact listener/root/no-URI/hidden provenance or admitted an "
            "action/timeout";
        return false;
    }
    const rut::Str output = lowered.value().view();
    if (output.ptr == nullptr || output.len == 0u ||
        output.len >= rut::nginx::RutSource::kCapacity || output.ptr[output.len] != '\0') {
        error = "#373 lower result lacked a safe terminal NUL and usable length";
        return false;
    }
    source.assign(output.ptr, output.len);
    return validate_proxy_hide_header_generated_source(source, frontend_port, backend_port, error);
}

static bool build_proxy_hide_header_generated_source(
    u16 frontend_port,
    u16 backend_port,
    bool listen_first,
    ProxyHideHeaderGeneratedSourceEvidence& evidence,
    std::string& error) {
    evidence = ProxyHideHeaderGeneratedSourceEvidence{};
    evidence.order = listen_first ? "listen-first" : "location-first";
    evidence.frontend_port = frontend_port;
    evidence.backend_port = backend_port;
    evidence.fragment = make_static_query_proxy_fragment(
        frontend_port, backend_port, listen_first, kProxyHideHeaderOracleProfile);
    if (!validate_proxy_hide_header_generated_model(
            evidence.fragment, frontend_port, backend_port, listen_first, evidence.source, error))
        return false;
    if (evidence.source.empty() || evidence.source == evidence.fragment) {
        error = "#373 lower result did not produce distinct ordinary-RUT source bytes";
        return false;
    }
    return true;
}

static bool run_proxy_hide_header_source_self_checks(std::string& error) {
    static constexpr u16 kPorts[4] = {8080u, 9000u, 8081u, 9001u};
    ProxyHideHeaderGeneratedSourceEvidence evidence[2];
    if (!build_proxy_hide_header_generated_source(kPorts[0], kPorts[1], true, evidence[0], error)) {
        if (error.empty()) error = "#373 first generated source build failed without detail";
        return false;
    }
    if (!build_proxy_hide_header_generated_source(
            kPorts[2], kPorts[3], false, evidence[1], error)) {
        if (error.empty()) error = "#373 second generated source build failed without detail";
        return false;
    }
    // Individual endpoint validation must precede this normalization.
    std::string canonical[2] = {evidence[0].source, evidence[1].source};
    const bool canonicalized =
        canonicalize_unique_port(canonical[0],
                                 "listen 127.0.0.1:" + std::to_string(kPorts[0]) + "\n",
                                 "listen 127.0.0.1:FRONTEND\n") &&
        canonicalize_unique_port(
            canonical[0],
            "upstream nginx_upstream at \"127.0.0.1:" + std::to_string(kPorts[1]) + "\"\n",
            "upstream nginx_upstream at \"127.0.0.1:BACKEND\"\n") &&
        canonicalize_unique_port(canonical[1],
                                 "listen 127.0.0.1:" + std::to_string(kPorts[2]) + "\n",
                                 "listen 127.0.0.1:FRONTEND\n") &&
        canonicalize_unique_port(
            canonical[1],
            "upstream nginx_upstream at \"127.0.0.1:" + std::to_string(kPorts[3]) + "\"\n",
            "upstream nginx_upstream at \"127.0.0.1:BACKEND\"\n");
    if (!canonicalized || canonical[0] != canonical[1]) {
        error = "#373 independently lowered declaration orders did not canonicalize equally";
        return false;
    }
    const auto reject_fragment = [&](std::string candidate, bool order, const char* label) {
        if (candidate == evidence[order ? 0u : 1u].fragment) {
            error = std::string("#373 mutation did not change fixture: ") + label;
            return false;
        }
        std::string ignored;
        std::string detail;
        const bool accepted =
            validate_proxy_hide_header_generated_model(candidate,
                                                       order ? kPorts[0] : kPorts[2],
                                                       order ? kPorts[1] : kPorts[3],
                                                       order,
                                                       ignored,
                                                       detail);
        if (accepted) {
            error = std::string("#373 fragment mutation accepted: ") + label;
            return false;
        }
        return true;
    };
    std::string candidate = evidence[0].fragment;
    const std::string hide = "proxy_hide_header X-Compat-Hidden;";
    const size_t hide_at = candidate.find(hide);
    if (hide_at == std::string::npos) {
        error = "#373 hide mutation fixture missing directive";
        return false;
    }
    if (!reject_fragment(candidate.substr(0u, hide_at) + candidate.substr(hide_at + hide.size()),
                         true,
                         "missing-hide") ||
        !reject_fragment(evidence[0].fragment + "\n", true, "length-change") ||
        !reject_fragment(
            std::string("server { proxy_hide_header X-Compat-Hidden; }\n") + evidence[0].fragment,
            true,
            "wrong-context") ||
        !reject_fragment(std::string(evidence[0].fragment)
                             .replace(hide_at, hide.size(), "proxy_hide_header X-Compat-Visible;"),
                         true,
                         "renamed-hide"))
        return false;
    candidate = evidence[1].fragment;
    const size_t hide2 = candidate.find(hide);
    if (!reject_fragment(candidate.substr(0u, hide2) + hide + candidate.substr(hide2),
                         false,
                         "duplicate-hide") ||
        !reject_fragment(candidate.substr(0u, hide2) + "proxy_hide_header X-Compat-Hidden;\n" +
                             candidate.substr(hide2),
                         false,
                         "moved-hide"))
        return false;
    const auto reject_source = [&](std::string changed, size_t side, const char* label) {
        if (changed == evidence[side].source) {
            error = std::string("#373 source mutation unchanged: ") + label;
            return false;
        }
        std::string detail;
        if (validate_proxy_hide_header_generated_source(
                changed, evidence[side].frontend_port, evidence[side].backend_port, detail)) {
            error = std::string("#373 source mutation accepted: ") + label;
            return false;
        }
        return true;
    };
    candidate = evidence[0].source;
    std::string redirect_mutation = evidence[0].source;
    const size_t body_at = redirect_mutation.find("body: b\"");
    if (body_at == std::string::npos) {
        error = "#373 redirect mutation fixture lacked a body";
        return false;
    }
    redirect_mutation += "\nreturn redirect(nginx_upstream)";
    redirect_mutation.erase(body_at + strlen("body: b\""),
                            strlen("\nreturn redirect(nginx_upstream)"));
    if (redirect_mutation.size() != evidence[0].source.size() ||
        count_text(redirect_mutation, "return forward(nginx_upstream") != 3u ||
        count_text(redirect_mutation, "return redirect(") != 1u ||
        !reject_source(std::move(redirect_mutation), 0u, "equal-length-redirect"))
        return false;
    if (!reject_source(candidate + "\n", 0u, "source-length") ||
        !reject_source(std::string(evidence[0].source)
                           .replace(evidence[0].source.find("X-Compat-Hidden"),
                                    strlen("X-Compat-Hidden"),
                                    "X-Compat-Visible"),
                       0u,
                       "wrong-case-name") ||
        !reject_source(
            std::string(evidence[0].source)
                .replace(
                    evidence[0].source.find(
                        "hide_headers: [\"Date\", \"Server\", \"X-Pad\", \"X-Compat-Hidden\"]"),
                    strlen("hide_headers: [\"Date\", \"Server\", \"X-Pad\", \"X-Compat-Hidden\"]"),
                    "hide_headers: [\"Date\", \"Server\", \"X-Pad\"]"),
            0u,
            "missing-fourth-header") ||
        !reject_source(evidence[0].source + "proxy_hide_header nginx.conf accessLog",
                       0u,
                       "injected-nginx-hook"))
        return false;
    std::string endpoint = evidence[0].source;
    const std::string listener = "listen 127.0.0.1:" + std::to_string(kPorts[0]);
    const std::string backend = "127.0.0.1:" + std::to_string(kPorts[1]);
    if (!reject_source(
            std::string(endpoint).replace(endpoint.find(listener),
                                          listener.size(),
                                          "listen 127.0.0.1:" + std::to_string(kPorts[1])),
            0u,
            "endpoint-swap") ||
        !reject_source(std::string(endpoint).replace(
                           endpoint.find(backend), backend.size(), backend + backend),
                       0u,
                       "endpoint-duplicate"))
        return false;
    const auto reject_unique_source_mutation =
        [&](const std::string& needle, const std::string& replacement, const char* label) {
            std::string changed = evidence[0].source;
            const size_t at = changed.find(needle);
            if (needle.empty() || at == std::string::npos) {
                error = std::string("#373 source mutation precondition failed: ") + label;
                return false;
            }
            changed.replace(at, needle.size(), replacement);
            return reject_source(std::move(changed), 0u, label);
        };
    if (!reject_unique_source_mutation(
            "route HEAD \"/\" {", "route GET \"/\" {", "missing-head-route") ||
        !reject_unique_source_mutation(
            "route GET \"/\" {", "route GET \"/\" {\nroute GET \"/\" {", "duplicate-get-route") ||
        !reject_unique_source_mutation("return forward(nginx_upstream",
                                       "return redirect(nginx_upstream",
                                       "unexpected-redirect") ||
        !reject_unique_source_mutation(
            "hide_headers: [\"Date\", \"Server\", \"X-Pad\", \"X-Compat-Hidden\"]",
            "hide_headers: [\"Date\", \"Server\", \"X-Pad\", \"X-Compat-Hidden\", "
            "\"X-Compat-Hidden\"]",
            "duplicate-fourth-header") ||
        !reject_unique_source_mutation(
            "hide_headers: [\"Date\", \"Server\", \"X-Pad\", \"X-Compat-Hidden\"]",
            "hide_headers: [\"Date\", \"X-Compat-Hidden\", \"Server\", \"X-Pad\"]",
            "reordered-header-list") ||
        !reject_unique_source_mutation("X-Compat-Hidden", "x-compat-hidden", "wrong-case-header") ||
        !reject_unique_source_mutation(
            "route HEAD \"/\" {", "route HEAD \"/extra\" {", "route-target-mismatch") ||
        !reject_unique_source_mutation("response_policy: {",
                                       "response_policy: {\n            strip_prefix: \"/\",",
                                       "unexpected-strip-transform") ||
        !reject_unique_source_mutation("route \"/\" {", "route \"/x\" {", "any-route-mismatch") ||
        !reject_fragment(evidence[1].fragment, true, "cross-order-fragment") ||
        !reject_fragment(
            std::string("server { listen 127.0.0.1:8080; return 204; }\n") + evidence[0].fragment,
            true,
            "wrong-context-action"))
        return false;
    return true;
}

// #373 Stage 4b1 is intentionally a one-side witness.  Keep its observation
// independent from the broad static-query oracle: this is the exact root
// proxy/header slice and has no access sink or nginx runtime hook.
struct ProxyHideHeaderGeneratedObservation {
    std::string temp_path;
    std::string fragment;
    std::string source;
    std::string source_path;
    std::string runtime_log_path;
    std::string access_probe_path;
    std::string rut_executable;
    std::string process_identity;
    std::vector<std::string> process_argv;
    pid_t child_pid = -1;
    std::string order;
    std::string poison;
    std::string runtime_log;
    std::vector<char> response;
    std::vector<std::vector<char>> upstream_history;
    u16 frontend_port = 0u;
    u16 backend_port = 0u;
    u32 accepted = 0u;
    u32 requests = 0u;
    u32 sends = 0u;
    u32 response_peer_close_count = 0u;
    u64 response_sent_ns = 0u;
    u64 response_peer_closed_ns = 0u;
    bool response_peer_closed = false;
    bool response_peer_unexpected_data = false;
    bool response_peer_observation_failed = false;
    bool eof = false;
    bool access_enoent_before = false;
    bool access_enoent_after = false;
    bool access_enoent_final = false;
    bool child_live_after_poison = false;
    bool stable_window = false;
    bool source_poisoned = false;
    bool exited_zero = false;
};

static bool proxy_hide_header_access_is_absent(const std::string& path, std::string& error) {
    errno = 0;
    const int fd = open(path.c_str(), O_RDONLY | O_CLOEXEC);
    if (fd >= 0) {
        close(fd);
        error = "#373 generated side disabled-access probe unexpectedly appeared";
        return false;
    }
    if (errno != ENOENT) {
        error = "#373 generated side disabled-access probe was not ENOENT";
        return false;
    }
    return true;
}

static bool validate_proxy_hide_header_generated_observation(
    const ProxyHideHeaderGeneratedObservation& observation, std::string& error) {
    const std::string expected_poison = "destroyed-after-373-" + observation.order + "-load\n";
    const std::string expected_listener =
        "Listening on port " + std::to_string(observation.frontend_port) + " with 1 shard(s)";
    const bool identities_valid =
        !observation.temp_path.empty() && !observation.source_path.empty() &&
        !observation.runtime_log_path.empty() && !observation.access_probe_path.empty() &&
        !observation.rut_executable.empty() && observation.rut_executable.front() == '/' &&
        observation.child_pid > 0 &&
        observation.process_identity ==
            observation.temp_path + "/rut-pid-" + std::to_string(observation.child_pid) &&
        observation.source_path == observation.temp_path + "/generated.rut" &&
        observation.runtime_log_path == observation.temp_path + "/rut.log" &&
        observation.access_probe_path == observation.temp_path + "/rut-access.log" &&
        observation.process_argv.size() == 7u &&
        observation.process_argv[0] == observation.rut_executable &&
        observation.process_argv[1] == observation.source_path &&
        observation.process_argv[2] == "--shards" && observation.process_argv[3] == "1" &&
        observation.process_argv[4] == "--no-pin" && observation.process_argv[5] == "--drain" &&
        observation.process_argv[6] == "0" &&
        std::find(observation.process_argv.begin(),
                  observation.process_argv.end(),
                  "--access-log") == observation.process_argv.end();
    if (observation.frontend_port < 1024u || observation.frontend_port > 9999u ||
        observation.backend_port < 1024u || observation.backend_port > 9999u ||
        observation.frontend_port == observation.backend_port ||
        (observation.order != "listen-first" && observation.order != "location-first") ||
        observation.fragment !=
            make_static_query_proxy_fragment(observation.frontend_port,
                                             observation.backend_port,
                                             observation.order == "listen-first",
                                             kProxyHideHeaderOracleProfile) ||
        !identities_valid ||
        !validate_proxy_hide_header_generated_source(
            observation.source, observation.frontend_port, observation.backend_port, error) ||
        observation.poison != expected_poison || !observation.source_poisoned ||
        !observation.child_live_after_poison || !observation.access_enoent_before ||
        !observation.access_enoent_after || !observation.access_enoent_final ||
        observation.response.size() != 176u || !observation.eof || observation.accepted != 1u ||
        observation.requests != 1u || observation.sends != 1u ||
        observation.response_peer_close_count != 1u || observation.upstream_history.size() != 1u ||
        observation.response_sent_ns == 0u ||
        observation.response_peer_closed_ns < observation.response_sent_ns ||
        observation.response_peer_closed_ns - observation.response_sent_ns > 2'000'000'000ull ||
        !observation.response_peer_closed || observation.response_peer_unexpected_data ||
        observation.response_peer_observation_failed || !observation.stable_window ||
        !observation.exited_zero) {
        if (error.empty()) error = "#373 generated observation failed lifecycle/inventory checks";
        return false;
    }
    const std::string request = static_query_proxy_request("/", kProxyHideHeaderOracleProfile);
    const std::vector<char> expected_upstream = static_query_expected_upstream(
        "/", observation.backend_port, kProxyHideHeaderOracleProfile);
    std::vector<char> normalized = observation.response;
    const std::string raw(observation.response.begin(), observation.response.end());
    const std::string normalized_text(kProxyHideHeaderResponseNormalized);
    const std::string upstream(observation.upstream_history[0].begin(),
                               observation.upstream_history[0].end());
    if (request.size() != 85u || raw.find("X-Compat-Hidden:") != std::string::npos ||
        raw.find("x-compat-hidden:") != std::string::npos ||
        raw.find("Server: origin\r\n") != std::string::npos ||
        raw.find("Date: Wed, 26 Aug 2026 23:57:18 GMT\r\n") != std::string::npos ||
        !normalize_date(normalized) ||
        std::string(normalized.begin(), normalized.end()) != normalized_text ||
        count_text(raw, "X-Compat-Visible: keep\r\n") != 1u ||
        count_text(raw, "Set-Cookie: a=1\r\n") != 1u ||
        count_text(raw, "Set-Cookie: b=2\r\n") != 1u ||
        raw.find("X-Compat-Visible: keep\r\nSet-Cookie: a=1\r\nSet-Cookie: b=2\r\n") ==
            std::string::npos ||
        observation.upstream_history[0] != expected_upstream || upstream.size() != 66u ||
        count_text(upstream,
                   "Host: 127.0.0.1:" + std::to_string(observation.backend_port) + "\r\n") != 1u ||
        count_text(upstream, "X-Dupe: one\r\n") != 1u ||
        count_text(upstream, "X-Dupe: two\r\n") != 1u ||
        upstream.find("X-Dupe: one\r\nX-Dupe: two\r\n") == std::string::npos ||
        upstream.find("hidden.example") != std::string::npos ||
        upstream.find("Connection:") != std::string::npos ||
        upstream.find("Content-Length:") != std::string::npos ||
        upstream.find("Transfer-Encoding:") != std::string::npos ||
        upstream.rfind("\r\n\r\n") != upstream.size() - 4u) {
        error = "#373 generated observation changed exact request/response header semantics";
        return false;
    }
    const std::string listener = expected_listener;
    if (!parse_exact_return204_runtime_log(
            observation.runtime_log, observation.source_path, listener, error)) {
        error += " actual=" + observation.runtime_log;
        return false;
    }
    return true;
}

static bool capture_proxy_hide_header_generated_side(
    u16 frontend_port,
    u16 backend_port,
    TempDir& temp,
    const char* rut_path,
    bool listen_first,
    ProxyHideHeaderGeneratedObservation& observation,
    std::string& error,
    int* frontend_reservation,
    int* backend_reservation) {
    if (rut_path == nullptr || rut_path[0] != '/' || access(rut_path, X_OK) != 0 ||
        frontend_reservation == nullptr || backend_reservation == nullptr ||
        !validate_held_loopback_port(
            *frontend_reservation, frontend_port, "#373 generated frontend handoff", error) ||
        !validate_held_loopback_port(
            *backend_reservation, backend_port, "#373 generated backend handoff", error)) {
        if (error.empty()) error = "#373 generated side requires executable and held P4 ports";
        return false;
    }
    observation = ProxyHideHeaderGeneratedObservation{};
    observation.temp_path = temp.path;
    observation.frontend_port = frontend_port;
    observation.backend_port = backend_port;
    observation.source_path = temp.source;
    observation.runtime_log_path = temp.rut_log;
    observation.access_probe_path = temp.rut_access_log;
    observation.rut_executable = rut_path;
    observation.order = listen_first ? "listen-first" : "location-first";
    observation.fragment = make_static_query_proxy_fragment(
        frontend_port, backend_port, listen_first, kProxyHideHeaderOracleProfile);

    // Parse and lower the borrowed fragment, then destroy both borrowed input
    // and lower-buffer ownership before persistence.  Stage 4a's exact source
    // validator remains the authority for the 5366-byte output.
    {
        std::string borrowed = observation.fragment;
        const auto parsed = rut::nginx::parse({borrowed.data(), static_cast<u32>(borrowed.size())});
        if (!parsed) {
            error = "#373 generated side failed genuine nginx parsing";
            return false;
        }
        auto lowered = rut::nginx::lower_to_rut(parsed.value());
        if (!lowered) {
            error = "#373 generated side failed genuine nginx lowering";
            return false;
        }
        if (lowered.value().len == 0u || lowered.value().len >= rut::nginx::RutSource::kCapacity ||
            lowered.value().data[lowered.value().len] != '\0') {
            error = "#373 generated side lowering lacked a bounded terminal NUL";
            return false;
        }
        observation.source.assign(lowered.value().data, lowered.value().len);
        if (!validate_proxy_hide_header_generated_source(
                observation.source, frontend_port, backend_port, error))
            return false;
        std::fill(borrowed.begin(), borrowed.end(), 'F');
        std::fill(lowered.value().data, lowered.value().data + lowered.value().len, 'L');
        if (!std::all_of(borrowed.begin(), borrowed.end(), [](char byte) { return byte == 'F'; }) ||
            !std::all_of(lowered.value().data,
                         lowered.value().data + lowered.value().len,
                         [](char byte) { return byte == 'L'; })) {
            error = "#373 generated side ownership poison did not cover every intended byte";
            return false;
        }
        if (!validate_proxy_hide_header_generated_source(
                observation.source, frontend_port, backend_port, error))
            return false;
    }
    if (!write_file(temp.source, observation.source.data(), observation.source.size())) {
        error = "#373 generated side could not persist ordinary source";
        return false;
    }
    std::string persisted;
    if (!read_exact_return204_log(
            temp.source, "#373 persisted generated source", persisted, error) ||
        persisted != observation.source ||
        !validate_proxy_hide_header_generated_source(persisted, frontend_port, backend_port, error))
        return false;
    if (!proxy_hide_header_access_is_absent(temp.rut_access_log, error)) return false;
    observation.access_enoent_before = true;

    struct RecorderGuard {
        Recorder* recorder;
        ~RecorderGuard() {
            if (recorder != nullptr) recorder->stop();
        }
    };
    Recorder backend;
    RecorderGuard backend_guard{&backend};
    backend.wait_response_peer_close = true;
    backend.observe_extra_requests_until_stop = true;
    if (!handoff_held_loopback_port(
            backend_reservation, backend_port, "#373 generated Recorder bind", error) ||
        !backend.setup(backend_port,
                       1u,
                       kProxyHideHeaderOriginResponse,
                       sizeof(kProxyHideHeaderOriginResponse) - 1u)) {
        if (error.empty()) error = "#373 generated Recorder could not bind held backend";
        return false;
    }
    const auto recorder_deadline = std::chrono::steady_clock::now() + std::chrono::seconds(2);
    while ((!backend.running.load(std::memory_order_acquire) ||
            !backend.thread_alive.load(std::memory_order_acquire)) &&
           std::chrono::steady_clock::now() < recorder_deadline)
        usleep(1000);
    if (!backend.running.load(std::memory_order_acquire) ||
        !backend.thread_alive.load(std::memory_order_acquire) ||
        backend.listener_failed.load(std::memory_order_acquire)) {
        error = "#373 generated Recorder was not live before frontend handoff";
        return false;
    }
    observation.process_argv = {rut_path, temp.source, "--shards", "1", "--no-pin", "--drain", "0"};
    ChildGuard runtime;
    if (!handoff_held_loopback_port(
            frontend_reservation, frontend_port, "#373 generated public bind", error) ||
        !spawn_child(observation.process_argv, temp.rut_log, runtime.child) ||
        !wait_ready(frontend_port, runtime.child, error)) {
        if (error.empty()) error = "#373 generated RUT failed before readiness";
        return false;
    }
    observation.process_identity =
        observation.temp_path + "/rut-pid-" + std::to_string(runtime.child.pid);
    observation.child_pid = runtime.child.pid;
    const std::string loaded = "Loaded program: " + temp.source + " (opt O2)\n";
    const std::string listener =
        "Listening on port " + std::to_string(frontend_port) + " with 1 shard(s)\n";
    const auto ready_deadline = std::chrono::steady_clock::now() + std::chrono::seconds(2);
    while ((!log_contains(temp.rut_log, loaded.c_str()) ||
            !log_contains(temp.rut_log, "Backend: io_uring\n") ||
            !log_contains(temp.rut_log, listener.c_str())) &&
           std::chrono::steady_clock::now() < ready_deadline) {
        if (poll_child(runtime.child)) {
            error = "#373 generated RUT exited before io_uring readiness";
            return false;
        }
        usleep(1000);
    }
    if (!log_contains(temp.rut_log, loaded.c_str()) ||
        !log_contains(temp.rut_log, "Backend: io_uring\n") ||
        !log_contains(temp.rut_log, listener.c_str())) {
        error = "#373 generated RUT lacked exact public io_uring readiness";
        return false;
    }
    const std::string poison = "destroyed-after-373-" + observation.order + "-load\n";
    std::string readback;
    if (!write_file(temp.source, poison.data(), poison.size()) ||
        !read_exact_return204_log(temp.source, "#373 poisoned generated source", readback, error) ||
        readback != poison || poll_child(runtime.child)) {
        error = "#373 generated source poison/readback did not preserve live child";
        return false;
    }
    observation.poison = readback;
    observation.source_poisoned = true;
    observation.child_live_after_poison = true;
    if (!proxy_hide_header_access_is_absent(temp.rut_access_log, error)) return false;
    observation.access_enoent_after = true;
    const auto live = [&]() {
        return !poll_child(runtime.child) && backend.running.load(std::memory_order_acquire) &&
               backend.thread_alive.load(std::memory_order_acquire) &&
               !backend.listener_failed.load(std::memory_order_acquire);
    };
    const auto quiet_deadline = std::chrono::steady_clock::now() + std::chrono::milliseconds(150);
    while (std::chrono::steady_clock::now() < quiet_deadline) {
        if (!live() || backend.accepted.load(std::memory_order_acquire) != 0u ||
            backend.requests.load(std::memory_order_acquire) != 0u ||
            backend.response_send_all_calls.load(std::memory_order_acquire) != 0u ||
            !proxy_hide_header_access_is_absent(temp.rut_access_log, error)) {
            if (error.empty()) error = "#373 generated pre-request window was not quiet";
            return false;
        }
        usleep(5000);
    }
    struct ClientGuard {
        int fd = -1;
        ~ClientGuard() {
            if (fd >= 0) close(fd);
        }
    };
    ClientGuard client{connect_once(frontend_port)};
    if (client.fd < 0 ||
        !send_all(
            client.fd, kProxyHideHeaderClientRequest, sizeof(kProxyHideHeaderClientRequest) - 1u) ||
        !read_response(client.fd, observation.response, error) || !read_eof(client.fd, error)) {
        error = "#373 generated exact request/response/EOF failed";
        return false;
    }
    observation.eof = true;
    close(client.fd);
    client.fd = -1;
    if (!wait_for_live_complete_origin_episode(backend, runtime.child, "#373 generated RUT", error))
        return false;
    observation.response_sent_ns = backend.response_sent_ns.load(std::memory_order_acquire);
    observation.response_peer_closed_ns =
        backend.response_peer_closed_ns.load(std::memory_order_acquire);
    observation.response_peer_close_count =
        backend.response_peer_close_count.load(std::memory_order_acquire);
    observation.response_peer_closed = backend.response_peer_closed.load(std::memory_order_acquire);
    observation.response_peer_unexpected_data =
        backend.response_peer_unexpected_data.load(std::memory_order_acquire);
    observation.response_peer_observation_failed =
        backend.response_peer_observation_failed.load(std::memory_order_acquire);
    if (observation.response_peer_close_count != 1u) {
        error = "#373 generated side did not observe exactly one live origin FIN";
        return false;
    }
    const auto stable_deadline = std::chrono::steady_clock::now() + std::chrono::milliseconds(500);
    while (std::chrono::steady_clock::now() < stable_deadline) {
        if (!live() || backend.accepted.load(std::memory_order_acquire) != 1u ||
            backend.requests.load(std::memory_order_acquire) != 1u ||
            backend.response_send_all_calls.load(std::memory_order_acquire) != 1u ||
            backend.response_sent_ns.load(std::memory_order_acquire) !=
                observation.response_sent_ns ||
            backend.response_peer_closed_ns.load(std::memory_order_acquire) !=
                observation.response_peer_closed_ns ||
            backend.response_peer_close_count.load(std::memory_order_acquire) != 1u ||
            backend.response_peer_unexpected_data.load(std::memory_order_acquire) ||
            backend.response_peer_observation_failed.load(std::memory_order_acquire) ||
            !proxy_hide_header_access_is_absent(temp.rut_access_log, error)) {
            if (error.empty()) error = "#373 generated live evidence was not stable";
            return false;
        }
        usleep(5000);
    }
    observation.stable_window = true;
    if (!stop_child(runtime.child) || !runtime.child.status_valid ||
        !WIFEXITED(runtime.child.status) || WEXITSTATUS(runtime.child.status) != 0) {
        error = "#373 generated RUT did not exit controlled with status 0";
        return false;
    }
    observation.exited_zero = true;
    if (!proxy_hide_header_access_is_absent(temp.rut_access_log, error)) return false;
    observation.access_enoent_final = true;
    backend.stop();
    backend_guard.recorder = nullptr;
    observation.accepted = backend.accepted.load(std::memory_order_acquire);
    observation.requests = backend.requests.load(std::memory_order_acquire);
    observation.sends = backend.response_send_all_calls.load(std::memory_order_acquire);
    observation.upstream_history = backend.history;
    observation.response_peer_close_count =
        backend.response_peer_close_count.load(std::memory_order_acquire);
    if (backend.thread_alive.load(std::memory_order_acquire) ||
        backend.listener_failed.load(std::memory_order_acquire) ||
        observation.response_peer_close_count != 1u ||
        !backend.response_send_succeeded.load(std::memory_order_acquire) ||
        !backend.response_clean_shutdown.load(std::memory_order_acquire) ||
        !backend.response_connection_closed.load(std::memory_order_acquire) ||
        !read_exact_return204_log(
            temp.rut_log, "#373 generated runtime log", observation.runtime_log, error))
        return false;
    return validate_proxy_hide_header_generated_observation(observation, error);
}

static bool run_proxy_hide_header_generated_observation_self_checks(
    const ProxyHideHeaderGeneratedObservation& baseline, std::string& error) {
    if (!validate_proxy_hide_header_generated_observation(baseline, error)) return false;
    const auto rejects = [&](ProxyHideHeaderGeneratedObservation candidate,
                             const char* field,
                             bool differs,
                             const char* label) {
        if (!differs) {
            error = std::string("#373 observation mutation did not change ") + field + ": " + label;
            return false;
        }
        std::string detail;
        if (validate_proxy_hide_header_generated_observation(candidate, detail)) {
            error = std::string("#373 observation mutation accepted: ") + label;
            return false;
        }
        return true;
    };
    auto candidate = baseline;
    candidate.response[100] = 'X';
    if (!rejects(
            candidate, "response", candidate.response != baseline.response, "wire hidden leakage"))
        return false;
    candidate = baseline;
    {
        std::string text(candidate.response.begin(), candidate.response.end());
        const size_t at = text.find("X-Compat-Visible: keep");
        if (at == std::string::npos) {
            error = "#373 visible-header mutation fixture was absent";
            return false;
        }
        text.replace(at, strlen("X-Compat-Visible: keep"), "X-Compat-Visible: drop");
        candidate.response.assign(text.begin(), text.end());
    }
    if (!rejects(
            candidate, "response", candidate.response != baseline.response, "visible-header value"))
        return false;
    candidate = baseline;
    {
        std::string text(candidate.response.begin(), candidate.response.end());
        const std::string cookies = "Set-Cookie: a=1\r\nSet-Cookie: b=2\r\n";
        const size_t at = text.find(cookies);
        if (at == std::string::npos) {
            error = "#373 cookie-order mutation fixture was absent";
            return false;
        }
        text.replace(at, cookies.size(), "Set-Cookie: b=2\r\nSet-Cookie: a=1\r\n");
        candidate.response.assign(text.begin(), text.end());
    }
    if (!rejects(candidate, "response", candidate.response != baseline.response, "cookie order"))
        return false;
    candidate = baseline;
    candidate.response.pop_back();
    if (!rejects(candidate, "response", candidate.response != baseline.response, "wire length"))
        return false;
    candidate = baseline;
    {
        std::string text(candidate.upstream_history[0].begin(),
                         candidate.upstream_history[0].end());
        const std::string duplicate_order = "X-Dupe: one\r\nX-Dupe: two\r\n";
        const size_t at = text.find(duplicate_order);
        if (at == std::string::npos) {
            error = "#373 upstream duplicate-order mutation fixture was absent";
            return false;
        }
        text.replace(at, duplicate_order.size(), "X-Dupe: two\r\nX-Dupe: one\r\n");
        candidate.upstream_history[0].assign(text.begin(), text.end());
    }
    if (!rejects(candidate,
                 "upstream_history",
                 candidate.upstream_history != baseline.upstream_history,
                 "upstream duplicate order"))
        return false;
    candidate = baseline;
    {
        std::string text(candidate.upstream_history[0].begin(),
                         candidate.upstream_history[0].end());
        const size_t at = text.find("X-Dupe: one\r\n");
        if (at == std::string::npos) return false;
        text.replace(at, strlen("X-Dupe: one\r\n"), "X-Dupe: xxx\r\n");
        candidate.upstream_history[0].assign(text.begin(), text.end());
    }
    if (!rejects(candidate,
                 "upstream_history",
                 candidate.upstream_history != baseline.upstream_history,
                 "upstream X-Dupe value"))
        return false;
    candidate = baseline;
    {
        std::string text(candidate.upstream_history[0].begin(),
                         candidate.upstream_history[0].end());
        const std::string host =
            "Host: 127.0.0.1:" + std::to_string(baseline.backend_port) + "\r\n";
        const size_t at = text.find(host);
        if (at == std::string::npos) {
            error = "#373 upstream Host mutation fixture was absent";
            return false;
        }
        const u16 alternate = baseline.backend_port == 9999u ? 9998u : baseline.backend_port + 1u;
        text.replace(at, host.size(), "Host: 127.0.0.1:" + std::to_string(alternate) + "\r\n");
        candidate.upstream_history[0].assign(text.begin(), text.end());
    }
    if (!rejects(candidate,
                 "upstream_history",
                 candidate.upstream_history != baseline.upstream_history,
                 "upstream Host/request"))
        return false;
    candidate = baseline;
    {
        std::string text(candidate.upstream_history[0].begin(),
                         candidate.upstream_history[0].end());
        const size_t at = text.find("X-Dupe: one");
        if (at == std::string::npos) {
            error = "#373 upstream-Connection mutation fixture was absent";
            return false;
        }
        text.replace(at, strlen("X-Dupe: one"), "Connection: ");
        candidate.upstream_history[0].assign(text.begin(), text.end());
    }
    if (!rejects(candidate,
                 "upstream_history",
                 candidate.upstream_history != baseline.upstream_history,
                 "upstream Connection"))
        return false;
    candidate = baseline;
    candidate.requests = 2u;
    if (!rejects(candidate, "requests", candidate.requests != baseline.requests, "upstream count"))
        return false;
    candidate = baseline;
    candidate.response_peer_closed_ns += 2'000'000'001ull;
    if (!rejects(candidate,
                 "response_peer_closed_ns",
                 candidate.response_peer_closed_ns != baseline.response_peer_closed_ns,
                 "FIN timing"))
        return false;
    candidate = baseline;
    candidate.response_peer_unexpected_data = true;
    if (!rejects(candidate,
                 "response_peer_unexpected_data",
                 candidate.response_peer_unexpected_data != baseline.response_peer_unexpected_data,
                 "late data/failure"))
        return false;
    candidate = baseline;
    candidate.access_enoent_final = false;
    if (!rejects(candidate,
                 "access_enoent_final",
                 candidate.access_enoent_final != baseline.access_enoent_final,
                 "access appearance"))
        return false;
    candidate = baseline;
    candidate.child_live_after_poison = false;
    if (!rejects(candidate,
                 "child_live_after_poison",
                 candidate.child_live_after_poison != baseline.child_live_after_poison,
                 "poison liveness"))
        return false;
    candidate = baseline;
    candidate.runtime_log += "fatal\n";
    if (!rejects(candidate,
                 "runtime_log",
                 candidate.runtime_log != baseline.runtime_log,
                 "lifecycle corruption"))
        return false;
    const auto replace_response = [&](const std::string& from, const std::string& to) {
        candidate = baseline;
        std::string text(candidate.response.begin(), candidate.response.end());
        const size_t at = text.find(from);
        if (at == std::string::npos || from.size() != to.size()) return false;
        text.replace(at, from.size(), to);
        candidate.response.assign(text.begin(), text.end());
        return true;
    };
    if (!replace_response("X-Compat-Visible: keep\r\n", "X-Compat-Hidden: keep \r\n") ||
        !rejects(candidate,
                 "response",
                 candidate.response != baseline.response,
                 "literal uppercase hidden leakage"))
        return false;
    if (!replace_response("X-Compat-Visible: keep\r\n", "x-compat-hidden: keep \r\n") ||
        !rejects(candidate,
                 "response",
                 candidate.response != baseline.response,
                 "literal lowercase hidden leakage"))
        return false;
    if (!replace_response("X-Compat-Visible: keep\r\n", "X-Removed-Head: xxxxxx\r\n") ||
        !rejects(candidate,
                 "response",
                 candidate.response != baseline.response,
                 "visible header removal"))
        return false;
    if (!replace_response("Set-Cookie: a=1\r\n", "X-Removed: xxxx\r\n") ||
        !rejects(candidate, "response", candidate.response != baseline.response, "cookie removal"))
        return false;
    for (const char* field : {"accepted", "requests", "sends"}) {
        for (const u32 value : {0u, 2u}) {
            candidate = baseline;
            if (strcmp(field, "accepted") == 0) candidate.accepted = value;
            if (strcmp(field, "requests") == 0) candidate.requests = value;
            if (strcmp(field, "sends") == 0) candidate.sends = value;
            const std::string label = std::string(field) + "=" + std::to_string(value);
            const bool differs =
                (strcmp(field, "accepted") == 0 && candidate.accepted != baseline.accepted) ||
                (strcmp(field, "requests") == 0 && candidate.requests != baseline.requests) ||
                (strcmp(field, "sends") == 0 && candidate.sends != baseline.sends);
            if (!rejects(candidate, field, differs, label.c_str())) return false;
        }
    }
    candidate = baseline;
    candidate.upstream_history.clear();
    if (!rejects(candidate,
                 "upstream_history",
                 candidate.upstream_history != baseline.upstream_history,
                 "upstream history empty"))
        return false;
    candidate = baseline;
    candidate.upstream_history.push_back(candidate.upstream_history.front());
    if (!rejects(candidate,
                 "upstream_history",
                 candidate.upstream_history != baseline.upstream_history,
                 "upstream history duplicate"))
        return false;
    candidate = baseline;
    candidate.response_peer_closed = false;
    if (!rejects(candidate,
                 "response_peer_closed",
                 candidate.response_peer_closed != baseline.response_peer_closed,
                 "FIN boolean false"))
        return false;
    for (const u32 value : {0u, 2u}) {
        candidate = baseline;
        candidate.response_peer_close_count = value;
        const std::string label = "FIN count=" + std::to_string(value);
        if (!rejects(candidate,
                     "response_peer_close_count",
                     candidate.response_peer_close_count != baseline.response_peer_close_count,
                     label.c_str()))
            return false;
    }
    candidate = baseline;
    candidate.response_sent_ns = 0u;
    if (!rejects(candidate,
                 "response_sent_ns",
                 candidate.response_sent_ns != baseline.response_sent_ns,
                 "FIN before-send timestamp"))
        return false;
    candidate = baseline;
    candidate.response_peer_closed_ns = candidate.response_sent_ns + 2'000'000'001ull;
    if (!rejects(candidate,
                 "response_peer_closed_ns",
                 candidate.response_peer_closed_ns != baseline.response_peer_closed_ns,
                 "FIN over-two-second timestamp"))
        return false;
    candidate = baseline;
    candidate.response_peer_observation_failed = true;
    if (!rejects(
            candidate,
            "response_peer_observation_failed",
            candidate.response_peer_observation_failed != baseline.response_peer_observation_failed,
            "FIN observation failure"))
        return false;
    candidate = baseline;
    candidate.stable_window = false;
    if (!rejects(candidate,
                 "stable_window",
                 candidate.stable_window != baseline.stable_window,
                 "stable window false"))
        return false;
    for (const char* field :
         {"access_enoent_before", "access_enoent_after", "access_enoent_final"}) {
        candidate = baseline;
        if (strcmp(field, "access_enoent_before") == 0) candidate.access_enoent_before = false;
        if (strcmp(field, "access_enoent_after") == 0) candidate.access_enoent_after = false;
        if (strcmp(field, "access_enoent_final") == 0) candidate.access_enoent_final = false;
        const bool differs = (strcmp(field, "access_enoent_before") == 0 &&
                              candidate.access_enoent_before != baseline.access_enoent_before) ||
                             (strcmp(field, "access_enoent_after") == 0 &&
                              candidate.access_enoent_after != baseline.access_enoent_after) ||
                             (strcmp(field, "access_enoent_final") == 0 &&
                              candidate.access_enoent_final != baseline.access_enoent_final);
        if (!rejects(candidate, field, differs, "access probe appeared")) return false;
    }
    candidate = baseline;
    candidate.poison = "wrong-poison\n";
    if (!rejects(candidate, "poison", candidate.poison != baseline.poison, "poison bytes"))
        return false;
    candidate = baseline;
    candidate.source_poisoned = false;
    if (!rejects(candidate,
                 "source_poisoned",
                 candidate.source_poisoned != baseline.source_poisoned,
                 "source poison marker false"))
        return false;
    candidate = baseline;
    candidate.exited_zero = false;
    if (!rejects(candidate,
                 "exited_zero",
                 candidate.exited_zero != baseline.exited_zero,
                 "exit status nonzero"))
        return false;
    candidate = baseline;
    const size_t lifecycle_newline = candidate.runtime_log.find("Backend: io_uring\n");
    if (lifecycle_newline == std::string::npos) return false;
    candidate.runtime_log.erase(lifecycle_newline, strlen("Backend: io_uring\n"));
    if (!rejects(candidate,
                 "runtime_log",
                 candidate.runtime_log != baseline.runtime_log,
                 "lifecycle missing line"))
        return false;
    candidate = baseline;
    const size_t lifecycle_backend = candidate.runtime_log.find("Backend: io_uring\n");
    const size_t lifecycle_loaded = candidate.runtime_log.find("Loaded program:");
    if (lifecycle_backend == std::string::npos || lifecycle_loaded == std::string::npos)
        return false;
    candidate.runtime_log.erase(lifecycle_backend, strlen("Backend: io_uring\n"));
    candidate.runtime_log.insert(lifecycle_loaded, "Backend: io_uring\n");
    if (!rejects(candidate,
                 "runtime_log",
                 candidate.runtime_log != baseline.runtime_log,
                 "lifecycle order"))
        return false;
    for (const char* extra : {"extra\n", "Fallback: epoll\n", "fatal\n"}) {
        candidate = baseline;
        candidate.runtime_log += extra;
        if (!rejects(
                candidate, "runtime_log", candidate.runtime_log != baseline.runtime_log, extra))
            return false;
    }
    candidate = baseline;
    candidate.child_pid++;
    if (!rejects(candidate, "child_pid", candidate.child_pid != baseline.child_pid, "child PID"))
        return false;
    candidate = baseline;
    candidate.process_identity += "-changed";
    if (!rejects(candidate,
                 "process_identity",
                 candidate.process_identity != baseline.process_identity,
                 "process identity"))
        return false;
    for (const char* field :
         {"temp_path", "source_path", "runtime_log_path", "access_probe_path"}) {
        candidate = baseline;
        if (strcmp(field, "temp_path") == 0) candidate.temp_path += "-changed";
        if (strcmp(field, "source_path") == 0) candidate.source_path += ".changed";
        if (strcmp(field, "runtime_log_path") == 0) candidate.runtime_log_path += ".changed";
        if (strcmp(field, "access_probe_path") == 0) candidate.access_probe_path += ".changed";
        const bool differs =
            (strcmp(field, "temp_path") == 0 && candidate.temp_path != baseline.temp_path) ||
            (strcmp(field, "source_path") == 0 && candidate.source_path != baseline.source_path) ||
            (strcmp(field, "runtime_log_path") == 0 &&
             candidate.runtime_log_path != baseline.runtime_log_path) ||
            (strcmp(field, "access_probe_path") == 0 &&
             candidate.access_probe_path != baseline.access_probe_path);
        if (!rejects(candidate, field, differs, "resource identity")) return false;
    }
    candidate = baseline;
    candidate.process_argv[6] = "1";
    if (!rejects(candidate,
                 "process_argv",
                 candidate.process_argv != baseline.process_argv,
                 "argv drain value"))
        return false;
    candidate = baseline;
    candidate.process_argv.push_back("--access-log");
    if (!rejects(candidate,
                 "process_argv",
                 candidate.process_argv != baseline.process_argv,
                 "argv access-log"))
        return false;
    candidate = baseline;
    candidate.eof = false;
    if (!rejects(candidate, "eof", candidate.eof != baseline.eof, "EOF evidence")) return false;
    candidate = baseline;
    const std::string opposite_order =
        baseline.order == "listen-first" ? "location-first" : "listen-first";
    candidate.poison = "destroyed-after-373-" + opposite_order + "-load\n";
    if (!rejects(candidate, "poison", candidate.poison != baseline.poison, "opposite-order poison"))
        return false;
    return true;
}

// Stage 4b2 deliberately composes two independently captured generated sides.
// This remains an RUT-vs-RUT declaration-order witness; pinned nginx and the
// eventual four-way comparison belong to the following stage.
struct ProxyHideHeaderGeneratedPair {
    ProxyHideHeaderGeneratedObservation sides[2];
};

static bool canonicalize_generated_upstream_host(const std::vector<char>& wire,
                                                 u16 backend_port,
                                                 std::string& canonical,
                                                 std::string& error) {
    if (wire.size() != 66u) {
        error = "#373 generated pair upstream wire was not exactly 66 bytes";
        return false;
    }
    const std::string value(wire.begin(), wire.end());
    const std::string endpoint = "127.0.0.1:" + std::to_string(backend_port);
    const size_t at = value.find(endpoint);
    if (at == std::string::npos ||
        value.find(endpoint, at + endpoint.size()) != std::string::npos || at < strlen("Host: ") ||
        value.compare(at - strlen("Host: "), strlen("Host: "), "Host: ") != 0 ||
        value.compare(at + endpoint.size(), 2u, "\r\n") != 0) {
        error = "#373 generated pair upstream Host endpoint was not one complete validated token";
        return false;
    }
    canonical = value;
    canonical.replace(at, endpoint.size(), "127.0.0.1:BACKEND");
    return true;
}

static bool validate_proxy_hide_header_generated_pair(const ProxyHideHeaderGeneratedPair& pair,
                                                      std::string& error) {
    const auto& first = pair.sides[0];
    const auto& second = pair.sides[1];
    if (!validate_proxy_hide_header_generated_observation(first, error) ||
        !validate_proxy_hide_header_generated_observation(second, error))
        return false;
    if (first.order != "listen-first" || second.order != "location-first" ||
        first.frontend_port == second.frontend_port || first.frontend_port == second.backend_port ||
        first.backend_port == second.frontend_port || first.backend_port == second.backend_port ||
        first.frontend_port < 1024u || first.frontend_port > 9999u || first.backend_port < 1024u ||
        first.backend_port > 9999u || second.frontend_port < 1024u ||
        second.frontend_port > 9999u || second.backend_port < 1024u ||
        second.backend_port > 9999u) {
        error = "#373 generated pair endpoint/order binding or four-digit uniqueness failed";
        return false;
    }
    const std::string* const strings[] = {&first.temp_path,
                                          &second.temp_path,
                                          &first.source_path,
                                          &second.source_path,
                                          &first.runtime_log_path,
                                          &second.runtime_log_path,
                                          &first.access_probe_path,
                                          &second.access_probe_path,
                                          &first.process_identity,
                                          &second.process_identity};
    for (size_t i = 0u; i < std::size(strings); i++)
        for (size_t j = i + 1u; j < std::size(strings); j++)
            if (*strings[i] == *strings[j]) {
                error = "#373 generated pair resource/process identities were reused";
                return false;
            }
    if (first.child_pid <= 0 || second.child_pid <= 0 || first.child_pid == second.child_pid ||
        first.source.size() != 5366u || second.source.size() != 5366u ||
        first.source.size() != second.source.size() ||
        first.rut_executable != second.rut_executable) {
        error = "#373 generated pair source size or PID identity failed";
        return false;
    }
    if (first.response.size() != 176u || second.response.size() != 176u) {
        error = "#373 generated pair downstream wire size failed";
        return false;
    }
    std::vector<char> first_downstream = first.response;
    std::vector<char> second_downstream = second.response;
    if (!normalize_date(first_downstream) || !normalize_date(second_downstream) ||
        first_downstream != second_downstream) {
        error =
            "#373 generated declaration orders did not produce the same Date-normalized 176-byte "
            "downstream wire";
        return false;
    }
    std::string first_upstream;
    std::string second_upstream;
    if (first.upstream_history.size() != 1u || second.upstream_history.size() != 1u ||
        !canonicalize_generated_upstream_host(
            first.upstream_history[0], first.backend_port, first_upstream, error) ||
        !canonicalize_generated_upstream_host(
            second.upstream_history[0], second.backend_port, second_upstream, error) ||
        first_upstream != second_upstream) {
        if (error.empty())
            error =
                "#373 generated declaration orders did not produce the same canonical upstream "
                "wire";
        return false;
    }
    std::string first_source = first.source;
    std::string second_source = second.source;
    const bool sources_canonical =
        canonicalize_unique_port(first_source,
                                 "listen 127.0.0.1:" + std::to_string(first.frontend_port) + "\n",
                                 "listen 127.0.0.1:FRONTEND\n") &&
        canonicalize_unique_port(
            first_source,
            "upstream nginx_upstream at \"127.0.0.1:" + std::to_string(first.backend_port) + "\"\n",
            "upstream nginx_upstream at \"127.0.0.1:BACKEND\"\n") &&
        canonicalize_unique_port(second_source,
                                 "listen 127.0.0.1:" + std::to_string(second.frontend_port) + "\n",
                                 "listen 127.0.0.1:FRONTEND\n") &&
        canonicalize_unique_port(second_source,
                                 "upstream nginx_upstream at \"127.0.0.1:" +
                                     std::to_string(second.backend_port) + "\"\n",
                                 "upstream nginx_upstream at \"127.0.0.1:BACKEND\"\n");
    if (!sources_canonical || first_source != second_source) {
        error =
            "#373 generated declaration-order sources differed beyond validated endpoint tokens";
        return false;
    }
    // Each side's observation validator already proves the exact count, one
    // FIN, no-late-data, EOF, stable window, clean exit and disabled access
    // probe. Keep these assertions explicit at the pair boundary so future
    // edits cannot accidentally turn this into a source-only comparison.
    if (first.accepted != second.accepted || first.requests != second.requests ||
        first.sends != second.sends || first.response_peer_close_count != 1u ||
        second.response_peer_close_count != 1u || !first.response_peer_closed ||
        !second.response_peer_closed || first.response_peer_unexpected_data ||
        second.response_peer_unexpected_data || first.response_peer_observation_failed ||
        second.response_peer_observation_failed || !first.eof || !second.eof ||
        !first.stable_window || !second.stable_window || !first.exited_zero ||
        !second.exited_zero || !first.access_enoent_before || !second.access_enoent_before ||
        !first.access_enoent_after || !second.access_enoent_after || !first.access_enoent_final ||
        !second.access_enoent_final || first.response_sent_ns == 0u ||
        second.response_sent_ns == 0u || first.response_peer_closed_ns < first.response_sent_ns ||
        second.response_peer_closed_ns < second.response_sent_ns ||
        first.response_peer_closed_ns - first.response_sent_ns > 2'000'000'000ull ||
        second.response_peer_closed_ns - second.response_sent_ns > 2'000'000'000ull) {
        error =
            "#373 generated pair count/FIN/timestamp/EOF/stability/access/lifecycle contract "
            "failed";
        return false;
    }
    return true;
}

static bool run_proxy_hide_header_generated_pair_self_checks(
    const ProxyHideHeaderGeneratedPair& baseline, std::string& error) {
    if (!validate_proxy_hide_header_generated_pair(baseline, error)) return false;
    const auto rejects = [&](ProxyHideHeaderGeneratedPair candidate,
                             const char* field,
                             bool differs,
                             const char* label) {
        if (!differs) {
            error =
                std::string("#373 generated pair mutation did not change ") + field + ": " + label;
            return false;
        }
        std::string detail;
        if (validate_proxy_hide_header_generated_pair(candidate, detail)) {
            error = std::string("#373 generated pair mutation accepted: ") + label;
            return false;
        }
        return true;
    };
    auto candidate = baseline;
    std::swap(candidate.sides[0].order, candidate.sides[1].order);
    if (!rejects(candidate,
                 "order",
                 candidate.sides[0].order != baseline.sides[0].order &&
                     candidate.sides[1].order != baseline.sides[1].order,
                 "swapped order"))
        return false;
    candidate = baseline;
    candidate.sides[1].frontend_port = baseline.sides[0].frontend_port;
    if (!rejects(candidate,
                 "frontend_port",
                 candidate.sides[1].frontend_port != baseline.sides[1].frontend_port,
                 "reused frontend endpoint"))
        return false;
    candidate = baseline;
    candidate.sides[1].backend_port = baseline.sides[0].backend_port;
    if (!rejects(candidate,
                 "backend_port",
                 candidate.sides[1].backend_port != baseline.sides[1].backend_port,
                 "reused backend endpoint"))
        return false;
    candidate = baseline;
    candidate.sides[1].frontend_port = baseline.sides[1].backend_port;
    if (!rejects(candidate,
                 "frontend_port",
                 candidate.sides[1].frontend_port != baseline.sides[1].frontend_port,
                 "frontend/backend collision"))
        return false;
    candidate = baseline;
    candidate.sides[1].source = candidate.sides[0].source;
    if (!rejects(candidate,
                 "source",
                 candidate.sides[1].source != baseline.sides[1].source,
                 "source identity reuse"))
        return false;
    candidate = baseline;
    candidate.sides[1].temp_path = candidate.sides[0].temp_path;
    if (!rejects(candidate,
                 "temp_path",
                 candidate.sides[1].temp_path != baseline.sides[1].temp_path,
                 "temp identity reuse"))
        return false;
    candidate = baseline;
    candidate.sides[1].source_path = candidate.sides[0].source_path;
    if (!rejects(candidate,
                 "source_path",
                 candidate.sides[1].source_path != baseline.sides[1].source_path,
                 "source-path identity reuse"))
        return false;
    candidate = baseline;
    candidate.sides[1].runtime_log_path = candidate.sides[0].runtime_log_path;
    if (!rejects(candidate,
                 "runtime_log_path",
                 candidate.sides[1].runtime_log_path != baseline.sides[1].runtime_log_path,
                 "runtime-log identity reuse"))
        return false;
    candidate = baseline;
    candidate.sides[1].access_probe_path = candidate.sides[0].access_probe_path;
    if (!rejects(candidate,
                 "access_probe_path",
                 candidate.sides[1].access_probe_path != baseline.sides[1].access_probe_path,
                 "access-probe identity reuse"))
        return false;
    candidate = baseline;
    candidate.sides[1].process_identity = candidate.sides[0].process_identity;
    if (!rejects(candidate,
                 "process_identity",
                 candidate.sides[1].process_identity != baseline.sides[1].process_identity,
                 "process identity reuse"))
        return false;
    candidate = baseline;
    candidate.sides[1].process_argv[6] = "1";
    if (!rejects(candidate,
                 "process_argv",
                 candidate.sides[1].process_argv != baseline.sides[1].process_argv,
                 "argv mismatch"))
        return false;
    candidate = baseline;
    candidate.sides[1].process_argv.push_back("--access-log");
    if (!rejects(candidate,
                 "process_argv",
                 candidate.sides[1].process_argv != baseline.sides[1].process_argv,
                 "argv access sink"))
        return false;
    candidate = baseline;
    candidate.sides[1].child_pid = candidate.sides[0].child_pid;
    if (!rejects(candidate,
                 "child_pid",
                 candidate.sides[1].child_pid != baseline.sides[1].child_pid,
                 "PID identity reuse"))
        return false;
    candidate = baseline;
    std::swap(candidate.sides[0].source, candidate.sides[1].source);
    if (!rejects(candidate,
                 "source",
                 candidate.sides[0].source != baseline.sides[0].source &&
                     candidate.sides[1].source != baseline.sides[1].source,
                 "side source swap"))
        return false;
    candidate = baseline;
    candidate.sides[1].response[100] = 'X';
    if (!rejects(candidate,
                 "response",
                 candidate.sides[1].response != baseline.sides[1].response,
                 "downstream mismatch"))
        return false;
    candidate = baseline;
    {
        std::string wire(candidate.sides[1].upstream_history[0].begin(),
                         candidate.sides[1].upstream_history[0].end());
        const std::string host =
            "Host: 127.0.0.1:" + std::to_string(candidate.sides[1].backend_port) + "\r\n";
        const size_t at = wire.find(host);
        if (at == std::string::npos) return false;
        const u16 alternate = candidate.sides[1].backend_port == 9999u
                                  ? 9998u
                                  : static_cast<u16>(candidate.sides[1].backend_port + 1u);
        const std::string replacement = "Host: 127.0.0.1:" + std::to_string(alternate) + "\r\n";
        if (replacement == host) return false;
        wire.replace(at, host.size(), replacement);
        candidate.sides[1].upstream_history[0].assign(wire.begin(), wire.end());
    }
    if (!rejects(candidate,
                 "upstream_history",
                 candidate.sides[1].upstream_history != baseline.sides[1].upstream_history,
                 "upstream Host mismatch"))
        return false;
    candidate = baseline;
    {
        std::string wire(candidate.sides[1].upstream_history[0].begin(),
                         candidate.sides[1].upstream_history[0].end());
        const size_t at = wire.find("X-Dupe: one");
        if (at == std::string::npos) return false;
        const std::string replacement = "X-Dupe: xxx";
        if (replacement == "X-Dupe: one") return false;
        wire.replace(at, strlen("X-Dupe: one"), replacement);
        candidate.sides[1].upstream_history[0].assign(wire.begin(), wire.end());
    }
    if (!rejects(candidate,
                 "upstream_history",
                 candidate.sides[1].upstream_history != baseline.sides[1].upstream_history,
                 "upstream header mismatch"))
        return false;
    candidate = baseline;
    candidate.sides[1].upstream_history[0].clear();
    if (!rejects(candidate,
                 "upstream_history",
                 candidate.sides[1].upstream_history != baseline.sides[1].upstream_history,
                 "upstream count/EOF mismatch"))
        return false;
    for (const u32 value : {0u, 2u}) {
        candidate = baseline;
        candidate.sides[1].accepted = value;
        const std::string label = "accepted=" + std::to_string(value);
        if (!rejects(candidate,
                     "accepted",
                     candidate.sides[1].accepted != baseline.sides[1].accepted,
                     label.c_str()))
            return false;
    }
    for (const u32 value : {0u, 2u}) {
        candidate = baseline;
        candidate.sides[1].requests = value;
        const std::string label = "requests=" + std::to_string(value);
        if (!rejects(candidate,
                     "requests",
                     candidate.sides[1].requests != baseline.sides[1].requests,
                     label.c_str()))
            return false;
    }
    for (const u32 value : {0u, 2u}) {
        candidate = baseline;
        candidate.sides[1].sends = value;
        const std::string label = "sends=" + std::to_string(value);
        if (!rejects(candidate,
                     "sends",
                     candidate.sides[1].sends != baseline.sides[1].sends,
                     label.c_str()))
            return false;
    }
    candidate = baseline;
    candidate.sides[1].response_peer_close_count = 2u;
    if (!rejects(candidate,
                 "response_peer_close_count",
                 candidate.sides[1].response_peer_close_count !=
                     baseline.sides[1].response_peer_close_count,
                 "FIN count mismatch"))
        return false;
    candidate = baseline;
    candidate.sides[1].response_peer_closed_ns =
        candidate.sides[1].response_sent_ns + 2'000'000'001ull;
    if (!rejects(
            candidate,
            "response_peer_closed_ns",
            candidate.sides[1].response_peer_closed_ns != baseline.sides[1].response_peer_closed_ns,
            "FIN timestamp mismatch"))
        return false;
    candidate = baseline;
    candidate.sides[1].eof = false;
    if (!rejects(candidate,
                 "eof",
                 candidate.sides[1].eof != baseline.sides[1].eof,
                 "downstream EOF mismatch"))
        return false;
    candidate = baseline;
    candidate.sides[1].stable_window = false;
    if (!rejects(candidate,
                 "stable_window",
                 candidate.sides[1].stable_window != baseline.sides[1].stable_window,
                 "lifecycle stability mismatch"))
        return false;
    candidate = baseline;
    candidate.sides[1].exited_zero = false;
    if (!rejects(candidate,
                 "exited_zero",
                 candidate.sides[1].exited_zero != baseline.sides[1].exited_zero,
                 "clean-exit mismatch"))
        return false;
    candidate = baseline;
    candidate.sides[1].access_enoent_final = false;
    if (!rejects(candidate,
                 "access_enoent_final",
                 candidate.sides[1].access_enoent_final != baseline.sides[1].access_enoent_final,
                 "access mismatch"))
        return false;
    candidate = baseline;
    candidate.sides[1].runtime_log += "fatal\n";
    if (!rejects(candidate,
                 "runtime_log",
                 candidate.sides[1].runtime_log != baseline.sides[1].runtime_log,
                 "lifecycle log mismatch"))
        return false;
    return true;
}

static bool capture_proxy_hide_header_generated_pair(const char* rut_path,
                                                     ProxyHideHeaderGeneratedPair& pair,
                                                     std::string& error) {
    TempDir temps[2];
    if (!temps[0].create() || !temps[1].create()) {
        error = "#373 generated pair could not create two independent secure TempDir trees";
        return false;
    }
    HeldLoopbackPorts reservations;
    u16 ports[4] = {};
    for (size_t i = 0u; i < 4u; i++) {
        if (!reservations.reserve_four_digit(i, ports[i])) {
            error =
                "#373 generated pair could not reserve all four unique four-digit ports before "
                "launch";
            return false;
        }
    }
    if (ports[0] == ports[1] || ports[0] == ports[2] || ports[0] == ports[3] ||
        ports[1] == ports[2] || ports[1] == ports[3] || ports[2] == ports[3]) {
        error = "#373 generated pair reserved a duplicate endpoint";
        return false;
    }
    // Capture consumes exactly its side's backend then frontend reservations;
    // the other side's two reservations remain held throughout the first run.
    if (!capture_proxy_hide_header_generated_side(ports[0],
                                                  ports[1],
                                                  temps[0],
                                                  rut_path,
                                                  true,
                                                  pair.sides[0],
                                                  error,
                                                  &reservations.fds[0],
                                                  &reservations.fds[1]) ||
        !capture_proxy_hide_header_generated_side(ports[2],
                                                  ports[3],
                                                  temps[1],
                                                  rut_path,
                                                  false,
                                                  pair.sides[1],
                                                  error,
                                                  &reservations.fds[2],
                                                  &reservations.fds[3]))
        return false;
    return true;
}

// Final Stage 4b2b composition.  The four captures deliberately share one
// reservation set, but consume only their own handoff pair.  Consequently all
// eight endpoints are held before N1 is started while each side remains an
// independent resource/process identity.
struct ProxyHideHeaderFinalDifferential {
    StaticQueryProxyOracleObservation pinned[2];
    ProxyHideHeaderGeneratedObservation generated[2];
    u16 ports[8]{};
};

static bool validate_proxy_hide_header_final(const ProxyHideHeaderFinalDifferential& value,
                                             std::string& error) {
    const u16 pinned_ports[4] = {value.ports[0], value.ports[1], value.ports[2], value.ports[3]};
    if (!validate_static_query_proxy_pair(
            value.pinned, pinned_ports, error, kProxyHideHeaderOracleProfile) ||
        !validate_proxy_hide_header_generated_pair({value.generated[0], value.generated[1]}, error))
        return false;
    if (value.generated[0].frontend_port != value.ports[4] ||
        value.generated[0].backend_port != value.ports[5] ||
        value.generated[1].frontend_port != value.ports[6] ||
        value.generated[1].backend_port != value.ports[7]) {
        error = "#373 final differential generated endpoint-array binding failed";
        return false;
    }
    for (size_t i = 0u; i < 8u; i++) {
        if (value.ports[i] < 1024u || value.ports[i] > 9999u) {
            error = "#373 final differential endpoint was not a four-digit port";
            return false;
        }
        for (size_t j = i + 1u; j < 8u; j++) {
            if (value.ports[i] == value.ports[j]) {
                error = "#373 final differential reused one of eight held endpoints";
                return false;
            }
        }
    }
    const std::string* identities[] = {&value.pinned[0].temp_path,
                                       &value.pinned[1].temp_path,
                                       &value.generated[0].temp_path,
                                       &value.generated[1].temp_path,
                                       &value.pinned[0].config_path,
                                       &value.pinned[1].config_path,
                                       &value.generated[0].source_path,
                                       &value.generated[1].source_path,
                                       &value.pinned[0].log_path,
                                       &value.pinned[1].log_path,
                                       &value.generated[0].runtime_log_path,
                                       &value.generated[1].runtime_log_path,
                                       &value.pinned[0].access_path,
                                       &value.pinned[1].access_path,
                                       &value.generated[0].access_probe_path,
                                       &value.generated[1].access_probe_path,
                                       &value.pinned[0].process_identity,
                                       &value.pinned[1].process_identity,
                                       &value.generated[0].process_identity,
                                       &value.generated[1].process_identity};
    for (const std::string* identity : identities) {
        if (identity->empty()) {
            error = "#373 final differential had an empty resource/process identity";
            return false;
        }
    }
    for (size_t i = 0u; i < std::size(identities); i++)
        for (size_t j = i + 1u; j < std::size(identities); j++)
            if (*identities[i] == *identities[j]) {
                error = "#373 final differential crossed a resource/process identity";
                return false;
            }

    // Each side has already proved status/header/body/EOF semantics in its
    // side-specific validator.  Compare all four exact Date-normalized wires.
    std::vector<std::vector<char>> downstream;
    downstream.reserve(4u);
    downstream.push_back(value.pinned[0].wires[0]);
    downstream.push_back(value.pinned[1].wires[0]);
    downstream.push_back(value.generated[0].response);
    downstream.push_back(value.generated[1].response);
    for (std::vector<char>& wire : downstream) {
        if (wire.size() != 176u || !normalize_date(wire)) {
            error =
                "#373 final differential downstream wire was not exact 176-byte Date-normalized";
            return false;
        }
    }
    for (size_t i = 1u; i < downstream.size(); i++)
        if (downstream[i] != downstream[0]) {
            error = "#373 final differential N/R downstream wires differed";
            return false;
        }

    std::vector<std::string> upstream;
    upstream.reserve(4u);
    std::string canonical;
    if (!canonicalize_generated_upstream_host(
            value.pinned[0].forward_history[0], value.pinned[0].backend_port, canonical, error))
        return false;
    upstream.push_back(canonical);
    if (!canonicalize_generated_upstream_host(
            value.pinned[1].forward_history[0], value.pinned[1].backend_port, canonical, error))
        return false;
    upstream.push_back(canonical);
    if (!canonicalize_generated_upstream_host(value.generated[0].upstream_history[0],
                                              value.generated[0].backend_port,
                                              canonical,
                                              error))
        return false;
    upstream.push_back(canonical);
    if (!canonicalize_generated_upstream_host(value.generated[1].upstream_history[0],
                                              value.generated[1].backend_port,
                                              canonical,
                                              error))
        return false;
    upstream.push_back(canonical);
    for (size_t i = 1u; i < upstream.size(); i++)
        if (upstream[i] != upstream[0]) {
            error = "#373 final differential N/R upstream Host/header wires differed";
            return false;
        }
    return true;
}

static bool run_proxy_hide_header_final_self_checks(
    const ProxyHideHeaderFinalDifferential& baseline, std::string& error) {
    if (!validate_proxy_hide_header_final(baseline, error)) return false;
    const auto rejects = [&](ProxyHideHeaderFinalDifferential candidate,
                             const char* field,
                             bool differs,
                             const char* label) {
        if (!differs) {
            error = std::string("#373 final mutation did not change ") + field + ": " + label;
            return false;
        }
        std::string detail;
        if (validate_proxy_hide_header_final(candidate, detail)) {
            error = std::string("#373 final mutation accepted: ") + label;
            return false;
        }
        return true;
    };
    auto candidate = baseline;
    std::swap(candidate.pinned[0].order, candidate.pinned[1].order);
    if (!rejects(candidate,
                 "order",
                 candidate.pinned[0].order != baseline.pinned[0].order &&
                     candidate.pinned[1].order != baseline.pinned[1].order,
                 "wrong pinned order"))
        return false;
    candidate = baseline;
    candidate.generated[0].order = "location-first";
    if (!rejects(candidate,
                 "order",
                 candidate.generated[0].order != baseline.generated[0].order,
                 "wrong generated order"))
        return false;
    candidate = baseline;
    u16 unused_port = 9999u;
    while (std::find(std::begin(baseline.ports), std::end(baseline.ports), unused_port) !=
           std::end(baseline.ports))
        --unused_port;
    if (unused_port < 1024u || unused_port == baseline.ports[4]) {
        error = "#373 final port mutation fixture lacked a unique four-digit endpoint";
        return false;
    }
    candidate.ports[4] = unused_port;
    if (!rejects(candidate,
                 "port",
                 candidate.ports[4] != baseline.ports[4],
                 "generated endpoint-array binding mismatch"))
        return false;
    candidate = baseline;
    candidate.generated[1].temp_path = candidate.generated[0].temp_path;
    if (!rejects(candidate,
                 "resource",
                 candidate.generated[1].temp_path != baseline.generated[1].temp_path,
                 "cross-side resource reuse"))
        return false;
    candidate = baseline;
    candidate.generated[1].process_identity = candidate.generated[0].process_identity;
    if (!rejects(candidate,
                 "process",
                 candidate.generated[1].process_identity != baseline.generated[1].process_identity,
                 "cross-side process identity reuse"))
        return false;
    candidate = baseline;
    candidate.pinned[1].config_path = candidate.pinned[0].config_path;
    if (!rejects(candidate,
                 "config",
                 candidate.pinned[1].config_path != baseline.pinned[1].config_path,
                 "cross-side config identity reuse"))
        return false;
    candidate = baseline;
    candidate.generated[1].response[100] = 'X';
    if (!rejects(candidate,
                 "downstream",
                 candidate.generated[1].response != baseline.generated[1].response,
                 "N/R downstream mismatch"))
        return false;
    candidate = baseline;
    {
        std::string wire(candidate.generated[1].upstream_history[0].begin(),
                         candidate.generated[1].upstream_history[0].end());
        const std::string host =
            "Host: 127.0.0.1:" + std::to_string(candidate.generated[1].backend_port) + "\r\n";
        const size_t at = wire.find(host);
        if (at == std::string::npos) {
            error = "#373 final upstream mutation fixture lacked complete Host token";
            return false;
        }
        const u16 alternate_port = candidate.generated[1].backend_port == 9999u
                                       ? 9998u
                                       : static_cast<u16>(candidate.generated[1].backend_port + 1u);
        const std::string alternate = "Host: 127.0.0.1:" + std::to_string(alternate_port) + "\r\n";
        if (alternate == host || alternate_port < 1024u || alternate_port > 9999u) {
            error = "#373 final upstream mutation fixture lacked a distinct four-digit Host";
            return false;
        }
        wire.replace(at, host.size(), alternate);
        candidate.generated[1].upstream_history[0].assign(wire.begin(), wire.end());
    }
    if (!rejects(candidate,
                 "upstream",
                 candidate.generated[1].upstream_history != baseline.generated[1].upstream_history,
                 "N/R upstream Host mismatch"))
        return false;
    candidate = baseline;
    candidate.generated[1].response.insert(
        candidate.generated[1].response.begin(),
        {'X', '-', 'C', 'o', 'm', 'p', 'a', 't', '-', 'H',  'i', 'd',
         'd', 'e', 'n', ':', ' ', 'l', 'e', 'a', 'k', '\r', '\n'});
    if (!rejects(candidate,
                 "hidden",
                 candidate.generated[1].response != baseline.generated[1].response,
                 "hidden header leak"))
        return false;
    candidate = baseline;
    {
        const std::string visible = "X-Compat-Visible: keep\r\n";
        std::string wire(candidate.generated[1].response.begin(),
                         candidate.generated[1].response.end());
        const size_t at = wire.find(visible);
        if (at == std::string::npos) {
            error = "#373 final visible-header mutation fixture was malformed";
            return false;
        }
        wire.replace(at, visible.size(), "X-Compat-Visible: keep\r\nX-Compat-Visible: keep\r\n");
        candidate.generated[1].response.assign(wire.begin(), wire.end());
    }
    if (!rejects(candidate,
                 "visible",
                 candidate.generated[1].response != baseline.generated[1].response,
                 "visible header duplicate"))
        return false;
    candidate = baseline;
    const std::string cookie_a = "Set-Cookie: a=1\r\n";
    const std::string cookie_b = "Set-Cookie: b=2\r\n";
    std::string response(candidate.generated[1].response.begin(),
                         candidate.generated[1].response.end());
    const size_t a = response.find(cookie_a), b = response.find(cookie_b);
    if (a == std::string::npos || b == std::string::npos || a > b) {
        error = "#373 final cookie-order mutation fixture was malformed";
        return false;
    }
    response.replace(a, cookie_a.size(), cookie_b);
    response.replace(b, cookie_b.size(), cookie_a);
    candidate.generated[1].response.assign(response.begin(), response.end());
    if (!rejects(candidate,
                 "cookies",
                 candidate.generated[1].response != baseline.generated[1].response,
                 "visible/cookie order mismatch"))
        return false;
    candidate = baseline;
    candidate.generated[1].accepted = 2u;
    if (!rejects(candidate,
                 "count",
                 candidate.generated[1].accepted != baseline.generated[1].accepted,
                 "retry/count mismatch"))
        return false;
    candidate = baseline;
    candidate.generated[1].response_peer_close_count = 2u;
    if (!rejects(candidate,
                 "FIN",
                 candidate.generated[1].response_peer_close_count !=
                     baseline.generated[1].response_peer_close_count,
                 "FIN mismatch"))
        return false;
    candidate = baseline;
    candidate.generated[1].response_peer_unexpected_data = true;
    if (!rejects(candidate,
                 "late",
                 candidate.generated[1].response_peer_unexpected_data !=
                     baseline.generated[1].response_peer_unexpected_data,
                 "late origin bytes"))
        return false;
    candidate = baseline;
    candidate.generated[1].eof = false;
    if (!rejects(candidate,
                 "EOF",
                 candidate.generated[1].eof != baseline.generated[1].eof,
                 "EOF mismatch"))
        return false;
    candidate = baseline;
    candidate.generated[1].stable_window = false;
    if (!rejects(candidate,
                 "stability",
                 candidate.generated[1].stable_window != baseline.generated[1].stable_window,
                 "stability mismatch"))
        return false;
    candidate = baseline;
    candidate.generated[1].access_enoent_final = false;
    if (!rejects(
            candidate,
            "access",
            candidate.generated[1].access_enoent_final != baseline.generated[1].access_enoent_final,
            "generated access appearance"))
        return false;
    candidate = baseline;
    candidate.generated[1].poison += "poison";
    if (!rejects(candidate,
                 "poison",
                 candidate.generated[1].poison != baseline.generated[1].poison,
                 "generated source poison bytes"))
        return false;
    candidate = baseline;
    candidate.generated[1].source_poisoned = false;
    if (!rejects(candidate,
                 "source_poisoned",
                 candidate.generated[1].source_poisoned != baseline.generated[1].source_poisoned,
                 "generated source poison ownership"))
        return false;
    candidate = baseline;
    candidate.generated[1].child_live_after_poison = false;
    if (!rejects(candidate,
                 "liveness",
                 candidate.generated[1].child_live_after_poison !=
                     baseline.generated[1].child_live_after_poison,
                 "post-poison liveness corruption"))
        return false;
    candidate = baseline;
    candidate.pinned[1].source_poison += "poison";
    if (!rejects(candidate,
                 "source_poison",
                 candidate.pinned[1].source_poison != baseline.pinned[1].source_poison,
                 "pinned source poison bytes"))
        return false;
    candidate = baseline;
    candidate.pinned[1].source_poisoned = false;
    if (!rejects(candidate,
                 "source_poisoned",
                 candidate.pinned[1].source_poisoned != baseline.pinned[1].source_poisoned,
                 "pinned source poison ownership"))
        return false;
    candidate = baseline;
    candidate.generated[1].exited_zero = false;
    if (!rejects(candidate,
                 "lifecycle",
                 candidate.generated[1].exited_zero != baseline.generated[1].exited_zero,
                 "lifecycle corruption"))
        return false;
    return true;
}

static bool capture_proxy_hide_header_final(const char* rut_path,
                                            const std::string& container_prefix,
                                            ProxyHideHeaderFinalDifferential& value,
                                            std::string& error) {
    TempDir temps[4];
    for (size_t i = 0u; i < 4u; i++) {
        if (!temps[i].create()) {
            error = "#373 final differential could not create four independent TempDir trees";
            return false;
        }
    }
    HeldLoopbackPorts reservations;
    for (size_t i = 0u; i < 8u; i++) {
        if (!reservations.reserve_four_digit(i, value.ports[i])) {
            error = "#373 final differential could not reserve all eight unique ports before N1";
            return false;
        }
    }
    // N1/N2 consume ports 0..3; R1/R2 consume ports 4..7.  Every other
    // reservation remains held during the active side's backend/frontend handoff.
    if (!capture_static_query_proxy_oracle_side(value.ports[0],
                                                value.ports[1],
                                                temps[0],
                                                container_prefix + "-N1",
                                                true,
                                                value.pinned[0],
                                                error,
                                                &reservations.fds[0],
                                                &reservations.fds[1],
                                                kProxyHideHeaderOracleProfile) ||
        !capture_static_query_proxy_oracle_side(value.ports[2],
                                                value.ports[3],
                                                temps[1],
                                                container_prefix + "-N2",
                                                false,
                                                value.pinned[1],
                                                error,
                                                &reservations.fds[2],
                                                &reservations.fds[3],
                                                kProxyHideHeaderOracleProfile) ||
        !capture_proxy_hide_header_generated_side(value.ports[4],
                                                  value.ports[5],
                                                  temps[2],
                                                  rut_path,
                                                  true,
                                                  value.generated[0],
                                                  error,
                                                  &reservations.fds[4],
                                                  &reservations.fds[5]) ||
        !capture_proxy_hide_header_generated_side(value.ports[6],
                                                  value.ports[7],
                                                  temps[3],
                                                  rut_path,
                                                  false,
                                                  value.generated[1],
                                                  error,
                                                  &reservations.fds[6],
                                                  &reservations.fds[7]))
        return false;
    return true;
}

